using CMS.DAO;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CMS.SQL.Examination
{
    public static class ExaminationSQL
    {
        public static string GetExaminationSQL(ExaminationSQLCommands sEnumCommand)
        {

            string query = "";
            switch (sEnumCommand)
            {
                case ExaminationSQLCommands.FetchCIAComponentsByCourseId:
                    {
                        query = @"SELECT 
                                        COURSE_GROUP_MARK,
                                        CIA_GROUP_MARK_ID,
                                        STUDENT_ID,
                                        NAME,
                                        REGISTER_NO,
                                        ROLL_NO,
                                        ADMISSION_NO,
                                        COURSE_ROOT_ID,
                                        MAX_MARK,
                                        ORDER_ID,
                                        CIA_GROUP_ID,
                                        COURSE_GROUP_ID,
                                        COMPONENT_ID,
                                        COMPONENT,
                                        SEMESTER_ID
                                    FROM
                                        (SELECT 
                                            '' AS COURSE_GROUP_MARK,
                                                '' AS CIA_GROUP_MARK_ID,
                                                CLS.STUDENT_ID,
                                                CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) NAME,
                                                SP.REGISTER_NO,
                                                SP.ROLL_NO,
                                                SP.ADMISSION_NO,
                                                COURSE_ROOT_ID,
                                                MAX_MARK,
                                                ORDER_ID,
                                                CIA_GROUP_ID,
                                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                                COMPONENT,
                                                SEMESTER_ID
                                        FROM
                                            STU_CLASS AS CLS
                                        JOIN (SELECT 
                                            CIA_GROUP_COMPONENT_ID,
                                                CIA_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID,
                                                MAX_MARK,
                                                MIN_MARK,
                                                CGC.ORDER_ID,
                                                SC.COMPONENT,
                                                CR.SEMESTER_ID,
                                                CR.COURSE_ROOT_ID
                                        FROM
                                            CIA_GROUP_COMPONENT AS CGC
                                        INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                            AND SC.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                            AND CT.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                            AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                            AND CR.IS_DELETED != 1
                                        WHERE
                                            CGC.IS_DELETED != 1
                                        ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                        INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                        INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                            AND CC.COURSE_ID = ?COURSE_ID 
                                            AND CC.IS_DELETED != 1
                                        WHERE
                                            CLS.CLASS_ID = ?CLASS_ID
                                                AND CLS.ACADEMIC_YEAR =?AC_YEAR
                                                AND CLS.IS_DELETED != 1
                                                AND SP.IS_LEFT != 1 UNION SELECT 
                                            '' AS COURSE_GROUP_MARK,
                                                '' AS CIA_GROUP_MARK_ID,
                                                CLS.STUDENT_ID,
                                                CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) NAME,
                                                SP.REGISTER_NO,
                                                SP.ROLL_NO,
                                                SP.ADMISSION_NO,
                                                COURSE_ROOT_ID,
                                                MAX_MARK,
                                                ORDER_ID,
                                                CIA_GROUP_ID,
                                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                                COMPONENT,
                                                SEMESTER_ID
                                        FROM
                                            STU_COURSE_INFO AS CLS
                                        JOIN (SELECT 
                                            CIA_GROUP_COMPONENT_ID,
                                                CIA_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID,
                                                MAX_MARK,
                                                MIN_MARK,
                                                CGC.ORDER_ID,
                                                SC.COMPONENT,
                                                CR.SEMESTER_ID,
                                                CR.COURSE_ROOT_ID
                                        FROM
                                            CIA_GROUP_COMPONENT AS CGC
                                        INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                            AND SC.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                            AND CT.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                            AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                            AND CR.IS_DELETED != 1
                                        WHERE
                                            CGC.IS_DELETED != 1
                                        ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                        INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                        WHERE
                                            CLS.S_CLASS_ID = ?CLASS_ID
                                                AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                                AND COURSE_ID = ?COURSE_ID
                                                AND CLS.IS_DELETED != 1
                                                AND SP.IS_LEFT != 1) AS T
                                    ORDER BY T.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAComponentsByCourseIdNew:
                    {
                        query = @"SELECT 
                                        COURSE_GROUP_MARK,
                                        CIA_GROUP_MARK_ID,
                                        STUDENT_ID,
                                        NAME,
                                        REGISTER_NO,
                                        ROLL_NO,
                                        ADMISSION_NO,
                                        COURSE_ROOT_ID,
                                        MAX_MARK,
                                        ORDER_ID,
                                        CIA_GROUP_ID,
                                        COURSE_GROUP_ID,
                                        COMPONENT_ID,
                                        COMPONENT,
                                        SEMESTER_ID,
                                        COURSE_TYPE_ID
                                    FROM
                                        (SELECT 
                                            '' AS COURSE_GROUP_MARK,
                                                '' AS CIA_GROUP_MARK_ID,
                                                CLS.STUDENT_ID,
                                                CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) NAME,
                                                SP.REGISTER_NO,
                                                SP.ROLL_NO,
                                                SP.ADMISSION_NO,
                                                COURSE_ROOT_ID,
                                                MAX_MARK,
                                                ORDER_ID,
                                                CIA_GROUP_ID,
                                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                                COMPONENT,
                                                SEMESTER_ID,
                                                COURSE_TYPE_ID
                                        FROM
                                            STU_CLASS AS CLS
                                        JOIN (SELECT 
                                            CIA_GROUP_COMPONENT_ID,
                                                CIA_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID,
                                                MAX_MARK,
                                                MIN_MARK,
                                                CGC.ORDER_ID,
                                                SC.COMPONENT,
                                                CR.SEMESTER_ID,
                                                CR.COURSE_ROOT_ID,
                                                CT.COURSE_TYPE_ID
                                        FROM
                                            CIA_GROUP_COMPONENT AS CGC
                                        INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                            AND SC.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                            AND CT.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                            AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                            AND CR.IS_DELETED != 1
                                        WHERE
                                            CGC.IS_DELETED != 1
                                        ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                        INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                        INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                            AND CC.COURSE_ID = ?COURSE_ID 
                                            AND CC.IS_DELETED != 1
                                        WHERE
                                            CLS.CLASS_ID = ?CLASS_ID
                                                AND CLS.ACADEMIC_YEAR =?AC_YEAR
                                                AND CLS.IS_DELETED != 1
                                                AND SP.IS_LEFT != 1 UNION SELECT 
                                            '' AS COURSE_GROUP_MARK,
                                                '' AS CIA_GROUP_MARK_ID,
                                                CLS.STUDENT_ID,
                                                CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) NAME,
                                                SP.REGISTER_NO,
                                                SP.ROLL_NO,
                                                SP.ADMISSION_NO,
                                                COURSE_ROOT_ID,
                                                MAX_MARK,
                                                ORDER_ID,
                                                CIA_GROUP_ID,
                                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                                COMPONENT,
                                                SEMESTER_ID,
                                                COURSE_TYPE_ID
                                        FROM
                                            STU_COURSE_INFO AS CLS
                                        JOIN (SELECT 
                                            CIA_GROUP_COMPONENT_ID,
                                                CIA_GROUP_ID,
                                                SUP_CIA_COMPONENT_ID,
                                                MAX_MARK,
                                                MIN_MARK,
                                                CGC.ORDER_ID,
                                                SC.COMPONENT,
                                                CR.SEMESTER_ID,
                                                CR.COURSE_ROOT_ID,
                                                CT.COURSE_TYPE_ID
                                        FROM
                                            CIA_GROUP_COMPONENT AS CGC
                                        INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                            AND SC.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                            AND CT.IS_DELETED != 1
                                        INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                            AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                            AND CR.IS_DELETED != 1
                                        WHERE
                                            CGC.IS_DELETED != 1
                                        ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                        INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                        WHERE
                                            CLS.S_CLASS_ID = ?CLASS_ID
                                                AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                                AND COURSE_ID = ?COURSE_ID
                                                AND CLS.IS_DELETED != 1
                                                AND SP.IS_LEFT != 1) AS T
                                    ORDER BY T.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAComponentsByCourseIdUsingStaffId:
                    {
                        query = @"SELECT 
                                ''AS COURSE_GROUP_MARK,'' AS CIA_GROUP_MARK_ID, CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_CLASS AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SC.IS_DELETED != 1
                                INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                    AND CT.IS_DELETED != 1
                                INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                    AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                            INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID=CLS.CLASS_ID AND CC.COURSE_ID=?COURSE_ID AND CC.IS_DELETED!=1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CLS.IS_DELETED != 1   AND SP.IS_LEFT!=1
                            UNION SELECT 
                               ''AS COURSE_GROUP_MARK,'' AS CIA_GROUP_MARK_ID,  CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,                               
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SC.IS_DELETED != 1
                                INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                    AND CT.IS_DELETED != 1
                                INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                    AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID -- AND CLS.STAFF_ID=?STAFF_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1  AND SP.IS_LEFT!=1 ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_Marks_Info:
                    {
                        query = @"SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_CLASS AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                                    INNER JOIN
                                CP_CLASS_COURSE AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                    AND CC.COURSE_ID = ?COURSE_ID
                                    AND CC.IS_DELETED != 1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CLS.IS_DELETED != 1 
                            UNION SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_COURSE_INFO AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_Marks_InfoUsingStaffId:
                    {
                        query = @"SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_CLASS AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                                CP_CLASS_COURSE AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                    AND CC.COURSE_ID = ?COURSE_ID
                                    AND CC.IS_DELETED != 1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CLS.IS_DELETED != 1 
                            UNION SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_COURSE_INFO AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID 
                                   -- AND CLS.STAFF_ID=?STAFF_ID
                                    AND CLS.COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingByAcitveId:
                    {
                        query = @"SELECT 
                        EXAM_SETTING_ID,
                        EXAM_NAME,
                        ACADEMIC_YEAR,
                        M_EXAM,
                        M_PASS,
                        SEMESTER,
                        LAST_DATE_FOR_EXAM_FEE,
                        DATE_FORMAT(start_date, '%d/%m/%Y') AS START_DATE,
                        DATE_FORMAT(end_date, '%d/%m/%Y') AS END_DATE
                    FROM
                        EXAM_SETTING
                    WHERE
                        IS_ACTIVE = 1 AND IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchArrearCourseByProgrammeIdAndBatch:
                    {
                        query = @"SELECT                                  
                                    CR.COURSE_CODE,
                                    CR.COURSE_TITLE,
                                    CR.COURSE_TYPE,
                                    CT.COURSE_TYPE,
                                    CR.SUBJECT_TYPE  AS 'SUBJECT_TYPE_ID',
                                    SM.SEMESTER,
                                    SB.SUBJECT_TYPE
                                FROM
                                    SEMESTER_MARKS_?AC_YEAR AS SM
                                        INNER JOIN
                                    CP_COURSE_ROOT_?AC_YEAR AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SB ON SB.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                INNER JOIN CP_COURSE_TYPE_?AC_YEAR AS CT ON CT.COURSE_TYPE_ID=CR.COURSE_TYPE
                                WHERE
                                    SM.STUDENT_ID IN (SELECT 
                                            SP.STUDENT_ID
                                        FROM
                                            STU_PERSONAL_INFO AS SP
                                        WHERE
                                            SP.PROGRAM_ID = ?PROGRAMME_ID AND SP.BATCH = ?BATCH_ID)
                                        AND RESULT !='P'
                                        AND SM.SEMESTER IN (?SEMESTER)
                                GROUP BY SM.COURSE_ID; ";
                        break;
                    }
                case ExaminationSQLCommands.FetchAcademicCurriculumByProgrammeIdAndBatch:
                    {
                        query = @"SELECT 
                                    CURRICULUM_ID,
                                    PROGRAMME,
                                    BATCH,
                                    COURSE_ID,
                                    CR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    ST.SUBJECT_TYPE,
                                    CR.COURSE_CODE,
                                    CR.COURSE_TITLE,    CT.COURSE_TYPE,
                                    SEMESTER
                                FROM
                                    ACADEMIC_CURRICULUM_?AC_YEAR AS AC
                                        INNER JOIN
                                    CP_COURSE_ROOT_?AC_YEAR AS CR ON AC.COURSE_ID = CR.COURSE_ROOT_ID AND CR.IS_DELETED!=1
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE  LEFT JOIN
                                     CP_COURSE_TYPE_?AC_YEAR AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                WHERE
                                    AC.IS_ACTIVE = 1 AND AC.IS_DELETED != 1
                                        AND AC.BATCH = ?BATCH_ID
                                        AND AC.PROGRAMME = ?PROGRAMME_ID;";
                        break;

                    }
                case ExaminationSQLCommands.FetchExamFeeStructureByProgrammeIdAndBatch:
                    {
                        //query = @"  SELECT 
                        //                PROGRAMME_HEAD_ID,
                        //                PROGRAMME_ID,
                        //                BATCH_ID,
                        //                AMOUNT,
                        //                EP.HEAD_ID,
                        //                SEMESTER,
                        //                ACADEMIC_YEAR,
                        //                SUBJECT_TYPE,
                        //                H.HEAD,EP.EXAM_SETTING_ID
                        //            FROM
                        //                EXAM_PROGRAMME_WISE_HEADS AS EP
                        //                 LEFT JOIN SUP_HEAD	 AS H ON H.HEAD_ID=EP.HEAD_ID
                        //            WHERE
                        //                EP.PROGRAMME_ID = ?PROGRAMME_ID AND EP.BATCH_ID = ?BATCH_ID
                        //                    AND EP.SEMESTER = (SELECT 
                        //                        semester
                        //                    FROM
                        //                        academic_semester_?AC_YEAR AS s
                        //                    WHERE
                        //                        s.PROGRAMME = ?PROGRAMME_ID AND s.BATCH = ?BATCH_ID
                        //                            AND s.IS_ACTIVE = 1)
                        //                    AND EP.IS_DELETED != 1;   ";
                        query = @"SELECT 
                                        EP.PROGRAMME_HEAD_ID,
                                        EP.PROGRAMME_ID,
                                        EP.BATCH_ID,
                                        EP.AMOUNT,
                                        EP.HEAD_ID,
                                        EP.SEMESTER,
                                        EP.ACADEMIC_YEAR,
                                        EP.SUBJECT_TYPE,
                                        H.HEAD,EP.EXAM_SETTING_ID
                                    FROM
                                        EXAM_PROGRAMME_WISE_HEADS AS EP
											INNER JOIN
										CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID=EP.PROGRAMME_GROUP_ID
											INNER JOIN
										ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID=EP.PROGRAMME_GROUP_ID
											AND SEM.SEMESTER=EP.SEMESTER
                                            AND SEM.BATCH=EP.BATCH_ID
                                            AND SEM.ACADEMIC_YEAR=EP.ACADEMIC_YEAR
                                            AND SEM.IS_DELETED!=1
                                           LEFT JOIN 
										SUP_HEAD AS H ON H.HEAD_ID=EP.HEAD_ID
                                    WHERE
										EP.IS_DELETED != 1 
                                        AND SEM.IS_ACTIVE=1
                                        AND EP.ACADEMIC_YEAR=?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamFeeStatus:
                    {
                        //query = @"SELECT 
                        //            SA.ACADEMIC_YEAR,
                        //            SA.FREQUENCY_ID,
                        //            HEAD,
                        //            SUM(IFNULL(CREDIT, 0)) AS CREDIT,
                        //            SUM(IFNULL(DEBIT, 0)) AS DEBIT,
                        //            (SUM(IFNULL(CREDIT, 0)) - SUM(IFNULL(DEBIT, 0))) AS BALANCE,
                        //            TRANSACTION_DATE
                        //        FROM
                        //            FEE_STUDENT_ACCOUNT AS SA
                        //                INNER JOIN
                        //            SUP_FEE_FREQUENCY AS FF ON FF.FREQUENCY_ID = SA.FREQUENCY_ID
                        //                INNER JOIN
                        //            SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = FF.SEMESTER_TYPE
                        //                AND IS_ACTIVE = 1
                        //        WHERE
                        //            SA.STUDENT_ID = ?STUDENT_ID
                        //                AND SA.ACADEMIC_YEAR = ?AC_YEAR; ";
                        //query = @"SELECT 
                        //            SA.ACADEMIC_YEAR,
                        //            SA.FREQUENCY_ID,
                        //            HEAD,
                        //            SUM(IFNULL(CREDIT, 0)) AS CREDIT,
                        //            SUM(IFNULL(DEBIT, 0)) AS DEBIT,
                        //            (SUM(IFNULL(CREDIT, 0)) - SUM(IFNULL(DEBIT, 0))) AS BALANCE,
                        //            TRANSACTION_DATE
                        //        FROM
                        //            FEE_STUDENT_ACCOUNT AS SA
                        //        WHERE
                        //            SA.STUDENT_ID = ?STUDENT_ID AND SA.FREQUENCY_ID = ?FREQUENCY
                        //                AND SA.ACADEMIC_YEAR = ?AC_YEAR;";

                        query = @"SELECT 
                                        FS.ACADEMIC_YEAR,
                                        FS.FREQUENCY_ID,
                                        FS.HEAD,
                                        SUM(IFNULL(FS.CREDIT, 0)) AS CREDIT,
                                        SUM(IFNULL(FS.DEBIT, 0)) AS DEBIT,
                                        (SUM(IFNULL(FS.CREDIT, 0)) - SUM(IFNULL(FS.DEBIT, 0))) AS BALANCE,
                                        FS.TRANSACTION_DATE
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        FEE_FREQUENCY_FEE_MODE AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                            INNER JOIN
                                        SUP_FEE_FREQUENCY AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FFF.FEE_MODE = ?FEE_MODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamFeeStatusByClassId:
                    {
                        query = @"SELECT 
                                        FS.ACADEMIC_YEAR,
                                        FS.FREQUENCY_ID,
                                        FS.HEAD,
                                        SUM(IFNULL(FS.CREDIT, 0)) AS CREDIT,
                                        SUM(IFNULL(FS.DEBIT, 0)) AS DEBIT,
                                        (SUM(IFNULL(FS.CREDIT, 0)) - SUM(IFNULL(FS.DEBIT, 0))) AS BALANCE,
                                        FS.TRANSACTION_DATE
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        FEE_FREQUENCY_FEE_MODE AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                            INNER JOIN
                                        SUP_FEE_FREQUENCY AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID
                                    WHERE
                                        SC.CLASS_ID=?CLASS
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND FFF.FEE_MODE = ?FEE_MODE
                                            GROUP BY SC.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamCreditAmountToStudentAccount:
                    {
                        query = @"INSERT INTO FEE_STUDENT_ACCOUNT
                                (STUDENT_ID,
                                ACADEMIC_YEAR,
                                FREQUENCY_ID,
                                HEAD,
                                CREDIT,FEE_MAIN_HEAD_ID)
                                VALUES
                                (
                                ?STUDENT_ID,
                                ?ACADEMIC_YEAR,
                                ?FREQUENCY_ID,
                                ?HEAD,
                                ?CREDIT,?FEE_MAIN_HEAD_ID);";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamCourseHeadsByStudentId:
                    {
                        //query = @"SELECT 
                        //            COURSE_HEAD_ID,
                        //            COURSE_CODE,
                        //            CH.PROGRAMME_HEAD_ID,
                        //            CH.PROGRAMME_ID,
                        //            CH.BATCH_ID,
                        //            EP.AMOUNT,
                        //            EP.HEAD_ID
                        //        FROM
                        //            EXAM_COURSE_WISE_HEADS AS CH
                        //                INNER JOIN
                        //            STU_PERSONAL_INFO AS SP ON SP.PROGRAM_ID = CH.PROGRAMME_ID
                        //                AND SP.BATCH = CH.BATCH_ID
                        //                INNER JOIN
                        //            EXAM_PROGRAMME_WISE_HEADS AS EP ON EP.PROGRAMME_HEAD_ID = CH.PROGRAMME_HEAD_ID
                        //        WHERE
                        //            CH.IS_DELETED != 1
                        //                AND SP.STUDENT_ID = ?STUDENT_ID;";
                        query = @"SELECT 
                                    CH.COURSE_HEAD_ID,
                                    COURSE_CODE,
                                    CH.PROGRAMME_HEAD_ID,
                                    CH.PROGRAMME_ID,
                                    CH.BATCH_ID,
                                    CW.AMOUNT,
                                    CH.HEAD_ID
                                FROM
                                    EXAM_COURSE_WISE_HEADS AS CH
                                        INNER JOIN
                                    SUP_COURSE_WISE_HEAD AS CW ON CW.COURSE_HEAD_ID=CH.HEAD_ID
                                WHERE
                                    CH.IS_DELETED != 1
                                        AND CH.COURSE_CODE = ?COURSE_CODE AND CH.EXAM_SETTING_ID=?EXAM_SETTING_ID AND CH.ACADEMIC_YEAR=?AC_YEAR;";
                        break;
                    }


                case ExaminationSQLCommands.FetchExamProgrameHeadsWithAmountByStudentId:
                    {
                        //query = @"SELECT 
                        //        EP.PROGRAMME_ID,
                        //        EP.BATCH_ID,
                        //        EP.HEAD_ID,
                        //        EP.AMOUNT,
                        //        EP.ACADEMIC_YEAR,
                        //        H.HEAD,
                        //        EP.SUBJECT_TYPE
                        //    FROM
                        //        EXAM_PROGRAMME_WISE_HEADS AS EP
                        //            INNER JOIN
                        //        STU_PERSONAL_INFO AS SP ON SP.PROGRAM_ID = EP.PROGRAMME_ID
                        //            AND EP.BATCH_ID = SP.BATCH
                        //            INNER JOIN
                        //        SUP_HEAD AS H ON H.HEAD_ID = EP.HEAD_ID
                        //    WHERE
                        //        SP.STUDENT_ID = ?STUDENT_ID
                        //            AND EP.IS_DELETED != 1;";
                        query = @"SELECT 
                                        PH.PROGRAMME_ID,
                                        PH.BATCH_ID,
                                        PH.HEAD_ID,
                                        PH.AMOUNT,
                                        PH.ACADEMIC_YEAR,
                                        H.HEAD,
                                        PH.SUBJECT_TYPE
                                    FROM
                                        STU_CLASS AS SC
		                                    INNER JOIN
	                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID=SC.PROGRAMME_GROUP_ID
		                                    INNER JOIN
	                                    EXAM_PROGRAMME_WISE_HEADS AS PH ON PH.PROGRAMME_GROUP_ID=PG.PROGRAMME_GROUP_ID
                                            AND PH.BATCH_ID=SC.BATCH
                                            AND PH.IS_DELETED!=1
		                                    INNER JOIN
                                       SUP_HEAD AS H ON H.HEAD_ID = PH.HEAD_ID
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.STUDENT_ID = ?STUDENT_ID AND PH.ACADEMIC_YEAR = ?AC_YEAR ;";
                        break;
                    }

                case ExaminationSQLCommands.FetchCourseHeadList:
                    {
                        //query = @"SELECT 
                        //            COURSE_HEAD_ID,
                        //            COURSE_CODE,
                        //            CH.PROGRAMME_HEAD_ID,
                        //            EP.PROGRAMME_ID,
                        //            EP.BATCH_ID,    B.BATCH,
                        //            EP.SEMESTER,
                        //            PROGRAMME_NAME,
                        //            AMOUNT,
                        //            ACCOUNT,SH.HEAD,EP.HEAD_ID,CH.EXAM_SETTING_ID
                        //        FROM
                        //            EXAM_COURSE_WISE_HEADS AS CH
                        //                INNER JOIN
                        //            CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CH.PROGRAMME_ID
                        //                INNER JOIN
                        //            EXAM_PROGRAMME_WISE_HEADS AS EP ON EP.PROGRAMME_HEAD_ID = CH.PROGRAMME_HEAD_ID
                        //                INNER JOIN
                        //            SUP_HEAD AS SH ON SH.HEAD_ID = EP.HEAD_ID
                        //        INNER JOIN SUP_BATCHES AS B ON B.BATCH_ID=EP.BATCH_ID
                        //        WHERE
                        //            CH.IS_DELETED != 1 AND EP.PROGRAMME_ID = ?PROGRAMME_ID
                        //            AND EP.BATCH_ID = ?BATCH_ID AND CH.ACADEMIC_YEAR=?AC_YEAR;";
                        query = @"SELECT 
                                    CCR.COURSE_ROOT_ID,
                                    CONCAT(IFNULL(CCR.COURSE_TITLE,''), ' ',IFNULL(CCR.COURSE_CODE,'')) AS 'COURSE_CODE',
                                    CCR.SEMESTER_ID AS 'SEMESTER',
                                    CWH.HEAD,
                                    CWH.AMOUNT,
                                    ES.EXAM_NAME,
                                    FF.FREQUENCY_NAME,
                                    FF.LAST_DATE_OF_PAYMENT
                                FROM
                                    EXAM_COURSE_WISE_HEADS AS CH
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_CODE = CH.COURSE_CODE
                                        INNER JOIN
                                    SUP_COURSE_WISE_HEAD AS CWH ON CWH.COURSE_HEAD_ID = CH.HEAD_ID
		                                AND CWH.IS_DELETED!=1
		                                INNER JOIN
	                                EXAM_SETTING  AS ES ON ES.EXAM_SETTING_ID=CH.EXAM_SETTING_ID
		                                AND ES.IS_ACTIVE=1
		                                AND ES.IS_DELETED!=1
		                                INNER JOIN
	                                SUP_FEE_FREQUENCY AS FF ON FF.ACADEMIC_YEAR=CH.ACADEMIC_YEAR
		                                AND FF.TYPE=1
                                        AND FF.IS_DELETED!=1
                                WHERE CH.ACADEMIC_YEAR=?AC_YEAR AND CH.IS_DELETED!=1; ";
                        break;
                    }
                case ExaminationSQLCommands.GetProgrammeIdByCourseCodeAndBatch:
                    {
                        query = @"SELECT 
                                    PROGRAMME_HEAD_ID,COURSE_HEAD_ID
                                FROM
                                    EXAM_COURSE_WISE_HEADS AS CH
                                WHERE
                                    CH.PROGRAMME_ID = ?PROGRAMME_ID AND CH.BATCH_ID = ?BATCH_ID
                                        AND CH.ACADEMIC_YEAR = ?ACADEMIC_YEAR
                                        AND CH.COURSE_CODE = ?COURSE_CODE
                                        AND CH.IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.SaveCourseHeads:
                    {
                        //query = @"INSERT INTO EXAM_COURSE_WISE_HEADS
                        //            (
                        //            COURSE_CODE,
                        //           -- PROGRAMME_HEAD_ID,
                        //           -- PROGRAMME_ID,
                        //           -- BATCH_ID,
                        //           -- SEMESTER,
                        //            HEAD_ID,
                        //            ACADEMIC_YEAR,EXAM_SETTING_ID)
                        //            VALUES
                        //            (?COURSE_CODE,
                        //           -- ?PROGRAMME_HEAD_ID,
                        //           -- ?PROGRAMME_ID,
                        //           -- ?BATCH_ID,
                        //           -- ?SEMESTER,
                        //            ?HEAD_ID,
                        //            ?ACADEMIC_YEAR,?EXAM_SETTING_ID);";
                        query = @"INSERT INTO EXAM_COURSE_WISE_HEADS
                                    (
                                    COURSE_CODE,
                                    HEAD_ID,
                                    ACADEMIC_YEAR,
                                    EXAM_SETTING_ID)
                                    VALUES
                                    (?COURSE_CODE,
                                    ?HEAD_ID,
                                    ?AC_YEAR,
                                    ?EXAM_SETTING_ID);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateCourseHeads:
                    {
                        //query = @"UPDATE EXAM_COURSE_WISE_HEADS
                        //            SET
                        //            COURSE_CODE = ?COURSE_CODE,
                        //         -- PROGRAMME_HEAD_ID = ?PROGRAMME_HEAD_ID,
                        //         -- PROGRAMME_ID = ?PROGRAMME_ID,
                        //         -- BATCH_ID = ?BATCH_ID,
                        //         -- SEMESTER = ?SEMESTER,
                        //            ACADEMIC_YEAR = ?ACADEMIC_YEAR , 
                        //            EXAM_SETTING_ID=?EXAM_SETTING_ID
                        //            WHERE COURSE_HEAD_ID = ?COURSE_HEAD_ID;";
                        query = @"UPDATE EXAM_COURSE_WISE_HEADS
                                    SET
                                    COURSE_CODE = ?COURSE_CODE,
                                    HEAD_ID=?HEAD_ID,
                                    EXAM_SETTING_ID=?EXAM_SETTING_ID
                                    WHERE COURSE_HEAD_ID = ?COURSE_HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteCourseHeads:
                    {
                        query = @"UPDATE EXAM_COURSE_WISE_HEADS
                                    SET
                                    IS_DELETED=1
                                    WHERE COURSE_HEAD_ID = ?COURSE_HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteProgrameHeads:
                    {
                        query = @"UPDATE EXAM_PROGRAMME_WISE_HEADS 
                                        SET 
                                            IS_DELETED =1 
                                        WHERE
                                            PROGRAMME_HEAD_ID = ?PROGRAMME_HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchProgramHeadsList:
                    {
                        //query = @"SELECT 
                        //            PROGRAMME_HEAD_ID,
                        //            AMOUNT,
                        //            PH.HEAD_ID,
                        //            PH.BATCH_ID,
                        //            B.BATCH,
                        //         SEMESTER,
                        //            PH.ACADEMIC_YEAR,
                        //            HEAD,
                        //            HEAD_CODE,
                        //            ACCOUNT,
                        //            P.PROGRAMME_ID,
                        //            P.PROGRAMME_NAME as PROGRAMME
                        //        FROM
                        //            EXAM_PROGRAMME_WISE_HEADS AS PH
                        //                LEFT JOIN
                        //            SUP_HEAD AS H ON H.HEAD_ID = PH.HEAD_ID
                        //                 INNER JOIN
                        //            CP_PROGRAMME AS P ON P.PROGRAMME_ID = PH.PROGRAMME_ID
                        //                  AND P.IS_DELETED != 1
                        //            INNER JOIN SUP_BATCHES AS B ON B.BATCH_ID=PH.BATCH_ID
                        //        WHERE
                        //            PH.IS_DELETED !=1 AND H.IS_DELETED != 1
                        //                AND PH.ACADEMIC_YEAR = ?AC_YEAR;";
                        query = @"SELECT 
                                    PROGRAMME_HEAD_ID,
                                    AMOUNT,
                                    PH.HEAD_ID,
                                    PH.BATCH_ID,
                                    B.BATCH,
                                    SEMESTER,
                                    PH.ACADEMIC_YEAR,
                                    HEAD,
                                    HEAD_CODE,
                                    ACCOUNT,
                                    P.PROGRAMME_ID,
                                    P.PROGRAMME_NAME AS PROGRAMME
                                FROM
                                    EXAM_PROGRAMME_WISE_HEADS AS PH
                                        LEFT JOIN
                                    SUP_HEAD AS H ON H.HEAD_ID = PH.HEAD_ID
                                        INNER JOIN
                                    cp_programme_group AS PG ON PG.PROGRAMME_GROUP_ID = PH.PROGRAMME_GROUP_ID
                                        AND PG.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        AND P.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_BATCHES AS B ON B.BATCH_ID = PH.BATCH_ID
                                WHERE
                                    PH.IS_DELETED != 1 AND H.IS_DELETED != 1
                                        AND PH.ACADEMIC_YEAR = ?AC_YEAR
                                        AND EXAM_SETTING_ID = (SELECT 
                                            FREQUENCY_ID
                                        FROM
                                            SUP_FEE_FREQUENCY
                                        WHERE
                                            TYPE = 1 AND IS_DELETED != 1);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateProgrammeHeads:
                    {
                        query = @"UPDATE EXAM_PROGRAMME_WISE_HEADS
                                    SET
                                    AMOUNT = ?AMOUNT,
                                    HEAD_ID = ?HEAD_ID,
                                    SEMESTER = ?SEMESTER
                                    WHERE PROGRAMME_HEAD_ID = ?PROGRAMME_HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveProgrammeHeads:
                    {
                        query = @"INSERT INTO EXAM_PROGRAMME_WISE_HEADS
                                    (
                                    PROGRAMME_GROUP_ID,
                                    BATCH_ID,
                                    AMOUNT,
                                    HEAD_ID,
                                    MAIN_HEAD_ID,
                                    SEMESTER,
                                    ACADEMIC_YEAR,SUBJECT_TYPE,EXAM_SETTING_ID)
                                    VALUES
                                    (
                                    ?PROGRAMME_ID,
                                    ?BATCH_ID,
                                    ?AMOUNT,
                                    ?HEAD_ID,
                                    ?MAIN_HEAD_ID,
                                    ?SEMESTER,
                                    ?AC_YEAR,?SUBJECT_TYPE,?EXAM_SETTING_ID
                                    );";
                        break;
                    }
                case ExaminationSQLCommands.FetchProgrammeheadsWithAmount:
                    {
                        query = @"SELECT 
                                    H.HEAD,
                                    H.HEAD_CODE,
                                    H.HEAD_ID,
                                    EP.PROGRAMME_ID,
                                    EP.BATCH_ID,
                                    EP.AMOUNT,
                                    EP.PROGRAMME_HEAD_ID,EP.SUBJECT_TYPE
                                FROM
                                    SUP_HEAD AS H
                                        LEFT JOIN
                                    EXAM_PROGRAMME_WISE_HEADS AS EP ON H.HEAD_ID = EP.HEAD_ID
                                        AND EP.PROGRAMME_GROUP_ID =?PROGRAMME_ID
                                        AND EP.BATCH_ID = ?BATCH_ID
                                        AND EP.IS_DELETED != 1
                                        AND EP.SEMESTER = ?SEMESTER
                                WHERE
                                    H.IS_DELETED != 1 AND H.HEAD_ID IN (?HEAD_ID);";
                        break;
                    }
                case ExaminationSQLCommands.FetchProgramHeads:
                    {
                        //query = @"SELECT 
                        //            HEAD,
                        //            H.HEAD_ID,
                        //            IF(PROGRAMME_HEAD_ID IS NOT NULL,
                        //                'SELECTED',
                        //                '') AS STATUS
                        //        FROM
                        //            SUP_HEAD AS H
                        //                LEFT JOIN
                        //            EXAM_PROGRAMME_WISE_HEADS AS EP ON H.HEAD_ID = EP.HEAD_ID
                        //                AND EP.PROGRAMME_ID = ?PROGRAMME_ID
                        //            AND EP.IS_DELETED != 1
                        //                AND EP.SEMESTER = (SELECT 
                        //                    SEMESTER
                        //                FROM
                        //                    ACADEMIC_SEMESTER
                        //                WHERE
                        //                    PROGRAMME = ?PROGRAMME_ID AND BATCH = ?BATCH_ID
                        //                        AND IS_ACTIVE = 1)
                        //        WHERE
                        //            H.IS_DELETED != 1";
                        query = @"SELECT 
                                    HEAD,
                                    H.HEAD_ID,
                                    IF(EP.PROGRAMME_HEAD_ID IS NOT NULL,'SELECTED','') AS STATUS
                                FROM
                                    EXAM_PROGRAMME_WISE_HEADS AS EP 
										INNER JOIN
									cp_programme_group AS PG ON PG.PROGRAMME_GROUP_ID=EP.PROGRAMME_GROUP_ID
										INNER JOIN
									cp_programme AS CP ON CP.PROGRAMME_ID=PG.PROGRAMME_ID
										INNER JOIN
									ACADEMIC_SEMESTER AS SEM ON SEM.SEMESTER=EP.SEMESTER
										AND SEM.PROGRAMME_GROUP_ID=EP.PROGRAMME_GROUP_ID 
                                        AND SEM.BATCH=EP.BATCH_ID
                                        AND SEM.IS_DELETED!=1
                                        LEFT JOIN
									SUP_HEAD AS H ON H.HEAD_ID=EP.HEAD_ID
                                WHERE
                                    H.IS_DELETED != 1 
                                    AND EP.ACADEMIC_YEAR=?AC_YEAR 
                                    AND SEM.IS_ACTIVE=1
                                    AND EP.PROGRAMME_GROUP_ID=?PROGRAMME_ID
                                    AND EP.BATCH_ID= ?BATCH_ID AND EP.IS_DELETED != 1 GROUP BY HEAD_ID;";

                        break;
                    }
                case ExaminationSQLCommands.FetchQuizOptionByStudentId:
                    {
                        query = @"SELECT 
                                    OPTION_ID,
                                    OPTIONS,
                                    QP.QUESTION_ID
                                FROM
                                    QUIZ_?AC_YEAR AS Q
		                                INNER JOIN
	                                QUIZ_OPTIONS_?AC_YEAR AS QP ON QP.QUESTION_ID=Q.QUESTION_ID
                                WHERE STUDENT_ID=?STUDENT_ID ORDER BY QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.QuizResult:
                    {
                        query = @"SELECT    
                                    QQ.QUESTION_ID, 
                                    QQ.QUESTION,
                                    Q.SELECTED_ANSWER AS 'SELECTED',
                                    QP.OPTIONS AS 'ANSWER',
                                    OP.OPTIONS AS 'SELECTED_ANSWER' ,
                                    IF(QP.OPTIONS !=OP.OPTIONS,'0','1') AS 'STATUS',
                                    SP.FIRST_NAME,
                                    CCR.COURSE_TITLE,
                                    DATE_FORMAT(Q.ENTRY_DATE,'%d/%m/%Y')AS 'DATE',
                                    (SELECT COUNT(QUESTION) FROM QUIZ_QUESTIONS_?AC_YEAR WHERE  COURSE_ID=?COURSE_ID)AS 'COUNT'
                                FROM
                                    QUIZ_?AC_YEAR AS Q 
		                                INNER JOIN
	                                QUIZ_QUESTIONS_?AC_YEAR AS QQ ON QQ.QUESTION_ID=Q.QUESTION_ID
		                                INNER JOIN
	                                QUIZ_OPTIONS_?AC_YEAR AS QP ON QP.OPTION_ID=QQ.ANSWER
		                                INNER JOIN
	                                QUIZ_OPTIONS_?AC_YEAR AS OP ON OP.OPTION_ID=Q.SELECTED_ANSWER  
		                                INNER JOIN
	                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=Q.STUDENT_ID
		                                INNER JOIN
	                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=QQ.COURSE_ID
                                WHERE Q.STUDENT_ID=?STUDENT_ID AND QQ.COURSE_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.QuizValidate:
                    {
                        query = @"SELECT 
                                      STUDENT_ID
                                    FROM
                                      QUIZ_?AC_YEAR AS Q
                                      INNER JOIN
                                      QUIZ_QUESTIONS_?AC_YEAR AS QQ ON QQ.QUESTION_ID=Q.QUESTION_ID
                                    WHERE
                                      STUDENT_ID = ?STUDENT_ID AND QQ.COURSE_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionIdByOption:
                    {
                        query = @"SELECT 
                                        OPTION_ID,
                                        `OPTION`,
                                        QUIZ_ID,
                                        SET_ID,
                                        MARK,
                                        SETTING_ID
                                    FROM
                                        QUIZ_OBJECTIVE_OPTIONS
                                    WHERE
                                        `OPTION` = ?ANSWER_ID
                                            AND QUIZ_ID = ?QUIZ_ID AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveQuestionAndAnswerByQuizId:
                    {
                        query = @"SELECT 
                                    QQ.QUIZ_ID,
                                    QQ.QUESTION,
                                    QQ.QUESTION_TYPE,
                                    QQ.CLASS_ID,
                                    QQ.COURSE_ID,
                                    QQ.ANSWER_ID,
                                    OP.OPTION_ID,
                                    OP.OPTION,
                                    OP.MARK,
                                    IF(QQ.ANSWER_ID = OP.OPTION_ID,OP.OPTION,'') AS ANSWER
                                FROM
                                    QUIZ_OBJECTIVE_QUESTIONS AS QQ
                                        INNER JOIN
                                    QUIZ_OBJECTIVE_OPTIONS AS OP ON OP.QUIZ_ID=QQ.QUIZ_ID
                                WHERE
                                    QQ.QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionIdByQuestionId:
                    {
                        query = @"SELECT 
                                    OPTION_ID,
                                    OPTIONS
                                FROM
                                    QUIZ_OPTIONS_?AC_YEAR
                                WHERE
                                    QUESTION_ID = ?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizByQuestionId:
                    {
                        query = @"SELECT 
	                                QUESTION_ID,
                                    QUESTION,
                                    CLASS_ID,
                                    COURSE_ID,
                                    STAFF_ID,
									ANSWER
                                FROM
                                    QUIZ_QUESTIONS_?AC_YEAR 
                                WHERE QUESTION_ID=?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ListObjectiveQuiz:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QT.QUESTION_TYPE_ID,
                                        QT.QUESTION_TYPE,
                                        CC.CLASS_NAME,
                                        STF.FIRST_NAME,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SE.SET_NAME AS 'SET_ID',
                                        SS.SEMESTER_NAME,
                                        QQ.MARK
                                    FROM
                                        QUIZ_OBJECTIVE_QUESTIONS AS QQ
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS STF ON STF.STAFF_ID = QQ.ENTRY_ID
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = QQ.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
		                                    INNER JOIN
	                                    SUP_QUIZ_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID=QQ.QUESTION_TYPE 
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=CCR.SEMESTER_ID
                                            LEFT JOIN
                                        SUP_SETS AS SE ON SE.SET_ID = QQ.SET_ID
                                    WHERE
                                        QQ.ENTRY_ID = ?ENTRY_ID
                                            AND QQ.SETTING_ID IN (?SETTING_ID)
                                            AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseForQuiz:
                    {
                        query = @"SELECT 
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_TITLE
                                FROM
                                    STU_CLASS AS SC
		                                INNER JOIN	                                 
								    QUIZ_QUESTIONS_?AC_YEAR AS QQ ON QQ.CLASS_ID=SC.CLASS_ID
                                       INNER JOIN
								    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=QQ.COURSE_ID AND CCR.IS_DELETED!=1
                                WHERE SC.STUDENT_ID=?STUDENT_ID GROUP BY CCR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveQuizOption:
                    {
                        query = @"INSERT INTO QUIZ_OBJECTIVE_OPTIONS
                                    (
                                        `OPTION`,
                                        QUIZ_ID,
                                        SET_ID,
                                        SETTING_ID
                                    )
                                    VALUES
                                    (
                                        ?OPTION,
                                        ?QUIZ_ID,
                                        ?SET_ID,
                                        ?SETTING_ID
                                    );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizOptions:
                    {
                        query = @"UPDATE `QUIZ_OBJECTIVE_OPTIONS`
                                    SET
                                    `OPTION` = ?OPTION,
                                    `MARK` = ?MARK
                                    WHERE `OPTION_ID` = ?OPTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizOptionByCourseId:
                    {
                        query = @"SELECT 
                                    OP.OPTION_ID, 
                                    OP.OPTIONS, 
                                    OP.QUESTION_ID
                                FROM
                                    QUIZ_OPTIONS_?AC_YEAR AS OP
                                        INNER JOIN
                                    QUIZ_QUESTIONS_?AC_YEAR AS QQ ON QQ.QUESTION_ID = OP.QUESTION_ID
                                WHERE QQ.COURSE_ID=?COURSE_ID AND CLASS_ID=?CLASS_ID AND QQ.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizQuestionByCourseId:
                    {
                        query = @"SELECT 
                                    QQ.QUESTION_ID,
                                    QQ.QUESTION,
                                    OP.OPTIONS AS 'ANSWER',
                                    QQ.CLASS_ID,
                                    QQ.COURSE_ID,
                                    QQ.STAFF_ID
                                FROM
                                    QUIZ_QUESTIONS_?AC_YEAR AS QQ
		                                INNER JOIN
	                                QUIZ_OPTIONS_?AC_YEAR AS OP ON OP.OPTION_ID=QQ.ANSWER
                                WHERE QQ.COURSE_ID=?COURSE_ID AND CLASS_ID=?CLASS_ID AND QQ.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveQuizQuestion:
                    {
                        query = @"INSERT INTO QUIZ_OBJECTIVE_QUESTIONS
                                  (                                      
                                      ENTRY_ID, 
                                      CLASS_ID, 
                                      COURSE_ID,
                                      QUESTION, 
                                      MARK,
                                      SET_ID, 
                                      QUESTION_TYPE, 
                                      ACADEMIC_YEAR,                                      
                                      SEMESTER_ID, 
                                      SETTING_ID
                                  )
                                  VALUES
                                  (
                                      ?ENTRY_ID, 
                                      ?CLASS_ID, 
                                      ?COURSE_ID,
                                      ?QUESTION, 
                                      ?MARK, 
                                      ?SET_ID, 
                                      ?QUESTION_TYPE, 
                                      ?AC_YEAR,                                      
                                      ?SEMESTER_ID, 
                                      ?SETTING_ID
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizQuestion:
                    {
                        query = @"UPDATE QUIZ_OBJECTIVE_QUESTIONS
                                    SET
                                    ENTRY_ID = ?ENTRY_ID,
                                    CLASS_ID = ?CLASS_ID,
                                    COURSE_ID = ?COURSE_ID,
                                    QUESTION = ?QUESTION,
                                    MARK = ?MARK,
                                    SET_ID = ?SET_ID,
                                    QUESTION_TYPE = ?QUESTION_TYPE,
                                    ANSWER_ID = ?ANSWER_ID
                                    WHERE QUESTION_ID = ?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassByStudentId:
                    {
                        query = @"SELECT 
                                        STUDENT_ID, 
                                        CLASS_ID
                                    FROM
                                        STU_CLASS
                                    WHERE
                                        STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassByStaffId:
                    {
                        query = @"SELECT 
                                    CC.CLASS_ID,
                                    CC.CLASS_NAME
                                FROM
                                   CP_CLASS_COURSE_STAFF AS CCS
		                                INNER JOIN
	                                CP_CLASSES AS CC ON CC.CLASS_ID=CCS.CLASS_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID=CCS.COURSE_ID
                                        INNER JOIN
                                    SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID=CCS.SEMESTER_TYPE_ID
                                        AND ST.IS_ACTIVE=1
                                WHERE 
	                                CCS.STAFF_ID=?STAFF_ID 
                                    AND CCS.IS_DELETED!=1 
                                  --  AND CR.SEMESTER_ID IN (?SEMESTER_ID)
                                    AND CCS.ACADEMIC_YEAR=?AC_YEAR GROUP BY CC.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteQuiz:
                    {
                        query = @"UPDATE QUIZ_QUESTIONS_?AC_YEAR SET IS_DELETED=1 WHERE QUESTION_ID=?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoByAcademicYear:
                    {
                        query = @"SELECT 
                                        CC.COURSE_CODE, CC.COURSE_TITLE, CC.SEMESTER_ID
                                    FROM
                                        CP_COURSE_ROOT AS CC
                                    WHERE
                                        CC.COURSE_ROOT_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCollegeDetails:
                    {
                        query = @"SELECT 
                                    UPPER(COLLEGE_CODE) AS 'COLLEGE_CODE',
                                    UPPER(COLLEGE_NAME) AS 'COLLEGE_NAME',
                                    CONCAT(UPPER(ADDRESS_ONE),' - ',PINCODE) AS 'COLLEGE_ADDRESS',
                                    UNIVERSITY AS 'UNIVERSITY',
                                    GRADE AS 'GRADE',
                                    CONCAT(PLACE,' - ',PINCODE) AS 'PLACE',
                                    COLLEGE_LOGO,
                                    LOGIN_IMG_PATH
                                FROM
                                    COLLEGE_DETAILS;";
                        break;
                    }
                case ExaminationSQLCommands.ValidateStudentForExamRegistration:
                    {
                        query = @"SELECT 
	                                COUNT(*) > 0 AS 'RESULT',
                                    STUDENT_ID
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS ER
                                        INNER JOIN  
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID=ER.EXAM_SETTING_ID
                                        AND ES.ACADEMIC_YEAR=?AC_YEAR
                                        AND ES.IS_ACTIVE=1
                                WHERE
                                    STUDENT_ID = ?STUDENT_ID; ";
                        break;
                    }
                case ExaminationSQLCommands.ExamControllerPrint:
                    {
                        query = @"SELECT 
                                   SP.ROLL_NO,
                                   SP.REGISTER_NO,
                                   CCR.COURSE_CODE,
                                   UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                   ER.STATUS,
                                   B.BATCH
                               FROM
                                   EXAM_REGISTRATION_?AC_YEAR ER 
	                                    INNER JOIN
	                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=ER.COURSE_ID
	                                    INNER JOIN 
	                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=ER.STUDENT_ID
	                                    INNER JOIN
	                                STU_CLASS AS SC ON SC.STUDENT_ID=ER.STUDENT_ID AND SC.ACADEMIC_YEAR=?AC_YEAR
			                            INNER JOIN
		                            SUP_BATCHES AS B ON B.BATCH_ID=SP.BATCH
                               WHERE SC.CLASS_ID IN (?CLASS_ID) AND  ER.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchHallTicketListPreview:
                    {
                        query = @"SELECT 
                                  REGISTRATION_ID,
                                  STUDENT_ID,
                                  CC.COURSE_CODE,
                                  CC.COURSE_TITLE,
                                  ER.COURSE_ID,
                                  STATUS,
                                  ER.IS_VIRIFIED,
                                  ER.ACADEMIC_YEAR,
                                  S.SEMESTER_NAME AS 'SEMESTER_ID',
                                  ES.M_PASS AS 'MONTH_YEAR',
                                  CC.SEMESTER_ID AS 'SEMESTER',
                                  ER.AMOUNT
                              FROM
                                  EXAM_REGISTRATION_?AC_YEAR AS ER
                        	        INNER JOIN 
                                 CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID=ER.COURSE_ID
                        	        INNER JOIN
                                 SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID=CC.SEMESTER_ID
                                    INNER JOIN
								 EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID=ER.EXAM_SETTING_ID 
									AND ES.IS_ACTIVE=1
                                    AND ES.IS_DELETED!=1
                              WHERE
                                 ER.STUDENT_ID = ?STUDENT_ID AND ER.ACADEMIC_YEAR=?AC_YEAR AND ER.IS_DELETED!=1
                                 ORDER BY CAST(CC.SEMESTER_ID AS UNSIGNED), CC.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchHallTicketList:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID,
                                        ER.STUDENT_ID,
                                        CC.COURSE_CODE,
                                        CC.COURSE_TITLE,
                                        IF(ET.IS_ADVANCE = '1',
                                            DATE_FORMAT(ET.ADVANCE_DATE, '%d/%m/%Y'),
                                            IF(ET.IS_POSTPONED = '1',
                                                DATE_FORMAT(ET.POSTPONED_DATE, '%d/%m/%Y'),
                                                DATE_FORMAT(ET.EXAM_DATE, '%d/%m/%Y'))) AS EXAM_DATE,
                                        IF(ET.IS_ADVANCE = '1',
                                            ET.ADVANCE_TIME,
                                            IF(ET.IS_POSTPONED = '1',
                                                ET.POSTPONED_TIME,
                                                ET.EXAM_TIME)) AS EXAM_TIME,
                                        ER.COURSE_ID,
                                        STATUS,
                                        ER.ACADEMIC_YEAR,
                                        S.SEMESTER_NAME AS 'SEMESTER_ID',
                                        ES.M_PASS AS 'MONTH_YEAR',
                                        CC.SEMESTER_ID AS 'SEMESTER',
                                        CONCAT(IFNULL(ESS.SEAT_CODE,'')) AS SEAT_CODE,
                                        SCB.BLOCK_CODE,
                                        SCB.BLOCK_NAME
    
                                    FROM
                                       EXAM_REGISTRATION_?AC_YEAR AS ER
                                        INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID 
                                            AND ES.IS_ACTIVE = 1
                                            LEFT JOIN
                                        EXAM_SEATING_ALLOTEMENT AS ESA ON ESA.STUDENT_ID = ER.STUDENT_ID
                                            AND ESA.COURSE_ID = ER.COURSE_ID AND  ESA.EXAM_TYPE=ES.EXAM_TYPE
                                            LEFT JOIN
                                        EXAM_SEATINGS AS ESS ON ESS.SEATING_ID = ESA.SEATING_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CC.SEMESTER_ID
                                            LEFT JOIN
                                        EXAM_TIMETABLE AS ET ON ET.COURSE_ID = CC.COURSE_ROOT_ID
                                            AND ET.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                            AND ET.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            LEFT JOIN
                                        SUP_ROOM AS SR ON SR.ROOM_ID = ESS.ROOM_ID
                                            LEFT JOIN
                                        SUP_COLLEGE_BLOCK AS SCB ON SCB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                    WHERE
                                        ER.STUDENT_ID = ?STUDENT_ID AND ER.STATUS='R'
                                            AND ER.ACADEMIC_YEAR = ?AC_YEAR AND ER.IS_DELETED!=1
                                    ORDER BY DATE_FORMAT(ET.EXAM_DATE, '%Y-%m-%d') ASC;";
                        break;
                    }

                case ExaminationSQLCommands.FetchHallTicket:
                    {
                        //query = @"SELECT 
                        //            D.DEPARTMENT,
                        //            REGISTER_NO,
                        //            FIRST_NAME,
                        //            CD.DEGREE,
                        //            SS.SEMESTER_NAME,
                        //            S.SEMESTER,
                        //            DATE_FORMAT(DATE_OF_BIRTH,'%d/%m/%Y')AS 'DATE_OF_BIRTH',
                        //            CONCAT(DATE_FORMAT(current_date(),'%M - %Y')) AS 'YEAR'
                        //        FROM
                        //            STU_PERSONAL_INFO SP
                        //                INNER JOIN
                        //            CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = SP.DEPT_ID
                        //          INNER JOIN
                        //         CP_PROGRAMME AS P ON P.PROGRAMME_ID=SP.PROGRAM_ID
                        //          LEFT JOIN
                        //         CP_DEGREE AS CD ON CD.DEGREE_ID=P.DEGREE
                        //          INNER JOIN
                        //         ACADEMIC_SEMESTER AS S ON S.PROGRAMME=SP.PROGRAM_ID AND S.BATCH=SP.BATCH
                        //          INNER JOIN
                        //         SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=S.SEMESTER
                        //        WHERE
                        //            SP.STUDENT_ID =?STUDENT_ID AND S.IS_ACTIVE=1;";
                        query = @"SELECT 
                                    D.DEPARTMENT,
                                    REGISTER_NO,
                                    ROLL_NO,
                                    PHOTO,
                                    CONCAT(IFNULL(FIRST_NAME,''),' ',IFNULL(LAST_NAME,'')) AS FIRST_NAME,
                                    C.CLASS_NAME,
                                    CD.DEGREE,
                                    SS.SEMESTER_NAME,
                                    S.SEMESTER,
                                    DATE_FORMAT(DATE_OF_BIRTH, '%d/%m/%Y') AS 'DATE_OF_BIRTH',
                                    CONCAT(DATE_FORMAT(CURRENT_DATE(), '%M - %Y')) AS 'YEAR'
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = C.DEPARTMENT
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                        AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                            ACADEMIC_YEAR_ID
                                        FROM
                                            ACADEMIC_YEAR
                                        WHERE
                                            AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS S ON S.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND S.BATCH = AB.BATCH_ID
                                        AND S.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                        AND S.IS_DELETED!=1
                                        INNER JOIN
                                    SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = S.SEMESTER
                                        LEFT JOIN
                                    CP_DEGREE AS CD ON CD.DEGREE_ID = P.DEGREE
                                WHERE
                                    SP.STUDENT_ID = ?STUDENT_ID -- AND S.IS_ACTIVE = 1
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchProgramAndBatchByStudentID:
                    {
                        query = @"SELECT 
                                        AB.BATCH_ID AS 'BATCH', 
                                        C.PROGRAMME_GROUP_ID AS 'PROGRAMME',
                                        C.CLASS_YEAR
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1;";

                        break;
                    }
                case ExaminationSQLCommands.FetchStudentDetailsForExamRegistration:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SC.CLASS_ID,
                                         CONCAT(UPPER(IFNULL(SP.FIRST_NAME, '')),
                                                ' ',
                                               UPPER(IFNULL(SP.LAST_NAME, ''))) AS 'NAME',
                                       
                                        DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS 'DATE_OF_BIRTH',
                                        NAME_IN_NATIVE,
                                        SP.REGISTER_NO,
                                        D.DEPARTMENT,
                                        IF(SP.STU_MOBILENO IS NULL
                                                || SP.STU_MOBILENO = '',
                                            IF(SP.FR_MOBILE IS NULL
                                                    || SP.FR_MOBILE = '',
                                                IF(SP.MO_MOBILE IS NULL
                                                        || SP.MO_MOBILE = '',
                                                    '',
                                                    SP.MO_MOBILE),
                                                SP.FR_MOBILE),
                                            SP.STU_MOBILENO) AS 'MOBILE_NO',
                                        CONCAT('#',
                                                A.P_DOOR_DETAIL,
                                                ',',
                                                A.P_VILLAGE_AREA,
                                                '(village) ,',
                                                A.P_POST_PLACE_TOWN,
                                                '(POST) ,') AS 'ADDRESS1',
                                        CONCAT(A.P_STREET,
                                                ',',
                                                A.P_DISTRICT,
                                                'D.T ,',
                                                P_PINCODE) AS 'ADDRESS2',
                                        CONCAT(DATE_FORMAT(CURRENT_DATE(), '%M'),
                                                '-',
                                                DATE_FORMAT(CURRENT_DATE(), '%Y')) AS 'YEAR',
                                        DATE_FORMAT(CURRENT_DATE(), '%d/%m/%Y') AS 'DATE',
                                        M_EXAM AS 'MONTH',
                                        ES.EXAM_SETTING_ID,
                                        CP.PROGRAMME_NAME,
                                        SS.SEMESTER_NAME,
                                        SP.BATCH                                      
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = CC.DEPARTMENT
                                            LEFT JOIN
                                        STU_ADDRESS AS A ON A.STUDENT_ID = SP.STUDENT_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CC.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = PG.PROGRAMME_ID
                                            INNER JOIN    
                                        EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PT.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                            AND ES.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND ES.IS_ACTIVE=1
                                            INNER JOIN
                                        ACADEMIC_YEAR AS AY ON AY.AC_YEAR = SC.ACADEMIC_YEAR
                                            AND AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = CC.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = AY.ACADEMIC_YEAR_ID
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = CC.PROGRAMME_GROUP_ID
                                            AND SEM.BATCH = AB.BATCH_ID
                                            AND SEM.IS_ACTIVE = 1
                                            AND SEM.IS_DELETED != 1
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = SEM.SEMESTER
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY SP.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentDetailsForExamRegistrationByClassId:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        CONCAT(UPPER(IFNULL(SP.FIRST_NAME, '')),
                                                ' ',
                                                UPPER(IFNULL(SP.LAST_NAME, ''))) AS 'NAME',
                                        NAME_IN_NATIVE,
                                        DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS 'DATE_OF_BIRTH',
                                        SP.REGISTER_NO,
                                        D.DEPARTMENT,
                                        IF(SP.STU_MOBILENO IS NULL
                                                || SP.STU_MOBILENO = '',
                                            IF(SP.FR_MOBILE IS NULL
                                                    || SP.FR_MOBILE = '',
                                                IF(SP.MO_MOBILE IS NULL
                                                        || SP.MO_MOBILE = '',
                                                    '',
                                                    SP.MO_MOBILE),
                                                SP.FR_MOBILE),
                                            SP.STU_MOBILENO) AS 'MOBILE_NO',
                                        CONCAT('#',
                                                A.P_DOOR_DETAIL,
                                                ',',
                                                A.P_VILLAGE_AREA,
                                                '(village) ,',
                                                A.P_POST_PLACE_TOWN,
                                                '(POST) ,') AS 'ADDRESS1',
                                        CONCAT(A.P_STREET,
                                                ',',
                                                A.P_DISTRICT,
                                                'D.T ,',
                                                P_PINCODE) AS 'ADDRESS2',
                                        CONCAT(DATE_FORMAT(CURRENT_DATE(), '%M'),
                                                '-',
                                                DATE_FORMAT(CURRENT_DATE(), '%Y')) AS 'YEAR',
                                        DATE_FORMAT(CURRENT_DATE(), '%d/%m/%Y') AS 'DATE',
                                        M_EXAM AS 'MONTH',
                                        ES.EXAM_SETTING_ID,
                                        SS.SEMESTER_NAME,
                                        ES.SEMESTER_TYPE
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED!=1
                                            AND SP.IS_LEFT!=1
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = CC.DEPARTMENT
                                            LEFT JOIN
                                        STU_ADDRESS AS A ON A.STUDENT_ID = SP.STUDENT_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            INNER JOIN
                                        EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PT.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                            AND ES.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        ACADEMIC_YEAR AS AY ON AY.AC_YEAR = SC.ACADEMIC_YEAR
                                            AND AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = CC.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = AY.ACADEMIC_YEAR_ID
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            AND SEM.BATCH = AB.BATCH_ID
                                            AND SEM.IS_ACTIVE = 1
                                            AND SEM.IS_DELETED != 1
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = SEM.SEMESTER
                                    WHERE
                                         SC.CLASS_ID = ?CLASS_ID AND SC.IS_DELETED != 1
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY SP.STUDENT_ID ORDER BY SP.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentDetailsForCIAExam:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        CONCAT(UPPER(IFNULL(SP.FIRST_NAME, '')),
                                                ' ',
                                                UPPER(IFNULL(SP.LAST_NAME, ''))) AS 'NAME',
                                        DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS 'DATE_OF_BIRTH',
                                        SP.REGISTER_NO,
                                        D.DEPARTMENT,
                                        IF(SP.STU_MOBILENO IS NULL
                                                || SP.STU_MOBILENO = '',
                                            IF(SP.FR_MOBILE IS NULL
                                                    || SP.FR_MOBILE = '',
                                                IF(SP.MO_MOBILE IS NULL
                                                        || SP.MO_MOBILE = '',
                                                    '',
                                                    SP.MO_MOBILE),
                                                SP.FR_MOBILE),
                                            SP.STU_MOBILENO) AS 'MOBILE_NO',
                                        CONCAT('#',
                                                A.P_DOOR_DETAIL,
                                                ',',
                                                A.P_VILLAGE_AREA,
                                                '(village) ,',
                                                A.P_POST_PLACE_TOWN,
                                                '(POST) ,') AS 'ADDRESS1',
                                        CONCAT(A.P_STREET,
                                                ',',
                                                A.P_DISTRICT,
                                                'D.T ,',
                                                P_PINCODE) AS 'ADDRESS2',
                                        CONCAT(DATE_FORMAT(CURRENT_DATE(), '%M'),
                                                '-',
                                                DATE_FORMAT(CURRENT_DATE(), '%Y')) AS 'YEAR',
                                        DATE_FORMAT(CURRENT_DATE(), '%d/%m/%Y') AS 'DATE',
                                        M_EXAM AS 'MONTH',
                                        ES.EXAM_SETTING_ID,
                                        SS.SEMESTER_NAME
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = CC.DEPARTMENT
                                            LEFT JOIN
                                        STU_ADDRESS AS A ON A.STUDENT_ID = SP.STUDENT_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            INNER JOIN
                                        CIA_EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PT.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        CIA_EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                            AND ES.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        ACADEMIC_YEAR AS AY ON AY.AC_YEAR = SC.ACADEMIC_YEAR
                                            AND AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = CC.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = AY.ACADEMIC_YEAR_ID
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            AND SEM.BATCH = AB.BATCH_ID
                                            AND SEM.IS_ACTIVE = 1
                                            AND SEM.IS_DELETED != 1
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = SEM.SEMESTER
                                    WHERE
                                        SC.STUDENT_ID IN (?STUDENT_ID)
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY SP.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegistration:
                    {
                        // Query For Fetch All The Courses From Course Pattern..
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CS.COURSE_STRUCTURE_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                    CCR.IS_COMPULSORY,
                                    SC.CLASS_ID,
                                    CCR.PART,
                                    ccr.INTERNAL,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    CP.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    CP_COURSE_STRUCTURE AS CS
                                        INNER JOIN
                                    CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                        AND CP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                        AND PG.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        AND P.IS_DELETED != 1
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                        AND C.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                        AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                        AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                            ACADEMIC_YEAR_ID
                                        FROM
                                            ACADEMIC_YEAR
                                        WHERE
                                            AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS S ON S.SEMESTER = CCR.SEMESTER_ID
                                        AND S.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                        AND S.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND S.BATCH = AB.BATCH_ID
                                        AND S.IS_DELETED != 1
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    CP.ACADEMIC_YEAR = ?AC_YEAR
                                        AND S.IS_ACTIVE = 1
                                        AND SC.STUDENT_ID = ?STUDENT_ID
                                        AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CS.IS_DELETED != 1
                                GROUP BY CCR.COURSE_CODE ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseListForFeedBackEntry:
                    {
                        // Query For Fetch All The Courses From Course Pattern..
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CS.COURSE_STRUCTURE_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    CONCAT(UPPER(CCR.COURSE_TITLE),' (', UPPER(CCR.COURSE_CODE),')') as 'COURSE_TITLE',
                                    CCR.IS_COMPULSORY,
                                    SC.CLASS_ID,
                                    CCR.PART,
                                    ccr.INTERNAL,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    CP.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    CP_COURSE_STRUCTURE AS CS
                                        INNER JOIN
                                    CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                        AND CP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                        AND PG.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        AND P.IS_DELETED != 1
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                        AND C.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                        AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                        AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                            ACADEMIC_YEAR_ID
                                        FROM
                                            ACADEMIC_YEAR
                                        WHERE
                                            AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS S ON S.SEMESTER = CCR.SEMESTER_ID
                                        AND S.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                        AND S.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND S.BATCH = AB.BATCH_ID
                                        AND S.IS_DELETED != 1
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    CP.ACADEMIC_YEAR = ?AC_YEAR
                                        AND S.IS_ACTIVE = 1
                                        AND SC.STUDENT_ID = ?STUDENT_ID
                                        AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CS.IS_DELETED != 1
                                GROUP BY CCR.COURSE_CODE ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentListFeedBack:
                    {
                        // Query For Fetch All The Courses From Course Pattern..
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    SPI.ROLL_NO,
                                    SPI.FIRST_NAME,
                                    C.CLASS_NAME,
                                    CP.COURSE_ID,
