                case ExaminationSQLCommands.SaveExamDetails:
                    {
                        query = @"INSERT INTO EXAM_REGISTRATION_?AC_YEAR
                                  (
	                                  STUDENT_ID,
	                                  COURSE_ID,
	                                  STATUS,
                                      ACADEMIC_YEAR,
                                      EXAM_SETTING_ID,
                                      EXAM_SEMESTER
                                  )
                                  VALUES
                                  (
                                     ?STUDENT_ID,
                                     ?COURSE_ROOT_ID,
                                     ?STATUS,
                                     ?AC_YEAR,
                                     ?EXAM_SETTING_ID,
                                     ?SEMESTER
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegistrationIfNotCompulsory:
                    {
                        query = @"SELECT 
                                    CCR.COURSE_ROOT_ID AS 'COURSE_ID',
	                                CCR.COURSE_CODE, 
                                    UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE'
                                FROM
                                    ACADEMIC_CURRICULUM_?AC_YEAR AS AC 
		                                INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.PROGRAM_ID=AC.PROGRAMME
		                                INNER JOIN 
	                                CP_CLASS_COURSE_?AC_YEAR AS CCC ON CCC.CLASS_ID=SP.CLASS_ID
		                                INNER JOIN
	                                CP_COURSE_ROOT_?AC_YEAR AS CCR ON CCR.COURSE_ROOT_ID=CCC.COURSE_ID
                                    WHERE AC.COURSE_ID=?COURSE_ROOT_ID AND SP.STUDENT_ID=?STUDENT_ID group by CCR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchActiveSemesterWithBatches:
                    {

                        query = @"SELECT 
                                    Y.ACADEMIC_YEAR_ID,
                                    Y.AC_YEAR,
                                    S.SEMESTER,
                                    S.IS_ACTIVE,
                                    PROGRAMME_GROUP_ID AS PROGRAMME,
                                    S.BATCH
                                FROM
                                    ACADEMIC_SEMESTER S
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS B ON B.BATCH_ID = S.BATCH
                                        INNER JOIN
                                    ACADEMIC_YEAR AS Y ON Y.ACADEMIC_YEAR_ID =  B.ACADEMIC_YEAR_ID 
                                WHERE
                                    PROGRAMME_GROUP_ID = ?PROGRAMME
                                        AND S.IS_ACTIVE =1                                       
                                        AND S.BATCH = ?BATCH
                                        AND S.ACADEMIC_YEAR =?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchActiveSemesterWithBatchesForSupplementry:
                    {

                        query = @"SELECT 
                                    Y.ACADEMIC_YEAR_ID,
                                    Y.AC_YEAR,
                                    S.SEMESTER,
                                    S.IS_ACTIVE,
                                    PROGRAMME_GROUP_ID AS PROGRAMME,
                                    S.BATCH
                                FROM
                                    ACADEMIC_SEMESTER S
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS B ON B.BATCH_ID = S.BATCH
                                        INNER JOIN
                                    ACADEMIC_YEAR AS Y ON Y.ACADEMIC_YEAR_ID =  B.ACADEMIC_YEAR_ID  AND Y.ACTIVE_YEAR = 1
                                WHERE
                                    PROGRAMME_GROUP_ID = ?PROGRAMME                                                                                                                
                                        AND S.ACADEMIC_YEAR =?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterResult:
                    {
                        query = @"SELECT 
                                    CC.COURSE_ROOT_ID,
                                    CC.COURSE_CODE,
                                    UPPER(CC.COURSE_TITLE) AS 'COURSE_TITLE',
                                    IF(SM.RESULT !='F',IF(SM.RESULT!='A','PASS','AAA'),'A')AS RESULT,
                                    SM.STUDENT_ID,
                                    SM.SEMESTER AS WRITTEN_SEMESTER,
                                    CC.SEMESTER_ID AS SEMESTER ,CC.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID' , SS.SUBJECT_TYPE
                                FROM
                                    SEMESTER_MARKS_?AC_YEAR SM
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = SM.COURSE_ID
                                    LEFT JOIN SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CC.SUBJECT_TYPE AND SS.IS_DELETED!=1
                                        WHERE 
	                                SM.STUDENT_ID =?STUDENT_ID AND SEMESTER IN (?SEMESTER);";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterResultForSupplementryRegistration:
                    {
                        query = @"SELECT 
                                    CC.COURSE_ROOT_ID,
                                    CC.COURSE_CODE,
                                    UPPER(CC.COURSE_TITLE) AS 'COURSE_TITLE',
                                    IF(SM.RESULT !='F',IF(SM.RESULT!='A','PASS','AAA'),'A')AS RESULT,
                                    SM.STUDENT_ID,
                                    SM.SEMESTER AS WRITTEN_SEMESTER,
                                    CC.SEMESTER_ID AS SEMESTER ,CC.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID' , SS.SUBJECT_TYPE, CC.COURSE_TYPE
                                FROM
                                    SEMESTER_MARKS_?AC_YEAR SM
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = SM.COURSE_ID
                                    LEFT JOIN SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CC.SUBJECT_TYPE AND SS.IS_DELETED!=1
                                WHERE 
	                                SM.STUDENT_ID =?STUDENT_ID AND SEMESTER IN (?SEMESTER);";
                        break;
                    }
                case ExaminationSQLCommands.FetchProgram:
                    {
                        query = @"SELECT 
                                   PROGRAMME_ID, PROGRAMME_NAME
                               FROM
                                  CP_PROGRAMME_?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchBatch:
                    {
                        query = @"SELECT 
                                    B.BATCH_ID,
                                    B.BATCH
                                FROM
                                    ACADEMIC_CURRICULUM_?AC_YEAR AC 
                                    INNER JOIN SUP_BATCHES AS B ON B.BATCH_ID=AC.BATCH
                                    WHERE AC.PROGRAMME=?PROGRAMME GROUP BY BATCH;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseList:
                    {
                        query = @"SELECT 
                                        CS.COURSE_ID, UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE'
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CS
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CS.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CS.CLASS_ID
                                            INNER JOIN
                                        SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CS.SEMESTER_TYPE_ID
                                            AND ST.IS_ACTIVE = 1
                                    WHERE
                                        CS.CLASS_ID = ?CLASS_ID AND CS.STAFF_ID = ?STAFF_ID
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY COURSE_ID;";

                        break;
                    }

                case ExaminationSQLCommands.FetchCourseListByClass:
                    {
                        query = @"SELECT 
                                        CS.COURSE_ID, UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE'
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CS
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CS.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CS.CLASS_ID
                                            INNER JOIN
                                        SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CS.SEMESTER_TYPE_ID
                                            AND ST.IS_ACTIVE = 1
                                    WHERE
                                        CS.CLASS_ID = ?CLASS_ID 
                                            -- AND CS.STAFF_ID = ?STAFF_ID
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY COURSE_ID;";

                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByStaffId:
                    {

                        query = @"SELECT 
                                        COURSE_ROOT_ID,
                                        CLSCRSSTF_ID,
                                        concat( UPPER(CCR.COURSE_TITLE) ,' - ',ccr.COURSE_CODE)AS 'COURSE_TITLE'
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CCS
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CCS.CLASS_ID
                                            AND CLS.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                            INNER JOIN
                                        SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CCS.SEMESTER_TYPE_ID
                                            AND ST.IS_ACTIVE = 1
                                    WHERE
                                        CCS.STAFF_ID = ?STAFF_ID AND CLS.CLASS_ID = ?CLASS_ID
                                            AND CCS.IS_DELETED != 1
                                            AND CCR.IS_DELETED != 1
