                                    GROUP BY CCR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAInfoForRegularByClassAndCourseId:
                    {
                        query = @"SELECT 
                                        CIA.MARK_ID,
                                        CIA.COURSE_ROOT_ID,
                                        SP.STUDENT_ID,
                                        SCLS.CLASS_ID,
                                        CONCAT(IF(SP.FIRST_NAME IS NULL,
                                                    '',
                                                    SP.FIRST_NAME),
                                                ' ',
                                                IF(SP.LAST_NAME IS NULL,
                                                    ' ',
                                                    SP.LAST_NAME)) AS NAME,
                                        SP.REGISTER_NO,
                                        IF(CIA.CIA_C1 IS NULL, '', CIA.CIA_C1) CIA_C1,
                                        IF(CIA.CIA_C2 IS NULL, '', CIA.CIA_C2) CIA_C2,
                                        IF(CIA.CIA_C3 IS NULL, '', CIA.CIA_C3) CIA_C3,
                                        IF(CIA.CIA_C4 IS NULL, '', CIA.CIA_C4) CIA_C4,
                                        IF(CIA.CIA_C5 IS NULL, '', CIA.CIA_C5) CIA_C5,
                                        IF(CIA.CIA_C6 IS NULL, '', CIA.CIA_C6) CIA_C6,
                                        IF(CIA.CIA_C7 IS NULL, '', CIA.CIA_C7) CIA_C7,
                                        IF(CIA.CIA_C8 IS NULL, '', CIA.CIA_C8) CIA_C8,
                                        IF(CIA.CIA_TOTAL IS NULL,
                                            0,
                                            CIA.CIA_TOTAL) CIA_TOTAL
                                    FROM
                                        STU_PERSONAL_INFO AS SP
                                            LEFT JOIN
                                        CIA_MARKS_?AC_YEAR AS CIA ON CIA.STUDENT_ID = SP.STUDENT_ID
                                           AND
                                           CIA.COURSE_ROOT_ID=?COURSE_ID
                                            INNER JOIN
                                        STU_CLASS AS SCLS ON SCLS.STUDENT_ID = SP.STUDENT_ID                                         
                                    WHERE
                                        SCLS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SCLS.CLASS_ID = ?S_CLASS_ID ORDER BY REGISTER_NO;";

                        break;
                    }
                case ExaminationSQLCommands.FetchCIAInfoForSelectedByClassAndCourseId:
                    {
                        query = @"SELECT 
                                        CIA.MARK_ID,
                                        CIA.COURSE_ROOT_ID,
                                        SP.STUDENT_ID,
                                        SCLS.CLASS_ID,
                                        CONCAT(IF(SP.FIRST_NAME IS NULL,
                                                    '',
                                                    SP.FIRST_NAME),
                                                ' ',
                                                IF(SP.LAST_NAME IS NULL,
                                                    ' ',
                                                    SP.LAST_NAME)) AS NAME,
                                        SP.REGISTER_NO,
                                        IF(CIA.CIA_C1 IS NULL, 0, CIA.CIA_C1) CIA_C1,
                                        IF(CIA.CIA_C2 IS NULL, 0, CIA.CIA_C2) CIA_C2,
                                        IF(CIA.CIA_C3 IS NULL, 0, CIA.CIA_C3) CIA_C3,
                                        IF(CIA.CIA_C4 IS NULL, 0, CIA.CIA_C4) CIA_C4,
                                        IF(CIA.CIA_C5 IS NULL, 0, CIA.CIA_C5) CIA_C5,
                                        IF(CIA.CIA_C6 IS NULL, 0, CIA.CIA_C6) CIA_C6,
                                        IF(CIA.CIA_C7 IS NULL, 0, CIA.CIA_C7) CIA_C7,
                                        IF(CIA.CIA_C8 IS NULL, 0, CIA.CIA_C8) CIA_C8,
                                        IF(CIA.CIA_TOTAL IS NULL,
                                            0,
                                            CIA.CIA_TOTAL) CIA_TOTAL
                                    FROM
                                        STU_PERSONAL_INFO AS SP
                                            INNER JOIN
                                        CIA_MARKS_?AC_YEAR AS CIA ON CIA.STUDENT_ID = SP.STUDENT_ID
                                           AND
                                           CIA.COURSE_ROOT_ID=?COURSE_ID
                                            INNER JOIN
                                        STU_COURSE_INFO_?AC_YEAR AS SCLS ON SCLS.STUDENT_ID = SP.STUDENT_ID
                                    WHERE
                                        SCLS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SCLS.S_CLASS_ID =?S_CLASS_ID GROUP BY SCLS.STUDENT_ID;";

                        break;
                    }
                case ExaminationSQLCommands.FetchCIATotal:
                    {
                        query = @"SELECT 
                                    SUM(IFNULL(T.CUMULATIVE, 0)) AS TOTAL,
                                    T.STUDENT_ID,
                                    T.ADMISSION_NO,
                                    T.COURSE_ID,
                                    T.REGISTER_NO,
                                    T.COURSE_CODE,
                                    T.COURSE_TITLE,
                                    T.CLASS_NAME,
                                    T.CLASS_ID,
                                    UPPER(T.NAME) AS NAME
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN scc.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN scc.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            CGM.COURSE_ID,
                                            SP.REGISTER_NO,
                                            CCR.COURSE_CODE,
                                            CCR.COURSE_TITLE,
                                            Class.CLASS_NAME,
                                            Class.CLASS_ID,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS NAME
                                    FROM
                                        STU_CLASS AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN SUP_CIA_COMPONENTS AS scc ON scc.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.COURSE_ID = ?COURSE_ID
                                        AND CC.IS_DELETED != 1
                                 
                                     INNER JOIN
                                            CP_CLASSES AS Class ON Class.CLASS_ID = SC.CLASS_ID 
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID
                                            AND CGM.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID 

                                UNION 

                                SELECT 
                                    SUM(IFNULL(T.CUMULATIVE, 0)) AS TOTAL,
                                    T.STUDENT_ID,
                                    T.ADMISSION_NO,
                                    T.COURSE_ID,
                                    T.REGISTER_NO,
                                    T.COURSE_CODE,
                                    T.COURSE_TITLE,
                                    T.CLASS_NAME,
                                    T.CLASS_ID,
                                    UPPER(T.NAME) AS NAME
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN scc.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN scc.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            CGM.COURSE_ID,
                                            SP.REGISTER_NO,
                                            CCR.COURSE_CODE,
                                            CCR.COURSE_TITLE,
                                            Class.CLASS_NAME,
                                            Class.CLASS_ID,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS NAME
                                    FROM
                                        STU_COURSE_INFO AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    LEFT JOIN SUP_CIA_COMPONENTS AS scc ON scc.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
INNER JOIN
                                    STU_CLASS AS stu ON stu.STUDENT_ID = SP.STUDENT_ID AND stu.ACADEMIC_YEAR=?AC_YEAR
                                     INNER JOIN
                                            CP_CLASSES AS Class ON Class.CLASS_ID = stu.CLASS_ID 
                                    WHERE
                                        SC.S_CLASS_ID = ?CLASS_ID
                                            AND SC.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY ADMISSION_NO;";

