                case ExaminationSQLCommands.FetchCIATotalUsingStaffId:
                    {
                        query = @"SELECT
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,COURSE_ID,
                                    REGISTER_NO,COURSE_CODE,COURSE_TITLE,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                        ((SUM(IF(COURSE_GROUP_MARK = -1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,CGM.COURSE_ID,
                                            SP.REGISTER_NO,CCR.COURSE_CODE,CCR.COURSE_TITLE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_CLASS AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.COURSE_ID = ?COURSE_ID
                                        AND CC.IS_DELETED != 1
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID AND CGM.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                UNION SELECT
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,COURSE_ID,
                                    REGISTER_NO,COURSE_CODE,COURSE_TITLE,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                        ((SUM(IF(COURSE_GROUP_MARK = -1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,CGM.COURSE_ID,
                                            SP.REGISTER_NO,CCR.COURSE_CODE,CCR.COURSE_TITLE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_COURSE_INFO AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    WHERE
                                        SC.S_CLASS_ID = ?CLASS_ID 
                                             AND SC.COURSE_ID = ?COURSE_ID
                                           --  AND SC.STAFF_ID = ?STAFF_ID
                                             AND SC.ACADEMIC_YEAR=?AC_YEAR 
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_Empty_Marks:
                    {
                        query = @"SELECT 
                                '' AS CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) AS 'NAME',
                                SP.REGISTER_NO,
                                CCR.COURSE_ROOT_ID,
                                '' AS COURSE_GROUP_MARK
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASS_COURSE_?AC_YEAR AS CCC ON CCC.CLASS_ID = SC.CLASS_ID
                                    AND CCC.IS_DELETED != 1
                                    INNER JOIN
                                CP_COURSE_ROOT_?AC_YEAR AS CCR ON CCR.COURSE_ROOT_ID = CCC.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                            WHERE
                                SC.CLASS_ID = ?CLASS_ID
                                    AND CCR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1 
                            UNION SELECT 
                                '' AS CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) AS 'NAME',
                                SP.REGISTER_NO,
                                CCR.COURSE_ROOT_ID,
                                '' AS COURSE_GROUP_MARK
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_CLASS AS SCL ON SCL.STUDENT_ID = SC.STUDENT_ID
                                    AND SCL.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    AND SCL.IS_DELETED!=1
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SCL.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    INNER JOIN
                                CP_COURSE_ROOT_?AC_YEAR AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                            WHERE
                                SC.S_CLASS_ID = ?CLASS_ID AND SC.ACADEMIC_YEAR=?AC_YEAR
                                    AND CCR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND SC.IS_DELETED != 1
                            ORDER BY REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_Marks:
                    {
                        query = @"SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CG.MAX_MARK,
                                CG.ORDER_ID,
                                CG.CIA_GROUP_ID,
                                CGM.COURSE_GROUP_ID,
                                CG.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID,
                                CGC.STATUS
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CG ON CG.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CG.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CG.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID AND CC.COURSE_ID=?COURSE_ID AND CC.ACADEMIC_YEAR=?AC_YEAR

                            LEFT JOIN
                                    cia_group_mark_checking AS CGC ON CGC.COURSE_ID=CCR.COURSE_ROOT_ID
                                    AND CGC.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    AND CGC.STUDENT_ID=SC.STUDENT_ID
                                    AND CGC.SEMESTER_ID=CCR.SEMESTER_ID

                            WHERE
                                SC.CLASS_ID = ?CLASS_ID                                    
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1 
                            UNION SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                CGM.COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID,
                                CMC.STATUS
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID 
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1

                                    LEFT JOIN
                                    cia_group_mark_checking AS CMC ON CMC.COURSE_ID=CCR.COURSE_ROOT_ID
                                    AND CMC.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    AND CMC.STUDENT_ID=SC.STUDENT_ID
                                    AND CMC.SEMESTER_ID=SC.SEMESTER
                            WHERE
                                SC.S_CLASS_ID = ?CLASS_ID and SC.COURSE_ID=?COURSE_ID
                                    AND SC.IS_DELETED != 1 AND SC.ACADEMIC_YEAR=?AC_YEAR
                            ORDER BY ORDER_ID , REGISTER_NO;";
                        break;
                    }
