                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID AND CC.COURSE_ID= ?COURSE_ID AND CC.ACADEMIC_YEAR=?ACADEMIC_YEAR

                            LEFT JOIN
