                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                CGM.COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID,
                                CMC.STATUS
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?ACADEMIC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID =  ?COURSE_ID 
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1

                                    LEFT JOIN
                                    cia_group_mark_checking AS CMC ON CMC.COURSE_ID=CCR.COURSE_ROOT_ID
                                    AND CMC.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    AND CMC.STUDENT_ID=SC.STUDENT_ID
                                    AND CMC.SEMESTER_ID=SC.SEMESTER
                            WHERE
                                SC.S_CLASS_ID IN ( ?COURSE_ID) and SC.COURSE_ID= ?COURSE_ID
                                    AND SC.IS_DELETED != 1 AND SC.ACADEMIC_YEAR=?ACADEMIC_YERA GROUP BY SC.CLASS_ID
                            ORDER BY ORDER_ID , REGISTER_NO;";
                                
                               
                        break;
                    }

                // cia cumulative for coe
                case ExaminationSQLCommands.FetchCIA_MarksCoe:
                    {
                        query = @"SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CG.MAX_MARK,
                                CG.ORDER_ID,
                                CG.CIA_GROUP_ID,
                                CGM.COURSE_GROUP_ID,
                                CG.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID,
                                CGC.STATUS
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CG ON CG.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CG.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CG.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID AND CC.COURSE_ID=?COURSE_ID AND CC.ACADEMIC_YEAR=?AC_YEAR

                            LEFT JOIN
                                    cia_group_mark_checking AS CGC ON CGC.COURSE_ID=CCR.COURSE_ROOT_ID
                                    AND CGC.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    AND CGC.STUDENT_ID=SC.STUDENT_ID
                                    AND CGC.SEMESTER_ID=CCR.SEMESTER_ID

                            WHERE
                                SC.CLASS_ID = ?CLASS_ID                                    
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1 
                            UNION SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                CGM.COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID,
                                CMC.STATUS
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID 
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1

                                    LEFT JOIN
                                    cia_group_mark_checking AS CMC ON CMC.COURSE_ID=CCR.COURSE_ROOT_ID
                                    AND CMC.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    AND CMC.STUDENT_ID=SC.STUDENT_ID
                                    AND CMC.SEMESTER_ID=SC.SEMESTER
                            WHERE
                                SC.CLASS_ID = ?CLASS_ID and SC.COURSE_ID=?COURSE_ID
                                    AND SC.IS_DELETED != 1 AND SC.ACADEMIC_YEAR=?AC_YEAR
                            ORDER BY ORDER_ID , REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_MarksUsingStaffId:
                    {
                        query = @"SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CG.MAX_MARK,
                                CG.ORDER_ID,
                                CG.CIA_GROUP_ID,
                                COURSE_GROUP_ID,
                                CG.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CG ON CG.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CG.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CG.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID AND CC.COURSE_ID=?COURSE_ID AND CC.ACADEMIC_YEAR=?AC_YEAR
                            WHERE
                                SC.CLASS_ID = ?CLASS_ID                                    
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1 
                            UNION SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID 
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                            WHERE
                                SC.S_CLASS_ID = ?CLASS_ID 
                                    AND SC.COURSE_ID=?COURSE_ID
                                   -- AND SC.STAFF_ID=?STAFF_ID
                                    AND SC.IS_DELETED != 1 
                                    AND SC.ACADEMIC_YEAR=?AC_YEAR
                            ORDER BY ORDER_ID , REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoByClassAndCourseId:
                    {
                        query = @"SELECT 
                                    CR.COURSE_ROOT_ID,
                                    CONCAT(IF(UGC.UGC_COURSE_TYPE IS NULL,
                                                ' - ',
                                                UPPER(UGC.UGC_COURSE_TYPE)),
                                            '(',
                                            UPPER(CR.COURSE_TITLE),
                                            ')') AS 'COURSE_TITLE',
                                    CR.COURSE_CODE,
                                    CT.COURSE_TYPE_ID,
                                    CT.COURSE_TYPE,
                                    CLS.CLASS_NAME,
                                    CR.SEMESTER_ID,
                                    CLS.CLASS_ID,
                                    CLS.CLASS_TYPE
                                FROM
                                    CP_COURSE_ROOT AS CR
                                        JOIN
                                    CP_CLASSES AS CLS ON CR.COURSE_ROOT_ID = ?COURSE_ID
                                        AND CLS.CLASS_ID = ?CLASS_ID
                                        INNER JOIN
                                    CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                        LEFT JOIN
                                    CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                WHERE
                                    CR.IS_DELETED != 1
                                        AND CLS.IS_DELETED != 1 AND CT.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByClassAndCourseId:
                    {
                        query = @"SELECT 
                                    CR.COURSE_ROOT_ID,
                                    CONCAT(IF(UGC.UGC_COURSE_TYPE IS NULL,
                                                ' - ',
                                                UPPER(UGC.UGC_COURSE_TYPE)),
                                            '(',
                                            UPPER(CR.COURSE_TITLE),
                                            ')') AS 'COURSE_TITLE',
                                    CR.COURSE_CODE,
                                    CT.COURSE_TYPE_ID,
                                    CT.COURSE_TYPE,
                                    CLS.CLASS_NAME,
                                    CR.SEMESTER_ID,
                                    CLS.CLASS_ID,
                                    CLS.CLASS_TYPE
                                FROM
                                    CP_COURSE_ROOT AS CR
                                        JOIN
                                    CP_CLASSES AS CLS ON CR.COURSE_ROOT_ID = ?COURSE_ID
                                        AND CLS.CLASS_ID IN (?CLASS_ID)
                                        INNER JOIN
                                    CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                        LEFT JOIN
                                    CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                WHERE
                                    CR.IS_DELETED != 1
                                        AND CLS.IS_DELETED != 1 AND CT.IS_DELETED!=1
                                    GROUP BY CLS.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseComponentByCourseTypeId:
                    {
                        query = @"SELECT 
                                    GC.CIA_GROUP_COMPONENT_ID,
                                    GC.MAX_MARK,
                                    SCC.COMPONENT,
                                    CG.COURSE_TYPE_ID,
                                    CG.GROUP_MARK,
                                    GC.CIA_GROUP_ID,
                                    GC.ORDER_ID,
                                    DATE_FORMAT(TS.LAST_DATE, '%d/%m/%Y') AS 'LAST_DATE',
                                    IF(TS.LAST_DATE < CURDATE(),'1','0')AS 'VALIDATE'
                                FROM
                                    CIA_GROUP_COMPONENT AS GC
                                        INNER JOIN
                                    CP_COURSE_TYPE_GROUP CG ON CG.GROUP_ID = GC.CIA_GROUP_ID
                                        INNER JOIN
                                    SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = GC.SUP_CIA_COMPONENT_ID
                                        LEFT JOIN
                                    SUP_TASK_SETTING AS TS ON TS.COMPONENT_ID = SCC.COMPONENT_ID
                                        AND TS.IS_DELETED != 1
                                        AND SEMESTER = ?SEMESTER
                                        AND TS.ACADEMIC_YEAR = ?AC_YEAR
                                WHERE
                                    CG.COURSE_TYPE_ID = ?COURSE_TYPE_ID and GC.IS_DELETED != 1 ORDER BY GC.ORDER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseComponentByCourseGroupId:
                    {
                        query = @"SELECT 
                                    GC.CIA_GROUP_COMPONENT_ID,
                                    GC.MAX_MARK,
                                    SCC.COMPONENT,
                                    CG.COURSE_TYPE_ID,
                                    CG.GROUP_MARK,
                                    GC.CIA_GROUP_ID,
                                    GC.ORDER_ID,
                                    DATE_FORMAT(TS.LAST_DATE, '%d/%m/%Y') AS 'LAST_DATE',
                                    IF(TS.LAST_DATE < CURDATE(),'1','0')AS 'VALIDATE'
                                FROM
                                    CIA_GROUP_COMPONENT AS GC
                                        INNER JOIN
                                    CP_COURSE_TYPE_GROUP CG ON CG.GROUP_ID = GC.CIA_GROUP_ID
                                        INNER JOIN
                                    SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = GC.SUP_CIA_COMPONENT_ID
                                        LEFT JOIN
                                    SUP_TASK_SETTING AS TS ON TS.COMPONENT_ID = SCC.COMPONENT_ID
                                        AND TS.IS_DELETED != 1
                                        AND SEMESTER = ?SEMESTER
                                        AND TS.ACADEMIC_YEAR = ?AC_YEAR
                                WHERE
                                    GC.CIA_GROUP_COMPONENT_ID = ?COURSE_GROUP_ID ORDER BY GC.ORDER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassList:
                    {
                        query = @"SELECT 
                                        CS.CLASS_ID,
                                        CLS.CLASS_NAME,
                                        CLS.PROGRAMME_GROUP_ID,
                                        CLS.CLASS_LEVEL,
                                        CLS.SHIFT,
                                        CLS.PROGRAMME_MODE,
                                        CLS.DEPARTMENT
                                    FROM
