                case ExaminationSQLCommands.FetchCourseAndClassByClassAndCourseId:
                    {

                        query = @"SELECT 
                                    DP.DEPARTMENT,
                                    CLS.CLASS_ID,
                                    CLS.CLASS_NAME,
                                    CR.COURSE_CODE,
                                    CR.SEMESTER_ID,
                                    UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE',
