                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegistrationList:
                    {
                        query = @"SELECT 
                                    EXR.REGISTRATION_ID,
                                    SP.STUDENT_ID,
                                    SP.ROLL_NO,
                                    SP.ADMISSION_NO,
                                    SP.REGISTER_NO,
                                    UPPER(CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                            IFNULL(SP.LAST_NAME, ''))) AS FIRST_NAME,
                                            C.CLASS_NAME,
                                    EXR.COURSE_ID,
                                    UPPER(CONCAT(IFNULL( CR.COURSE_TITLE , ''),
                                            ' - ',
                                            IFNULL(CR.COURSE_CODE, ''))) AS COURSE_TITLE,
	                                EXR.STATUS
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS EXR
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = EXR.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EXR.COURSE_ID
		                                 INNER JOIN
	                                CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
                                WHERE
                                    EXR.EXAM_SETTING_ID IN (SELECT 
                                            EXAM_SETTING_ID
                                        FROM
                                            EXAM_SETTING
                                        WHERE
                                            IS_ACTIVE = 1 AND ACADEMIC_YEAR = ?AC_YEAR) ORDER BY C.CLASS_ID,SC.STUDENT_ID,CR.PART,EXR.STATUS;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegistrationListBySettingId:
                    {
                        query = @"SELECT 
                                    EXR.REGISTRATION_ID,
                                    SP.STUDENT_ID,
                                    CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                            IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                    EXR.COURSE_ID,
                                    EXR.STATUS,
                                    CONCAT(IFNULL(CR.COURSE_CODE, ''),
                                            '(',
                                            IFNULL(UPPER(CR.COURSE_TITLE), ''),
                                            ')') AS COURSE_TITLE
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS EXR
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = EXR.STUDENT_ID AND SC.ACADEMIC_YEAR=?AC_YEAR
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EXR.COURSE_ID WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID AND EXR.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.ListExamRegisteredStudentCount:
                    {
                        query = @"SELECT 
                                        CR.COURSE_CODE, CR.COURSE_TITLE, COUNT(ER.STUDENT_ID) AS TOTAL_COUNT,ES.EXAM_NAME
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                   WHERE ER.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                    GROUP BY ER.COURSE_ID ORDER BY CR.SEMESTER_ID,CR.UGC_COURSE_TYPE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearExamRegisteredStudent:
                    {
                        query = @"SELECT 
                                        CLS.CLASS_NAME,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                       UPPER(CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                IFNULL(SP.LAST_NAME, ''))) AS FIRST_NAME,
                                        CR.COURSE_CODE,
                                        CR.COURSE_TITLE
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                            AND SC.IS_DELETED!=1 AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = SC.CLASS_ID
                                    WHERE
                                        CLS.CLASS_ID IN (?CLASS_ID)
                                            AND ER.STATUS != 'R' AND ER.EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchRegularExamRegisteredStudent:
                    {
                        query = @"SELECT 
                                        CLS.CLASS_NAME,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                        CR.COURSE_CODE,
                                        CR.COURSE_TITLE
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR AND SC.IS_DELETED!=1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = SC.CLASS_ID
                                    WHERE
                                        CLS.CLASS_ID IN (?CLASS_ID)
                                            AND ER.STATUS = 'R' AND ER.EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchHallTicketValidationByStudentId:
                    {
                        query = @"SELECT 
                                        HALL_TICKET_VALIDATION_ID, 
                                        SP.STUDENT_ID, 
                                        REASON
                                    FROM
                                        HALL_TICKET_VALIDATION AS HT
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = HT.STUDENT_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            INNER JOIN
                                        EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PT.ACADEMIC_YEAR = HT.ACADEMIC_YEAR
                                    WHERE
                                        HT.STUDENT_ID = ?STUDENT_ID
                                            AND HT.ACADEMIC_YEAR = ?AC_YEAR
                                            AND HT.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                            AND HT.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByClassId:
                    {
                        query = @"SELECT 
                                    CR.COURSE_ROOT_ID,
                                    UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE',
                                    CR.SEMESTER_ID,
                                    CR.COURSE_TYPE AS COURSE_TYPE_ID
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CC
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CC.COURSE_ID
                                        INNER JOIN
                                    CP_CLASSES AS CLS ON CLS.CLASS_ID = CC.CLASS_ID
                                        INNER JOIN
                                    SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CC.SEMESTER_TYPE_ID
                                        AND ST.IS_ACTIVE = 1
                                WHERE
                                    CC.CLASS_ID = ?CLASS_ID AND CC.IS_DELETED != 1
                                        AND CC.ACADEMIC_YEAR = ?AC_YEAR
                                GROUP BY CR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.Fetch_CIA_Is_Exist:
                    {
                        query = @"SELECT 
                                        UPLOAD_ID 
                                  FROM CIA_STATUS WHERE STAFF_ID=?STAFF_ID
                                  AND CLASS_ID=?CLASS_ID 
                                  AND COURSE_ID=?COURSE_ID 
                                  AND ACADEMIC_YEAR=?AC_YEAR 
                                  AND SEMESTER_ID=?SEMESTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCiaMarkByComponent:
                    {
                        query = @"SELECT 
                                    CG.STUDENT_ID
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    CIA_GROUP_MARKS_?AC_YEAR AS CG ON CG.STUDENT_ID = SC.STUDENT_ID
                                        INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CS ON CS.COURSE_ID = CG.COURSE_ID
                                        AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CS.IS_DELETED != 1
                                WHERE
                                    CG.COURSE_ID = ?COURSE_ID AND SC.CLASS_ID = ?CLASS_ID
                                        AND CS.STAFF_ID = ?STAFF_ID
                                        AND CG.COURSE_GROUP_ID = ?COURSE_GROUP_ID
                                        AND CG.SEMESTER_ID = ?SEMESTER_ID
                                        AND CG.COURSE_GROUP_MARK != 0
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                GROUP BY CG.STUDENT_ID 
                                UNION SELECT 
                                    SC.STUDENT_ID
                                FROM
                                    STU_COURSE_INFO AS SC
                                        INNER JOIN
                                    CIA_GROUP_MARKS_?AC_YEAR AS CG ON CG.STUDENT_ID = SC.STUDENT_ID
                                        INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CCS ON CCS.COURSE_ID = CG.COURSE_ID
                                        AND CCS.IS_DELETED != 1
                                WHERE
                                    SC.S_CLASS_ID = ?CLASS_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CCS.STAFF_ID = ?STAFF_ID
                                        AND CG.COURSE_ID = ?COURSE_ID 
                                        AND CG.COURSE_GROUP_ID = ?COURSE_GROUP_ID
                                        AND CG.SEMESTER_ID = ?SEMESTER_ID
                                        AND CG.COURSE_GROUP_MARK != 0
                                GROUP BY SC.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentByCourseIdAndClassId:
                    {
                        query = @"SELECT 
                                         CLS.STUDENT_ID, SP.RFID,SP.ROLL_NO,SP.REGISTER_NO,CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                            ' ',IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,RFID
                                    FROM
                                        STU_CLASS AS CLS
                                            INNER JOIN
                                        CP_CLASS_COURSE AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                            AND CC.COURSE_ID = ?COURSE_ID
                                            AND CC.IS_DELETED != 1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    WHERE
                                        CLS.CLASS_ID = ?CLASS_ID
                                            AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CLS.IS_DELETED != 1 
                                    UNION SELECT 
                                         CLS.STUDENT_ID, SP.RFID,SP.ROLL_NO,SP.REGISTER_NO,CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                            ' ',IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,RFID
                                    FROM
                                        STU_COURSE_INFO AS CLS
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    WHERE
                                        CLS.S_CLASS_ID = ?CLASS_ID AND CLS.COURSE_ID = ?COURSE_ID
                                            AND CLS.IS_DELETED != 1
                                            AND CLS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterMarksByClassId:
                    {
                        query = @"";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalCourses:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                    CCR.IS_COMPULSORY,
                                    SC.S_CLASS_ID AS CLASS_ID,
                                    CCR.PART,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    SC.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    STU_COURSE_INFO AS SC
                                        INNER JOIN
                                    STU_CLASS AS S ON S.STUDENT_ID = SC.STUDENT_ID
                                        AND S.IS_DELETED != 1
                                        AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID AND C.IS_DELETED != 1
										INNER JOIN
									ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
									AND AB.ACADEMIC_YEAR_ID = (SELECT 
										ACADEMIC_YEAR_ID
									FROM
										ACADEMIC_YEAR
									WHERE
										AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS SEM ON SEM.SEMESTER = CCR.SEMESTER_ID
                                        AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND SEM.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND SEM.BATCH = AB.BATCH_ID
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    SC.STUDENT_ID = ?STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SEM.IS_ACTIVE = 1
                                        AND CCR.IS_DELETED != 1
                                        AND SC.IS_DELETED != 1 ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalCoursesForQuiz:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE',
                                        CCR.COURSE_TYPE,
                                        CCR.IS_COMPULSORY,
                                        SC.S_CLASS_ID AS CLASS_ID,
                                        CCR.PART,
                                        CCR.SEMESTER_ID,
                                        CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                        SS.SUBJECT_TYPE,
                                        SC.ACADEMIC_YEAR AS 'AC_YEAR',
                                        CCR.COURSE_ORDER
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                            INNER JOIN
                                        SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                            AND SS.IS_DELETED != 1
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCR.IS_DELETED != 1
                                            AND SC.IS_DELETED != 1
                                    ORDER BY CCR.PART , CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalCoursesForFeedBackEntry:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    CONCAT(UPPER(CCR.COURSE_TITLE),' (',CCR.COURSE_CODE,')') AS 'COURSE_TITLE',
                                    CCR.IS_COMPULSORY,
                                    SC.S_CLASS_ID AS CLASS_ID,
                                    CCR.PART,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    SC.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    STU_COURSE_INFO AS SC
                                        INNER JOIN
                                    STU_CLASS AS S ON S.STUDENT_ID = SC.STUDENT_ID
                                        AND S.IS_DELETED != 1
                                        AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID AND C.IS_DELETED != 1
										INNER JOIN
									ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
									AND AB.ACADEMIC_YEAR_ID = (SELECT 
										ACADEMIC_YEAR_ID
									FROM
										ACADEMIC_YEAR
									WHERE
										AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS SEM ON SEM.SEMESTER = CCR.SEMESTER_ID
                                        AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND SEM.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND SEM.BATCH = AB.BATCH_ID
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    SC.STUDENT_ID = ?STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SEM.IS_ACTIVE = 1
                                        AND CCR.IS_DELETED != 1
                                        AND SC.IS_DELETED != 1 ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalCourses1:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                    CCR.IS_COMPULSORY,
                                    SC.S_CLASS_ID AS CLASS_ID,
                                    CCR.PART,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    SC.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    STU_COURSE_INFO AS SC
                                        INNER JOIN
                                    STU_CLASS AS S ON S.STUDENT_ID = SC.STUDENT_ID
                                        AND S.IS_DELETED != 1
                                        AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID AND C.IS_DELETED != 1
										INNER JOIN
									ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
									AND AB.ACADEMIC_YEAR_ID = (SELECT 
										ACADEMIC_YEAR_ID
									FROM
										ACADEMIC_YEAR
									WHERE
										AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS SEM ON SEM.SEMESTER = CCR.SEMESTER_ID
                                        AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND SEM.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND SEM.BATCH = AB.BATCH_ID
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    SC.CLASS_ID = ?CLASS_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SEM.IS_ACTIVE = 1
                                        AND CCR.IS_DELETED != 1
                                        AND SC.IS_DELETED != 1 ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterAndCreditByCourseId:
                    {
                        query = @"SELECT 
                                        SEMESTER_ID AS SEMESTER, CREDITS AS CREDIT
                                    FROM
                                        CP_COURSE_ROOT
                                    WHERE
                                        COURSE_ROOT_ID = ?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveSemesterMarks:
                    {
                        query = @"INSERT INTO SEMESTER_MARKS
                                            (
                                            STUDENT_ID,
                                            COURSE_ID,
                                            CREDIT,
                                            APPLIED,
                                            SEMESTER,
                                            ACADEMIC_YEAR,
                                            M_PASS,
                                            IS_ARREAR,
                                            EXAM_SETTING_ID)
                                            VALUES
                                            (
                                            ?STUDENT_ID,
                                            ?COURSE_ID,
                                            ?CREDIT,
                                            ?APPLIED,
                                            ?SEMESTER,
                                            ?AC_YEAR,
                                            'Y',
                                            ?IS_ARREAR,
                                            ?EXAM_SETTING_ID);";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamRegistrationById:
                    {
                        query = @"UPDATE EXAM_REGISTRATION_?AC_YEAR
                                        SET
                                        IS_DELETED=1
                                        WHERE REGISTRATION_ID=?REGISTRATION_ID";
                        break;
                    }
                #region Match The Following


                case ExaminationSQLCommands.SaveMathTheFollowingQuestions:
                    {
                        query = @"INSERT INTO QUIZ_MATCH_THE_FOLLOWING_QUESTIONS
                                (
                                    ENTRY_ID,
                                    CLASS_ID,
                                    COURSE_ID,
                                    QUESTION,
                                    MARK,
                                    QUESTION_TYPE,
                                    SET_ID,
                                    ACADEMIC_YEAR,
                                    SEMESTER_ID,
                                    SETTING_ID
                                )
                                VALUES
                                (
                                    ?ENTRY_ID,
                                    ?CLASS_ID,
                                    ?COURSE_ID,
                                    ?QUESTION,
                                    ?MARK,
                                    ?QUESTION_TYPE,
                                    ?SET_ID,
                                    ?AC_YEAR,
                                    ?SEMESTER_ID,
                                    ?SETTING_ID
                                );";
                        break;
                    }
                case ExaminationSQLCommands.SaveMathTheFollowingOptions:
                    {
                        query = @"INSERT INTO QUIZ_MATCH_THE_FOLLOWING_OPTIONS
                                (
                                    QUESTION,
                                    ANSWER,
                                    QUIZ_ID,
                                    SET_ID,
                                    ACADEMIC_YEAR,
                                    SEMESTER_ID
                                )
                                VALUES
                                (
                                   ?QUESTION,
                                   ?ANSWER,
                                   ?QUIZ_ID,
                                   ?SET_ID,
                                   ?AC_YEAR,
                                   ?SEMESTER_ID
                                );";
