                    }
                case ExaminationSQLCommands.UpdateMathTheFollowingQuestions:
                    {
                        query = @"UPDATE QUIZ_MATCH_THE_FOLLOWING_QUESTIONS SET QUESTION=?QUESTION,MARK=?MARK WHERE QUIZ_ID=?QUIZ_ID;";
