                    }
                case ExaminationSQLCommands.UpdateMathTheFollowingOptions:
                    {
                        query = @"UPDATE QUIZ_MATCH_THE_FOLLOWING_OPTIONS SET QUESTION=?QUESTION ,ANSWER=?ANSWER WHERE OPTION_ID=?OPTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizQuestionByQuizId:
                    {
                        query = @"SELECT 
                                    QUIZ_ID,
                                    ENTRY_ID,
                                    CLASS_ID,
                                    COURSE_ID,
                                    QUESTION,
                                    SET_ID,
                                    SEMESTER_ID
                                FROM
                                    QUIZ_MATCH_THE_FOLLOWING_QUESTIONS
                                WHERE
                                    QUIZ_ID = ?QUIZ_ID;";
