                    }
                case ExaminationSQLCommands.ListMathTheFollowingQuiz:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        C.CLASS_NAME AS 'CLASS_ID',
                                        UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                        ' ',
                                                        IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                        SS.SEMESTER_NAME AS 'SEMESTER_ID',
                                        QQ.QUESTION,
                                        IFNULL(QQ.MARK,0) AS MARK,
                                        SE.SET_NAME AS 'SET_ID',
                                        QT.QUESTION_TYPE,
                                        QT.QUESTION_TYPE_ID
                                    FROM
                                        QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = QQ.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = QQ.SEMESTER_ID
                                            LEFT JOIN
                                        SUP_SETS AS SE ON SE.SET_ID = QQ.SET_ID
                                            INNER JOIN
                                        ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QQ.ACADEMIC_YEAR
                                            INNER JOIN
	                                    SUP_QUIZ_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID=QQ.QUESTION_TYPE 
                                    WHERE
                                        QQ.ACADEMIC_YEAR = ?AC_YEAR
                                            AND QQ.SETTING_ID IN (?SETTING_ID)
                                            AND QQ.ENTRY_ID = ?ENTRY_ID
                                            AND QQ.IS_DELETED != 1;";

                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingQuizById:
                    {
                        query = @"SELECT 
                                        QP.OPTION_ID, 
                                        QP.QUESTION, 
                                        QP.ANSWER
                                    FROM
                                        QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS QP
                                    WHERE
                                        QP.QUIZ_ID = ?QUIZ_ID AND QP.IS_DELETED!=1;";
                        break;
                    }

                case ExaminationSQLCommands.DeleteMatchTheFollowingQuestion:
                    {
                        query = @"UPDATE QUIZ_MATCH_THE_FOLLOWING_QUESTIONS SET IS_DELETED=1 WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteMatchTheFollowingOption:
                    {
                        query = @"UPDATE QUIZ_MATCH_THE_FOLLOWING_OPTIONS SET IS_DELETED=1 WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }

                //Objective Type Delete .
                case ExaminationSQLCommands.DeleteObjectiveQuizQuestion:
                    {
                        query = @"UPDATE QUIZ_OBJECTIVE_QUESTIONS SET IS_DELETED=1 WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteObjectiveQuizOption:
                    {
                        query = @"UPDATE QUIZ_OBJECTIVE_OPTIONS SET IS_DELETED=1 WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }

                // Fill In The Blank Delete ..
                case ExaminationSQLCommands.DeleteFillInTheBlanksQuestion:
                    {
                        query = @"UPDATE QUIZ_FILL_IN_BLANK_QUESTIONS SET IS_DELETED=1 WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteFillInTheBlanksOption:
                    {
                        query = @"UPDATE QUIZ_FILL_IN_BLANK_OPTIONS SET IS_DELETED=1 WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                #endregion

                #region CIA Marks For COE
                case ExaminationSQLCommands.FetchClass_Course_StaffByProgrammeGroupId:
                    {
                        query = @"SELECT 
                                    CCP.COURSE_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    S.SEMESTER_NAME,
                                    C.CLASS_NAME,
                                    CCP.PROGRAMME_GROUP_ID,
                                    GROUP_CONCAT(DISTINCT IFNULL(SP.FIRST_NAME,''),' ', IFNULL(SP.LAST_NAME,'')) AS 'NAME',
                                    D.DEPARTMENT,
                                    CT.INTERNAL
                                FROM
                                    CP_COURSE_PATTERN AS CCP
										INNER JOIN
	                                CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID=CCP.PROGRAMME_GROUP_ID
		                                INNER JOIN
	                                CP_CLASS_COURSE_STAFF AS CCS ON CCS.COURSE_ID=CCP.COURSE_ID
		                                AND CCS.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
		                                -- AND CCS.CLASS_ID=C.CLASS_ID
		                                INNER JOIN
	                                STF_PERSONAL_INFO AS SP ON SP.STAFF_ID=CCS.STAFF_ID
		                                AND SP.IS_DELETED!=1
                                        AND SP.IS_LEFT!=1
										INNER JOIN
									CP_DEPARTMENT AS D ON D.DEPARTMENT_ID=C.DEPARTMENT
										INNER JOIN
									ACADEMIC_BATCHES AS B ON B.BATCH_YEAR=C.CLASS_YEAR
										AND B.ACADEMIC_YEAR_ID=(SELECT ACADEMIC_YEAR_ID FROM ACADEMIC_YEAR WHERE AC_YEAR=?AC_YEAR)
										INNER JOIN
									ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID=CCP.PROGRAMME_GROUP_ID
										AND SEM.BATCH=B.BATCH_ID
                                        AND SEM.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
                                        AND SEM.IS_DELETED!=1
                                        INNER JOIN
	                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=CCP.COURSE_ID
										AND CCR.SEMESTER_ID=SEM.SEMESTER
                                        INNER JOIN
	                                SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID=CCR.SEMESTER_ID
										INNER JOIN
									CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID=CCR.COURSE_TYPE
                                WHERE
                                    CCP.PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
										AND SEM.IS_ACTIVE=1
		                                AND C.CLASS_YEAR=?CLASS_YEAR
                                      --  AND CCR.COURSE_TYPE!=29
                                        AND CCP.IS_DELETED != 1
                                        AND CCS.IS_DELETED!=1
                                        AND CCP.COURSE_ID != ''
                                        AND CCP.ACADEMIC_YEAR = ?AC_YEAR GROUP BY CCP.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.BindCIAMarksForCOE:
                    {
                        query = @"SELECT 
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
                                    PROGRAMME_GROUP_ID,
                                    UPPER(NAME) AS 'NAME',
                                    COURSE_ID
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN CIA.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN CIA.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO,
                                            SP.REGISTER_NO,
                                            CCP.PROGRAMME_GROUP_ID,
                                            CCP.COURSE_ID,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                    INNER JOIN CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                    INNER JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                        AND CCR.IS_COMPULSORY = 1
                                    INNER JOIN CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                    INNER JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
                                    INNER JOIN SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    INNER JOIN STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                        AND SC.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = CCP.COURSE_ID
                                        AND CGM.COURSE_GROUP_ID = CGC.CIA_GROUP_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    WHERE
                                        C.CLASS_YEAR = ?CLASS_YEAR
                                            AND CCP.PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
                                            AND CCP.COURSE_ID IN (?COURSE_ID)
                                            AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            AND SP.IS_DELETED != 1
                                    GROUP BY SP.STUDENT_ID , CCP.COURSE_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID , COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.BindOptionalCourseCIAMarksForCOE:
                    {
                        query = @"SELECT 
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,
                                    REGISTER_NO,
                                    PROGRAMME_GROUP_ID,
                                    COURSE_ID,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT 
                                       (SUM(
                                            CASE
                                                WHEN CIA.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN CIA.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            CCP.PROGRAMME_GROUP_ID,
                                            CCP.COURSE_ID,
                                            SP.REGISTER_NO,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                    INNER JOIN STU_COURSE_INFO AS SC ON SC.COURSE_ID = CCP.COURSE_ID
                                    INNER JOIN CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID=CCP.PROGRAMME_GROUP_ID AND C.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                            left JOIN SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID

                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    WHERE
                                              CCP.COURSE_ID = ?COURSE_ID
										   AND C.CLASS_YEAR=?CLASS_YEAR
										  AND CCP.PROGRAMME_GROUP_ID=?PROGRAMME_GROUP_ID
										  AND SC.ACADEMIC_YEAR = ?AC_YEAR
										  AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY REGISTER_NO;";
                        //query = @"SELECT 
                        //            SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                        //            STUDENT_ID,
                        //            ADMISSION_NO,
                        //            REGISTER_NO,
                        //            PROGRAMME_GROUP_ID,
                        //            COURSE_ID,
                        //            UPPER(NAME) AS 'NAME'
                        //        FROM
                        //            (SELECT 
                        //                ((SUM(IF(COURSE_GROUP_MARK = - 1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT 
                        //                            GROUP_MARK
                        //                        FROM
                        //                            CP_COURSE_TYPE_GROUP AS CTG
                        //                        WHERE
                        //                            CTG.GROUP_ID = CGC.CIA_GROUP_ID
                        //                        LIMIT 1)) AS CUMULATIVE,
                        //                    SP.STUDENT_ID,
                        //                    SP.ROLL_NO AS ADMISSION_NO,
                        //                    CCP.PROGRAMME_GROUP_ID,
                        //                    CCP.COURSE_ID,
                        //                    SP.REGISTER_NO,
                        //                    CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                        //            FROM
                        //                CP_COURSE_PATTERN AS CCP
                        //            INNER JOIN STU_COURSE_INFO AS SC ON SC.COURSE_ID = CCP.COURSE_ID
                        //            INNER JOIN CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID=CCP.PROGRAMME_GROUP_ID AND C.CLASS_ID = SC.CLASS_ID
                        //            INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                        //                AND SP.IS_LEFT != 1
                        //                AND SP.IS_DELETED != 1
                        //            LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                        //                AND SC.COURSE_ID = CGM.COURSE_ID
                        //            LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                        //                AND CGC.IS_DELETED != 1
                        //            LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                        //                AND CCR.IS_DELETED != 1
                        //            WHERE
                        //                CCP.COURSE_ID = ?COURSE_ID
                        //           AND C.CLASS_YEAR=?CLASS_YEAR
                        //           AND CCP.PROGRAMME_GROUP_ID=?PROGRAMME_GROUP_ID
                        //                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                        //                    AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                        //                    AND SC.IS_DELETED != 1
                        //                    AND CCP.IS_DELETED != 1
                        //                    AND SP.IS_LEFT != 1
