                #endregion

                #region Exam TimeTable
                case ExaminationSQLCommands.FetchPaperCodesForExam:
                    {
                        query = @"SELECT 
                                        TT.COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        ES.EXAM_SESSION AS EXAM_TIME,
                                        UPPER(CONCAT(SE.EXAM_NAME, '-', SE.ACADEMIC_YEAR)) AS EXAM_NAME
                                    FROM
                                        CIA_EXAM_TIMETABLE AS TT
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = TT.COURSE_ID
		                                    AND CCR.IS_DELETED!=1
                                            INNER JOIN
                                        SUP_EXAM_SESSION AS ES ON ES.EXAM_SESSION_ID = TT.EXAM_SESSION_ID
		                                    AND ES.IS_DELETED!=1
                                            INNER JOIN
                                        CIA_EXAM_SETTING AS SE ON SE.EXAM_SETTING_ID = TT.EXAM_SETTING_ID
                                            AND SE.IS_DELETED != 1
                                            AND SE.ACADEMIC_YEAR = TT.ACADEMIC_YEAR
                                    WHERE
                                        TT.IS_DELETED != 1
                                            AND TT.ACADEMIC_YEAR = ?AC_YEAR;";
                        //query = @"SELECT 
                        //                ET.TIMETABLE_ID,
                        //                ER.COURSE_ID,
                        //                CCR.COURSE_CODE,
                        //                CCR.COURSE_TITLE,
                        //                IFNULL(ET.IS_ADVANCE,'0') As IS_ADVANCE,
                        //                IFNULL(ET.IS_POSTPONED,'0') AS IS_POSTPONED,
                        //                IF(ET.IS_ADVANCE = '1',
                        //                    DATE_FORMAT(ET.ADVANCE_DATE, '%d/%m/%Y'),
                        //                    IF(ET.IS_POSTPONED = '1',
                        //                        DATE_FORMAT(ET.POSTPONED_DATE, '%d/%m/%Y'),
                        //                        DATE_FORMAT(ET.EXAM_DATE, '%d/%m/%Y'))) AS EXAM_DATE,
                        //                IF(ET.IS_ADVANCE = '1',
                        //                    ET.ADVANCE_TIME,
                        //                    IF(ET.IS_POSTPONED = '1',
                        //                        ET.POSTPONED_TIME,
                        //                        ET.EXAM_TIME)) AS EXAM_TIME
                        //            FROM
                        //                EXAM_REGISTRATION_?AC_YEAR AS ER
                        //                    LEFT JOIN
                        //                EXAM_TIMETABLE AS ET ON ET.COURSE_ID = ER.COURSE_ID
                        //                    AND ET.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                        //                    AND ET.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                        //                    INNER JOIN
                        //             CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=ER.COURSE_ID
                        //            WHERE
                        //                ER.ACADEMIC_YEAR = ?AC_YEAR AND ET.IS_DELETED!=1
                        //                    AND ER.EXAM_SETTING_ID = (SELECT 
                        //                        EXAM_SETTING_ID
                        //                    FROM
                        //                        EXAM_SETTING
                        //                    WHERE
                        //                        IS_ACTIVE = 1) GROUP BY CCR.COURSE_CODE;";
                        break;
                    }
                case ExaminationSQLCommands.BindExamTimeTable:
                    {
                        query = @"SELECT 
                                    ET.TIMETABLE_ID,
                                    CCP.COURSE_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    DATE_FORMAT(ET.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                    ES.EXAM_SESSION,
                                    UPPER(CONCAT(CY.CLASS_YEAR,
                                            ' - ',
                                            P.PROGRAMME_NAME,'  ',SPM.PROGRAMME_MODE,' ( SHIFT - ',SS.SHIFT_NAME,' ) ')) AS PROGRAMME_NAME,
                                    CCS.PROGRAMME_YEAR,
                                    PL.PROGRAMME_LEVEL,
                                    SST.SUBJECT_TYPE
                                FROM
                                    CP_COURSE_PATTERN AS CCP
                                        INNER JOIN
                                    CP_COURSE_STRUCTURE AS CCS ON CCS.COURSE_STRUCTURE_ID = CCP.COURSE_STRUCTURE_ID
                                        AND CCS.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        INNER JOIN
                                    CIA_EXAM_PROGRAMME_TYPE_SETTING AS ST ON ST.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                        AND ST.ACADEMIC_YEAR =  CCP.ACADEMIC_YEAR
                                        INNER JOIN
                                    CIA_EXAM_TIMETABLE AS ET ON ET.COURSE_ID = CCP.COURSE_ID
                                        AND ET.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                        AND ET.EXAM_SETTING_ID = ST.EXAM_SETTING_ID
                                        AND ET.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_EXAM_SESSION AS ES ON ES.EXAM_SESSION_ID = ET.EXAM_SESSION_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
		                                AND CCR.IS_DELETED!=1
		                                INNER JOIN
	                                ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID=CCP.PROGRAMME_GROUP_ID
		                                AND SEM.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
                                        AND SEM.IS_DELETED!=1
                                        AND SEM.IS_ACTIVE=1
                                        AND SEM.SEMESTER=CCR.SEMESTER_ID
                                        INNER JOIN
                                    SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CCR.SEMESTER_ID
                                        INNER JOIN
                                    SUP_SHIFT AS SS ON SS.SHIFT_ID = PG.SHIFT
                                        INNER JOIN
                                    SUP_PROGRAMME_MODE AS SPM ON SPM.PROGRAMME_MODE_ID = PG.PROGRAMME_MODE
                                        INNER JOIN
                                    SUP_CLASS_YEAR AS CY ON CY.CLASS_YEAR_ID = CCS.PROGRAMME_YEAR
                                        INNER JOIN
                                    SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CCS.PROGRAMME_LEVEL
                                        INNER JOIN
                                    SUP_SUBJECT_TYPE AS SST ON SST.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                WHERE
                                    CCP.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CCP.IS_DELETED != 1
                                        AND CCP.PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
                                        AND ET.EXAM_SETTING_ID =(SELECT EXAM_SETTING_ID FROM CIA_EXAM_SETTING WHERE ACADEMIC_YEAR=?AC_YEAR AND IS_ACTIVE=1)
                                ORDER BY PROGRAMME_YEAR,EXAM_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTimeTableById:
                    {
                        query = @"SELECT 
                                    TIMETABLE_ID,
                                    DATE_FORMAT(EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                    EXAM_TIME,
                                    COURSE_ID,
                                    ET.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    IFNULL(IS_ADVANCE,'0') AS IS_ADVANCE,
                                    DATE_FORMAT(ADVANCE_DATE,'%d/%m/%Y') AS ADVANCE_DATE,
                                    ADVANCE_TIME,
                                    IFNULL(IS_POSTPONED,'0') AS IS_POSTPONED,
                                    DATE_FORMAT(POSTPONED_DATE,'%d/%m/%Y') AS POSTPONED_DATE,
                                    POSTPONED_TIME
                                FROM
                                    EXAM_TIMETABLE AS ET 
										INNER JOIN
									CP_COURSE_ROOT AS CCR ON CCR.COURSE_CODE=ET.COURSE_CODE
                                WHERE
                                    TIMETABLE_ID = ?TIMETABLE_ID;";

                        break;
                    }
                case ExaminationSQLCommands.SaveExamTimeTable:
                    {
                        query = @"INSERT INTO CIA_EXAM_TIMETABLE
                                  (
                                    EXAM_DATE,
                                    COURSE_ID,
                                    COURSE_CODE,
                                    EXAM_SESSION_ID,
                                    ACADEMIC_YEAR,
                                    EXAM_SETTING_ID
                                  )
                                  VALUES
                                  (
                                    ?EXAM_DATE,
                                    ?COURSE_ID,
                                    ?COURSE_CODE,
                                    ?EXAM_SESSION_ID,
                                    ?AC_YEAR,
                                    ?EXAM_SETTING_ID
                                   );";
                        //query = @"INSERT INTO exam_timetable
                        //          (
                        //            EXAM_DATE,
                        //            EXAM_TIME,
                        //            COURSE_ID,
                        //            COURSE_CODE,
                        //            EXAM_SESSION_ID,
                        //            ACADEMIC_YEAR,
                        //            IS_ADVANCE,
                        //            ADVANCE_DATE,
                        //            ADVANCE_TIME,
                        //            IS_POSTPONED,
                        //            POSTPONED_DATE,
                        //            POSTPONED_TIME,
                        //            EXAM_SETTING_ID
                        //          )
                        //          VALUES
                        //          (
                        //            ?EXAM_DATE,
                        //            ?EXAM_TIME,
                        //            ?COURSE_ID,
                        //            ?COURSE_CODE,
                        //            ?EXAM_SESSION_ID,
                        //            ?AC_YEAR,
                        //            ?IS_ADVANCE,
                        //            ?ADVANCE_DATE,
                        //            ?ADVANCE_TIME,
                        //            ?IS_POSTPONED,
                        //            ?POSTPONED_DATE,
                        //            ?POSTPONED_TIME,
                        //            ?EXAM_SETTING_ID
                        //           );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamTimeTable:
                    {
                        query = @"UPDATE CIA_EXAM_TIMETABLE
                                  SET
                                    EXAM_DATE = ?EXAM_DATE,
                                    COURSE_ID = ?COURSE_ID,
                                    COURSE_CODE = ?COURSE_CODE,
                                    EXAM_SESSION_ID=?EXAM_SESSION_ID,
                                    ACADEMIC_YEAR = ?AC_YEAR,
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    WHERE TIMETABLE_ID = ?TIMETABLE_ID;";
                        //query = @"UPDATE EXAM_TIMETABLE
                        //          SET
                        //            EXAM_DATE = ?EXAM_DATE,
                        //            EXAM_TIME = ?EXAM_TIME,
                        //            COURSE_ID = ?COURSE_ID,
                        //            COURSE_CODE = ?COURSE_CODE,
                        //            EXAM_SESSION_ID=?EXAM_SESSION_ID,
                        //            ACADEMIC_YEAR = ?AC_YEAR,
                        //            IS_ADVANCE = ?IS_ADVANCE,
                        //            ADVANCE_DATE = ?ADVANCE_DATE,
                        //            ADVANCE_TIME = ?ADVANCE_TIME,
                        //            IS_POSTPONED = ?IS_POSTPONED,
                        //            POSTPONED_DATE = ?POSTPONED_DATE,
                        //            POSTPONED_TIME = ?POSTPONED_TIME,
                        //            EXAM_SETTING_ID = ?EXAM_SETTING_ID
                        //            WHERE TIMETABLE_ID = ?TIMETABLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteCIAExamTimeTable:
                    {
                        query = @"UPDATE  CIA_EXAM_TIMETABLE SET IS_DELETED=1 WHERE TIMETABLE_ID=?TIMETABLE_ID;";
                        break;
                    }
                #endregion

                #region CIA Report For Language Course
                case ExaminationSQLCommands.FetchCIATotalForLanguageCourse:
                    {
                        query = @"SELECT
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,
                                    REGISTER_NO,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                        ((SUM(IF(COURSE_GROUP_MARK = -1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            SP.REGISTER_NO,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_COURSE_INFO AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    WHERE
                                         SC.COURSE_ID = ?COURSE_ID
                                             AND SC.ACADEMIC_YEAR=?AC_YEAR
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoByCourseId:
                    {
                        query = @"SELECT 
                                        DP.DEPARTMENT,
                                        CLS.CLASS_NAME,
                                        CR.COURSE_CODE,
                                        CR.SEMESTER_ID,
                                        UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE',
                                        CT.INTERNAL,
                                        UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                                        '',
                                                        SP.FIRST_NAME),
                                                    ' ',
                                                    IF(SP.LAST_NAME IS NULL,
                                                        '',
                                                        SP.LAST_NAME))) AS STAFF_NAME,
                                        SP.STAFF_ID,
                                        CR.COURSE_TYPE
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CC
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CC.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CC.CLASS_ID
                                            INNER JOIN
                                        CP_DEPARTMENT AS DP ON CR.DEPARTMENT = DP.DEPARTMENT_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CC.STAFF_ID
                                            INNER JOIN
                                        CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                    WHERE
                                        CC.COURSE_ID = ?COURSE_ID AND CC.CLASS_ID=?CLASS_ID 
                                        AND CC.IS_PRIMARY_STAFF=1 AND CC.STAFF_ID=?STAFF_ID AND CC.ACADEMIC_YEAR = ?AC_YEAR 
                                        AND CC.IS_DELETED!=1 LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoByCourseIdforcoe:
                    {
                        query = @"SELECT 
                                        DP.DEPARTMENT,
                                        CLS.CLASS_NAME,
                                        CR.COURSE_CODE,
                                        CR.SEMESTER_ID,
                                        UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE',
                                        CT.INTERNAL,
                                        UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                                        '',
                                                        SP.FIRST_NAME),
                                                    ' ',
                                                    IF(SP.LAST_NAME IS NULL,
                                                        '',
                                                        SP.LAST_NAME))) AS STAFF_NAME,
                                        SP.STAFF_ID,
                                        CR.COURSE_TYPE,
                                        CT.INTERNAL
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CC
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CC.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CC.CLASS_ID
                                            INNER JOIN
                                        CP_DEPARTMENT AS DP ON CR.DEPARTMENT = DP.DEPARTMENT_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CC.STAFF_ID
                                            INNER JOIN
                                        CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                    WHERE
                                        CC.COURSE_ID = ?COURSE_ID AND CC.CLASS_ID=?CLASS_ID 
                                        AND CC.IS_PRIMARY_STAFF=1 AND CC.ACADEMIC_YEAR = ?AC_YEAR 
                                        AND CC.IS_DELETED!=1 LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_MarksForLanguage:
                    {
                        query = @"SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                            WHERE
                                 SC.COURSE_ID=?COURSE_ID
                                    AND SC.IS_DELETED != 1 AND SC.ACADEMIC_YEAR=?AC_YEAR
                            ORDER BY ORDER_ID , REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoForLanguage:
                    {
                        query = @"SELECT 
                                    CR.COURSE_ROOT_ID,
                                    CONCAT(IF(UGC.UGC_COURSE_TYPE IS NULL,
                                                ' - ',
                                                UPPER(UGC.UGC_COURSE_TYPE)),
                                            '(',
                                            UPPER(CR.COURSE_TITLE),
                                            ')') AS 'COURSE_TITLE',
                                    CR.COURSE_CODE,
                                    CT.COURSE_TYPE_ID,
                                    CT.COURSE_TYPE,
                                    CLS.CLASS_NAME,
                                    CR.SEMESTER_ID,
                                    CLS.CLASS_ID
                                FROM
                                    CP_COURSE_ROOT AS CR
                                        JOIN
                                    CP_CLASSES AS CLS ON CR.COURSE_ROOT_ID = ?COURSE_ID
                                        INNER JOIN
                                    CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                        LEFT JOIN
                                    CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                WHERE
                                    CR.IS_DELETED != 1
                                        AND CLS.IS_DELETED != 1 AND CT.IS_DELETED!=1 limit 1;";
                        break;
                    }
                #endregion

                #region Fee & Attendance Validation For Hall Ticket
                case ExaminationSQLCommands.FetchFeeTransaction:
                    {
                        query = @"SELECT 
                                        SUM(IFNULL(FS.CREDIT, '0')) - SUM(IFNULL(FS.DEBIT, '0')) AS BALANCE,
                                        FS.DEBIT,
                                        SUM(FS.DEBIT) AS DEBIT,
                                        FT.FREQUENCY_TYPE_ID,
                                        FS.STUDENT_ID,
                                        FS.HEAD,
                                        SC.CLASS_ID,
                                        FS.FREQUENCY_ID,
                                        FT.FREQUENCY_TYPE AS FREQUENCY_NAME,
                                        FT.FEE_ROOT_ID
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        fee_frequency_fee_mode AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID AND FFF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                            INNER JOIN
                                        sup_fee_frequency AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID AND FF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    WHERE
                                            SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FS.IS_DELETED!=1
                                    GROUP BY FFF.FEE_MODE
                                    ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalAbsentHours:
                    {
                        query = @"SELECT  
                                        COUNT(ATT.ATTENDANCE_ID) AS 'TOTAL_HRS'
                                    FROM
                                        ATT_ABSENTEE_LIST AS ATT
                                            INNER JOIN
                                        CALENDER AS CAL ON CAL.DAY_ORDER_DATE = ATT.ATTENDENCE_DATE
                                            AND CAL.ACADEMIC_YEAR = ATT.ACADEMIC_YEAR
                                            AND CAL.IS_HOLIDAY != 1
                                            INNER JOIN
                                        TT_TIMETABLE AS TT ON TT.DAY_ORDER_ID = CAL.DAY_ORDER
                                            AND TT.CLASS_ID = ATT.S_CLASS_ID
                                            AND TT.STAFF_ID = ATT.STAFF_ID
                                          --  AND TT.HOUR_ID = ATT.HOUR_FROM
                                            AND TT.COURSE_ID = ATT.COURSE_ID
                                            AND TT.ACADEMIC_YEAR = ATT.ACADEMIC_YEAR
                                            AND TT.IS_DELETED != 1
                                    WHERE ATT.ACADEMIC_YEAR = ?AC_YEAR 
                                          AND ATT.IS_DELETED!=1 
                                          AND ATT.ATTENDANCE_TYPE_ID=2
                                          AND ATT.STUDENT_ID=?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemsterDateByStudentId:
                    {
                        query = @"SELECT 
                                        SEM.DATE_FROM, SEM.DATE_TO
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS B ON B.BATCH_YEAR = C.CLASS_YEAR
                                            AND B.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                ACTIVE_YEAR = 1 AND IS_DELETED != 1)
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND SEM.BATCH = B.BATCH_ID
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND SEM.IS_DELETED!=1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SEM.IS_ACTIVE = 1
                                            AND SC.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalHours:
                    {
                        query = @"SELECT 
                                        COUNT(TT.HOUR_ID) AS 'TOTAL_HRS'
                                    FROM
	                                    STU_CLASS AS SC
		                                    INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
		                                    INNER JOIN
	                                    ACADEMIC_BATCHES AS B ON B.BATCH_YEAR = C.CLASS_YEAR
		                                    AND B.ACADEMIC_YEAR_ID = (SELECT ACADEMIC_YEAR_ID FROM ACADEMIC_YEAR WHERE ACTIVE_YEAR=1 AND IS_DELETED!=1)
		                                    INNER JOIN
	                                    ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID=C.PROGRAMME_GROUP_ID
		                                    AND SEM.BATCH=B.BATCH_ID
                                            AND SEM.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND SEM.IS_DELETED!=1
		                                    AND SEM.IS_ACTIVE=1
                                            INNER JOIN
                                        TT_TIMETABLE AS TT ON TT.CLASS_ID=SC.CLASS_ID
                                            AND TT.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND TT.COURSE_ID IN (?COURSE_ID)
                                            AND TT.SEMESTER_ID=SEM.SEMESTER
                                            AND TT.IS_DELETED != 1
                                            INNER JOIN
	                                    CALENDER AS CAL ON CAL.DAY_ORDER = TT.DAY_ORDER_ID
		                                    AND CAL.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND CAL.IS_HOLIDAY != 1
                                            AND CAL.DAY_ORDER_DATE BETWEEN SEM.DATE_FROM AND CURDATE()
                                            AND SEM.DATE_TO >= CURDATE()
                                    WHERE
                                             SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.STUDENT_ID=?STUDENT_ID AND SC.IS_DELETED!=1;";
                        break;
                    }
                #endregion
                case ExaminationSQLCommands.FetchCourseFromExamRegistrationByProgrammeGroup:
                    {
                        query = @"SELECT 
                                EXR.REGISTRATION_ID,
                                PG.PROGRAMME_GROUP_ID,
                                EXR.COURSE_ID,
                                CL.CLASS_YEAR,
                                CL.CLASS_ID
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR AS EXR
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = EXR.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EXR.COURSE_ID
                                    INNER JOIN
                                CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CL.PROGRAMME_GROUP_ID
                                    INNER JOIN
                                CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = PG.PROGRAMME_ID
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EXR.IS_DELETED != 1
                                    AND EXR.STATUS = 'R'
                            GROUP BY CL.CLASS_ID , EXR.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchRegularExamRegisteredStudentByProgramme:
                    {
                        query = @"SELECT 
                                    EXR.REGISTRATION_ID,
                                    SP.STUDENT_ID,
                                    CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                            IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                    EXR.COURSE_ID,
                                    EXR.STATUS,
                                    CONCAT(IFNULL(CR.COURSE_CODE, ''),
                                            '(',
                                            IFNULL(UPPER(CR.COURSE_TITLE), ''),
                                            ')') AS COURSE_TITLE,
	                                PG.PROGRAMME_GROUP_ID,
                                    CL.CLASS_YEAR,
                                    EXR.EXAM_SEMESTER AS SEMESTER,
	                                EX.EXAM_SETTING_ID ,
	                                EX.M_PASS
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS EXR
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = EXR.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EXR.COURSE_ID
                                        INNER JOIN
                                    CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CL.PROGRAMME_GROUP_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = PG.PROGRAMME_ID
                                    INNER JOIN EXAM_SETTING AS EX ON EX.EXAM_SETTING_ID=EXR.EXAM_SETTING_ID
                                WHERE
                                    EXR.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EXR.IS_DELETED != 1
                                        AND EXR.STATUS = 'R'
		                                AND PG.PROGRAMME_GROUP_ID=?PROGRAMME_GROUP_ID
                                        AND CL.CLASS_ID=?CLASS_ID
                                        AND EXR.COURSE_ID=?COURSE_ID
                                        AND CLASS_YEAR=?CLASS_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAgroupmarkForSemester:
                    {
                        query = @"SELECT 
                                SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                STUDENT_ID,
                                ROLL_NO,
                                REGISTER_NO,
                                PROGRAMME_GROUP_ID,
                                UPPER(NAME) AS 'NAME',
                                COURSE_ID
                            FROM
                                (SELECT 
                                    ((SUM(IF(COURSE_GROUP_MARK = - 1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT 
                                                GROUP_MARK
                                            FROM
                                                CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE
                                                CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1)) AS CUMULATIVE,
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CCP.PROGRAMME_GROUP_ID,
                                        CCP.COURSE_ID,
                                        CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                FROM
                                    CP_COURSE_PATTERN AS CCP
                                INNER JOIN CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                INNER JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                INNER JOIN CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                INNER JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
                                INNER JOIN STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                    AND SC.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                INNER JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                    AND CGM.COURSE_ID = CCP.COURSE_ID
                                    AND CGM.COURSE_GROUP_ID = CGC.CIA_GROUP_COMPONENT_ID
                                    AND CGC.IS_DELETED != 1
                                WHERE
                                    C.CLASS_YEAR = ?CLASS_YEAR
                                        AND CCP.PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
                                        AND CCP.COURSE_ID IN (?COURSE_ID)
                                        AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SC.IS_DELETED != 1
                                        AND CCP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                GROUP BY SP.STUDENT_ID , CCP.COURSE_ID , CGC.CIA_GROUP_ID) AS T
                            GROUP BY STUDENT_ID , COURSE_ID
                            ORDER BY REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearStudentByCourse:
                    {
                        query = @"SELECT 
                            EXR.REGISTRATION_ID,
                            SP.STUDENT_ID,
                            CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                    IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                            EXR.COURSE_ID,
                            EXR.STATUS,
                            CONCAT(IFNULL(CR.COURSE_CODE, ''),
                                    '(',
                                    IFNULL(UPPER(CR.COURSE_TITLE), ''),
                                    ')') AS COURSE_TITLE,
	                        PG.PROGRAMME_GROUP_ID,
                            CL.CLASS_YEAR,
                            CR.SEMESTER_ID AS SEMESTER,
	                        EX.EXAM_SETTING_ID ,
	                        EX.M_PASS
                        FROM
                            EXAM_REGISTRATION_?AC_YEAR AS EXR
                                INNER JOIN
                            STU_CLASS AS SC ON SC.STUDENT_ID = EXR.STUDENT_ID
                                AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                INNER JOIN
                            STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                AND SP.IS_DELETED != 1
                                INNER JOIN
                            CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EXR.COURSE_ID
                                INNER JOIN
                            CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                INNER JOIN
                            CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CL.PROGRAMME_GROUP_ID
                                INNER JOIN
                            CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = PG.PROGRAMME_ID
                            INNER JOIN EXAM_SETTING AS EX ON EX.EXAM_SETTING_ID=EXR.EXAM_SETTING_ID
                        WHERE
                            EXR.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                AND EXR.IS_DELETED != 1
                                AND EXR.STATUS != 'R'		                     
                                AND EXR.COURSE_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrierStudentInternal:
                    {
                        query = @"SELECT STUDENT_ID,COURSE_ID,INTERNAL_MARK,SEMESTER FROM semester_marks_?AC_YEAR WHERE STUDENT_ID=?STUDENT_ID AND COURSE_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterMarkByCourse:
                    {
                        query = @"SELECT 
                                    SEMESTER_MARK_ID,
                                    SM.STUDENT_ID,
                                    SP.ROLL_NO,
                                    SP.REGISTER_NO,
                                    CONCAT(IFNULL(FIRST_NAME, ''),
                                            ' ',
                                            IFNULL(LAST_NAME, '')) AS NAME,
                                    CR.PART,
                                    SM.COURSE_ID,
                                    P.PART AS PART_NAME,
                                    CR.COURSE_CODE,
                                    CONCAT(CT.UGC_COURSE_TYPE,
                                            ': ',
                                            CR.COURSE_TITLE) COURSE_TITLE,
                                    SM.SEMESTER,
                                    SEM.SEMESTER_NAME,
                                    SM.INTERNAL_MARK,
                                    SM.EXTERNAL_MARK,
                                    SM.GRADE,
                                    SM.GRADE_POINT,
                                    SM.TOTAL,
                                    PR.PROGRAMME_NAME,
                                    CR.CREDITS AS CREDIT,
                                    SM.M_PASS,
                                    CLS.CLASS_LEVEL,
                                    SM.RESULT,
                                    CR.UGC_COURSE_TYPE,
                                    CR.INTERNAL,CR.EXTERNAL,CR.TOTAL AS TOTAL_MARK
                                FROM
                                    SEMESTER_MARKS_?AC_YEAR AS SM
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = SM.STUDENT_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SC.STUDENT_ID = SP.STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                        AND CR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_UGC_COURSE_TYPE AS CT ON CT.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                        AND CT.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_SEMESTER AS SEM ON SEM.SUP_SEMESTER_ID = SM.SEMESTER
                                        LEFT JOIN
                                    SUP_PART AS P ON P.PART_ID = CR.PART
                                        INNER JOIN
                                    CP_CLASSES AS CLS ON CLS.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CLS.PROGRAMME_GROUP_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS PR ON PR.PROGRAMME_ID = PG.PROGRAMME_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND SM.COURSE_ID IN (?COURSE_ID)
                                        AND PG.PROGRAMME_GROUP_ID IN (?PROGRAMME_GROUP_ID)
                                ORDER BY REGISTER_NO , CR.PART , CT.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateSemesterMark:
                    {
                        query = @"UPDATE SEMESTER_MARKS_?AC_YEAR
                                SET
                               `INTERNAL_MARK` = ?INTERNAL_MARK,
                               `EXTERNAL_MARK` = ?EXTERNAL_MARK,
                               `TOTAL` = ?TOTAL,
                               `RESULT` = ?RESULT,
                                COURSE_ID=?COURSE_ID,
                                ENTRY_ID=?ENTRY_ID
                               WHERE `SEMESTER_MARK_ID` = ?SEMESTER_MARK_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingBySettingId:
                    {
                        query = @"SELECT EXAM_SETTING_ID, EXAM_NAME, ACADEMIC_YEAR, M_EXAM, M_PASS, IS_ACTIVE, SEMESTER, LAST_DATE_FOR_EXAM_FEE, START_DATE, END_DATE FROM EXAM_SETTING  WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }

                #region Quiz Setting
                case ExaminationSQLCommands.ListQuizSetting:
                    {
                        query = @"SELECT 
                                    QS.SETTING_ID,
                                    QS.SETTING_NAME,
                                    QS.NO_OF_QUESTIONS,
                                    QS.EACH_QUESTION_MARKS,
                                    QS.TOTAL_MARK,
                                    QS.QUIZ_STF_ID,
                                    QS.TIME,
                                    DATE_FORMAT(QS.ENTRY_DATE,'%d/%m/%Y') AS ENTRY_DATE,  
                                    QS.ACADEMIC_YEAR,
                                    DATE_FORMAT(QS.START_DATE,'%d/%m/%Y') AS START_DATE ,
                                    DATE_FORMAT(QS.END_DATE,'%d/%m/%Y') AS END_DATE,
                                    IFNULL(QS.IS_ACTIVE,'0')AS IS_ACTIVE,
                                    C.CLASS_NAME,
                                    concat(ifnull(CCR.COURSE_CODE,''),' - ',ifnull(CCR.COURSE_TITLE,'')) AS COURSE,
                                    CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME 
                                FROM
                                    QUIZ_SETTING AS QS
										INNER JOIN
									cp_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID=QS.QUIZ_STF_ID
										AND CCS.IS_DELETED!=1
                                        AND CCS.ACADEMIC_YEAR=QS.ACADEMIC_YEAR
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID=CCS.CLASS_ID
										INNER JOIN
									CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=CCS.COURSE_ID
										INNER JOIN
									STF_PERSONAL_INFO AS SP ON SP.STAFF_ID=CCS.STAFF_ID 
										AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                WHERE 
                                    QS.IS_DELETED != 1 
                                    AND QS.ACADEMIC_YEAR=?AC_YEAR 
                                    AND CCS.CLASS_ID=?CLASS_ID 
                                    AND CCS.COURSE_ID=?COURSE_ID 
                                    AND CCS.STAFF_ID=?STAFF_ID;";
                        break;
                    }
                case ExaminationSQLCommands.GetClassCourseStaffIdForQuizSetting:
                    {
                        query = @"SELECT 
                                        CLSCRSSTF_ID AS QUIZ_STF_ID,STAFF_ID
                                    FROM
                                        CP_CLASS_COURSE_STAFF
                                    WHERE
                                        ACADEMIC_YEAR = ?AC_YEAR AND CLASS_ID = ?CLASS_ID
                                            AND COURSE_ID = ?COURSE_ID
                                            AND STAFF_ID = ?STAFF_ID
                                            AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchActiveQuizSettingIdByClsStaffId:
                    {
                        query = @"SELECT 
                                    SETTING_ID,
                                    CONCAT(IFNULL(SETTING_NAME, ''),
                                            ' - ',
                                            IFNULL(ACADEMIC_YEAR, '')) AS SETTING_NAME,
                                    TIME,
                                    START_DATE,
                                    END_DATE,
                                    IF(DATEDIFF( DATE_SUB(CURDATE(),INTERVAL 1 DAY),END_DATE)<0,'1','0') AS ACTIVE_DATE
                                FROM
                                    QUIZ_SETTING
                                WHERE
                                    IS_ACTIVE = 1 AND QUIZ_STF_ID=?QUIZ_STF_ID
                                    AND ACADEMIC_YEAR=?AC_YEAR AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.GetActiveSettingByClassAndCourseAndStaffIds:
                    {
                        query = @"SELECT 
                                    SETTING_ID,
                                    CONCAT(IFNULL(SETTING_NAME, ''),
                                            ' - ',
                                            IFNULL(QS.ACADEMIC_YEAR, '')) AS SETTING_NAME,
                                    TIME,
                                    START_DATE,
                                    END_DATE,
                                    NO_OF_QUESTIONS,
                                    '1' AS ACTIVE_DATE
                                FROM
                                    QUIZ_SETTING AS QS
                                        INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID = QS.QUIZ_STF_ID
                                        AND CCS.ACADEMIC_YEAR=QS.ACADEMIC_YEAR
		                                AND CCS.IS_DELETED!=1
                                WHERE
                                    QS.IS_ACTIVE = 1 AND QS.IS_DELETED != 1
                                        AND CCS.COURSE_ID = ?COURSE_ID
                                        AND CCS.CLASS_ID = ?CLASS_ID
                                        AND CCS.STAFF_ID = ?STAFF_ID
                                        AND QS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.SaveQuizSetting:
                    {
                        query = @"INSERT INTO QUIZ_SETTING
                                  (
                                      SETTING_NAME,
                                      QUIZ_TYPE_ID,
                                      NO_OF_QUESTIONS,
                                      EACH_QUESTION_MARKS,
                                      TOTAL_MARK,
                                      QUIZ_STF_ID,
                                      STAFF_ID,
                                      TIME,
                                      ACADEMIC_YEAR,
                                      START_DATE,
                                    --  END_DATE,
                                      IS_CORRECT,
                                      IS_SHOW_MARKS,
                                      IS_SHOW_RIGHT_ANSWER
                                  )
                                  VALUES
                                  (
                                      ?SETTING_NAME,
                                      ?QUIZ_TYPE_ID,
                                      ?NO_OF_QUESTIONS,
                                      ?EACH_QUESTION_MARKS,
                                      ?TOTAL_MARK,
                                      ?QUIZ_STF_ID,
                                      ?STAFF_ID,
                                      ?TIME,
                                      ?AC_YEAR,
                                      ?START_DATE,
                                  --    ?END_DATE,
                                      ?IS_CORRECT,
                                      ?IS_SHOW_MARKS,
                                      ?IS_SHOW_RIGHT_ANSWER
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizSetting:
                    {
                        query = @"UPDATE QUIZ_SETTING
                                  SET
                                  SETTING_ID = ?SETTING_ID,
                                  SETTING_NAME = ?SETTING_NAME,
                                  QUIZ_TYPE_ID = ?QUIZ_TYPE_ID,
                                  NO_OF_QUESTIONS = ?NO_OF_QUESTIONS,
                                  EACH_QUESTION_MARKS = ?EACH_QUESTION_MARKS,
                                  TIME=?TIME,
                                  TOTAL_MARK = ?TOTAL_MARK,
                                  START_DATE = ?START_DATE,
                                --  END_DATE = ?END_DATE,
                                  IS_CORRECT=?IS_CORRECT,
                                  IS_SHOW_MARKS=?IS_SHOW_MARKS,
                                  IS_SHOW_RIGHT_ANSWER=?IS_SHOW_RIGHT_ANSWER
                                  WHERE SETTING_ID = ?SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteQuizSetting:
                    {
                        query = @"UPDATE QUIZ_SETTING SET IS_DELETED=1 WHERE SETTING_ID = ?SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ActiveOrDeactiveQuizSetting:
                    {
                        query = @"UPDATE QUIZ_SETTING SET IS_ACTIVE=?IS_ACTIVE WHERE SETTING_ID = ?SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizSettingById:
                    {
                        query = @"SELECT 
                                    SETTING_ID,
                                    SETTING_NAME,
                                    QUIZ_TYPE_ID,
                                    NO_OF_QUESTIONS,
                                    EACH_QUESTION_MARKS,
                                    TOTAL_MARK,
                                    TIME,
                                    ACADEMIC_YEAR,
                                    DATE_FORMAT(START_DATE,'%d/%m/%Y') AS START_DATE ,
                                    DATE_FORMAT(END_DATE,'%d/%m/%Y') AS END_DATE,
                                    IFNULL(IS_ACTIVE,'0')AS IS_ACTIVE,
                                    IFNULL(IS_CORRECT,0) AS IS_CORRECT,
                                    IFNULL(IS_SHOW_MARKS,0) AS IS_SHOW_MARKS,
                                    IFNULL(IS_SHOW_RIGHT_ANSWER,0) AS IS_SHOW_RIGHT_ANSWER
                                FROM
                                    QUIZ_SETTING
                                WHERE
                                  SETTING_ID=?SETTING_ID AND IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchActiveQuizSettingId:
                    {
                        query = @"SELECT 
                                    SETTING_ID,
                                    CONCAT(IFNULL(SETTING_NAME, ''),
                                            ' - ',
                                            IFNULL(ACADEMIC_YEAR, '')) AS SETTING_NAME,
                                    TIME,
                                    START_DATE,
                                    END_DATE,
                                    IF(DATEDIFF( DATE_SUB(curdate(),INTERVAL 1 DAY),END_DATE)<0,'1','0') AS ACTIVE_DATE
                                FROM
                                    QUIZ_SETTING
                                WHERE
                                    IS_ACTIVE = 1 AND STAFF_ID = ?STAFF_ID 
                                    AND ACADEMIC_YEAR=?AC_YEAR AND IS_DELETED != 1;";
                        //query = @"SELECT 
                        //              SETTING_ID,
                        //              CONCAT(IFNULL(SETTING_NAME,''),' - ',IFNULL(ACADEMIC_YEAR,'')) AS SETTING_NAME,
                        //              TIME,
                        //          FROM QUIZ_SETTING 
                        //          WHERE IS_ACTIVE=1 AND STAFF_ID=?STAFF_ID AND IS_DELETED!=1;";
                        break;
                    }
                #endregion

                #region Quiz Student Shuffle

                case ExaminationSQLCommands.ListQuizStudentShuffle:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME,
                                        C.CLASS_NAME,
                                        Q.SET_ID,
                                        Q.QUIZ_SHUFFLE_ID
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.CLASS_ID
		                                    AND CCS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
										CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=CCS.COURSE_ID 
											-- AND CCR.IS_COMPULSORY=1
                                            LEFT JOIN
	                                    QUIZ_STUDENT_SHUFFLE AS Q ON Q.CLASS_ID=SC.CLASS_ID
		                                    AND Q.COURSE_ID=CCS.COURSE_ID
		                                    AND Q.ENTRY_ID=CCS.STAFF_ID
                                            AND Q.STUDENT_ID=SC.STUDENT_ID
                                            AND Q.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND Q.SETTING_ID IN (?SETTING_ID)
                                    WHERE
                                        CCS.CLASS_ID = ?CLASS_ID AND CCS.STAFF_ID = ?ENTRY_ID
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    UNION
                                    SELECT 
                                         SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME,
                                        C.CLASS_NAME,
                                        Q.SET_ID,
                                        Q.QUIZ_SHUFFLE_ID
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.S_CLASS_ID
		                                    AND CCS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND CCS.IS_DELETED != 1
                                            LEFT JOIN
	                                    QUIZ_STUDENT_SHUFFLE AS Q ON Q.CLASS_ID=SC.S_CLASS_ID
		                                    AND Q.COURSE_ID=SC.COURSE_ID
		                                    AND Q.ENTRY_ID=CCS.STAFF_ID
                                            AND Q.STUDENT_ID=SC.STUDENT_ID
                                            AND Q.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND Q.SETTING_ID IN (?SETTING_ID)
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SC.S_CLASS_ID = ?CLASS_ID
                                            AND SC.COURSE_ID = ?COURSE_ID
                                            AND CCS.STAFF_ID = ?ENTRY_ID;";
                        //query = @"SELECT 
                        //                QUIZ_SHUFFLE_ID,
                        //                C.CLASS_NAME,
                        //                CR.COURSE_CODE,
                        //                CR.COURSE_TITLE,
                        //                SP.ROLL_NO,
                        //                SP.REGISTER_NO,
                        //                CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME,
                        //                S.SET_NAME,
                        //                SS.SEMESTER_NAME,
                        //                IFNULL(QS.IS_ACTIVE,'0') AS IS_ACTIVE
                        //            FROM
                        //                QUIZ_STUDENT_SHUFFLE AS QS
                        //              INNER JOIN
                        //             CP_CLASSES AS C ON C.CLASS_ID=QS.CLASS_ID
                        //              AND C.IS_DELETED!=1
                        //              INNER JOIN
                        //             CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID=QS.COURSE_ID
                        //              AND CR.IS_DELETED!=1
                        //              INNER JOIN
                        //             STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=QS.STUDENT_ID
                        //              AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                        //              INNER JOIN
                        //             SUP_SETS AS S ON S.SET_ID=QS.SET_ID
                        //              AND S.IS_DELETED!=1
                        //              INNER JOIN
                        //             SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=QS.SEMESTER_ID
                        //              AND SS.IS_DELETED!=1
                        //            WHERE
                        //                QS.IS_DELETED != 1 AND QS.SETTING_ID IN (?SETTING_ID) AND QS.ENTRY_ID=?ENTRY_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchStudentByCourseIdAndClassIdAndStaffId:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, ''),
                                                ' - ',
                                                IFNULL(SP.REGISTER_NO, SP.ROLL_NO),
                                                '  ',
                                                IF(SS.SET_ID = QSS.SET_ID,CONCAT(' (', SS.SET_NAME, ' )'),IFNULL(CONCAT(' (', SETS.SET_NAME, ' )'),''))) AS FIRST_NAME,
                                        IF(SS.SET_ID = QSS.SET_ID,
                                            'SELECTED',
                                            '') AS SELECTED
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.CLASS_ID
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND CCS.STAFF_ID = ?STAFF_ID
                                            AND CCS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            LEFT JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QSS ON QSS.STUDENT_ID = SC.STUDENT_ID
                                            AND QSS.CLASS_ID = SC.CLASS_ID
                                            AND QSS.COURSE_ID = CCS.COURSE_ID
                                            AND QSS.SETTING_ID = ?SETTING_ID
                                            AND QSS.IS_DELETED != 1
                                            Inner JOIN
                                        SUP_SETS AS SS ON SS.SET_ID = ?SET_ID
		                                    LEFT JOIN
	                                    SUP_SETS AS SETS ON SETS.SET_ID=QSS.SET_ID
                                    WHERE
                                        CCS.CLASS_ID = ?CLASS_ID
                                            AND SC.IS_DELETED != 1
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR GROUP BY SC.STUDENT_ID 
                                    UNION SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.REGISTER_NO, SP.ROLL_NO),
                                                '  ',
                                               IF(SS.SET_ID = QSS.SET_ID,CONCAT(' (', SS.SET_NAME, ' )'),IFNULL(CONCAT(' (', SETS.SET_NAME, ' )'),''))) AS FIRST_NAME,
                                           IF(SS.SET_ID = QSS.SET_ID,
                                            'SELECTED',
                                            '') AS SELECTED
                                    FROM
                                        STU_COURSE_INFO AS CLS
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = CLS.S_CLASS_ID
                                            AND CCS.COURSE_ID = CLS.COURSE_ID
                                            AND CCS.ACADEMIC_YEAR = CLS.ACADEMIC_YEAR
                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            LEFT JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QSS ON QSS.STUDENT_ID = CLS.STUDENT_ID
                                            AND QSS.CLASS_ID = CLS.CLASS_ID
                                            AND QSS.COURSE_ID = CCS.COURSE_ID
                                            AND QSS.SETTING_ID = ?SETTING_ID
                                            AND QSS.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_SETS AS SS ON SS.SET_ID = ?SET_ID
		                                    LEFT JOIN
	                                    SUP_SETS AS SETS ON SETS.SET_ID=QSS.SET_ID
                                    WHERE
                                        CCS.CLASS_ID = ?CLASS_ID
                                            AND CCS.COURSE_ID = ?COURSE_ID  
                                            AND CCS.STAFF_ID = ?STAFF_ID
                                            AND CLS.IS_DELETED != 1
                                            AND CLS.ACADEMIC_YEAR = ?AC_YEAR GROUP BY CLS.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizStudentShuffleById:
                    {
                        query = @"SELECT 
                                    QUIZ_SHUFFLE_ID,
                                    CLASS_ID,
                                    COURSE_ID,
                                    STUDENT_ID,
                                    ENTRY_ID,
                                    SET_ID,
                                    SETTING_ID,
                                    SEMESTER_ID
                                FROM
                                    QUIZ_STUDENT_SHUFFLE WHERE QUIZ_SHUFFLE_ID=?QUIZ_SHUFFLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.IsExistQuizStudentShuffle:
                    {
                        query = @"SELECT 
                                    QUIZ_SHUFFLE_ID,
                                    CLASS_ID,
                                    COURSE_ID,
                                    STUDENT_ID,
                                    ENTRY_ID,
                                    SET_ID,
                                    SETTING_ID,
                                    SEMESTER_ID
                                FROM
                                    QUIZ_STUDENT_SHUFFLE
                                WHERE
                                     CLASS_ID = ?CLASS_ID
                                        AND COURSE_ID = ?COURSE_ID
                                        AND SETTING_ID = ?SETTING_ID
                                        AND ACADEMIC_YEAR = ?AC_YEAR AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllShuffleStudentListBySettingId:
                    {
                        query = @"";
                        break;
                    }
                case ExaminationSQLCommands.SaveQuizStudentShuffle:
                    {
                        query = @"INSERT INTO QUIZ_STUDENT_SHUFFLE
                                  (
	                                  CLASS_ID,
	                                  COURSE_ID,
	                                  STUDENT_ID,
	                                  ENTRY_ID,
                                      SETTING_ID,
	                                  SET_ID,
	                                  SEMESTER_ID,
	                                  ACADEMIC_YEAR
                                  )
                                  VALUES
                                  (
                                      ?CLASS_ID,
	                                  ?COURSE_ID,
	                                  ?STUDENT_ID,
	                                  ?ENTRY_ID,
                                      ?SETTING_ID,
	                                  ?SET_ID,
	                                  ?SEMESTER_ID,
	                                  ?AC_YEAR
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizStudentShuffle:
                    {
                        query = @"UPDATE QUIZ_STUDENT_SHUFFLE
                                  SET
                                  STUDENT_ID = ?STUDENT_ID,
                                  SET_ID = ?SET_ID
                                  WHERE QUIZ_SHUFFLE_ID = ?QUIZ_SHUFFLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteQuizStudentShuffle:
                    {
                        query = @"UPDATE QUIZ_STUDENT_SHUFFLE SET IS_DELETED=1 WHERE QUIZ_SHUFFLE_ID = ?QUIZ_SHUFFLE_ID;";
                        break;
                    }
                #endregion

                #region Quiz Entry For Student SetWise
                case ExaminationSQLCommands.FetchCourseInfoForQuiz:
                    {

                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        C.CLASS_ID,
                                        C.CLASS_NAME,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SP.STAFF_CODE,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS STAFF_NAME,
                                        DATE_FORMAT(CURDATE(), '%d/%m/%Y') AS DATE,
                                        CCR.SEMESTER_ID,SP.MOBILE_NO
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.CLASS_ID
                                            AND CCS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CCS.STAFF_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_SETTING AS QS ON QS.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                            AND QS.IS_ACTIVE = 1
                                            AND QS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                    GROUP BY CCS.COURSE_ID
                                    union
                                    SELECT 
                                        SC.STUDENT_ID,
                                        C.CLASS_ID,
                                        C.CLASS_NAME,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SP.STAFF_CODE,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS STAFF_NAME,
                                        DATE_FORMAT(CURDATE(), '%d/%m/%Y') AS DATE,
                                        CCR.SEMESTER_ID,SP.MOBILE_NO
                        
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.S_CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CCS.STAFF_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_SETTING AS QS ON QS.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                            AND QS.IS_ACTIVE = 1
                                            AND QS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                    GROUP BY CCS.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoForQuizWithoutActive:
                    {

                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        C.CLASS_ID,
                                        C.CLASS_NAME,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SP.STAFF_CODE,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS STAFF_NAME,
                                        DATE_FORMAT(CURDATE(), '%d/%m/%Y') AS DATE,
                                        CCR.SEMESTER_ID,SP.MOBILE_NO
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.CLASS_ID
                                            AND CCS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CCS.STAFF_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_SETTING AS QS ON QS.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                            AND QS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                    GROUP BY CCS.COURSE_ID
                                    union
                                    SELECT 
                                        SC.STUDENT_ID,
                                        C.CLASS_ID,
                                        C.CLASS_NAME,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SP.STAFF_CODE,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS STAFF_NAME,
                                        DATE_FORMAT(CURDATE(), '%d/%m/%Y') AS DATE,
                                        CCR.SEMESTER_ID,SP.MOBILE_NO
                        
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.S_CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CCS.STAFF_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_SETTING AS QS ON QS.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                            AND QS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                    GROUP BY CCS.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingQuizQuestions:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION AS QUIZ_QUESTION,
                                        QQ.SET_ID,
                                        QQ.QUESTION_TYPE
                                    FROM
                                        QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ
                                            INNER JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QS ON QS.CLASS_ID = QQ.CLASS_ID
                                            AND QS.COURSE_ID = QQ.COURSE_ID
                                            AND QS.SET_ID = QQ.SET_ID
                                            AND QS.STUDENT_ID = ?STUDENT_ID
                                            AND QS.SETTING_ID = QQ.SETTING_ID
                                            AND QS.ENTRY_ID = QQ.ENTRY_ID
                                            AND QS.ACADEMIC_YEAR = QQ.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        QQ.IS_DELETED != 1 
                                            AND QQ.QUIZ_ID NOT IN(SELECT 
                                            QUIZ_ID
                                        FROM
                                            QUIZ_SAVE_MATCH_THE_FOLLOWING
                                        WHERE
                                            SETTING_ID =?SETTING_ID  AND STUDENT_ID = ?STUDENT_ID)
                                            AND QQ.SETTING_ID = ?SETTING_ID
                                            AND QQ.COURSE_ID = ?COURSE_ID
                                            AND QQ.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY QUIZ_ID
                                    ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingQuizOptions:
                    {
                        query = @"SELECT 
                                            QQ.QUIZ_ID,
                                            QQ.QUESTION AS QUIZ_QUESTION,
                                            QQ.SET_ID,
                                            QQ.QUESTION_TYPE,
                                            OP.OPTION_ID,
                                            OP.QUESTION,
                                            OP.ANSWER
                                        FROM
                                            QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ 
                                                INNER JOIN
                                            QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS OP ON OP.QUIZ_ID = QQ.QUIZ_ID
                                                INNER JOIN
                                            QUIZ_STUDENT_SHUFFLE AS QS ON QS.CLASS_ID = QQ.CLASS_ID
                                                AND QS.COURSE_ID = QQ.COURSE_ID
                                                AND QS.SET_ID = QQ.SET_ID
                                                AND QS.STUDENT_ID = ?STUDENT_ID
                                                AND QS.SETTING_ID = QQ.SETTING_ID
                                                AND QS.ENTRY_ID = QQ.ENTRY_ID
                                                AND QS.ACADEMIC_YEAR = QQ.ACADEMIC_YEAR
                                                AND QS.IS_DELETED != 1
                                        WHERE
                                            QQ.IS_DELETED != 1 
		                                        AND QQ.SETTING_ID = ?SETTING_ID
                                                AND QQ.COURSE_ID = ?COURSE_ID
                                                AND QQ.ACADEMIC_YEAR = ?AC_YEAR
                                        GROUP BY OP.OPTION_ID
                                        ORDER BY RAND();";
