                case ExaminationSQLCommands.UpdateQuizAnswerForObjectiveQuestions:
                    {
                        query = @"UPDATE QUIZ_OBJECTIVE_QUESTIONS SET ANSWER_ID=?ANSWER_ID WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizObjectiveOptionsByQuizId:
                    {
                        query = @"SELECT 
                                        OPTION_ID,
                                        `OPTION`,
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QQ.CLASS_ID,
                                        QQ.COURSE_ID,
                                        QQ.ANSWER_ID,
                                        QQ.SEMESTER_ID,
                                        QQ.SET_ID,
                                        QQ.SETTING_ID,
                                        QP.MARK
                                    FROM
	                                    QUIZ_OBJECTIVE_QUESTIONS AS QQ
		                                    INNER JOIN
                                        QUIZ_OBJECTIVE_OPTIONS AS QP ON QP.QUIZ_ID=QQ.QUIZ_ID
                                    WHERE
                                        QQ.QUIZ_ID = ?QUIZ_ID AND QP.IS_DELETED!=1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchQuizFillintheBlanksOptionByQuizId:
                    {
                        query = @"SELECT 
                                        OPTION_ID,
                                        `OPTION`,
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QQ.CLASS_ID,
                                        QQ.COURSE_ID,
                                        QQ.ANSWER_ID,
                                        QQ.SEMESTER_ID,
                                        QQ.SET_ID,
                                        QQ.SETTING_ID,
                                        QP.MARK
                                    FROM
	                                    QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
		                                    INNER JOIN
                                        QUIZ_FILL_IN_BLANK_OPTIONS AS QP ON QP.QUIZ_ID=QQ.QUIZ_ID
                                    WHERE
                                        QQ.QUIZ_ID =?QUIZ_ID AND QP.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateObjectiveQuizQuestionByQuizId:
                    {
                        query = @"UPDATE QUIZ_OBJECTIVE_QUESTIONS SET QUESTION=?QUESTION,MARK=?MARK WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectivesQuizQuestions:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION AS QUIZ_QUESTION,
                                        QQ.SET_ID,
                                        QQ.QUESTION_TYPE,
                                        QQ.ANSWER_ID
                                    FROM
                                        QUIZ_OBJECTIVE_QUESTIONS AS QQ
                                            INNER JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QS ON QS.CLASS_ID = QQ.CLASS_ID
                                            AND QS.COURSE_ID = QQ.COURSE_ID
                                            AND QS.SET_ID = QQ.SET_ID
                                            AND QS.SETTING_ID = QQ.SETTING_ID
                                            -- AND QS.ENTRY_ID = QQ.ENTRY_ID
                                            AND QS.STUDENT_ID=?STUDENT_ID
                                            AND QS.ACADEMIC_YEAR = QQ.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        QQ.IS_DELETED != 1 AND QQ.SETTING_ID = ?SETTING_ID 
                                            AND QQ.QUIZ_ID NOT IN (SELECT 
                                            QUIZ_ID
                                        FROM
                                            QUIZ_SAVE_OBJECTIVES
                                        WHERE
                                            SETTING_ID = ?SETTING_ID AND STUDENT_ID = ?STUDENT_ID)
                                            AND QQ.COURSE_ID = ?COURSE_ID
                                            AND QQ.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY QUIZ_ID
                                    ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectivesQuizOptions:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        -- QQ.QUESTION AS QUIZ_QUESTION,
                                        QQ.SET_ID,
                                        QQ.QUESTION_TYPE,
                                        OP.OPTION_ID,
                                        OP.OPTION,
                                        OP.MARK
                                    FROM
                                        QUIZ_OBJECTIVE_QUESTIONS AS QQ
		                                    INNER JOIN
	                                    QUIZ_OBJECTIVE_OPTIONS AS OP ON OP.QUIZ_ID=QQ.QUIZ_ID AND OP.SETTING_ID = ?SETTING_ID
                                            INNER JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QS ON QS.CLASS_ID = QQ.CLASS_ID
                                            AND QS.COURSE_ID = QQ.COURSE_ID
                                            AND QS.SET_ID = QQ.SET_ID
                                            AND QS.STUDENT_ID=?STUDENT_ID
                                            AND QS.SETTING_ID = QQ.SETTING_ID
                                            -- AND QS.ENTRY_ID = QQ.ENTRY_ID
                                            AND QS.ACADEMIC_YEAR = QQ.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        QQ.IS_DELETED != 1 
                                            AND QQ.SETTING_ID = ?SETTING_ID
                                            AND QQ.COURSE_ID = ?COURSE_ID
                                            AND QQ.ACADEMIC_YEAR = ?AC_YEAR
                                            -- AND QQ.ENTRY_ID=?STAFF_ID
                                    GROUP BY OP.OPTION_ID
                                    ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseCompletedByDeptId:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(LAST_NAME, '')) AS NAME,
                                CR.PART,
                                P.PART AS PART_NAME,
                                CR.COURSE_CODE,
                                CONCAT(UGC.UGC_COURSE_TYPE,
                                        ': ',
                                        CR.COURSE_TITLE) COURSE_TITLE,
                                UGC.COURSE_ORDER,
                                SEM.SEMESTER,
                                SS.SEMESTER_NAME,
                                SEM.INTERNAL_MARK,
                                SEM.EXTERNAL_MARK,
                                SEM.COURSE_ID,
                                SEM.TOTAL,
                                IFNULL(CR.TOTAL, 100) AS MAXIMUM,
                                CP.PROGRAMME_DESCRIPTION AS PROGRAMME_NAME,
                                CPG.PROGRAMME_GROUP_ID,
                                CPG.APPTYPE_ID AS APPLICATION_TYPE_ID,
                                CR.CREDITS AS CREDIT,
                                SEM.GRADE_POINT,
                                SEM.M_PASS,
                                SEM.RESULT,
                                ES.M_EXAM,
                                DATE_FORMAT(ES.START_DATE, '%D/%M/%Y') AS START_DATE, CR.UGC_COURSE_TYPE,
                                SEM.EXAM_SETTING_ID
                            FROM
                                STU_CLASS AS ST
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON ST.STUDENT_ID = SP.STUDENT_ID AND (SP.IS_DELETED!=1 AND IS_LEFT!=1)
                                    INNER JOIN
                                CP_CLASSES AS CC ON CC.CLASS_ID = ST.CLASS_ID                                   
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID = CC.PROGRAMME_GROUP_ID
                                    AND CPG.PROGRAMME_GROUP_ID IN(?PROGRAMME_GROUP_ID)
                                    AND CPG.APPTYPE_ID = ?APPLICATION_TYPE_ID
                                    INNER JOIN
                                CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPG.PROGRAMME_ID
                                    INNER JOIN                                    
                                SEMESTER_MARKS_?AC_YEAR AS SEM ON SEM.STUDENT_ID = ST.STUDENT_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SEM.COURSE_ID
                                    LEFT JOIN
                                CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    LEFT JOIN
                                CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                    LEFT JOIN
                                SUP_PART AS P ON P.PART_ID = CR.PART
                                    LEFT JOIN
                                SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CR.SEMESTER_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = SEM.EXAM_SETTING_ID
                                    AND ES.ACADEMIC_YEAR = ?AC_YEAR 
                                INNER JOIN SUP_SHIFT AS SH ON SH.SHIFT_ID=CPG.SHIFT
                                INNER JOIN SUP_PROGRAMME_MODE AS SPM ON SPM.PROGRAMME_MODE_ID=CPG.PROGRAMME_MODE                               
                            WHERE
		                            ST.BATCH=?BATCH  GROUP BY ST.STUDENT_ID ,SEM.COURSE_ID,SEM.SEMESTER,SEM.EXAM_SETTING_ID          
                            ORDER BY SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseCompletedByApplicationType:
                    {
                        query = @"SELECT 
                                    SP.STUDENT_ID,
                                    SP.ROLL_NO,
                                    SP.REGISTER_NO,
                                    CONCAT(IFNULL(FIRST_NAME, ''),
                                            ' ',
                                            IFNULL(LAST_NAME, '')) AS NAME,
                                    CR.PART,
                                    P.PART AS PART_NAME,
                                    CR.COURSE_CODE,
                                    CONCAT(UGC.UGC_COURSE_TYPE,
                                            ': ',
                                            CR.COURSE_TITLE) COURSE_TITLE,
                                    UGC.COURSE_ORDER,
                                    SEM.SEMESTER,
                                    SS.SEMESTER_NAME,
                                    SEM.INTERNAL_MARK,
                                    SEM.EXTERNAL_MARK,
                                    SEM.COURSE_ID,
                                    SEM.EXAM_SETTING_ID,
                                    SEM.TOTAL,
                                    IFNULL(CR.TOTAL, 100) AS MAXIMUM,
                                    CP.PROGRAMME_DESCRIPTION AS PROGRAMME_NAME,
                                    CPG.PROGRAMME_GROUP_ID,
                                    IF(CPG.SHIFT=1,'D',IF(CPG.SHIFT=2,'E','F')) AS DAY_EVEN,
                                    CPG.APPTYPE_ID AS APPLICATION_TYPE_ID,
                                    CR.CREDITS AS CREDIT,
                                    SEM.GRADE_POINT,
                                    SEM.M_PASS,
                                    SEM.RESULT,
                                    ES.M_EXAM,
                                    DATE_FORMAT(ES.START_DATE, '%d/%m/%Y') AS START_DATE,
                                    CR.UGC_COURSE_TYPE,
                                    UPPER(DP.DEPARTMENT) AS DEPARTMENT,
                                    DG.DEGREE
                                FROM
                                    STU_CLASS AS ST
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON ST.STUDENT_ID = SP.STUDENT_ID
                                        AND (SP.IS_DELETED != 1 AND IS_LEFT != 1)
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = ST.CLASS_ID
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID = CC.PROGRAMME_GROUP_ID
                                        AND CPG.PROGRAMME_GROUP_ID IN(?PROGRAMME_GROUP_ID)
                                        AND CPG.APPTYPE_ID = ?APPLICATION_TYPE_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPG.PROGRAMME_ID
                                        INNER JOIN
                                    SEMESTER_MARKS_?AC_YEAR AS SEM ON SEM.STUDENT_ID = ST.STUDENT_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SEM.COURSE_ID
                                        LEFT JOIN
                                    CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                        LEFT JOIN
                                    CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                        LEFT JOIN
                                    SUP_PART AS P ON P.PART_ID = CR.PART
                                        LEFT JOIN
                                    SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CR.SEMESTER_ID
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = SEM.EXAM_SETTING_ID
                                        AND ES.ACADEMIC_YEAR = ?AC_YEAR
                                        LEFT JOIN
                                    SUP_DEGREE AS DG ON DG.DEGREE_ID = CP.DEGREE
                                        LEFT JOIN
                                    CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CP.DEPARTMENT
                                WHERE
                                    ST.BATCH=?BATCH  GROUP BY ST.STUDENT_ID ,SEM.COURSE_ID,SEM.SEMESTER,SEM.EXAM_SETTING_ID     
                                ORDER BY SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAcademicBatchid:
                    {
                        query = @"SELECT 
                                        BATCH_ID, ACADEMIC_YEAR_ID
                                    FROM
                                        ACADEMIC_BATCHES
                                    WHERE
                                        BATCH_YEAR = ?BATCH_YEAR
                                     AND ACADEMIC_YEAR_ID = ?ACADEMIC_YEAR_ID; ";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsStudentAttenQuiz:
                    {
                        query = @"SELECT QUIZ_SHUFFLE_ID AS QUIZ_ID FROM QUIZ_STUDENT_SHUFFLE WHERE STUDENT_ID=?STUDENT_ID AND SETTING_ID=?SETTING_ID AND IS_ATTEMPT=?IS_ATTEMPT AND ACADEMIC_YEAR=?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizStudentAttempt:
                    {
                        query = @"UPDATE QUIZ_STUDENT_SHUFFLE SET IS_ATTEMPT=1 WHERE STUDENT_ID=?STUDENT_ID AND SETTING_ID=?SETTING_ID;";
                        break;
                    }
                #endregion

                #region Quiz Entry By Random
                case ExaminationSQLCommands.FechOnlineQuizQuestionForRandomEntry:
                    {
                        query = @"SELECT 
                                    Q.QUIZ_ID,
                                    OP.OPTION_ID,
                                    Q.SET_ID,
                                    Q.QUESTION AS QUIZ_QUESTION,
                                    OP.QUESTION,
                                    OP.ANSWER
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS Q ON Q.CLASS_ID 
                                        AND Q.COURSE_ID = ?COURSE_ID
                                        AND Q.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND Q.IS_DELETED != 1
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS OP ON OP.QUIZ_ID = Q.QUIZ_ID
                                        AND OP.IS_DELETED!=1
                                WHERE
                                    SC.ACADEMIC_YEAR = ?AC_YEAR  AND Q.SETTING_ID=?SETTING_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.STUDENT_ID = ?STUDENT_ID
                                        ORDER BY RAND() LIMIT 20;";
                        break;
                    }
                #endregion

                #region  Quiz Result

                case ExaminationSQLCommands.OnlineQuizMatchTheFollowingResultForCourseStaff:
                    {
                        query = @"SELECT 
                                        QS.QUIZ_SAVE_ID,
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                        Q.QUIZ_ID,
                                        IFNULL(Q.MARK,0) AS MARK,
                                        Q.QUESTION AS QUIZ_QUESTION,
                                        QP.OPTION_ID,
                                        QP.QUESTION,
                                        QP.ANSWER,
                                        OP.ANSWER AS SELECTED_ANSWER,
                                        QS.STATUS
                                    FROM
                                        QUIZ_SAVE_MATCH_THE_FOLLOWING AS QS
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = QS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS Q ON Q.QUIZ_ID = QS.QUIZ_ID
                                            INNER JOIN
                                        QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS QP ON QP.QUIZ_ID = Q.QUIZ_ID
                                            AND QP.OPTION_ID = QS.OPTION_ID
                                            INNER JOIN
                                        QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS OP ON OP.QUIZ_ID = QS.QUIZ_ID
                                            AND OP.OPTION_ID = QS.ANSWER_ID
                                    WHERE
                                        QS.SETTING_ID = ?SETTING_ID
                                            AND QS.COURSE_ID = ?COURSE_ID
                                            AND QS.CLASS_ID = ?CLASS_ID
                                            AND QS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.OnlineQuizResultForMatchTheFollowing:
                    {
                        query = @"SELECT 
                                    QS.QUIZ_SAVE_ID,
                                    Q.QUIZ_ID,
                                    Q.QUESTION AS QUIZ_QUESTION,
                                    Q.QUESTION_TYPE,
                                    QP.OPTION_ID,
                                    IFNULL(Q.MARK,0) AS MARK,
                                    OP.QUESTION,
                                    OP.ANSWER,
                                    QP.ANSWER AS SELECTED_ANSWER,
                                    QS.STATUS
                                FROM
                                    QUIZ_SAVE_MATCH_THE_FOLLOWING AS QS
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS Q ON Q.QUIZ_ID = QS.QUIZ_ID
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS QP ON QP.QUIZ_ID = Q.QUIZ_ID
                                        AND QP.OPTION_ID = QS.OPTION_ID
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS OP ON OP.QUIZ_ID = QS.QUIZ_ID
                                        AND OP.OPTION_ID = QS.ANSWER_ID
                                WHERE
                                    QS.SETTING_ID = ?SETTING_ID AND QS.COURSE_ID = ?COURSE_ID
                                        AND QS.ACADEMIC_YEAR = ?AC_YEAR
                                        AND QS.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.OnlineQuizResultForObjectiveTypes:
                    {
                        query = @"SELECT 
                                        QS.QUIZ_SAVE_ID,
                                        Q.QUIZ_ID,
                                        Q.QUESTION AS QUIZ_QUESTION,
                                        Q.QUESTION_TYPE,
                                        QP.OPTION_ID,
                                        OP.OPTION,
                                         IFNULL(Q.MARK,0) AS MARK,
                                        QP.OPTION AS SELECTED_ANSWER,
                                        QS.STATUS
                                    FROM
                                        QUIZ_SAVE_OBJECTIVES AS QS
                                            INNER JOIN
                                        QUIZ_OBJECTIVE_QUESTIONS AS Q ON Q.QUIZ_ID = QS.QUIZ_ID
                                            INNER JOIN
                                        QUIZ_OBJECTIVE_OPTIONS AS QP ON QP.QUIZ_ID = Q.QUIZ_ID
                                            AND QP.OPTION_ID = QS.OPTION_ID AND  QP.SETTING_ID=?SETTING_ID 
                                            INNER JOIN
                                        QUIZ_OBJECTIVE_OPTIONS AS OP ON OP.QUIZ_ID = QS.QUIZ_ID
                                            AND OP.OPTION_ID = QS.ANSWER_ID
                                    WHERE
                                        QS.SETTING_ID = ?SETTING_ID 
                                            AND QS.COURSE_ID = ?COURSE_ID
                                            AND QS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND QS.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.OnlineQuizResultForFillInBlank:
                    {
                        query = @"SELECT 
                                        QS.QUIZ_SAVE_ID,
                                        Q.QUIZ_ID,
                                        Q.QUESTION AS QUIZ_QUESTION,
                                        Q.QUESTION_TYPE,
                                        QP.OPTION_ID,
                                        OP.OPTION,
                                         IFNULL(Q.MARK,0) AS MARK,
                                        QP.OPTION AS SELECTED_ANSWER,
                                        QS.STATUS
                                    FROM
                                        QUIZ_SAVE_FILL_IN_BLANKS AS QS
                                            INNER JOIN
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS Q ON Q.QUIZ_ID = QS.QUIZ_ID
                                            INNER JOIN
                                        QUIZ_FILL_IN_BLANK_OPTIONS AS QP ON QP.QUIZ_ID = Q.QUIZ_ID
                                            AND QP.OPTION_ID = QS.OPTION_ID
                                            INNER JOIN
                                        QUIZ_FILL_IN_BLANK_OPTIONS AS OP ON OP.QUIZ_ID = QS.QUIZ_ID
                                            AND OP.OPTION_ID = QS.ANSWER_ID
                                    WHERE
                                        QS.SETTING_ID = ?SETTING_ID
                                            AND QS.COURSE_ID = ?COURSE_ID
                                            AND QS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND QS.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ListFillInBlankQuiz:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QT.QUESTION_TYPE_ID,
                                        QT.QUESTION_TYPE,
                                        CC.CLASS_NAME,
                                        STF.FIRST_NAME,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SE.SET_NAME AS 'SET_ID',
                                        SS.SEMESTER_NAME,
                                        QQ.MARK
                                    FROM
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS STF ON STF.STAFF_ID = QQ.ENTRY_ID
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = QQ.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
		                                    INNER JOIN
	                                    SUP_QUIZ_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID=QQ.QUESTION_TYPE 
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=CCR.SEMESTER_ID
                                            LEFT JOIN
                                        SUP_SETS AS SE ON SE.SET_ID = QQ.SET_ID
                                    WHERE
                                        QQ.ENTRY_ID = ?ENTRY_ID
                                            AND QQ.SETTING_ID IN (?SETTING_ID)
                                            AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveQuizFillInBlankQuestions:
                    {
                        query = @"INSERT INTO QUIZ_FILL_IN_BLANK_QUESTIONS
                                  (                                      
                                      ENTRY_ID, 
                                      CLASS_ID, 
                                      COURSE_ID,
                                      QUESTION, 
                                      MARK, 
                                      SET_ID, 
                                      QUESTION_TYPE, 
                                      ACADEMIC_YEAR,                                      
                                      SEMESTER_ID, 
                                      SETTING_ID
                                  )
                                  VALUES
                                  (
                                      ?ENTRY_ID, 
                                      ?CLASS_ID, 
                                      ?COURSE_ID,
                                      ?QUESTION, 
                                      ?MARK, 
                                      ?SET_ID, 
                                      ?QUESTION_TYPE, 
                                      ?AC_YEAR,                                      
                                      ?SEMESTER_ID, 
                                      ?SETTING_ID
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.SaveQuizFillInBlankOptions:
                    {
                        query = @"INSERT INTO QUIZ_FILL_IN_BLANK_OPTIONS
                                    (
                                        `OPTION`,
                                        QUIZ_ID,
                                        SET_ID,
                                        SETTING_ID
                                    )
                                    VALUES
                                    (
                                        ?OPTIONS,
                                        ?QUIZ_ID,
                                        ?SET_ID,                                        
                                        ?SETTING_ID
                                    );";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizFillInBlankOptionIdByOption:
                    {
                        query = @"SELECT 
                                        OPTION_ID,
                                        `OPTION`,
                                        QUIZ_ID,
                                        SET_ID,
                                        MARK,
                                        SETTING_ID
                                    FROM
                                        QUIZ_FILL_IN_BLANK_OPTIONS
                                    WHERE
                                        `OPTION` = ?ANSWER_ID
                                            AND QUIZ_ID = ?QUIZ_ID AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizAnswerForFillInBlankQuestions:
                    {
                        query = @"UPDATE QUIZ_FILL_IN_BLANK_QUESTIONS SET ANSWER_ID=?ANSWER_ID WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankQuestionAndAnswerByQuizId:
                    {
                        query = @"SELECT 
                                    QQ.QUIZ_ID,
                                    QQ.QUESTION,
                                    QQ.QUESTION_TYPE,
                                    QQ.CLASS_ID,
                                    QQ.COURSE_ID,
                                    QQ.ANSWER_ID,
                                    OP.OPTION_ID,
                                    OP.OPTION,
                                    OP.MARK,
                                    IF(QQ.ANSWER_ID = OP.OPTION_ID,OP.OPTION,'') AS ANSWER
                                FROM
                                    QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
                                        INNER JOIN
                                    QUIZ_FILL_IN_BLANK_OPTIONS AS OP ON OP.QUIZ_ID=QQ.QUIZ_ID
                                WHERE
                                    QQ.QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankOptionsByQuizId:
                    {
                        query = @"SELECT 
                                        OPTION_ID,
                                        `OPTION`,
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QQ.CLASS_ID,
                                        QQ.COURSE_ID,
                                        QQ.ANSWER_ID,
                                        QQ.SEMESTER_ID,
                                        QQ.SET_ID,
                                        QQ.SETTING_ID,
                                        QP.MARK
                                    FROM
	                                    QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
		                                    INNER JOIN
                                        QUIZ_FILL_IN_BLANK_OPTIONS AS QP ON QP.QUIZ_ID=QQ.QUIZ_ID
                                    WHERE
                                        QQ.QUIZ_ID = ?QUIZ_ID AND QP.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizFillInTheBlankOptions:
                    {
                        query = @"UPDATE `QUIZ_FILL_IN_BLANK_OPTIONS`
                                    SET
                                    `OPTION` = ?OPTION,
                                    `MARK` = ?MARK
                                    WHERE `OPTION_ID` = ?OPTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateFillInTheBlankQuizQuestionByQuizId:
                    {
                        query = @"UPDATE QUIZ_FILL_IN_BLANK_QUESTIONS SET QUESTION=?QUESTION,MARK=?MARK WHERE QUIZ_ID=?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankQuizQuestions:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION AS QUIZ_QUESTION,
                                        QQ.SET_ID,
                                        QQ.QUESTION_TYPE,
                                        QQ.ANSWER_ID
                                    FROM
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
                                            INNER JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QS ON QS.CLASS_ID = QQ.CLASS_ID
                                            AND QS.COURSE_ID = QQ.COURSE_ID
                                            AND QS.SET_ID = QQ.SET_ID
                                            AND QS.SETTING_ID = QQ.SETTING_ID
                                            AND QS.ENTRY_ID = QQ.ENTRY_ID
                                            AND QS.STUDENT_ID=?STUDENT_ID
                                            AND QS.ACADEMIC_YEAR = QQ.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        QQ.IS_DELETED != 1 
                                            AND QQ.QUIZ_ID NOT IN(SELECT 
												QUIZ_ID
											FROM
												QUIZ_SAVE_FILL_IN_BLANKS
											WHERE
												SETTING_ID =?SETTING_ID  AND STUDENT_ID = ?STUDENT_ID)
                                            AND QQ.SETTING_ID = ?SETTING_ID
                                            AND QQ.COURSE_ID = ?COURSE_ID
                                            AND QQ.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY QUIZ_ID
                                    ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankQuizOptions:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION AS QUIZ_QUESTION,
                                        QQ.SET_ID,
                                        QQ.QUESTION_TYPE,
                                        OP.OPTION_ID,
                                        OP.OPTION,
                                        OP.MARK
                                    FROM
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
		                                    INNER JOIN
	                                    QUIZ_FILL_IN_BLANK_OPTIONS AS OP ON OP.QUIZ_ID=QQ.QUIZ_ID
                                            INNER JOIN
                                        QUIZ_STUDENT_SHUFFLE AS QS ON QS.CLASS_ID = QQ.CLASS_ID
                                            AND QS.COURSE_ID = QQ.COURSE_ID
                                            AND QS.SET_ID = QQ.SET_ID
                                            AND QS.STUDENT_ID=?STUDENT_ID
                                            AND QS.SETTING_ID = QQ.SETTING_ID
                                            AND QS.ENTRY_ID = QQ.ENTRY_ID
                                            AND QS.ACADEMIC_YEAR = QQ.ACADEMIC_YEAR
                                            AND QS.IS_DELETED != 1
                                    WHERE
                                        QQ.IS_DELETED != 1 
                                            AND QQ.SETTING_ID = ?SETTING_ID
                                            AND QQ.COURSE_ID = ?COURSE_ID
                                            AND QQ.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY OP.OPTION_ID
                                    ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.SaveFillInTheBlankQuizByStudent:
                    {
                        //query = @"INSERT INTO QUIZ_SAVE_FILL_IN_BLANKS
                        //          (
                        //              CLASS_ID,
                        //              COURSE_ID,
                        //              STUDENT_ID,
