                        //              ACADEMIC_YEAR
                        //          )
                        //          VALUES
                        //          (
                        //              ?CLASS_ID,
                        //              ?COURSE_ID,
                        //              ?STUDENT_ID,
                        //              ?QUIZ_ID,
                        //              ?OPTION_ID,
                        //              ?ANSWER_ID,
                        //              ?STATUS,
                        //              ?SETTING_ID,
                        //              ?SET_ID,
                        //              ?SEMESTER_ID,
                        //              ?AC_YEAR
                        //          );";
                        query = @"INSERT INTO QUIZ_SAVE_FILL_IN_BLANKS
                                  (
                                      CLASS_ID,
                                      COURSE_ID,
                                      STUDENT_ID,
                                      QUIZ_ID,
                                      OPTION_ID,
                                      ANSWER_ID,
                                      STATUS,
                                      SETTING_ID,
                                      SET_ID,
                                      SEMESTER_ID,
                                      ACADEMIC_YEAR,MINUTES
                                  )
                                  VALUES";
                        break;
                    }
                case ExaminationSQLCommands.GetSettingInfoByClassCourseStaffIds:
                    {
                        query = @"SELECT 
                                        SETTING_ID,
                                        SETTING_NAME
                                    FROM
                                        QUIZ_SETTING AS QS
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CLSCRSSTF_ID= QS.QUIZ_STF_ID
                                    WHERE
                                        QS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCS.CLASS_ID = ?CLASS_ID
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND CCS.STAFF_ID = ?STAFF_ID AND QS.IS_DELETED!=1 AND CCS.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.OnlineQuizObjectiveTypeResultForCourseStaff:
                    {
                        query = @"SELECT 
                                        QS.QUIZ_SAVE_ID,
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                        Q.QUIZ_ID,
                                        Q.QUESTION AS QUIZ_QUESTION,
                                        QP.OPTION_ID,
                                        OP.OPTION,
                                        IFNULL(Q.MARK,0) AS MARK,
                                        QP.OPTION AS SELECTED_ANSWER,
                                        QS.STATUS
                                    FROM
                                        QUIZ_SAVE_OBJECTIVES AS QS
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = QS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_OBJECTIVE_QUESTIONS AS Q ON Q.QUIZ_ID = QS.QUIZ_ID
                                            INNER JOIN
                                        QUIZ_OBJECTIVE_OPTIONS AS QP ON QP.QUIZ_ID = Q.QUIZ_ID
                                            AND QP.OPTION_ID = QS.OPTION_ID
                                            INNER JOIN
                                        QUIZ_OBJECTIVE_OPTIONS AS OP ON OP.QUIZ_ID = QS.QUIZ_ID
                                            AND OP.OPTION_ID = QS.ANSWER_ID
                                    WHERE
                                        QS.SETTING_ID = ?SETTING_ID
                                            AND QS.COURSE_ID = ?COURSE_ID
                                            AND QS.CLASS_ID = ?CLASS_ID
                                            AND QS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.OnlineQuizFillInBlanksResultForCourseStaff:
                    {
                        query = @"SELECT 
                                        QS.QUIZ_SAVE_ID,
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                        Q.QUIZ_ID,
                                        Q.QUESTION AS QUIZ_QUESTION,
                                        QP.OPTION_ID,
                                        OP.OPTION,
                                        IFNULL(Q.MARK,0) AS MARK,
                                        QP.OPTION AS SELECTED_ANSWER,
                                        QS.STATUS
                                    FROM
                                        QUIZ_SAVE_FILL_IN_BLANKS AS QS
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = QS.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS Q ON Q.QUIZ_ID = QS.QUIZ_ID
                                            INNER JOIN
                                        QUIZ_FILL_IN_BLANK_OPTIONS AS QP ON QP.QUIZ_ID = Q.QUIZ_ID
                                            AND QP.OPTION_ID = QS.OPTION_ID
                                            INNER JOIN
                                        QUIZ_FILL_IN_BLANK_OPTIONS AS OP ON OP.QUIZ_ID = QS.QUIZ_ID
                                            AND OP.OPTION_ID = QS.ANSWER_ID
                                    WHERE
                                        QS.SETTING_ID = ?SETTING_ID
                                            AND QS.COURSE_ID = ?COURSE_ID
                                            AND QS.CLASS_ID = ?CLASS_ID
                                            AND QS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchActiveSettingForStudentQuizEntryByClassAndCourseIds:
                    {
                        query = @"SELECT 
                                        QS.SETTING_ID,
                                        QS.SETTING_NAME,
                                        QS.TIME AS TIME,
                                        C.CLASS_ID,
                                        C.CLASS_NAME,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SP.STAFF_ID,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME,
                                        SQT.QUIZ_TYPE_NAME
                                    FROM
                                        QUIZ_SETTING AS QS
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID = QS.QUIZ_STF_ID
		                                    AND CCS.IS_DELETED!=1
                                            AND CCS.ACADEMIC_YEAR=QS.ACADEMIC_YEAR
		                                    INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=CCS.CLASS_ID
		                                    AND C.IS_DELETED!=1
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=CCS.COURSE_ID
		                                    AND CCR.IS_DELETED!=1
		                                    INNER JOIN
	                                    STF_PERSONAL_INFO AS SP ON SP.STAFF_ID=CCS.STAFF_ID
		                                    AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                         LEFT JOIN
                                        SUP_QUIZ_TYPE AS SQT ON SQT.QUIZ_TYPE_ID = QS.QUIZ_TYPE_ID
                                    WHERE
                                        CCS.CLASS_ID IN (?CLASS_ID)
                                            AND CCS.COURSE_ID IN (?COURSE_ID)
                                            AND QS.ACADEMIC_YEAR=?AC_YEAR
                                            AND CURDATE() = QS.START_DATE 
                                            AND QS.IS_ACTIVE = 1 AND QS.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.OnlineQuizResultForTimeUp:
                    {
                        query = @"SELECT 
                                        QS.QUIZ_SAVE_ID,
                                        QS.QUIZ_ID,
                                        QS.STATUS
                                    FROM
                                        QUIZ_SAVE_FILL_IN_BLANKS AS QS
                                    WHERE
                                        QS.SETTING_ID = ?SETTING_ID
                                            AND QS.COURSE_ID = ?COURSE_ID
                                            AND QS.QUIZ_ID = 0
                                            AND QS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND QS.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchMatchTheFollowingResult:
                    {
                        query = @"SELECT 
                                        STUDENT_ID,
                                        COUNT(MF.QUIZ_ID) AS QUESTION_COUNT,
                                        SUM(IF(MF.STATUS = 1, 1, 0)) AS 'STATUS',
                                        IF(COUNT(MF.QUIZ_ID) =SUM(IF(MF.STATUS = 1, 1, 0)),QQ.MARK,0) AS MARK
                                    FROM
                                        QUIZ_SAVE_MATCH_THE_FOLLOWING AS MF
		                                    INNER JOIN
	                                    QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ ON QQ.QUIZ_ID=MF.QUIZ_ID
                                    WHERE
                                        MF.ACADEMIC_YEAR = ?AC_YEAR 
                                            AND MF.CLASS_ID = ?CLASS_ID
                                            AND MF.COURSE_ID = ?COURSE_ID 
                                            AND QQ.SETTING_ID=?SETTING_ID
                                     GROUP BY MF.STUDENT_ID , MF.QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveQuizResult:
                    {
                        query = @"SELECT 
                                        STUDENT_ID,
                                        COUNT(MF.QUIZ_ID) AS QUESTION_COUNT,
                                        SUM(IF(MF.STATUS = 1, 1, 0)) AS 'STATUS',
                                        IF(COUNT(MF.QUIZ_ID) =SUM(IF(MF.STATUS = 1, 1, 0)),QQ.MARK,0) AS MARK
                                    FROM
                                        QUIZ_SAVE_OBJECTIVES AS MF
		                                    INNER JOIN
	                                    QUIZ_OBJECTIVE_QUESTIONS AS QQ ON QQ.QUIZ_ID=MF.QUIZ_ID
                                    WHERE
                                        MF.ACADEMIC_YEAR = ?AC_YEAR 
                                            AND MF.CLASS_ID = ?CLASS_ID
                                            AND MF.COURSE_ID = ?COURSE_ID 
                                            AND QQ.SETTING_ID=?SETTING_ID
                                     GROUP BY MF.STUDENT_ID , MF.QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlanksResult:
                    {
                        query = @"SELECT 
                                        STUDENT_ID,
                                        COUNT(MF.QUIZ_ID) AS QUESTION_COUNT,
                                        SUM(IF(MF.STATUS = 1, 1, 0)) AS 'STATUS',
                                        IF(COUNT(MF.QUIZ_ID) =SUM(IF(MF.STATUS = 1, 1, 0)),QQ.MARK,0) AS MARK
                                    FROM
                                        QUIZ_SAVE_FILL_IN_BLANKS AS MF
		                                    INNER JOIN
	                                    QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ ON QQ.QUIZ_ID=MF.QUIZ_ID
                                    WHERE
                                        MF.ACADEMIC_YEAR = ?AC_YEAR 
                                            AND MF.CLASS_ID = ?CLASS_ID
                                            AND MF.COURSE_ID = ?COURSE_ID 
                                            AND QQ.SETTING_ID=?SETTING_ID
                                    GROUP BY MF.STUDENT_ID , MF.QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizObjectiveQuestionBySettingId:
                    {
                        query = @"SELECT 
                                    QQ.QUIZ_ID,QQ.QUESTION, QQ.MARK, QQ.SET_ID, QQ.QUESTION_TYPE,QO.OPTION AS ANSWER_ID,ENTRY_ID
                                FROM
                                    quiz_objective_questions AS QQ
                                    
                                    INNER JOIN 
                                    QUIZ_OBJECTIVE_OPTIONS AS QO ON QO.OPTION_ID=QQ.ANSWER_ID
                                    AND QO.IS_DELETED!=1
    
                                WHERE
                                    QQ.SETTING_ID =?SETTING_ID AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizFillinTheBlanksQuestionBySettingId:
                    {
                        query = @"SELECT 
                                    QQ.QUIZ_ID,QQ.QUESTION, QQ.MARK, QQ.SET_ID, QQ.QUESTION_TYPE,QO.OPTION AS ANSWER_ID,ENTRY_ID
                                FROM
                                    quiz_fill_in_blank_questions AS QQ
                                     INNER JOIN 
                                    QUIZ_FILL_IN_BLANK_OPTIONS AS QO ON QO.OPTION_ID=QQ.ANSWER_ID
                                    AND QO.IS_DELETED!=1

                                WHERE
                                    QQ.SETTING_ID=?SETTING_ID AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizMatchTheFollowingQuestionBySettingId:
                    {
                        query = @"SELECT 
                                    QQ.QUIZ_ID,QQ.QUESTION,QQ.MARK,QQ.SET_ID,QQ.QUESTION_TYPE,ENTRY_ID
                                FROM
                                    quiz_match_the_following_questions AS QQ
                                WHERE
                                    QQ.SETTING_ID=?SETTING_ID AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizMatchTheFollowingOptionByQuizId:
                    {
                        query = @"SELECT 
                                        OPTION_ID,
                                        `ANSWER`,
                                        QQ.QUIZ_ID,
                                        QP.QUESTION
                                      
                                    FROM
	                                    quiz_match_the_following_questions AS QQ
		                                    INNER JOIN
                                        quiz_match_the_following_options AS QP ON QP.QUIZ_ID=QQ.QUIZ_ID
                                    WHERE
                                        QQ.QUIZ_ID =?QUIZ_ID AND QP.IS_DELETED!=1;";
                        break;
                    }

                #endregion

                #region Display Semester Marks For Student 
                case ExaminationSQLCommands.FetchSemesterIdsByStudentIdAndAcademicYear:
                    {
                        query = @"SELECT 
                                       SEM.SEMESTER,
                                       SC.STUDENT_ID,
	                                   B.BEGIN_YEAR,
                                       B.EXPIRED_YEAR,
                                       SEM.PROGRAMME_GROUP_ID,
                                       B.BATCH_ID AS BATCH
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                ACTIVE_YEAR = 1)
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                            AND SEM.BATCH = AB.BATCH_ID
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND SEM.IS_DELETED != 1
											INNER JOIN
										CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID=C.PROGRAMME_GROUP_ID
											INNER JOIN
										SUP_BATCH_DURATION AS B ON B.BATCH_ID=AB.BATCH_ID
											AND B.APPLICATION_TYPE_ID=PG.APPTYPE_ID
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SEM.IS_ACTIVE = 1
                                            AND SC.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllCourseFromCoursePatternByStudentId:
                    {
                        query = @"SELECT 
                                        CCP.COURSE_ID,
                                        CCP.COURSE_STRUCTURE_ID,
                                        UPPER(CCR.COURSE_CODE) AS COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS COURSE_TITLE,
                                        CCR.SEMESTER_ID
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS CCP ON CCP.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                            AND CCP.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND CCP.IS_ACTIVE=1
                                            AND CCP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                            AND CCR.SEMESTER_ID IN (?SEMESTER_ID)
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.IS_DELETED != 1
                                    ORDER BY CCR.COURSE_ROOT_ID,CCR.SEMESTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalCoursesByStudentIdAndSemesterIds:
                    {
                        query = @"SELECT 
                                        SC.COURSE_ID,
                                        UPPER(CCR.COURSE_CODE) AS COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS COURSE_TITLE,
                                        CCR.SEMESTER_ID
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                            AND CCR.SEMESTER_ID IN (?SEMESTER_ID)
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.IS_DELETED != 1 
                                        ORDER BY CCR.COURSE_ROOT_ID,CCR.SEMESTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterMarksByStudentIdAndAcademicYear:
                    {
                        //query = @"SELECT 
                        //                SEM.STUDENT_ID,
                        //                SEM.COURSE_ID AS COURSE_ROOT_ID,
                        //                SEM.INTERNAL_MARK,
                        //                SEM.EXTERNAL_MARK,
                        //                SEM.TOTAL,
                        //                UPPER(SEM.RESULT) AS RESULT,
                        //                SEM.APPLIED,
                        //                SEM.SEMESTER,
                        //                SEM.GRADE,
                        //                SEM.GRADE_POINT,
                        //                CCR.CREDITS AS CREDIT,
                        //                CCR.COURSE_CODE,
                        //                CCR.COURSE_TITLE,
                        //                UPPER(SEM.M_PASS) AS M_PASS
                        //            FROM
                        //                SEMESTER_MARKS_?AC_YEAR AS SEM
                        //                    INNER JOIN
                        //                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=SEM.COURSE_ID
                        //            WHERE
                        //                SEM.STUDENT_ID = ?STUDENT_ID ORDER BY CCR.SEMESTER_ID,SEM.EXAM_SETTING_ID,CCR.PART;";
                        query = @"SELECT 
                                        SEM.STUDENT_ID,
                                        SEM.COURSE_ID AS COURSE_ROOT_ID,
                                        SEM.INTERNAL_MARK,
                                        SEM.EXTERNAL_MARK,
                                        SEM.TOTAL,
                                        UPPER(SEM.RESULT) AS RESULT,
                                        SEM.APPLIED,
                                        SEM.SEMESTER,
                                        SEM.GRADE,
                                        SEM.GRADE_POINT,
                                        CCR.CREDITS AS CREDIT,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        UPPER(SEM.M_PASS) AS M_PASS,
                                        SEM.EXAM_SETTING_ID
                                    FROM
                                        SEMESTER_MARKS_?AC_YEAR AS SEM
                                    INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SEM.COURSE_ID
                                    INNER JOIN
                                        exam_setting AS es ON es.exam_setting_id = sem.exam_setting_id
                                    LEFT JOIN
                                        exam_defaulters AS ed ON ed.exam_setting_id = sem.exam_setting_id
                                        AND ed.STUDENT_ID = SEM.STUDENT_ID  
                                    WHERE
                                        (ed.IS_DELETED IS NULL OR ed.IS_DELETED != 0 OR ed.exam_setting_id IS NULL)
                                    AND 
                                        SEM.STUDENT_ID = ?STUDENT_ID
                                    ORDER BY 
                                        CCR.SEMESTER_ID, SEM.EXAM_SETTING_ID, CCR.PART;";
                        //query = @"SELECT 
                        //                SEM.STUDENT_ID,
                        //                SEM.COURSE_ID AS COURSE_ROOT_ID,
                        //                SEM.INTERNAL_MARK,
                        //                SEM.EXTERNAL_MARK,
                        //                SEM.TOTAL,
                        //                UPPER(SEM.RESULT) AS RESULT,
                        //                SEM.APPLIED,
                        //                SEM.SEMESTER,
                        //                SEM.GRADE,
                        //                SEM.GRADE_POINT,
                        //                CCR.CREDITS AS CREDIT,
                        //                UPPER(SEM.M_PASS) AS M_PASS
                        //            FROM
                        //                SEMESTER_MARKS_?AC_YEAR AS SEM
                        //                    INNER JOIN
                        //                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=SEM.COURSE_ID
                        //            WHERE
                        //                SEM.STUDENT_ID = ?STUDENT_ID ORDER BY SEM.COURSE_ID,SEM.SEMESTER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemeterIdByBatchAndAcYear:
                    {
                        query = @"SELECT 
	                                ACC_SEMESTER_ID,
                                    BATCH,
                                    PROGRAMME_GROUP_ID,
                                    GROUP_CONCAT(SEMESTER) AS SEMESTER,
                                    ACADEMIC_YEAR,
                                    IS_ACTIVE
                                FROM
                                    ACADEMIC_SEMESTER
                                WHERE
                                    ACADEMIC_YEAR = ?AC_YEAR AND BATCH = ?BATCH
                                        AND PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
                                        AND IS_DELETED != 1 ;";
                        break;
                    }
                #endregion

                #region InternalAssesmentForRescapes
                case ExaminationSQLCommands.FetchCIAComponentsByCourseIdForRescapes:
                    {
                        query = @"SELECT 
                                ''AS COURSE_GROUP_MARK,'' AS CIA_GROUP_MARK_ID, CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_CLASS AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                        INNER JOIN 
                                    SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN 
                                    CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                        AND CT.IS_DELETED != 1
                                        INNER JOIN 
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                        AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                        AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                    INNER JOIN 
                                CLASSCOURSESTAFFFORRESCAPES AS CC ON CC.CLASS_ID=CLS.CLASS_ID 
                                    AND CC.COURSE_ID=?COURSE_ID 
                                    AND CC.IS_DELETED!=1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CLS.IS_DELETED != 1   AND SP.IS_LEFT!=1
                            UNION SELECT 
                               ''AS COURSE_GROUP_MARK,'' AS CIA_GROUP_MARK_ID,  CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,                               
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                        INNER JOIN 
                                    SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN 
                                    CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                        AND CT.IS_DELETED != 1
                                        INNER JOIN 
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                        AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                        AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1  AND SP.IS_LEFT!=1 ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoByCourseIdForRescapes:
                    {
                        query = @"SELECT 
                                        DP.DEPARTMENT,
                                        CLS.CLASS_NAME,
                                        CR.COURSE_CODE,
                                        CR.SEMESTER_ID,
                                        UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE',
                                        CT.INTERNAL,
                                        UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                                        '',
                                                        SP.FIRST_NAME),
                                                    ' ',
                                                    IF(SP.LAST_NAME IS NULL,
                                                        '',
                                                        SP.LAST_NAME))) AS STAFF_NAME,
                                        SP.STAFF_ID,
                                        CR.COURSE_TYPE
                                    FROM
                                        CLASSCOURSESTAFFFORRESCAPES AS CC
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CC.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CC.CLASS_ID
                                            INNER JOIN
                                        CP_DEPARTMENT AS DP ON CR.DEPARTMENT = DP.DEPARTMENT_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CC.STAFF_ID
                                            INNER JOIN
                                        CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                    WHERE
                                        CC.COURSE_ID = ?COURSE_ID AND CC.CLASS_ID=?CLASS_ID -- AND CC.IS_PRIMARY_STAFF=1
                                            AND CC.ACADEMIC_YEAR = ?AC_YEAR LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllClassesByStaffIdForRescapes:
                    {
                        query = @"SELECT 
                                        C.CLASS_ID,
                                        C.CLASS_NAME
                                    FROM
                                        CLASSCOURSESTAFFFORRESCAPES AS CCS
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = CCS.CLASS_ID
                                    WHERE
                                        CCS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCS.STAFF_ID = ?STAFF_ID
                                            AND CCS.IS_DELETED != 1 GROUP BY CCS.CLASS_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchAllCoursesByClassAndStaffIdsForRescapes:
                    {
                        query = @"SELECT 
                                        CCR.COURSE_ROOT_ID,
                                        CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                ' ( ',
                                                IFNULL(CCR.COURSE_CODE, ''),
                                                ' ) ') AS COURSE_TITLE
                                    FROM
                                        CLASSCOURSESTAFFFORRESCAPES AS CCS
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                    WHERE
                                        CCS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCS.CLASS_ID = ?CLASS_ID
                                            AND CCS.STAFF_ID = ?STAFF_ID
                                            AND CCS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentsForRescapesCIAEntry:
                    {
                        query = @"SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_CLASS AS CLS
                                    LEFT JOIN
                                CIA_RESCAPES_MARKS AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                                    INNER JOIN
                                CLASSCOURSESTAFFFORRESCAPES AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                    AND CC.COURSE_ID = ?COURSE_ID AND CC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CC.IS_DELETED != 1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CLS.IS_DELETED != 1 
                            UNION SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_COURSE_INFO AS CLS
                                    LEFT JOIN
                                CIA_RESCAPES_MARKS AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.BindCIAMarksReportForRescapes:
                    {
                        query = @"SELECT
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,
                                    REGISTER_NO,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                        ((SUM(IF(COURSE_GROUP_MARK = -1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            SP.REGISTER_NO,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_CLASS AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_RESCAPES_MARKS AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    INNER JOIN CLASSCOURSESTAFFFORRESCAPES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.COURSE_ID = ?COURSE_ID AND CC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CC.IS_DELETED != 1
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID AND CGM.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                UNION SELECT
                                    SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,
                                    REGISTER_NO,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                        ((SUM(IF(COURSE_GROUP_MARK = -1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            SP.REGISTER_NO,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_COURSE_INFO AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_RESCAPES_MARKS AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    WHERE
                                        SC.S_CLASS_ID = ?CLASS_ID AND SC.COURSE_ID = ?COURSE_ID
                                             AND SC.ACADEMIC_YEAR=?AC_YEAR
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.BindCIAComponentMarksReportForRescapes:
                    {
                        query = @"SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CG.MAX_MARK,
                                CG.ORDER_ID,
                                CG.CIA_GROUP_ID,
                                COURSE_GROUP_ID,
                                CG.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_RESCAPES_MARKS AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID 
                                    AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CG ON CG.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CG.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CG.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                                    INNER JOIN 
                                CLASSCOURSESTAFFFORRESCAPES AS CC ON CC.CLASS_ID = SC.CLASS_ID 
                                    AND CC.COURSE_ID=?COURSE_ID 
                                    AND CC.ACADEMIC_YEAR=?AC_YEAR
                            WHERE
                                SC.CLASS_ID = ?CLASS_ID                                    
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1 
                            UNION SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_RESCAPES_MARKS AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID 
                                    AND CGM.COURSE_ID = ?COURSE_ID 
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                            WHERE
                                SC.S_CLASS_ID = ?CLASS_ID and SC.COURSE_ID=?COURSE_ID
                                    AND SC.IS_DELETED != 1 AND SC.ACADEMIC_YEAR=?AC_YEAR
                            ORDER BY ORDER_ID , REGISTER_NO;";
                        break;
                    }
                #endregion

                #region Online Examination Setting
                case ExaminationSQLCommands.FetchOnlineExamSettingList:
                    {
                        query = @"SELECT 
	                                    ES.EXAM_SETTING_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        C.CLASS_NAME,
                                        SS.SESSION_NAME,
                                        DATE_FORMAT(ES.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                        ES.TIME,
                                        ES.IS_ACTIVE,
                                        ES.NO_OF_QUESTIONS,
                                        ES.EACH_QUESTION_MARKS,
                                        ES.TOTAL_MARK
                                    FROM
                                        ONLINE_EXAM_SETTING AS ES
                                            INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=es.CLASS_ID
		                                    INNER JOIN
	                                    SUP_SESSION AS SS ON SS.SESSION_ID=ES.SESSION_ID
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=ES.COURSE_ID
                                    WHERE ES.ACADEMIC_YEAR=?AC_YEAR AND ES.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamSettingStudentList:
                    {
                        query = @"SELECT 
	                                    ES.EXAM_SETTING_ID,
                                        SC.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        C.CLASS_NAME,
                                        SS.SESSION_NAME,
                                        DATE_FORMAT(ES.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                        ES.TIME,
                                        ES.IS_ACTIVE
                                        
                                    FROM
                                        ONLINE_EXAM_SETTING AS ES
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.CLASS_ID = ES.CLASS_ID
		                                    AND FIND_IN_SET(SC.STUDENT_ID,ES.STUDENT_ID)
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            INNER JOIN
	                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=SC.STUDENT_ID
		                                    AND SP.IS_DELETED!=1 
		                                    AND SP.IS_LEFT!=1
                                            INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
		                                    INNER JOIN
	                                    SUP_SESSION AS SS ON SS.SESSION_ID=ES.SESSION_ID
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=ES.COURSE_ID
                                            
                                    WHERE 
                                        ES.ACADEMIC_YEAR=?AC_YEAR 
                                        AND ES.EXAM_SETTING_ID=?EXAM_SETTING_ID 
                                        AND ES.IS_DELETED!=1;";

                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamSettingById:
                    {
                        query = @"SELECT 
                                        EXAM_SETTING_ID,
                                        CLASS_ID,
                                        COURSE_ID,
                                        STUDENT_ID,
                                        DATE_FORMAT(EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                        TIME,
                                        SESSION_ID,
                                        ACADEMIC_YEAR,
                                        STAFF_ID,
                                        NO_OF_QUESTIONS,
                                        QUESTIONS_TO_ATTEN,
                                        EACH_QUESTION_MARKS,
                                        TOTAL_MARK,
                                        SEMESTER_ID,
                                        IS_ACTIVE
                                    FROM
                                        ONLINE_EXAM_SETTING
                                    WHERE
                                        EXAM_SETTING_ID = ?EXAM_SETTING_ID AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateOnlineExamSetting:
                    {
                        query = @"UPDATE ONLINE_EXAM_SETTING
                                  SET
                                  CLASS_ID =?CLASS_ID,
                                  COURSE_ID =?COURSE_ID,
                                  STUDENT_ID =?STUDENT_ID,
                                  EXAM_DATE =?EXAM_DATE,
                                  TIME =?TIME,
                                  SESSION_ID =?SESSION_ID,
                                  NO_OF_QUESTIONS =?NO_OF_QUESTIONS,
                                  QUESTIONS_TO_ATTEN=?QUESTIONS_TO_ATTEN,
                                  EACH_QUESTION_MARKS =?EACH_QUESTION_MARKS,
                                  TOTAL_MARK =?TOTAL_MARK,
                                  SEMESTER_ID =?SEMESTER_ID,
                                  IS_ACTIVE =?IS_ACTIVE 
                                  WHERE EXAM_SETTING_ID =?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.InsertOnlineExamSetting:
                    {
                        query = @"INSERT INTO ONLINE_EXAM_SETTING
                                  (
                                      CLASS_ID,
                                      COURSE_ID,
                                      STUDENT_ID,
                                      EXAM_DATE,
                                      TIME,
                                      SESSION_ID,
                                      ACADEMIC_YEAR,
                                      STAFF_ID,
                                      NO_OF_QUESTIONS,
                                      QUESTIONS_TO_ATTEN,
                                      EACH_QUESTION_MARKS,
                                      TOTAL_MARK,
                                      SEMESTER_ID,
                                      IS_ACTIVE
                                  )
                                  VALUES
                                  (
                                      ?CLASS_ID ,
                                      ?COURSE_ID ,
                                      ?STUDENT_ID ,
                                      ?EXAM_DATE ,
                                      ?TIME ,
                                      ?SESSION_ID ,
                                      ?AC_YEAR ,
                                      ?STAFF_ID ,
                                      ?NO_OF_QUESTIONS ,
                                      ?QUESTIONS_TO_ATTEN,
                                      ?EACH_QUESTION_MARKS ,
                                      ?TOTAL_MARK ,
                                      ?SEMESTER_ID ,
                                      ?IS_ACTIVE 
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.DeleteOnlineExamSetting:
                    {
                        query = @"UPDATE ONLINE_EXAM_SETTING SET IS_DELETED=?IS_DELETED WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateIsActiveOnlineExamSetting:
                    {
                        query = @"UPDATE ONLINE_EXAM_SETTING SET IS_ACTIVE=?IS_ACTIVE WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteStudentInExamSetting:
                    {
                        query = @"UPDATE ONLINE_EXAM_SETTING 
                                SET 
                                    STUDENT_ID = REPLACE(STUDENT_ID, ',?STUDENT_ID', '')
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND STUDENT_ID LIKE '%,?STUDENT_ID%';";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingByClassAndCourseId:
                    {
                        query = @"SELECT 
                                        EXAM_SETTING_ID,
                                        EXAM_DATE,
                                        TIME
                                    FROM
                                        ONLINE_EXAM_SETTING
                                    WHERE
                                        CLASS_ID = ?CLASS_ID AND COURSE_ID = ?COURSE_ID
                                            AND ACADEMIC_YEAR = ?AC_YEAR AND IS_ACTIVE=1 AND IS_DELETED!=1;";
                        break;
                    }
                #endregion

                #region Online Examination Questions
                case ExaminationSQLCommands.FetchOnlineExamQuestionList:
                    {
                        query = @"SELECT 
                                        Q.EXAM_QUESTIONS_ID,
	                                    C.CLASS_ID,
                                        C.CLASS_NAME,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        Q.QUESTION AS QUESTIONS
                                    FROM
                                        ONLINE_EXAM_QUESTIONS AS Q
		                                    INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=Q.CLASS_ID
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=Q.COURSE_ID
                                    WHERE
                                        Q.CLASS_ID = ?CLASS_ID AND Q.COURSE_ID = ?COURSE_ID
                                            AND Q.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND Q.ACADEMIC_YEAR = ?AC_YEAR
                                            AND Q.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamQuestionById:
                    {
                        query = @"SELECT 
                                        EXAM_QUESTIONS_ID,
                                        CLASS_ID,
                                        COURSE_ID,
                                        EXAM_SETTING_ID,
	                                    DATE_FORMAT(ENTRY_DATE,'%d/%m/%Y')AS ENTRY_DATE,
                                        QUESTION
                                    FROM
                                        ONLINE_EXAM_QUESTIONS
                                    WHERE
                                        EXAM_QUESTIONS_ID = ?EXAM_QUESTIONS_ID
                                            AND ACADEMIC_YEAR=?AC_YEAR
                                            AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.IsOnlineExamQuestionExist:
                    {
                        query = @"SELECT 
                                    EXAM_QUESTIONS_ID,
                                    CLASS_ID,
                                    COURSE_ID,
                                    EXAM_SETTING_ID,
                                    ENTRY_DATE,
                                    QUESTION
                                FROM
                                    ONLINE_EXAM_QUESTIONS
                                WHERE
                                    CLASS_ID = ?CLASS_ID 
                                        AND COURSE_ID = ?COURSE_ID
                                        AND QUESTION=?QUESTION
                                        AND ACADEMIC_YEAR = ?AC_YEAR AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteOnlineExamQuestion:
                    {
                        query = @"UPDATE ONLINE_EXAM_QUESTIONS SET IS_DELETED=1 WHERE EXAM_QUESTIONS_ID=?EXAM_QUESTIONS_ID;";
                        break;
                    }
                #endregion

                #region Online Examination Answers
                case ExaminationSQLCommands.FetchSettingAndStudentInfo:
                    {
                        query = @"SELECT 
                                        ES.EXAM_SETTING_ID,
                                        DATE_FORMAT(ES.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                        CONCAT(IFNULL(SS.SESSION_NAME,''),' ( ',IFNULL(SS.DESCRIPTION,''),' )') AS SESSION_NAME,
                                        ES.TIME,
                                        ES.NO_OF_QUESTIONS,
                                        ES.QUESTIONS_TO_ATTEN,
                                        ES.EACH_QUESTION_MARKS,
                                        ES.TOTAL_MARK,
                                        UPPER(S.SEMESTER_NAME) AS SEMESTER_NAME,
                                        UPPER(C.CLASS_NAME) AS CLASS_NAME,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        UPPER(CCR.COURSE_TITLE) AS COURSE_TITLE,
                                        UPPER(CCR.COURSE_CODE) AS COURSE_CODE,
                                        UPPER(SP.ROLL_NO) AS ROLL_NO,
                                        UPPER(SP.ADMISSION_NO) AS ADMISSION_NO,
                                        UPPER(SP.REGISTER_NO) AS REGISTER_NO,
                                        UPPER(CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,''))) AS FIRST_NAME,
                                        SP.PHOTO,
                                        UPPER(D.DEPARTMENT) AS DEPARTMENT,
                                        IF(SUB.SUBMIT_ID IS NULL,0,1) AS 'STATUS'
                                    FROM
                                        ONLINE_EXAM_SETTING AS ES
		                                    INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=ES.CLASS_ID
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=ES.COURSE_ID
		                                    INNER JOIN
	                                    SUP_SESSION AS SS ON SS.SESSION_ID=ES.SESSION_ID
                                        --    AND SS.START_TIME <=TIME_FORMAT(CURRENT_TIME(),'%h:%i:%s') AND SS.END_TIME>=TIME_FORMAT(CURRENT_TIME(),'%h:%i:%s')
		                                    INNER JOIN
	                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=?STUDENT_ID
		                                    AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                            INNER JOIN
	                                    SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID=ES.SEMESTER_ID
		                                    INNER JOIN
	                                    CP_DEPARTMENT AS D  ON D.DEPARTMENT_ID=C.DEPARTMENT
                                            LEFT JOIN
										ONLINE_EXAM_SUBMITTED AS SUB ON SUB.STUDENT_ID=SP.STUDENT_ID
											AND SUB.EXAM_SETTING_ID=ES.EXAM_SETTING_ID
                                    WHERE
                                        ES.IS_DELETED != 1
                                            AND ES.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ES.EXAM_DATE=CURDATE() 
                                            AND ES.IS_ACTIVE=1 
                                            AND FIND_IN_SET(?STUDENT_ID,ES.STUDENT_ID);";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuestionsForstudentOnlineExam:
                    {
                        query = @"SELECT 
                                        Q.EXAM_QUESTIONS_ID,
                                        Q.CLASS_ID,
                                        Q.COURSE_ID,
                                        Q.EXAM_SETTING_ID,
                                        DATE_FORMAt(ENTRY_DATE,'%d/%m/%Y') AS ENTRY_DATE,
                                        Q.QUESTION,
                                        Q.ACADEMIC_YEAR,
                                        Q.STAFF_ID,
                                        Q.SEMESTER_ID
                                    FROM
                                        ONLINE_EXAM_QUESTIONS AS Q
                                    WHERE
                                         Q.IS_DELETED != 1 
                                       --  AND Q.ACADEMIC_YEAR = ?AC_YEAR 
                                         AND Q.EXAM_SETTING_ID=?EXAM_SETTING_ID ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAnswersByQuestionId:
                    {
                        query = @"SELECT 
                                        EXAM_ANSWER_ID,
                                        CLASS_ID,
                                        COURSE_ID,
                                        STUDENT_ID,
                                        EXAM_SETTING_ID,
                                        ENTRY_DATE,
                                        QUESTION_ID,
                                        ANSWER
                                    FROM
                                        ONLINE_EXAM_ANSWERS
                                    WHERE
                                        ACADEMIC_YEAR = ?AC_YEAR
                                            AND STUDENT_ID = ?STUDENT_ID
                                            AND QUESTION_ID = ?QUESTION_ID AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseAndStudentInfo:
                    {
                        query = @"SELECT 
                                        ES.EXAM_SETTING_ID,
                                        DATE_FORMAT(ES.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                        CONCAT(IFNULL(SS.SESSION_NAME,''),' ( ',IFNULL(SS.DESCRIPTION,''),' )') AS SESSION_NAME,
                                        ES.TIME,
                                        ES.NO_OF_QUESTIONS,
                                        ES.QUESTIONS_TO_ATTEN,
                                        ES.EACH_QUESTION_MARKS,
                                        ES.TOTAL_MARK,
                                        CCR.SEMESTER_ID,
                                        UPPER(S.SEMESTER_NAME) AS SEMESTER_NAME,
                                        C.CLASS_ID,
                                        ES.ACADEMIC_YEAR,
                                        UPPER(C.CLASS_NAME) AS CLASS_NAME,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        UPPER(CCR.COURSE_TITLE) AS COURSE_TITLE,
                                        UPPER(CCR.COURSE_CODE) AS COURSE_CODE,
                                        SP.STUDENT_ID,
                                        UPPER(SP.ROLL_NO) AS ROLL_NO,
                                        UPPER(SP.ADMISSION_NO) AS ADMISSION_NO,
                                        UPPER(SP.REGISTER_NO) AS REGISTER_NO,
                                        UPPER(CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,''))) AS FIRST_NAME,
                                        SP.PHOTO,
                                        UPPER(D.DEPARTMENT) AS DEPARTMENT
                                    FROM
                                        ONLINE_EXAM_SETTING AS ES
		                                    INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=ES.CLASS_ID
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=ES.COURSE_ID
		                                    INNER JOIN
	                                    SUP_SESSION AS SS ON SS.SESSION_ID=ES.SESSION_ID
		                                    INNER JOIN
	                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=?STUDENT_ID
		                                    AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                            INNER JOIN
	                                    SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID=ES.SEMESTER_ID
		                                    INNER JOIN
	                                    CP_DEPARTMENT AS D  ON D.DEPARTMENT_ID=C.DEPARTMENT
                                    WHERE
                                        ES.IS_DELETED != 1
                                            AND ES.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ES.EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineExamAnswers:
                    {
                        query = @"INSERT INTO online_exam_answers
                                  (
	                                  CLASS_ID,
	                                  COURSE_ID,
	                                  STUDENT_ID,
	                                  EXAM_SETTING_ID,
	                                  ENTRY_DATE,
	                                  QUESTION_ID,
	                                  ANSWER,
	                                  SEMESTER_ID,
	                                  TIME_DURATION,
	                                  ACADEMIC_YEAR
                                  )
                                  VALUES
                                  (
	                                  ?CLASS_ID,
	                                  ?COURSE_ID,
	                                  ?STUDENT_ID,
	                                  ?EXAM_SETTING_ID,
	                                  ?ENTRY_DATE,
	                                  ?QUESTION_ID,
	                                  ?ANSWER,
	                                  ?SEMESTER_ID,
	                                  ?TIME_DURATION,
	                                  ?ACADEMIC_YEAR
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateOnlineExamAnswers:
                    {
                        query = @"UPDATE ONLINE_EXAM_ANSWERS
                                  SET
                                  ANSWER = ?ANSWER
                                  WHERE EXAM_ANSWER_ID = ?EXAM_ANSWER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineExamSubmittion:
                    {
                        query = @"INSERT INTO ONLINE_EXAM_SUBMITTED
                                    (
	                                    CLASS_ID,
	                                    COURSE_ID,
	                                    STUDENT_ID,
	                                    EXAM_SETTING_ID,
	                                    SEMESTER_ID,
	                                    TIME_DURATION,
	                                    STATUS,
	                                    ACADEMIC_YEAR
                                    )
                                    VALUES
                                    (
                                        ?CLASS_ID,
	                                    ?COURSE_ID,
	                                    ?STUDENT_ID,
	                                    ?EXAM_SETTING_ID,
	                                    ?SEMESTER_ID,
	                                    ?TIME_DURATION,
	                                    ?STATUS,
	                                    ?ACADEMIC_YEAR
                                    );";
                        break;
                    }
                #endregion

                #region Exam Fee Mapping - Ugc Type Cost

                case ExaminationSQLCommands.FetchUGCTypeCostList:
                    {
                        query = @"SELECT 
                                        EC.UGC_TYPE_COST_ID,
                                        EC.TITLE,
                                        EC.UGC_COURSE_TYPE_ID,
                                         SST.SUBJECT_TYPE,
                                        EC.PROGRAMME_TYPE_ID,
                                        APP.APPLICATION_TYPE,
                                        EC.EXAM_SETTING_ID,
                                        EC.COST,
                                        EC.STAFF_ID,
                                        DATE_FORMAT(EC.ENTRY_DATE,'%d/%m/%Y') AS ENTRY_DATE,
 CONCAT(ST.EXAM_NAME, '-', ST.ACADEMIC_YEAR) AS EXAM_NAME, DATE_FORMAT(ST.last_date_for_exam_fee, '%d/%m/%Y') AS LAST_DATE_FOR_EXAM_FEE
                                    FROM
                                        EXAM_UGC_COURSE_TYPE_COST AS EC
		                                    INNER JOIN
	                                     SUP_SUBJECT_TYPE AS SST ON SST.SUBJECT_TYPE_ID=EC.UGC_COURSE_TYPE_ID
		                                    INNER JOIN
	                                    SUP_APPLICATION_TYPE AS APP ON APP.APPLICATION_TYPE_ID=EC.PROGRAMME_TYPE_ID
		                                    INNER JOIN
	                                    EXAM_SETTING AS ST ON ST.EXAM_SETTING_ID=EC.EXAM_SETTING_ID
		                                    AND ST.IS_ACTIVE=1 AND ST.IS_DELETED!=1
                                    WHERE 
                                        EC.ACADEMIC_YEAR=?AC_YEAR
                                        AND EC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchUGCTypeCostById:
                    {
                        query = @"SELECT 
                                        UGC_TYPE_COST_ID,
                                        TITLE,
                                        UGC_COURSE_TYPE_ID,
                                        PROGRAMME_TYPE_ID,
                                        EXAM_SETTING_ID,
                                        COST,
                                        STAFF_ID,
                                        DATE_FORMAT(ENTRY_DATE,'%d/%m/%Y') AS ENTRY_DATE
                                    FROM
                                        EXAM_UGC_COURSE_TYPE_COST WHERE 
                                        UGC_TYPE_COST_ID=?UGC_TYPE_COST_ID
                                        AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveUGCTypeCostInfo:
                    {
                        query = @"INSERT INTO EXAM_UGC_COURSE_TYPE_COST
                                  (
	                                  TITLE,
	                                  UGC_COURSE_TYPE_ID,
	                                  PROGRAMME_TYPE_ID,
	                                  EXAM_SETTING_ID,
	                                  COST,
	                                  STAFF_ID,
	                                  ACADEMIC_YEAR
                                  )
                                  VALUES
                                  (
	                                  ?TITLE,
	                                  ?UGC_COURSE_TYPE_ID,
	                                  ?PROGRAMME_TYPE_ID,
	                                  ?EXAM_SETTING_ID,
	                                  ?COST,
	                                  ?STAFF_ID,
	                                  ?AC_YEAR
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateUGCTypeCostInfo:
                    {
                        query = @"UPDATE EXAM_UGC_COURSE_TYPE_COST
                                    SET
                                    TITLE =?TITLE ,
                                    UGC_COURSE_TYPE_ID =?UGC_COURSE_TYPE_ID ,
                                    PROGRAMME_TYPE_ID =?PROGRAMME_TYPE_ID ,
                                    EXAM_SETTING_ID =?EXAM_SETTING_ID ,
                                    COST =?COST ,
                                    STAFF_ID =?STAFF_ID 
                                    WHERE UGC_TYPE_COST_ID =?UGC_TYPE_COST_ID;";
                        break;
                    }
                case ExaminationSQLCommands.IsExistUGCTypeCostInfo:
                    {
                        query = @"SELECT 
                                        UGC_TYPE_COST_ID
                                    FROM
                                        EXAM_UGC_COURSE_TYPE_COST
                                    WHERE
                                        UGC_COURSE_TYPE_ID = ?UGC_COURSE_TYPE_ID
                                            AND EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteUGCTypeCostInfo:
                    {
                        query = @"UPDATE EXAM_UGC_COURSE_TYPE_COST SET IS_DELETED=1 WHERE UGC_TYPE_COST_ID=?UGC_TYPE_COST_ID;";
                        break;
                    }
                #endregion

                #region Exam Fee Mapping - Course Wise Cost 
                // Exam Course Wise Cost List ,...
                case ExaminationSQLCommands.FetchExamCourseWiseCost:
                    {
                        query = @"SELECT 
                                        EX.COURSE_WISE_COST_ID,
                                        IF(EXAM_TYPE_ID = 1, 'R', 'AR') AS EXAM_TYPE_ID,
                                        SST.SUBJECT_TYPE_ID,
                                        SST.SUBJECT_TYPE,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,   
                                        EX.UGC_TYPE_COST_ID,
                                        CONCAT(IFNULL(CT.TITLE, ''),
                                                ' ',
                                                IFNULL(CT.COST, '')) AS TITLE,
                                        APP.APPLICATION_TYPE
                                    FROM
                                        EXAM_COURSE_WISE_COST AS EX
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EX.COURSE_ID AND CCR.IS_DELETED!=1
                                            INNER JOIN
                                        EXAM_UGC_COURSE_TYPE_COST AS CT ON CT.UGC_TYPE_COST_ID = EX.UGC_TYPE_COST_ID AND CT.IS_DELETED!=1
                                            INNER JOIN
                                        SUP_SUBJECT_TYPE AS SST ON SST.SUBJECT_TYPE_ID = CT.UGC_COURSE_TYPE_ID
                                            INNER JOIN
                                        SUP_APPLICATION_TYPE AS APP ON APP.APPLICATION_TYPE_ID = CT.PROGRAMME_TYPE_ID
                                        INNER JOIN 
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID=EX.EXAM_SETTING_ID
                                        AND ES.IS_ACTIVE=1 AND ES.IS_DELETED != 1
                                    WHERE                                   
                                             EX.IS_DELETED != 1
                                            AND EX.ACADEMIC_YEAR = ?AC_YEAR
                                           ;";
                        break;
                    }

                // Exam Course Wise Cost Add Or Edit ,..
                case ExaminationSQLCommands.FetchExamCourseWiseCostAddOrEdit:
                    {
                        query = @"SELECT 
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        CCR.SUBJECT_TYPE,
                                        EC.COURSE_WISE_COST_ID,
                                        EC.UGC_TYPE_COST_ID,
                                        ES.EXAM_SETTING_ID,
                                        PG.APPTYPE_ID AS PROGRAMME_TYPE_ID,
                                        APT.APPLICATION_TYPE AS PROGRAMME_TYPE
                                    FROM
                                        CP_COURSE_STRUCTURE AS CS
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS CCP ON CCP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                            AND CCP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                            AND CCR.IS_DELETED != 1
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            AND SEM.SEMESTER = CS.SEMESTER_ID
                                            AND SEM.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SEM.IS_ACTIVE = 1
                                            AND SEM.IS_DELETED != 1
                                            INNER JOIN
                                        cp_programme_group AS PG ON PG.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        SUP_APPLICATION_TYPE AS APT ON APT.APPLICATION_TYPE_ID = PG.APPTYPE_ID
                                            AND APT.IS_DELETED != 1
                                            LEFT JOIN
                                        EXAM_COURSE_WISE_COST AS EC ON EC.COURSE_ID = CCR.COURSE_ROOT_ID
                                            AND EC.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                            AND EC.IS_DELETED != 1 
                                            AND EC.EXAM_SETTING_ID = (SELECT 
                                                EXAM_SETTING_ID
                                            FROM
                                                EXAM_SETTING
                                            WHERE
                                                ACADEMIC_YEAR = ?AC_YEAR AND IS_ACTIVE = 1
                                                    AND IS_DELETED != 1)                                          
                                            LEFT JOIN
                                        EXAM_PROGRAMME_TYPE_SETTING AS PS ON PS.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND PS.IS_ACTIVE=1
                                            LEFT JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PS.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE = 1
                                            AND ES.IS_DELETED != 1
                                    WHERE
                                        CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCR.SUBJECT_TYPE = ?SUBJECT_TYPE_ID
                                            AND CS.PROGRAMME_YEAR = ?PROGRAMME_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY CCR.COURSE_ROOT_ID ORDER BY PG.APPTYPE_ID,CCR.PART,CCR.SEMESTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamUGCCourseTypeCostForDDL:
                    {
                        query = @"SELECT 
                                        UGC.UGC_TYPE_COST_ID,
                                        UGC.UGC_COURSE_TYPE_ID,
                                        CONCAT(IFNULL(UGC.TITLE, ''),
                                                ' ( ',
                                                IFNULL(UGC.COST, ''),
                                                ' ) ') AS TITLE,
                                        UGC.PROGRAMME_TYPE_ID
                                    FROM
                                        EXAM_UGC_COURSE_TYPE_COST AS UGC
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = UGC.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE = 1
                                            AND ES.IS_DELETED != 1
                                    WHERE
                                        UGC.UGC_COURSE_TYPE_ID = ?UGC_COURSE_TYPE_ID
                                            AND UGC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamCourseWiseCost:
                    {
                        query = @"INSERT INTO EXAM_COURSE_WISE_COST 
                                  (
	                                  COURSE_ID,
	                                  COURSE_CODE,
                                      EXAM_TYPE_ID,
	                                  UGC_TYPE_COST_ID,
	                                  EXAM_SETTING_ID,
	                                  STAFF_ID,
	                                  ENTRY_DATE,
	                                  ACADEMIC_YEAR
                                  )VALUES 
                                  (
                                      ?COURSE_ID,
	                                  ?COURSE_CODE,
                                      ?EXAM_TYPE_ID,
	                                  ?UGC_TYPE_COST_ID,
	                                  ?EXAM_SETTING_ID,
	                                  ?STAFF_ID,
	                                  ?ENTRY_DATE,
	                                  ?AC_YEAR
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamCourseWiseCost:
                    {
                        query = @"UPDATE EXAM_COURSE_WISE_COST SET
	                              COURSE_ID=?COURSE_ID,
	                              COURSE_CODE=?COURSE_CODE,
	                              UGC_TYPE_COST_ID=?UGC_TYPE_COST_ID,
	                              EXAM_SETTING_ID=?EXAM_SETTING_ID,
	                              STAFF_ID=?STAFF_ID
                                WHERE COURSE_WISE_COST_ID=?COURSE_WISE_COST_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamCourseWiseCost:
                    {
                        query = @"UPDATE EXAM_COURSE_WISE_COST SET IS_DELETED=1 WHERE COURSE_WISE_COST_ID=?COURSE_WISE_COST_ID;";
                        break;
                    }
                #endregion

                #region Exam Fee Mapping - Exam Heads
                case ExaminationSQLCommands.FetchExamHeadsList:
                    {
                        query = @"SELECT 
                                        EH.EXAM_HEAD_ID,
                                        APP.APPLICATION_TYPE,
                                        CONCAT(IFNULL(SFM.MAIN_HEAD,''),' ( ',IFNULL(H.HEAD,''),' )') AS HEAD,
                                        CONCAT(IFNULL(FF.FREQUENCY_NAME,''),' ( ',IFNULL(FT.FREQUENCY_TYPE,''),' - ',EH.ACADEMIC_YEAR,' )') AS FREQUENCY_NAME,
                                        EH.COST,
                                        SS.SHIFT_NAME,
                                        PM.PROGRAMME_MODE,
                                        CY.CLASS_YEAR AS 'PROGRAMME_LEVEL'
                                    FROM 
                                        EXAM_HEADS AS EH
                                            INNER JOIN
                                        FEE_MAIN_HEADS AS MH ON MH.FEE_MAIN_HEAD_ID = EH.FEE_MAIN_HEAD_ID
                                            AND MH.IS_DELETED != 1
		                                    INNER JOIN
	                                    SUP_HEAD AS H ON H.HEAD_ID=MH.HEAD_ID
		                                    INNER JOIN
	                                    SUP_FEE_MAIN_HEAD AS SFM ON SFM.MAIN_HEAD_ID=MH.MAIN_HEAD_ID
                                            INNER JOIN
                                        FEE_FREQUENCY_FEE_MODE AS FM ON FM.FEE_FREQUENCY_FEE_MODE_ID = EH.FREQUENCY_ID
		                                    AND FM.ACADEMIC_YEAR=EH.ACADEMIC_YEAR
		                                    INNER JOIN
	                                    SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID=FM.FEE_MODE
		                                    INNER JOIN
	                                    SUP_FEE_FREQUENCY AS FF ON FF.FREQUENCY_ID=FM.FREQUENCY_ID
		                                    INNER JOIN
	                                    SUP_APPLICATION_TYPE AS APP ON APP.APPLICATION_TYPE_ID=EH.PROGRAMME_TYPE_ID
                                            INNER JOIN
	                                    SUP_SHIFT AS SS ON SS.SHIFT_ID=MH.SHIFT
		                                    INNER JOIN
	                                    SUP_PROGRAMME_MODE AS PM ON PM.PROGRAMME_MODE_ID=MH.PROGRAMME_MODE
                                            INNER JOIN
                                        SUP_CLASS_YEAR AS CY ON CY.CLASS_YEAR_ID=EH.PROGRAMME_LEVEL_ID
                                    WHERE
                                        EH.ACADEMIC_YEAR = ?AC_YEAR
                                            AND EH.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFeeMainHeadsByIds:
                    {
                        query = @"SELECT 
                                        MH.FEE_MAIN_HEAD_ID,
                                        MH.MAIN_HEAD_ID,
                                        MH.HEAD_ID,
                                        CONCAT(IFNULL(SMH.MAIN_HEAD, ''),
                                                ' ( ',
                                                IFNULL(H.HEAD, ''),
                                                ' )') MAIN_HEAD,
	                                    EH.EXAM_HEAD_ID,
                                        IFNULL(EH.COST,0) AS COST,
                                        '' AS EXAM_SETTING_ID
                                    FROM
                                        FEE_MAIN_HEADS AS MH
                                            INNER JOIN
                                        SUP_FEE_MAIN_HEAD AS SMH ON SMH.MAIN_HEAD_ID = MH.MAIN_HEAD_ID
                                            INNER JOIN
                                        SUP_HEAD AS H ON H.HEAD_ID = MH.HEAD_ID
		                                    LEFT JOIN
	                                    EXAM_HEADS AS EH ON EH.FEE_MAIN_HEAD_ID=MH.FEE_MAIN_HEAD_ID AND EH.PROGRAMME_LEVEL_ID =?PROGRAMME_LEVEL_ID
		                                   --  AND EH.EXAM_SETTING_ID=(SELECT EXAM_SETTING_ID FROM EXAM_SETTING WHERE IS_ACTIVE=1 AND IS_DELETED!=1)
                                    WHERE
                                        MH.FEE_MAIN_HEAD_ID IN (?FEE_MAIN_HEAD_ID)
                                        AND MH.IS_DELETED!=1
                                    ORDER BY FEE_MAIN_HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamHeads:
                    {
                        query = @"INSERT INTO EXAM_HEADS 
                                  (
                                    PROGRAMME_TYPE_ID,
                                    PROGRAMME_LEVEL_ID,
                                    SHIFT_ID,
                                    EXAM_SETTING_ID,
                                    ENTRY_DATE,
                                    FREQUENCY_ID,
                                    FEE_MAIN_HEAD_ID,
                                    COST,
                                    ACADEMIC_YEAR
                                  )
                                  VALUES
                                  (
                                    ?PROGRAMME_TYPE_ID,
                                    ?PROGRAMME_LEVEL_ID,
                                    ?SHIFT_ID,
                                    ?EXAM_SETTING_ID,
                                    ?ENTRY_DATE,
                                    ?FREQUENCY_ID,
                                    ?FEE_MAIN_HEAD_ID,
                                    ?COST,
                                    ?AC_YEAR
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamHeads:
                    {
                        query = @"UPDATE EXAM_HEADS SET
                                    PROGRAMME_TYPE_ID=?PROGRAMME_TYPE_ID,
                                    PROGRAMME_LEVEL_ID=?PROGRAMME_LEVEL_ID,
                                    SHIFT_ID=?SHIFT_ID,
                                    EXAM_SETTING_ID=?EXAM_SETTING_ID,
                                    ENTRY_DATE=?ENTRY_DATE,
                                    FREQUENCY_ID=?FREQUENCY_ID,
                                    FEE_MAIN_HEAD_ID=?FEE_MAIN_HEAD_ID,
                                    COST=?COST
                                  WHERE EXAM_HEAD_ID=?EXAM_HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamHeads:
                    {
                        query = @"UPDATE EXAM_HEADS SET IS_DELETED=1 WHERE EXAM_HEAD_ID=?EXAM_HEAD_ID;";
                        break;
                    }
                #endregion

                #region Exam Fee Mapping - Arrer Course Wise Cost 
                case ExaminationSQLCommands.FetchArrerCourseByAcYear:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
	                                    CCR.COURSE_TITLE,
                                        CCR.SEMESTER_ID,
                                        CCR.UGC_COURSE_TYPE,
                                        CCR.SUBJECT_TYPE,
                                        PG.PROGRAMME_GROUP_ID,
                                      --  ACSEM.BATCH,
                                        PG.APPTYPE_ID AS PROGRAMME_TYPE_ID,
                                        PG.SHIFT,
                                        PG.PROGRAMME_MODE,
                                        SEM.RESULT,
                                        '' AS COURSE_WISE_COST_ID,
                                        '' AS UGC_TYPE_COST_ID,
                                        CCR.DEPARTMENT,
                                        PT.EXAM_SETTING_ID,
                                        APP.APPLICATION_TYPE AS PROGRAMME_TYPE,
                                        '?ACADEMIC_YEAR' AS ACADEMIC_YEAR
                                    FROM
                                        STU_PERSONAL_INFO AS SP
                                            INNER JOIN
                                        SEMESTER_MARKS_?ACADEMIC_YEAR AS SEM ON SEM.STUDENT_ID = SP.STUDENT_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SEM.COURSE_ID
                                    --        INNER JOIN
                                    --    ACADEMIC_SEMESTER AS ACSEM ON ACSEM.PROGRAMME_GROUP_ID = PG.PROGRAMME_GROUP_ID
                                    --        AND ACSEM.SEMESTER = CCR.SEMESTER_ID
                                    --        AND ACSEM.IS_DELETED != 1
		                                    INNER JOIN
	                                    EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID=PG.APPTYPE_ID
                                            AND PT.IS_ACTIVE=1
		                                    AND PT.IS_DELETED!=1
		                                    INNER JOIN
	                                    SUP_APPLICATION_TYPE AS APP ON APP.APPLICATION_TYPE_ID=PG.APPTYPE_ID
                                    WHERE
                                        SEM.RESULT NOT IN ('P' , 'M')
                                       --     AND ACSEM.IS_ACTIVE = 1
                                       --     AND ACSEM.ACADEMIC_YEAR = ?AC_YEAR 
                                        ORDER BY SP.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CourseCheckIsPassedByStudentIdAndCourseId:
                    {
                        query = @"SELECT SEMESTER_MARK_ID FROM SEMESTER_MARKS_?AC_YEAR WHERE STUDENT_ID=?STUDENT_ID AND COURSE_ID=?COURSE_ID AND RESULT='P';";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllCoursesFromExamCourseWiseCost:
                    {
                        query = @"SELECT 
                                    EC.COURSE_WISE_COST_ID,
                                    EC.COURSE_ID,
                                    EC.COURSE_CODE,
                                    EC.EXAM_SETTING_ID
                                FROM
                                    EXAM_COURSE_WISE_COST AS EC
		                                INNER JOIN
	                                EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.EXAM_SETTING_ID=EC.EXAM_SETTING_ID
		                                AND PT.ACADEMIC_YEAR=EC.ACADEMIC_YEAR
                                        AND PT.IS_ACTIVE=1
                                        AND PT.IS_DELETED!=1
                                WHERE
                                    EC.ACADEMIC_YEAR = ?AC_YEAR AND EC.IS_DELETED!=1 ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllExamUGCCourseTypeCostForDDLByExamSettingId:
                    {
                        query = @"SELECT 
                                        UGC.UGC_TYPE_COST_ID,
                                        UGC.UGC_COURSE_TYPE_ID,
                                        CONCAT(IFNULL(UGC.TITLE, ''),
                                                ' ( ',
                                                IFNULL(UGC.COST, ''),
                                                ' ) ') AS TITLE,
                                        UGC.PROGRAMME_TYPE_ID
                                    FROM
                                        EXAM_UGC_COURSE_TYPE_COST AS UGC
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = UGC.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE = 1
                                            AND ES.IS_DELETED != 1
                                    WHERE
                                        UGC.IS_DELETED != 1;";
                        break;
                    }
                #endregion

                #region Student Exam Registration

                case ExaminationSQLCommands.FetchFrequencyWithAmount:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        PG.PROGRAMME_GROUP_ID,
                                        FM.FEE_FREQUENCY_FEE_MODE_ID,
                                        MH.FEE_MAIN_HEAD_ID,
                                        MH.MAIN_HEAD_ID,
                                        MH.HEAD_ID,
                                        EH.EXAM_HEAD_ID,
                                        EH.COST
                                    FROM
                                        SUP_FEE_FREQUENCY AS FF
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = FF.SEMESTER_TYPE
                                            AND ST.IS_ACTIVE = 1
                                            AND ST.IS_DELETED != 1
                                            INNER JOIN
                                        FEE_FREQUENCY_FEE_MODE AS FM ON FM.FREQUENCY_ID = FF.FREQUENCY_ID
                                            AND FM.FEE_MODE = 1
                                            AND FM.ACADEMIC_YEAR = FF.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FM.FEE_MODE
                                            AND FT.FEE_ROOT_ID = ?FEE_ROOT_ID
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ?STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
										STU_CLASS AS SC ON SC.STUDENT_ID=SP.STUDENT_ID
											AND SC.ACADEMIC_YEAR=FF.ACADEMIC_YEAR
                                            AND SC.IS_DELETED!=1
											INNER JOIN
										CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            INNER JOIN
                                        FEE_MAIN_HEADS AS MH ON MH.FREQUENCY_ID = FM.FEE_FREQUENCY_FEE_MODE_ID
                                            AND MH.SHIFT = PG.SHIFT
                                            AND MH.PROGRAMME_MODE = PG.PROGRAMME_MODE
                                            AND MH.APPLICATION_TYPE_ID=PG.APPTYPE_ID
                                            AND MH.ACADEMIC_YEAR = FF.ACADEMIC_YEAR
                                            AND MH.FEE_ROOT_ID = ?FEE_ROOT_ID
                                            AND MH.IS_DELETED != 1
                                            LEFT JOIN
                                        EXAM_HEADS AS EH ON EH.FEE_MAIN_HEAD_ID = MH.FEE_MAIN_HEAD_ID
                                            AND EH.PROGRAMME_LEVEL_ID=C.CLASS_YEAR
                                            AND EH.SHIFT_ID=PG.SHIFT
                                            AND EH.FREQUENCY_ID = MH.FREQUENCY_ID AND EH.IS_DELETED!=1
                                    WHERE
                                        FF.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FF.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseWiseCost:
                    {
                        query = @"SELECT 
                                        EC.COURSE_ID,
                                        EC.COURSE_CODE,
                                        EC.EXAM_SETTING_ID,
                                        UGC.COST,
                                        IUGC.COST AS 'INTERNAL_COST_ID'
                                    FROM
                                        EXAM_COURSE_WISE_COST AS EC
		                                    INNER JOIN
	                                    EXAM_UGC_COURSE_TYPE_COST AS UGC ON UGC.UGC_TYPE_COST_ID=EC.UGC_TYPE_COST_ID
		                                    AND UGC.ACADEMIC_YEAR=EC.ACADEMIC_YEAR
                                            AND UGC.IS_DELETED=EC.IS_DELETED 
                                            LEFT JOIN
	                                    EXAM_UGC_COURSE_TYPE_COST AS IUGC ON UGC.UGC_TYPE_COST_ID=EC.INTERNAL_COST_ID
		                                    AND IUGC.ACADEMIC_YEAR=EC.ACADEMIC_YEAR
                                            AND IUGC.IS_DELETED=EC.IS_DELETED                                            
                                    WHERE
                                        EC.COURSE_ID = ?COURSE_ROOT_ID
                                            AND EC.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                            AND EC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND EC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchActiveExamSettingByProgrammeType:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        PG.PROGRAMME_GROUP_ID,
                                        PT.EXAM_SETTING_ID,
                                        IF(CURDATE()>ES.LAST_DATE_FOR_EXAM_FEE,1,0) AS FINE
                                    FROM
                                        STU_PERSONAL_INFO AS SP
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            AND PG.IS_DELETED!=1
                                            INNER JOIN
                                        EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PT.ACADEMIC_YEAR=?AC_YEAR
                                            AND PT.IS_DELETED!=1
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE=1
                                    WHERE SP.STUDENT_ID=?STUDENT_ID;";
                        break;
                    }
                #endregion

                #region miscellaneous
                case ExaminationSQLCommands.FetchStudentByClassAndCourse:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS PG ON PG.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
		                                    AND PG.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND PG.COURSE_ID=?COURSE_ID
                                            AND PG.IS_DELETED!=1
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=PG.COURSE_ID
		                                    -- AND CCR.IS_COMPULSORY=1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR AND SC.CLASS_ID=?CLASS_ID
                                            AND SC.IS_DELETED != 1
                                    UNION
                                    SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.S_CLASS_ID = ?CLASS_ID
                                            AND SC.COURSE_ID =?COURSE_ID
                                            AND SC.IS_DELETED != 1
                                               ORDER BY ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentByClassAndCourseForOnlineExam:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS PG ON PG.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
		                                    AND PG.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND PG.COURSE_ID=?COURSE_ID
                                            AND PG.IS_DELETED!=1
		                                    INNER JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=PG.COURSE_ID
		                                    AND CCR.IS_COMPULSORY=1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR AND SC.CLASS_ID=?CLASS_ID
                                            AND SC.IS_DELETED != 1
                                    UNION
                                    SELECT 
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.S_CLASS_ID = ?CLASS_ID
                                            AND SC.COURSE_ID =?COURSE_ID
                                            AND SC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.BindReportForOnlineExamByClassandCourseandStudent:
                    {
                        query = @"
                                    SELECT 
                                        OA.STUDENT_ID,
                                        OQ.QUESTION,
                                        OA.ANSWER,
                                        DATE_FORMAT(OQ.ENTRY_DATE,'%d/%m/%y') AS ENTRY_DATE,
                                        DATE_FORMAT(OQ.ENTRY_DATE,'%H:%i:%s') AS ENTRY_TIME
                                    FROM
                                        ONLINE_EXAM_SETTING AS OS
                                            INNER JOIN
                                        ONLINE_EXAM_QUESTIONS AS OQ ON OQ.EXAM_SETTING_ID = OS.EXAM_SETTING_ID
                                            INNER JOIN
                                        ONLINE_EXAM_ANSWERS AS OA ON OQ.EXAM_QUESTIONS_ID = OA.QUESTION_ID
                                    WHERE
                                        OS.CLASS_ID =?CLASS_ID AND OS.COURSE_ID =?COURSE_ID
                                            AND OA.STUDENT_ID IN(?STUDENT_ID)
                                            AND OS.IS_ACTIVE = '1'
                                            AND OS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentDetailsByStudentId:

                    {
                        query = @"SELECT 
                                    SP.STUDENT_ID,
                                    SP.ROLL_NO,
                                    CONCAT(UPPER(IFNULL(SP.FIRST_NAME, '')),
                                            ' ',
                                            UPPER(IFNULL(SP.LAST_NAME, ''))) AS FIRST_NAME,
                                    SP.REGISTER_NO,
                                    CC.CLASS_NAME,
                                    SP.PHOTO
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_DELETED != 1 AND SP.IS_LEFT!=1
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = CC.DEPARTMENT
                                WHERE
                                    SC.STUDENT_ID IN (?STUDENT_ID)
                                GROUP BY SP.STUDENT_ID";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentDetailsByStudentIdForarrear:

                    {
                        query = @"SELECT 
                                        STUDENT_ID,
                                        ROLL_NO,
                                        CONCAT(UPPER(IFNULL(FIRST_NAME, '')),
                                                ' ',
                                                UPPER(IFNULL(LAST_NAME, ''))) AS FIRST_NAME,
                                        REGISTER_NO,
                                        cd.DEPARTMENT AS CLASS_NAME,
                                        PHOTO
                                    FROM
                                        STU_PERSONAL_INFO AS SPI
                                            LEFT JOIN
                                        CP_DEPARTMENT AS CD ON CD.DEPARTMENT_ID = SPI.DEPT_ID
                                    WHERE
                                        SPI.IS_DELETED != 1
                                            AND STUDENT_ID IN (?STUDENT_ID)
                                    GROUP BY STUDENT_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchMatchTheFollowingQuizQuestionsByStaff:
                    {
                        query = @"SELECT 
                                    QM.QUESTION,QM.QUESTION_TYPE, QM.QUIZ_ID, QM.SET_ID
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                    QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                      --  AND QZ.IS_ACTIVE=1
                                        AND QZ.ACADEMIC_YEAR=?AC_YEAR
                                        AND QZ.IS_DELETED != 1
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QM ON QM.SETTING_ID = QZ.SETTING_ID
                                        AND QM.SET_ID IN(?SET_ID)
                                        AND QM.IS_DELETED!=1
                                WHERE
                                    CCS.STAFF_ID =?STAFF_ID AND CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND QZ.SETTING_ID=?SETTING_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1 ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingQuizOptionsByStaff:
                    {
                        query = @"    
                                SELECT 
                                    QMO.QUIZ_ID,
                                    QM.QUESTION_TYPE,
	                                QMO.OPTION_ID,
                                    QMO.ANSWER,
                                    QMO.QUESTION
  

                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                    QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                      --  AND QZ.IS_ACTIVE=1
                                        AND QZ.ACADEMIC_YEAR=?AC_YEAR
                                        AND QZ.IS_DELETED != 1
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QM ON QM.SETTING_ID = QZ.SETTING_ID
                                        AND QM.SET_ID IN(?SET_ID)
                                        AND QM.IS_DELETED!=1
                                        INNER JOIN
                                    QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS QMO ON QMO.QUIZ_ID = QM.QUIZ_ID
                                        AND QMO.IS_DELETED != 1
                                        AND QMO.SET_ID = QM.SET_ID
                                WHERE
                                    CCS.STAFF_ID =?STAFF_ID AND CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND QZ.SETTING_ID=?SETTING_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveQuizQuestionsByStaff:
                    {
                        query = @"SELECT 
                                    QO.QUESTION, QO.QUESTION_TYPE, QO.QUIZ_ID, QO.SET_ID
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                    QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                      --  AND QZ.IS_ACTIVE=1
                                        AND QZ.ACADEMIC_YEAR=?AC_YEAR
                                        AND QZ.IS_DELETED != 1
                                        INNER JOIN
                                       QUIZ_OBJECTIVE_QUESTIONS AS QO ON QO.SETTING_ID = QZ.SETTING_ID
                                       AND QO.SET_ID IN(?SET_ID)
                                        AND QO.IS_DELETED!=1
                                WHERE
                                    CCS.STAFF_ID =?STAFF_ID AND CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND QZ.SETTING_ID=?SETTING_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1 ORDER BY QO.QUIZ_ID ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveQuizOptionsByStaff:
                    {
                        query = @"SELECT 
                                    QOO.QUIZ_ID,
                                    QO.QUESTION_TYPE,
	                                QOO.OPTION_ID,
                                    QOO.OPTION
  
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                    QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                      --  AND QZ.IS_ACTIVE=1
                                        AND QZ.ACADEMIC_YEAR=?AC_YEAR
                                        AND QZ.IS_DELETED != 1
                                        INNER JOIN
                                     QUIZ_OBJECTIVE_QUESTIONS AS QO ON QO.SETTING_ID = QZ.SETTING_ID
                                       AND QO.SET_ID IN(?SET_ID)
                                       AND QO.IS_DELETED!=1
                                        INNER JOIN
                                    QUIZ_OBJECTIVE_OPTIONS AS QOO ON QOO.QUIZ_ID = QO.QUIZ_ID
                                        AND  QOO.SETTING_ID=?SETTING_ID
                                        AND QOO.IS_DELETED != 1
                                        AND QOO.SET_ID = QO.SET_ID
                                WHERE
                                    CCS.STAFF_ID =?STAFF_ID AND CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND QZ.SETTING_ID=?SETTING_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlanksQuizQuestionsByStaff:
                    {
                        query = @"SELECT 
                                QFO.QUESTION,QFO.QUESTION_TYPE, QFO.QUIZ_ID, QFO.SET_ID
                            FROM
                                CP_CLASS_COURSE_STAFF AS CCS
                                    INNER JOIN
                                QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                  --  AND QZ.IS_ACTIVE=1
                                    AND QZ.ACADEMIC_YEAR=?AC_YEAR
                                    AND QZ.IS_DELETED != 1
                                    INNER JOIN
                                   QUIZ_FILL_IN_BLANK_QUESTIONS AS QFO ON QFO.SETTING_ID = QZ.SETTING_ID
                                   AND QFO.SET_ID IN(?SET_ID)
                                    AND QFO.IS_DELETED!=1
                            WHERE
                                CCS.STAFF_ID =?STAFF_ID AND CCS.CLASS_ID =?CLASS_ID
                                    AND CCS.COURSE_ID =?COURSE_ID
                                    AND QZ.SETTING_ID=?SETTING_ID
                                    AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                    AND CCS.IS_DELETED != 1 ORDER BY RAND();";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlanksQuizOptionsByStaff:
                    {
                        query = @"SELECT 
                                    QBO.QUIZ_ID,
                                   QFO.QUESTION_TYPE,
	                                QBO.OPTION_ID,
                                    QBO.OPTION
  
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                    QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                     --   AND QZ.IS_ACTIVE=1
                                        AND QZ.ACADEMIC_YEAR=?AC_YEAR
                                        AND QZ.IS_DELETED != 1
                                        INNER JOIN
                                     QUIZ_FILL_IN_BLANK_QUESTIONS AS QFO ON QFO.SETTING_ID = QZ.SETTING_ID
                                       AND QFO.SET_ID=?SET_ID
                                        AND QFO.IS_DELETED!=1
                                        INNER JOIN
                                    QUIZ_FILL_IN_BLANK_OPTIONS AS QBO ON QBO.QUIZ_ID = QFO.QUIZ_ID
                                        AND QBO.IS_DELETED != 1
                                        AND QBO.SET_ID = QFO.SET_ID
                                WHERE
                                    CCS.STAFF_ID =?STAFF_ID AND CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND QZ.SETTING_ID=?SETTING_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchCourseInfoForQuizByStaff:
                    {
                        query = @"SELECT 
                                    C.CLASS_ID,
                                    C.CLASS_NAME,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    SP.STAFF_CODE,
                                    CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                            ' ',
                                            IFNULL(SP.LAST_NAME, '')) AS STAFF_NAME,
                                    DATE_FORMAT(CURDATE(), '%d/%m/%Y') AS DATE,
                                    CCR.SEMESTER_ID
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.CLASS_ID = CCS.CLASS_ID
                                        AND C.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                    AND CCR.IS_DELETED!=1
                                        INNER JOIN
                                    STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CCS.STAFF_ID
                                        AND SP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                        INNER JOIN
                                        QUIZ_SETTING AS QS ON QS.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                        AND QS.ACADEMIC_YEAR=CCS.ACADEMIC_YEAR
                                  --      INNER  JOIN
                                 --   QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS Q ON Q.STF_QUIZ_ID = CCS.CLSCRSSTF_ID
                                  --      AND Q.IS_DELETED != 1
                                WHERE
                                        CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.STAFF_ID =?STAFF_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        and qs.SETTING_ID=?SETTING_ID
                                        AND CCS.IS_DELETED != 1
                                GROUP BY CCS.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchtheFollowingMarkListForStaff:
                    {
                        query = @"SELECT 
                                        CCS.STAFF_ID,
                                        MF.STUDENT_ID,
                                        QQ.QUESTION_TYPE,
                                        COUNT(DISTINCT QQ.QUIZ_ID) AS QUESTION_COUNT,
                                        IF(COUNT(OP.OPTION_ID) = SUM(MF.STATUS),
                                            QQ.MARK,
                                            0) AS MARK
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CCS
                                            INNER JOIN
                                        QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                            AND QZ.ACADEMIC_YEAR = CCS.ACADEMIC_YEAR
                                            AND QZ.IS_DELETED != 1
                                            INNER JOIN
                                        QUIZ_SAVE_MATCH_THE_FOLLOWING AS MF ON MF.SETTING_ID = QZ.SETTING_ID
                                            AND MF.ACADEMIC_YEAR = QZ.ACADEMIC_YEAR
                                            AND MF.IS_DELETED!=1
                                            INNER JOIN
                                        QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ ON QQ.QUIZ_ID = MF.QUIZ_ID
                                            AND QQ.IS_DELETED != 1
                                            LEFT JOIN
                                        QUIZ_MATCH_THE_FOLLOWING_OPTIONS AS OP ON OP.QUIZ_ID = MF.QUIZ_ID
                                            AND OP.IS_DELETED!=1
                                    WHERE
                                        QZ.SETTING_ID = ?SETTING_ID
                                            AND QZ.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY MF.STUDENT_ID,MF.QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveMarkListForStaff:
                    {
                        query = @"SELECT 
                                CCS.STAFF_ID,
                                MF.STUDENT_ID,
                                QQ.QUESTION_TYPE,
                                COUNT(DISTINCT QQ.QUIZ_ID) AS QUESTION_COUNT,
                                SUM(IF(MF.STATUS = 1, 1, 0)) AS 'STATUS',
                                 SUM(IF(MF.STATUS = 1, QQ.MARK, 0))
                                     AS MARK
                            FROM
                                CP_CLASS_COURSE_STAFF AS CCS
                                    INNER JOIN
                                QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                 AND QZ.ACADEMIC_YEAR=CCS.ACADEMIC_YEAR
                                    AND QZ.IS_DELETED != 1
                                    INNER JOIN
                                QUIZ_SAVE_OBJECTIVES AS MF ON MF.SETTING_ID = QZ.SETTING_ID
                                    AND MF.ACADEMIC_YEAR = QZ.ACADEMIC_YEAR
                                    AND MF.IS_DELETED!=1
                                    INNER JOIN
                                QUIZ_OBJECTIVE_QUESTIONS AS QQ ON QQ.QUIZ_ID = MF.QUIZ_ID
                                    AND QQ.IS_DELETED != 1
                            WHERE
                                 QZ.SETTING_ID=?SETTING_ID
                                AND QZ.ACADEMIC_YEAR=?AC_YEAR
                            GROUP BY MF.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillintheBlanksMarkListForStaff:
                    {
                        query = @"SELECT 
                                CCS.STAFF_ID,
                                MF.STUDENT_ID,
                                QQ.QUESTION_TYPE,
                                COUNT(DISTINCT QQ.QUIZ_ID) AS QUESTION_COUNT,
                                SUM(IF(MF.STATUS = 1, 1, 0)) AS 'STATUS',
                                SUM(IF(MF.STATUS = 1, QQ.MARK, 0)) AS MARK
                            FROM
                                CP_CLASS_COURSE_STAFF AS CCS
                                    INNER JOIN
                                QUIZ_SETTING AS QZ ON QZ.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                 AND QZ.ACADEMIC_YEAR=CCS.ACADEMIC_YEAR
                                    AND QZ.IS_DELETED != 1
                                    INNER JOIN
                                QUIZ_SAVE_FILL_IN_BLANKS AS MF ON MF.SETTING_ID = QZ.SETTING_ID
                                    AND MF.ACADEMIC_YEAR = QZ.ACADEMIC_YEAR
                                    AND MF.IS_DELETED!=1
                                    INNER JOIN
                                QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ ON QQ.QUIZ_ID = MF.QUIZ_ID
                                    AND QQ.IS_DELETED != 1
                            WHERE
                                 QZ.SETTING_ID=?SETTING_ID
                                AND QZ.ACADEMIC_YEAR=?AC_YEAR
                            GROUP BY MF.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSettingByStaffandCourse:
                    {
                        query = @"SELECT 
                                    QZ.SETTING_ID,
                                     QZ.SETTING_NAME
                                FROM
                                CP_CLASS_COURSE_STAFF  AS CCS
                                INNER JOIN
                                    QUIZ_SETTING AS QZ
                                     ON QZ.QUIZ_STF_ID=CCS.CLSCRSSTF_ID
                                        AND QZ.ACADEMIC_YEAR = CCS.ACADEMIC_YEAR
                                        AND QZ.IS_DELETED!=1
                                WHERE
                                    CCS.STAFF_ID =?STAFF_ID AND
                                    CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizQuestionCount:
                    {
                        query = @"SELECT 
                                        SUM(MF_COUNT + OBJ_COUNT + FB_COUNT) AS NO_OF_QUESTIONS
                                    FROM
                                        (SELECT 
                                            COUNT(QUIZ_ID) AS MF_COUNT
                                        FROM
                                            QUIZ_MATCH_THE_FOLLOWING_QUESTIONS
                                        WHERE
                                            COURSE_ID = ?COURSE_ID AND CLASS_ID = ?CLASS_ID
                                                AND ENTRY_ID = ?ENTRY_ID
			                                    AND ACADEMIC_YEAR=?AC_YEAR
                                                AND SETTING_ID=?SETTING_ID
                                                AND SET_ID=?SET_ID
                                                AND IS_DELETED != 1) AS MF_COUNT,
                                        (SELECT 
                                            COUNT(QUIZ_ID) AS OBJ_COUNT
                                        FROM
                                            QUIZ_OBJECTIVE_QUESTIONS
                                        WHERE
                                            COURSE_ID = ?COURSE_ID AND CLASS_ID = ?CLASS_ID
                                                AND ENTRY_ID = ?ENTRY_ID
			                                    AND ACADEMIC_YEAR=?AC_YEAR
                                                AND SETTING_ID=?SETTING_ID
                                                AND SET_ID=?SET_ID
                                                AND IS_DELETED != 1) AS OBJ_COUNT,
                                        (SELECT 
                                            COUNT(QUIZ_ID) AS FB_COUNT
                                        FROM
                                            QUIZ_FILL_IN_BLANK_QUESTIONS
                                        WHERE
                                            COURSE_ID = ?COURSE_ID AND CLASS_ID = ?CLASS_ID
                                                AND ENTRY_ID = ?ENTRY_ID
			                                    AND ACADEMIC_YEAR=?AC_YEAR
                                                AND SETTING_ID=?SETTING_ID
                                                AND SET_ID=?SET_ID
                                                AND IS_DELETED != 1) AS FB_COUNT;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMathTheFollowingGroupSet:
                    {
                        query = @"SELECT 
                                        SS.SET_ID, SS.SET_NAME
                                    FROM
                                        QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ
                                            INNER JOIN
                                        SUP_SETS AS SS ON SS.SET_ID = QQ.SET_ID
                                    WHERE
                                        SETTING_ID = ?SETTING_ID AND QQ.IS_DELETED != 1
                                    GROUP BY SS.SET_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveGroupSet:
                    {
                        query = @"SELECT 
                                        SS.SET_ID, SS.SET_NAME
                                    FROM
                                        QUIZ_OBJECTIVE_QUESTIONS AS QQ
                                            INNER JOIN
                                        SUP_SETS AS SS ON SS.SET_ID = QQ.SET_ID
                                    WHERE
                                        SETTING_ID = ?SETTING_ID AND QQ.IS_DELETED != 1
                                    GROUP BY QQ.SET_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInBlankGroupSet:
                    {
                        query = @"SELECT 
                                        SS.SET_ID, SS.SET_NAME
                                    FROM
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
                                            INNER JOIN
                                        SUP_SETS AS SS ON SS.SET_ID = QQ.SET_ID
                                    WHERE
                                        SETTING_ID = ?SETTING_ID AND QQ.IS_DELETED != 1
                                    GROUP BY QQ.SET_ID;";
                        break;
                    }
                #endregion

                case ExaminationSQLCommands.InsertExamSeating:
                    {
                        query = @"INSERT INTO `EXAM_SEATINGS`
                                (
                                `ROOM_ID`,
                                `COLUMN_NO`,
                                `ROW_NO`,
                                `SEAT_CODE`,
                                `SEAT_POSITION`,                                
                                `EXAM_TYPE`
                                 )
                                 VALUES
                                 (
                                 ?ROOM_ID,
                                 ?COLUMN_NO,
                                 ?ROW_NO,
                                 ?SEAT_CODE,
                                 ?SEAT_POSITION,
                                 ?EXAM_TYPE
                                 );
                                ";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByExamSessionFromTimeTable:
                    {
                        query = @"SELECT 
                                DATE_FORMAT(E.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,    
                                E.COURSE_ID,
	                            E.EXAM_SESSION_ID,
                                E.EXAM_SETTING_ID,
                                S.EXAM_SESSION,
                                CR.COURSE_CODE,
                                CR.SEMESTER_ID,
                                CR.COURSE_TITLE,
                                CR.SUBJECT_TYPE,
                                U.UGC_COURSE_TYPE_ID,
                                U.UGC_COURSE_TYPE,        
                                PL.PROGRAMME_LEVEL_ID,                              
                                ES.EXAM_NAME
                            FROM
                                CIA_EXAM_TIMETABLE AS E
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = E.COURSE_ID
                                    AND CR.IS_DELETED != 1
                                    INNER JOIN
                                CP_UGC_COURSE_TYPE AS U ON U.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    AND U.IS_DELETED != 1
                                    INNER JOIN
                                SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                    AND ST.IS_DELETED != 1
                                    INNER JOIN
                                CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CR.DEPARTMENT
                                    AND DP.IS_DELETED != 1
                                    INNER JOIN
                                SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = E.EXAM_SESSION_ID
                                    AND S.IS_DELETED != 1
                                    INNER JOIN
                                SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CR.PROGRAMME_LEVEL_ID
                                    AND PL.IS_DELETED != 1
                                    INNER JOIN
                                CIA_EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = E.EXAM_SETTING_ID
                                    AND ES.IS_DELETED != 1
                            WHERE
                                E.IS_DELETED != 1
                                    AND E.ACADEMIC_YEAR = ?AC_YEAR AND E.EXAM_SETTING_ID=?EXAM_SETTING_ID
                            ORDER BY E.EXAM_DATE , E.EXAM_SESSION_ID , CR.PROGRAMME_LEVEL_ID , U.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByExamSettingForExternal:
                    {
                        query = @"SELECT 
                                DATE_FORMAT(E.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,    
                                E.COURSE_ID,
	                            E.EXAM_SESSION_ID,
                                E.EXAM_SETTING_ID,
                                S.EXAM_SESSION,
                                CR.COURSE_CODE,
                                CR.SEMESTER_ID,
                                CR.COURSE_TITLE,
                                CR.SUBJECT_TYPE,
                                U.UGC_COURSE_TYPE_ID,
                                U.UGC_COURSE_TYPE,        
                                PL.PROGRAMME_LEVEL_ID,                              
                                ES.EXAM_NAME
                            FROM
                                EXAM_TIMETABLE AS E
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = E.COURSE_ID
                                    AND CR.IS_DELETED != 1
                                    INNER JOIN
                                CP_UGC_COURSE_TYPE AS U ON U.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    AND U.IS_DELETED != 1
                                    INNER JOIN
                                SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                    AND ST.IS_DELETED != 1
                                    INNER JOIN
                                CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CR.DEPARTMENT
                                    AND DP.IS_DELETED != 1
                                    INNER JOIN
                                SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = E.EXAM_SESSION_ID
                                    AND S.IS_DELETED != 1
                                    INNER JOIN
                                SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CR.PROGRAMME_LEVEL_ID
                                    AND PL.IS_DELETED != 1
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = E.EXAM_SETTING_ID
                                    AND ES.IS_DELETED != 1
                            WHERE
                                E.IS_DELETED != 1
                                    AND E.ACADEMIC_YEAR = ?AC_YEAR AND E.EXAM_SETTING_ID=?EXAM_SETTING_ID
                            ORDER BY E.EXAM_DATE , E.EXAM_SESSION_ID , CR.PROGRAMME_LEVEL_ID , U.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExceptionCourseByExamSettingForExternal:
                    {
                        query = @"SELECT 
                                    DATE_FORMAT(E.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    E.COURSE_ID,
                                    E.EXAM_SESSION_ID,
                                    E.EXAM_SETTING_ID,
                                    S.EXAM_SESSION,
                                    CR.COURSE_CODE,
                                    CR.SEMESTER_ID,
                                    CR.COURSE_TITLE,
                                    CR.SUBJECT_TYPE,
                                    U.UGC_COURSE_TYPE_ID,
                                    U.UGC_COURSE_TYPE,
                                    PL.PROGRAMME_LEVEL_ID,
                                    ES.EXAM_NAME
                                FROM
                                    exam_seating_exception_course AS E
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = E.COURSE_ID
                                        AND CR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_UGC_COURSE_TYPE AS U ON U.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                        AND U.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                        AND ST.IS_DELETED != 1
                                        INNER JOIN
                                    CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CR.DEPARTMENT
                                        AND DP.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = E.EXAM_SESSION_ID
                                        AND S.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CR.PROGRAMME_LEVEL_ID
                                        AND PL.IS_DELETED != 1
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = E.EXAM_SETTING_ID
                                        AND ES.IS_DELETED != 1
                                WHERE
                                    E.IS_DELETED != 1
                                        AND E.ACADEMIC_YEAR = ?AC_YEAR
                                        AND E.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                ORDER BY E.EXAM_DATE , E.EXAM_SESSION_ID , CR.PROGRAMME_LEVEL_ID , U.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExceptionCourseByExamSettingForInternal:
                    {
                        query = @"SELECT 
                                    DATE_FORMAT(E.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    E.COURSE_ID,
                                    E.EXAM_SESSION_ID,
                                    E.EXAM_SETTING_ID,
                                    S.EXAM_SESSION,
                                    CR.COURSE_CODE,
                                    CR.SEMESTER_ID,
                                    CR.COURSE_TITLE,
                                    CR.SUBJECT_TYPE,
                                    U.UGC_COURSE_TYPE_ID,
                                    U.UGC_COURSE_TYPE,
                                    PL.PROGRAMME_LEVEL_ID,
                                    ES.EXAM_NAME
                                FROM
                                    CIA_EXAM_SEATING_EXCEPTION_COURSE AS E
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = E.COURSE_ID
                                        AND CR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_UGC_COURSE_TYPE AS U ON U.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                        AND U.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                        AND ST.IS_DELETED != 1
                                        INNER JOIN
                                    CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CR.DEPARTMENT
                                        AND DP.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = E.EXAM_SESSION_ID
                                        AND S.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CR.PROGRAMME_LEVEL_ID
                                        AND PL.IS_DELETED != 1
                                        INNER JOIN
                                    CIA_EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = E.EXAM_SETTING_ID
                                        AND ES.IS_DELETED != 1
                                WHERE
                                    E.IS_DELETED != 1
                                        AND E.ACADEMIC_YEAR = ?AC_YEAR
                                        AND E.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                ORDER BY E.EXAM_DATE , E.EXAM_SESSION_ID , CR.PROGRAMME_LEVEL_ID , U.COURSE_ORDER;";
                        break;
                    }
                #region ExamOverallFee
                case ExaminationSQLCommands.FetchExamOverallFeeByExamSettingandProgramme:
                    {
                        query = @"SELECT 
                                     PG.PROGRAMME_GROUP_ID,
                                    P.PROGRAMME_NAME,
                                    CONCAT(IFNULL(CY.CLASS_YEAR,' ' ),
                                    ' -  ',
                                    IFNULL(P.PROGRAMME_NAME,' '),
                                    ' ',IFNULL(PM.PROGRAMME_MODE,' '),
                                    ' ( SHIFT - ',IFNULL(SH.SHIFT_NAME,' '),' )')  AS CLASS_NAME,
                                   
                                     CONCAT(IFNULL(CY.CLASS_YEAR,''),
                                    ' - ',IFNULL(AT.APPLICATION_TYPE,'')) AS PROGRAMME,
                                    EH.PROGRAMME_LEVEL_ID,
                                   EH.PROGRAMME_TYPE_ID,
                                    FM.FREQUENCY_ID,
                                    FM.FEE_MAIN_HEAD_ID,
                                    CONCAT(IFNULL(FMH.MAIN_HEAD,''),
                                    ' ( ',IFNULL(H.HEAD,''),' )') AS MAIN_HEAD,
                                    H.HEAD,
                                    EH.COST
                                FROM
                                    CP_PROGRAMME_GROUP AS PG
                                        INNER JOIN
                                    EXAM_PROGRAMME_TYPE_SETTING AS TS ON TS.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                        AND EXAM_SETTING_ID =?EXAM_SETTING_ID
                                        INNER JOIN
                                    FEE_MAIN_HEADS AS FM ON FM.APPLICATION_TYPE_ID = PG.APPTYPE_ID
                                        AND FM.SHIFT = PG.SHIFT
                                        AND FM.PROGRAMME_MODE = PG.PROGRAMME_MODE
                                        AND FM.FREQUENCY_ID =?FREQUENCY_ID
                                        AND FM.IS_DELETED != 1
                                        LEFT JOIN
                                    EXAM_HEADS AS EH ON EH.FEE_MAIN_HEAD_ID = FM.FEE_MAIN_HEAD_ID
                                        AND EH.IS_DELETED != 1
                                        AND EH.ACADEMIC_YEAR =?AC_YEAR
                                        INNER JOIN
                                    SUP_FEE_MAIN_HEAD AS FMH ON FMH.MAIN_HEAD_ID = FM.MAIN_HEAD_ID
                                        INNER JOIN
                                    SUP_HEAD AS H ON H.HEAD_ID = FM.HEAD_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                     LEFT JOIN 
                                    SUP_CLASS_YEAR AS CY
                                    ON CY.CLASS_YEAR_ID=EH.PROGRAMME_LEVEL_ID
                                    INNER JOIN SUP_SHIFT AS SH
                                    ON SH.SHIFT_ID=PG.SHIFT
                                    INNER JOIN 
                                    SUP_PROGRAMME_MODE AS PM
                                    ON PM.PROGRAMME_MODE_ID=PG.PROGRAMME_MODE
                                    LEFT JOIN 
                                    SUP_APPLICATION_TYPE AS AT ON AT.APPLICATION_TYPE_ID=EH.PROGRAMME_TYPE_ID
                                    AND AT.IS_DELETED!=1
                                WHERE
                                    PG.PROGRAMME_GROUP_ID IN (?PROGRAMME_GROUP_ID)
                                ORDER BY PG.PROGRAMME_GROUP_ID,EH.PROGRAMME_LEVEL_ID,H.HEAD_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamCourseFeeByExamSettingandProgramme:

                    {
                        query = @"        
                                SELECT
                                    PG.PROGRAMME_GROUP_ID, 
                                    P.PROGRAMME_NAME,
                                    EH.PROGRAMME_LEVEL_ID,
									EH.PROGRAMME_TYPE_ID,
                                    CCP.COURSE_ID,
                                    UGC.TITLE,
                                    UGC.COST
                                FROM
                                    CP_COURSE_PATTERN AS CCP
										INNER JOIN
									cp_course_structure AS CS ON CS.COURSE_STRUCTURE_ID=CCP.COURSE_STRUCTURE_ID AND CS.IS_DELETED!=1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                        INNER JOIN
                                    EXAM_COURSE_WISE_COST AS CC ON CC.COURSE_ID = CCP.COURSE_ID
                                        AND CC.IS_DELETED != 1
                                        AND CC.ACADEMIC_YEAR =CCP.ACADEMIC_YEAR
                                        INNER JOIN
                                    EXAM_UGC_COURSE_TYPE_COST AS UGC ON UGC.UGC_TYPE_COST_ID = CC.UGC_TYPE_COST_ID
                                        AND UGC.IS_DELETED != 1
                                        AND UGC.ACADEMIC_YEAR =CCP.ACADEMIC_YEAR
			                                INNER JOIN
	                                CP_PROGRAMME AS P ON P.PROGRAMME_ID=PG.PROGRAMME_ID
                                         INNER JOIN EXAM_SETTING AS ES
                                      ON ES.EXAM_SETTING_ID=CC.EXAM_SETTING_ID
                                      AND ES.IS_DELETED!=1
                                      INNER JOIN 
                                      EXAM_HEADS AS EH 
                                      ON EH.EXAM_SETTING_ID=ES.EXAM_SETTING_ID
                                      AND EH.PROGRAMME_TYPE_ID=PG.APPTYPE_ID
                                      AND EH.ACADEMIC_YEAR=ES.ACADEMIC_YEAR
                                     AND EH.IS_DELETED!=1
                                     AND EH.PROGRAMME_LEVEL_ID=CS.PROGRAMME_YEAR
                                WHERE
                                    CCP.ACADEMIC_YEAR =?AC_YEAR
                                     AND CCP.PROGRAMME_GROUP_ID IN(?PROGRAMME_GROUP_ID)
                                      AND ES.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                        AND CCP.IS_DELETED != 1 
                                GROUP BY CCP.PROGRAMME_GROUP_ID,CCP.COURSE_STRUCTURE_ID ORDER BY CCP.PROGRAMME_GROUP_ID;";
                        break;
                    }
                #endregion
                case ExaminationSQLCommands.InsertExamSeatingAllotment:
                    {
                        query = @"";
                        break;
                    }
                case ExaminationSQLCommands.FetchExaminationSeatAllotmentList:
                    {
                        query = @"SELECT 
                            ES.SEATING_ID,
                            ES.SEAT_CODE,
                            ES.SEAT_POSITION,
                            SP.STUDENT_ID,
                            CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                    '',
                                    IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                            SP.ROLL_NO,
                            ES.COLUMN_NO,
                            ES.ROW_NO,
                            DATE_FORMAT(ST.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                            SS.EXAM_SESSION,
                            CL.CLASS_NAME,
                            SP.REGISTER_NO,
                            CR.COURSE_TITLE,
                            CB.BLOCK_NAME,
                            CB.BLOCK_ORDER,
                            R.ROOM_ID,
                            R.ROOM_ORDER,
                            R.ROOM_NO,
                            R.`COLUMN`,
                            R.SPACE_COLUMN,
                            R.`ROW`,
                            R.EXAM_CAPACITY,
                            R.EXAM_TYPE
                        FROM
                            EXAM_SEATINGS AS ES
                                LEFT JOIN
                            EXAM_SEATING_ALLOTEMENT AS ST ON ST.SEATING_ID = ES.SEATING_ID
                              AND  ST.ACADEMIC_YEAR = ?AC_YEAR
                                AND ST.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                AND ST.EXAM_DATE = ?EXAM_DATE
                                AND ST.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                AND ST.EXAM_TYPE = ?EXAM_TYPE
                                LEFT JOIN
                            STU_CLASS AS SC ON SC.STUDENT_ID = ST.STUDENT_ID
                                AND SC.IS_DELETED != 1
                                AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                LEFT JOIN
                            STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                AND SP.IS_DELETED != 1
                                AND IS_LEFT != 1
                                LEFT JOIN
                            CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                LEFT JOIN
                            CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ST.COURSE_ID
                                LEFT JOIN
                            SUP_ROOM AS R ON R.ROOM_ID = ES.ROOM_ID
                                AND R.IS_DELETED != 1
                                LEFT JOIN
                            SUP_COLLEGE_BLOCK AS CB ON CB.COLLEGE_BLOCK_ID = R.COLLEGE_BLOCK_ID
                                AND CB.IS_DELETED != 1
                                LEFT JOIN
                            SUP_EXAM_SESSION AS SS ON SS.EXAM_SESSION_ID = ST.EXAM_SESSION_ID
                                AND SS.EXAM_TYPE = ?EXAM_TYPE WHERE ES.EXAM_TYPE=?EXAM_TYPE 
                        ORDER BY R.ROOM_ORDER,ES.SEATING_ID;";
                        break;
                    }
                //for quiz setting for admin
                case ExaminationSQLCommands.FetchQuizSettingByStaff:
                    {
                        query = @"SELECT 
                                    QS.SETTING_ID,
                                    QS.SETTING_NAME,
                                    QS.NO_OF_QUESTIONS,
                                    QS.EACH_QUESTION_MARKS,
                                    QS.TOTAL_MARK,
                                    QS.QUIZ_STF_ID,
                                    QS.TIME,
                                    DATE_FORMAT(QS.ENTRY_DATE,'%d/%m/%Y') AS ENTRY_DATE,  
                                    QS.ACADEMIC_YEAR,
                                    DATE_FORMAT(QS.START_DATE,'%d/%m/%Y') AS START_DATE ,
                                    DATE_FORMAT(QS.END_DATE,'%d/%m/%Y') AS END_DATE,
                                    IFNULL(QS.IS_ACTIVE,'0')AS IS_ACTIVE,
                                    CCS.CLASS_ID,
                                    C.CLASS_NAME,
                                    CCS.COURSE_ID,
                                    concat(ifnull(CCR.COURSE_CODE,''),' - ',ifnull(CCR.COURSE_TITLE,'')) AS COURSE,
                                    CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME 
                                FROM
                                    QUIZ_SETTING AS QS
										INNER JOIN
									cp_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID=QS.QUIZ_STF_ID
										AND CCS.IS_DELETED!=1
                                        AND CCS.ACADEMIC_YEAR=QS.ACADEMIC_YEAR
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID=CCS.CLASS_ID
										INNER JOIN
									CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=CCS.COURSE_ID
										INNER JOIN
									STF_PERSONAL_INFO AS SP ON SP.STAFF_ID=CCS.STAFF_ID 
										AND SP.IS_DELETED!=1 AND SP.IS_LEFT!=1
                                WHERE 
                                    QS.IS_DELETED != 1 
                                    AND QS.ACADEMIC_YEAR=?AC_YEAR
                                     AND QS.STAFF_ID=?STAFF_ID
                                    GROUP BY QS.SETTING_ID  ORDER BY QS.SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizSettingByQuizStaffId:
                    {
                        query = @"SELECT 
                                    QS.SETTING_ID,
                                    QS.SETTING_NAME,
                                    QS.NO_OF_QUESTIONS,
                                    QS.EACH_QUESTION_MARKS,
                                    QS.TOTAL_MARK,
                                    QS.QUIZ_STF_ID,
                                    QS.TIME,
                                    DATE_FORMAT(QS.ENTRY_DATE,'%d/%m/%Y') AS ENTRY_DATE,  
                                    QS.ACADEMIC_YEAR,
                                    DATE_FORMAT(QS.START_DATE,'%d/%m/%Y') AS START_DATE ,
                                    DATE_FORMAT(QS.END_DATE,'%d/%m/%Y') AS END_DATE,
                                    IFNULL(QS.IS_ACTIVE,'0')AS IS_ACTIVE
                                  
                                FROM
                                    QUIZ_SETTING AS QS
										
                                WHERE 
                                    QS.IS_DELETED != 1 
                                    AND QS.ACADEMIC_YEAR=?AC_YEAR
                                     AND QS.QUIZ_STF_ID=?QUIZ_STF_ID
                                    GROUP BY QS.SETTING_ID  ORDER BY QS.SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSeatingsList:
                    {
                        query = @"SELECT 
                                ES.SEATING_ID,
                                ES.SEAT_CODE,
                                ES.SEAT_POSITION,
                                ES.COLUMN_NO,
                                ES.ROW_NO,
                                CB.BLOCK_NAME,
                                CB.BLOCK_CODE,
                                R.ROOM_ID,
                                R.SPACE_COLUMN,
                                R.ROOM_NO,
                                R.`COLUMN`,
                                R.`ROW`,
                                R.EXAM_CAPACITY,
                                R.ROOM_ORDER,
                                CB.BLOCK_ORDER,
                                R.EXAM_TYPE
                            FROM
                                EXAM_SEATINGS AS ES
                                    LEFT JOIN
                                SUP_ROOM AS R ON R.ROOM_ID = ES.ROOM_ID
                                    AND R.EXAM_TYPE = ES.EXAM_TYPE
                                    AND R.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_COLLEGE_BLOCK AS CB ON CB.COLLEGE_BLOCK_ID = R.COLLEGE_BLOCK_ID
                                    AND CB.IS_DELETED != 1
                            WHERE
                                ES.EXAM_TYPE = ?EXAM_TYPE AND ES.IS_DELETED != 1 
                            ORDER BY CB.BLOCK_ORDER,R.ROOM_ORDER,ES.SEATING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTimetableDatesByExamSetting:
                    {
                        query = @"SELECT EXAM_SETTING_ID, DATE_FORMAT(EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE FROM EXAM_TIMETABLE WHERE EXAM_SETTING_ID = ?EXAM_SETTING_ID GROUP BY EXAM_DATE ORDER BY DATE(EXAM_DATE);";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTimetableDatesByCIAExamSetting:
                    {
                        query = @"SELECT EXAM_SETTING_ID, DATE_FORMAT(EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE FROM CIA_EXAM_TIMETABLE WHERE EXAM_SETTING_ID = ?EXAM_SETTING_ID GROUP BY EXAM_DATE ORDER BY DATE(EXAM_DATE);";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAExamTimetableSessionByExamDate:
                    {
                        query = @"SELECT 
                                ES.EXAM_SESSION_ID, ES.EXAM_SESSION
                            FROM
                                CIA_EXAM_TIMETABLE AS TT
                                    INNER JOIN
                                SUP_EXAM_SESSION AS ES
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EXAM_DATE = ?EXAM_DATE
                            GROUP BY EXAM_SESSION
                            ORDER BY EXAM_SESSION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTimetableSessionByExamDate:
                    {
                        query = @"SELECT 
                                ES.EXAM_SESSION_ID, ES.EXAM_SESSION
                            FROM
                                EXAM_TIMETABLE AS TT
                                    INNER JOIN
                                 SUP_EXAM_SESSION AS ES ON ES.EXAM_SESSION_ID = TT.EXAM_SESSION_ID
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EXAM_DATE = ?EXAM_DATE                                 
                            GROUP BY EXAM_SESSION
                            ORDER BY EXAM_SESSION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ExamSeatingCourseWiseReport:
                    {
                        query = @"SELECT 
                                ES.ROOM_ID,
                                COUNT(ES.ROOM_ID) AS STUDENT_COUNT,
                                R.ROOM_NO,
                                B.BLOCK_NAME,
                                DATE_FORMAT(EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                S.EXAM_SESSION,
                                CL.CLASS_ID,
                                CL.CLASS_NAME,
                                CR.COURSE_TITLE,
                                ST.COURSE_ID,
                                DP.DEPARTMENT,
                                DP.DEPARTMENT_ID
                            FROM
                                EXAM_SEATING_ALLOTEMENT AS ST
                                    INNER JOIN
                                EXAM_SEATINGS AS ES ON ES.SEATING_ID = ST.SEATING_ID AND ES.IS_DELETED!=1
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = ST.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ST.COURSE_ID
                                    INNER JOIN
                                cp_department AS DP ON DP.DEPARTMENT_ID = CL.DEPARTMENT
                                    INNER JOIN
                                SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = ST.EXAM_SESSION_ID
                                    INNER JOIN
                                SUP_ROOM AS R ON R.ROOM_ID = ES.ROOM_ID
                                    INNER JOIN
                                SUP_COLLEGE_BLOCK AS B ON B.COLLEGE_BLOCK_ID = R.COLLEGE_BLOCK_ID
                            WHERE
                                ST.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND ST.EXAM_DATE = ?EXAM_DATE
                                    AND ST.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                    AND ST.EXAM_TYPE=?EXAM_TYPE
                                    AND ST.ACADEMIC_YEAR=?AC_YEAR
                                    AND ST.IS_DELETED!=1
                            GROUP BY ROOM_ID , CL.CLASS_ID , ST.COURSE_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchStudentCountByCourseId:
                    {
                        query = @"SELECT 
                                    COUNT(STUDENT_ID) AS STUDENT_COUNT, COURSE_ID, STATUS
                                FROM
                                    (SELECT 
                                        SP.STUDENT_ID, CC.COURSE_ID, '' AS STATUS
                                    FROM
                                        CP_CLASS_COURSE AS CC
                                    INNER JOIN STU_CLASS AS C ON C.CLASS_ID = CC.CLASS_ID
                                        AND C.ACADEMIC_YEAR = ?AC_YEAR
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = C.STUDENT_ID
                                        AND (SP.REGISTER_NO IS NOT NULL OR SP.ROLL_NO IS NOT NULL)
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    WHERE
                                        COURSE_ID IN (?COURSE_ID) AND CC.IS_DELETED!=1 
                                            AND CC.ACADEMIC_YEAR = ?AC_YEAR UNION SELECT 
                                        SP.STUDENT_ID, CC.COURSE_ID, '' AS STATUS
                                    FROM
                                        STU_COURSE_INFO AS CC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CC.STUDENT_ID
                                        AND (SP.REGISTER_NO IS NOT NULL OR SP.ROLL_NO IS NOT NULL)
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    WHERE
                                        CC.COURSE_ID IN (?COURSE_ID)
                                            AND CC.IS_DELETED != 1
                                            AND CC.ACADEMIC_YEAR = ?AC_YEAR) AS T
                                GROUP BY COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentCountByCourseIdAndGender:
                    {
                        query = @"SELECT 
                                    COUNT(STUDENT_ID) AS STUDENT_COUNT, COURSE_ID, STATUS
                                FROM
                                    (SELECT 
                                        SP.STUDENT_ID, CC.COURSE_ID, '' AS STATUS
                                    FROM
                                        CP_CLASS_COURSE AS CC
                                    INNER JOIN STU_CLASS AS C ON C.CLASS_ID = CC.CLASS_ID
                                        AND C.ACADEMIC_YEAR = ?AC_YEAR
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = C.STUDENT_ID
                                        AND SP.REGISTER_NO IS NOT NULL
                                        AND SP.GENDER=?GENDER
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    WHERE
                                        COURSE_ID IN (?COURSE_ID) AND CC.IS_DELETED!=1 
                                            AND CC.ACADEMIC_YEAR = ?AC_YEAR UNION SELECT 
                                        SP.STUDENT_ID, CC.COURSE_ID, '' AS STATUS
                                    FROM
                                        STU_COURSE_INFO AS CC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CC.STUDENT_ID
                                        AND SP.REGISTER_NO IS NOT NULL
                                        AND SP.GENDER=?GENDER
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    WHERE
                                        CC.COURSE_ID IN (?COURSE_ID)
                                            AND CC.IS_DELETED != 1
                                            AND CC.ACADEMIC_YEAR = ?AC_YEAR) AS T
                                GROUP BY COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentCountByCourseIdForExternal:
                    {
                        query = @"SELECT 
                                    COUNT(STUDENT_ID) AS STUDENT_COUNT, COURSE_ID, '' STATUS
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS R
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = R.COURSE_ID
                                        AND CR.IS_DELETED != 1
                                WHERE
                                    R.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND R.COURSE_ID IN (?COURSE_ID)     
                                        AND R.IS_DELETED != 1
                                GROUP BY COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentByCourseForSeatingAllotmentForExternal:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                CL.CLASS_ID,
                                CL.CLASS_NAME,
                                R.COURSE_ID,
                                R.`STATUS`,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                CR.SEMESTER_ID,
                                PG.PROGRAMME_GROUP_ID,
                                P.PROGRAMME_NAME
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR AS R
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = R.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = R.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = SP.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CL.PROGRAMME_GROUP_ID
                                    INNER JOIN
                                CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                LEFT JOIN CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID=CR.UGC_COURSE_TYPE
                            WHERE
                                R.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND R.STATUS='R'
                                    AND R.ACADEMIC_YEAR = ?AC_YEAR
                                    AND R.IS_DELETED != 1
                                    AND R.COURSE_ID  IN (?COURSE_ID) ORDER BY COURSE_ID , CLASS_ID , REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentByCourseForSeatingAllotmentForInternal:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                C.CLASS_ID,
                                C.CLASS_NAME,
                                CP.COURSE_ID,
                                CCR.COURSE_CODE,
                                CCR.COURSE_TITLE,
                                CCR.SEMESTER_ID,
                                CP.PROGRAMME_GROUP_ID,
                                CONCAT(IFNULL(P.PROGRAMME_NAME, ''),
                                        '  ',
                                        IFNULL(PM.PROGRAMME_MODE, ''),
                                        ' ( SHIFT - ',
                                        IFNULL(SS.SHIFT_NAME, ''),
                                        ' ) ') AS PROGRAMME_NAME
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                   AND SP.IS_DELETED != 1
                                                AND SP.IS_LEFT != 1
                                                AND (SP.REGISTER_NO IS NOT NULL OR SP.ROLL_NO IS NOT NULL)
                                    INNER JOIN
                                CP_COURSE_PATTERN AS CP ON CP.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                    AND CP.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                    AND CP.IS_DELETED != 1
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                    AND CCR.IS_COMPULSORY = 1
                                    AND CCR.IS_DELETED != 1
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                    AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                        AY.ACADEMIC_YEAR_ID
                                    FROM
                                        ACADEMIC_YEAR AS AY
                                    WHERE
                                        AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1)
                                    INNER JOIN
                                ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = PG.PROGRAMME_GROUP_ID
                                    AND SEM.SEMESTER = CCR.SEMESTER_ID
                                    AND SEM.BATCH = AB.BATCH_ID
                                    AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                    AND SEM.IS_DELETED != 1
                                    AND SEM.IS_ACTIVE = 1
                                    INNER JOIN
                                CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                    INNER JOIN
                                SUP_SHIFT AS SS ON SS.SHIFT_ID = PG.SHIFT
                                    INNER JOIN
                                SUP_PROGRAMME_MODE AS PM ON PM.PROGRAMME_MODE_ID = PG.PROGRAMME_MODE
                            WHERE
                                SC.ACADEMIC_YEAR=?AC_YEAR AND SC.IS_DELETED != 1
                                    AND CP.COURSE_ID IN (?COURSE_ID) 
                            UNION SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                C.CLASS_ID,
                                C.CLASS_NAME,
                                SC.COURSE_ID,
                                CCR.COURSE_CODE,
                                CCR.COURSE_TITLE,
                                CCR.SEMESTER_ID,
                                PG.PROGRAMME_GROUP_ID,
                                CONCAT(IFNULL(P.PROGRAMME_NAME, ''),
                                        '  ',
                                        IFNULL(PM.PROGRAMME_MODE, ''),
                                        ' ( SHIFT - ',
                                        IFNULL(SS.SHIFT_NAME, ''),
                                        ' ) ') AS PROGRAMME_NAME
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                                    AND SP.IS_LEFT != 1
                                                 AND (SP.REGISTER_NO IS NOT NULL OR SP.ROLL_NO IS NOT NULL)
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                                    INNER JOIN
                                ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                    AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                        AY.ACADEMIC_YEAR_ID
                                    FROM
                                        ACADEMIC_YEAR AS AY
                                    WHERE
                                        AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1)
                                    INNER JOIN
                                ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = PG.PROGRAMME_GROUP_ID
                                    AND SEM.SEMESTER = CCR.SEMESTER_ID
                                    AND SEM.BATCH = AB.BATCH_ID
                                    AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                    AND SEM.IS_DELETED != 1
                                    AND SEM.IS_ACTIVE = 1
                                    INNER JOIN
                                CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                    INNER JOIN
                                SUP_SHIFT AS SS ON SS.SHIFT_ID = PG.SHIFT
                                    INNER JOIN
                                SUP_PROGRAMME_MODE AS PM ON PM.PROGRAMME_MODE_ID = PG.PROGRAMME_MODE
                            WHERE
                                SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    AND SC.COURSE_ID IN (?COURSE_ID)
                            ORDER BY COURSE_ID , CLASS_ID , IFNULL(REGISTER_NO,ROLL_NO);";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentByCourseForSeatingAllotmentForInternalByGender:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                C.CLASS_ID,
                                C.CLASS_NAME,
                                CP.COURSE_ID,
                                CCR.COURSE_CODE,
                                CCR.COURSE_TITLE,
                                CCR.SEMESTER_ID,
                                CP.PROGRAMME_GROUP_ID,
                                CONCAT(IFNULL(P.PROGRAMME_NAME, ''),
                                        '  ',
                                        IFNULL(PM.PROGRAMME_MODE, ''),
                                        ' ( SHIFT - ',
                                        IFNULL(SS.SHIFT_NAME, ''),
                                        ' ) ') AS PROGRAMME_NAME
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                   AND SP.IS_DELETED != 1
                                   AND SP.GENDER=?GENDER
                                                AND SP.IS_LEFT != 1
                                                AND SP.REGISTER_NO IS NOT NULL
                                    INNER JOIN
                                CP_COURSE_PATTERN AS CP ON CP.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                    AND CP.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                    AND CP.IS_DELETED != 1
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                    AND CCR.IS_COMPULSORY = 1
                                    AND CCR.IS_DELETED != 1
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                    AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                        AY.ACADEMIC_YEAR_ID
                                    FROM
                                        ACADEMIC_YEAR AS AY
                                    WHERE
                                        AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1)
                                    INNER JOIN
                                ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = PG.PROGRAMME_GROUP_ID
                                    AND SEM.SEMESTER = CCR.SEMESTER_ID
                                    AND SEM.BATCH = AB.BATCH_ID
                                    AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                    AND SEM.IS_DELETED != 1
                                    AND SEM.IS_ACTIVE = 1
                                    INNER JOIN
                                CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                    INNER JOIN
                                SUP_SHIFT AS SS ON SS.SHIFT_ID = PG.SHIFT
                                    INNER JOIN
                                SUP_PROGRAMME_MODE AS PM ON PM.PROGRAMME_MODE_ID = PG.PROGRAMME_MODE
                            WHERE
                                SC.ACADEMIC_YEAR=?AC_YEAR AND SC.IS_DELETED != 1
                                    AND CP.COURSE_ID IN (?COURSE_ID) 
                            UNION SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                C.CLASS_ID,
                                C.CLASS_NAME,
                                SC.COURSE_ID,
                                CCR.COURSE_CODE,
                                CCR.COURSE_TITLE,
                                CCR.SEMESTER_ID,
                                PG.PROGRAMME_GROUP_ID,
                                CONCAT(IFNULL(P.PROGRAMME_NAME, ''),
                                        '  ',
                                        IFNULL(PM.PROGRAMME_MODE, ''),
                                        ' ( SHIFT - ',
                                        IFNULL(SS.SHIFT_NAME, ''),
                                        ' ) ') AS PROGRAMME_NAME
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_DELETED != 1 AND SP.GENDER=?GENDER
                                                    AND SP.IS_LEFT != 1
                                                AND SP.REGISTER_NO IS NOT NULL
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                                    INNER JOIN
                                ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                    AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                        AY.ACADEMIC_YEAR_ID
                                    FROM
                                        ACADEMIC_YEAR AS AY
                                    WHERE
                                        AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1)
                                    INNER JOIN
                                ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = PG.PROGRAMME_GROUP_ID
                                    AND SEM.SEMESTER = CCR.SEMESTER_ID
                                    AND SEM.BATCH = AB.BATCH_ID
                                    AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                    AND SEM.IS_DELETED != 1
                                    AND SEM.IS_ACTIVE = 1
                                    INNER JOIN
                                CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                    INNER JOIN
                                SUP_SHIFT AS SS ON SS.SHIFT_ID = PG.SHIFT
                                    INNER JOIN
                                SUP_PROGRAMME_MODE AS PM ON PM.PROGRAMME_MODE_ID = PG.PROGRAMME_MODE
                            WHERE
                                SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    AND SC.COURSE_ID IN (?COURSE_ID)
                            ORDER BY COURSE_ID , CLASS_ID , REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseBasedAttendanceReportForExam:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME,
                                CL.CLASS_ID,
                                CL.CLASS_NAME,
                                ST.COURSE_ID,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                ES.SEAT_CODE,
                                DATE_FORMAT(ST.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                SS.EXAM_SESSION,
                                R.ROOM_ID,
                                R.ROOM_NO,
                                B.BLOCK_NAME
                            FROM
                                EXAM_SEATING_ALLOTEMENT AS ST
                                    INNER JOIN
                                EXAM_SEATINGS AS ES ON ES.SEATING_ID = ST.SEATING_ID AND ST.IS_DELETED!=1
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = ST.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    INNER JOIN
                                CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ST.COURSE_ID
                                    INNER JOIN
                                SUP_EXAM_SESSION AS SS ON SS.EXAM_SESSION_ID = ST.EXAM_SESSION_ID
                                    INNER JOIN
                                SUP_ROOM AS R ON R.ROOM_ID = ES.ROOM_ID  AND R.IS_DELETED != 1 
                                    INNER JOIN
                                SUP_COLLEGE_BLOCK AS B ON B.COLLEGE_BLOCK_ID = R.COLLEGE_BLOCK_ID
                            WHERE
                                ST.ACADEMIC_YEAR = ?AC_YEAR
                                    AND ST.IS_DELETED != 1
                                    AND ST.EXAM_DATE = ?EXAM_DATE
                                    AND ST.EXAM_SESSION_ID = ?EXAM_SESSION_ID       
                                    AND ST.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND ST.EXAM_TYPE = ?EXAM_TYPE ORDER BY ES.SEATING_ID, SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateIsDeletedInExamSeatingsByRoomId:
                    {
                        query = @"UPDATE EXAM_SEATINGS SET IS_DELETED=1 WHERE ROOM_ID=?ROOM_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByExamDateAndSession:
                    {
                        query = @"SELECT 
                                DATE_FORMAT(E.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                E.COURSE_ID,
                                E.EXAM_SESSION_ID,
                                E.EXAM_SETTING_ID,
                                S.EXAM_SESSION,
                                CR.COURSE_CODE,
                                CR.SEMESTER_ID,
                                CR.COURSE_TITLE,
                                CR.SUBJECT_TYPE,
                                U.UGC_COURSE_TYPE_ID,
                                U.UGC_COURSE_TYPE,
                                PL.PROGRAMME_LEVEL_ID,
                                ES.EXAM_TYPE,
                                ES.EXAM_NAME
                            FROM
                                CIA_EXAM_TIMETABLE AS E
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = E.COURSE_ID
                                    AND CR.IS_DELETED != 1
                                    INNER JOIN
                                CP_UGC_COURSE_TYPE AS U ON U.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    AND U.IS_DELETED != 1
                                    INNER JOIN
                                SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                    AND ST.IS_DELETED != 1
                                    INNER JOIN
                                CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CR.DEPARTMENT
                                    AND DP.IS_DELETED != 1
                                    INNER JOIN
                                SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = E.EXAM_SESSION_ID
                                    AND S.IS_DELETED != 1
                                    INNER JOIN
                                SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CR.PROGRAMME_LEVEL_ID
                                    AND PL.IS_DELETED != 1
                                    INNER JOIN
                                CIA_EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = E.EXAM_SETTING_ID
                            WHERE
                                E.IS_DELETED != 1
                                    AND E.ACADEMIC_YEAR = ?AC_YEAR
                                    AND E.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND E.EXAM_DATE = ?EXAM_DATE
                                    AND E.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                    AND ES.EXAM_TYPE = ?EXAM_TYPE
                            ORDER BY E.EXAM_DATE , E.EXAM_SESSION_ID , CR.PROGRAMME_LEVEL_ID , U.COURSE_ORDER";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseByExamDateAndSessionForExternal:
                    {
                        query = @"SELECT 
                                DATE_FORMAT(E.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                E.COURSE_ID,
                                E.EXAM_SESSION_ID,
                                E.EXAM_SETTING_ID,
                                S.EXAM_SESSION,
                                CR.COURSE_CODE,
                                CR.SEMESTER_ID,
                                CR.COURSE_TITLE,
                                CR.SUBJECT_TYPE,
                                U.UGC_COURSE_TYPE_ID,
                                U.UGC_COURSE_TYPE,
                                PL.PROGRAMME_LEVEL_ID,
                                '?EXAM_TYPE' AS EXAM_TYPE,
                                ES.EXAM_NAME
                            FROM
                                EXAM_TIMETABLE AS E
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = E.COURSE_ID
                                    AND CR.IS_DELETED != 1
                                    LEFT JOIN
                                CP_UGC_COURSE_TYPE AS U ON U.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    AND U.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                    AND ST.IS_DELETED != 1
                                    LEFT JOIN
                                CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = CR.DEPARTMENT
                                    AND DP.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = E.EXAM_SESSION_ID
                                    AND S.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = CR.PROGRAMME_LEVEL_ID
                                    AND PL.IS_DELETED != 1
                                    LEFT JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = E.EXAM_SETTING_ID
                            WHERE
                                E.IS_DELETED != 1
                                    AND E.ACADEMIC_YEAR = ?AC_YEAR
                                    AND E.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND E.EXAM_DATE = ?EXAM_DATE
                                    AND E.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                  --   AND ES.EXAM_TYPE = ?EXAM_TYPE
                            ORDER BY E.EXAM_DATE , E.EXAM_SESSION_ID , CR.PROGRAMME_LEVEL_ID , U.COURSE_ORDER;";
                        break;
                    }
                #region Fetch CIA Hall Ticket
                case ExaminationSQLCommands.FetchCIAHallTicket:
                    {
                        query = @"SELECT 
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    CCR.SEMESTER_ID,
                                    ES.SEAT_CODE,
                                    ES.SEAT_POSITION,
                                    CB.BLOCK_CODE,
                                    CB.BLOCK_NAME,
                                    DATE_FORMAT(EA.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                    SS.EXAM_SESSION AS EXAM_TIME
                                FROM
                                    EXAM_SEATING_ALLOTEMENT AS EA
                                        INNER JOIN
                                    EXAM_SEATINGS AS ES ON ES.SEATING_ID = EA.SEATING_ID
                                        AND ES.IS_DELETED != 1
                                        INNER JOIN
                                    CIA_EXAM_SETTING AS S ON S.EXAM_SETTING_ID = EA.EXAM_SETTING_ID
                                        AND S.ACADEMIC_YEAR = EA.ACADEMIC_YEAR
                                        AND S.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_EXAM_SESSION AS SS ON SS.EXAM_SESSION_ID = EA.EXAM_SESSION_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EA.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_ROOM AS SR ON SR.ROOM_ID = ES.ROOM_ID
                                        INNER JOIN
                                    SUP_COLLEGE_BLOCK AS CB ON CB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                WHERE
                                    EA.STUDENT_ID = ?STUDENT_ID
                                        AND EA.IS_DELETED != 1
                                        AND EA.ACADEMIC_YEAR = ?AC_YEAR
                                ORDER BY EXAM_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAHallTicketForClassIncharges:
                    {
                        query = @"SELECT 
                                    CCR.COURSE_ROOT_ID,
                                    EA.STUDENT_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    CCR.SEMESTER_ID,
                                    ES.SEAT_CODE,
                                    ES.SEAT_POSITION,
                                    CB.BLOCK_CODE,
                                    CB.BLOCK_NAME,
                                    DATE_FORMAT(EA.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                    SS.EXAM_SESSION AS EXAM_TIME
                                FROM
                                    EXAM_SEATING_ALLOTEMENT AS EA
                                        INNER JOIN
                                    EXAM_SEATINGS AS ES ON ES.SEATING_ID = EA.SEATING_ID
                                        AND ES.IS_DELETED != 1
                                        INNER JOIN
                                    CIA_EXAM_SETTING AS S ON S.EXAM_SETTING_ID = EA.EXAM_SETTING_ID
                                        AND S.ACADEMIC_YEAR = EA.ACADEMIC_YEAR
                                        AND S.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_EXAM_SESSION AS SS ON SS.EXAM_SESSION_ID = EA.EXAM_SESSION_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EA.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_ROOM AS SR ON SR.ROOM_ID = ES.ROOM_ID
                                        INNER JOIN
                                    SUP_COLLEGE_BLOCK AS CB ON CB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                WHERE
                                    EA.STUDENT_ID IN (?STUDENT_ID)
                                        AND EA.IS_DELETED != 1
                                        AND EA.ACADEMIC_YEAR = ?AC_YEAR
                                        AND EA.EXAM_TYPE=?EXAM_TYPE
                                        AND EA.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                ORDER BY EA.STUDENT_ID,EXAM_DATE;";
                        break;
                    }
                #endregion

                #region CIA Exam TimeTable
                case ExaminationSQLCommands.FetchCoureByProgrammeGroupAndYear:
                    {
                        query = @"SELECT 
                                    CCP.COURSE_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    CT.UGC_COURSE_TYPE,
                                    CF.FACULTY,
                                    SE.EXAM_SESSION,
                                    TT.TIMETABLE_ID,
                                    TT.EXAM_SESSION_ID,
                                    DATE_FORMAT(EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    ES.EXAM_SETTING_ID,
                                    UPPER(CONCAT(ES.EXAM_NAME, '-', ES.ACADEMIC_YEAR)) AS EXAM_NAME
                                FROM
                                    CP_COURSE_STRUCTURE AS SC
                                        INNER JOIN
                                    CP_COURSE_PATTERN AS CCP ON CCP.COURSE_STRUCTURE_ID = SC.COURSE_STRUCTURE_ID
                                        AND CCP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_UGC_COURSE_TYPE AS CT ON CT.UGC_COURSE_TYPE_ID = CCR.UGC_COURSE_TYPE
                                        INNER JOIN
                                    CP_FACULTY AS CF ON CF.FACULTY_ID=SC.FACULTY_ID
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                        AND SEM.SEMESTER = CCR.SEMESTER_ID
                                        AND SEM.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                        AND SEM.IS_ACTIVE = 1
                                        AND SEM.IS_DELETED != 1
                                        LEFT JOIN
	                                CIA_EXAM_TIMETABLE AS TT ON TT.COURSE_ID=CCP.COURSE_ID
		                                AND TT.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
                                        AND TT.IS_DELETED!=1
                                        AND TT.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                        LEFT JOIN
	                                SUP_EXAM_SESSION AS SE ON SE.EXAM_SESSION_ID=TT.EXAM_SESSION_ID
		                                LEFT JOIN
	                                CIA_EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID=TT.EXAM_SETTING_ID
		                                AND ES.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
                                        AND ES.IS_DELETED!=1
                                WHERE
                                    SC.IS_DELETED != 1 
                                        AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CCP.PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
                                        AND SC.PROGRAMME_YEAR = ?PROGRAMME_YEAR ORDER BY CT.COURSE_ORDER;";
                        break;
                    }

                #endregion

                case ExaminationSQLCommands.CheckSupplementryExamByProgrammeGroupId:
                    {
                        query = @"SELECT 
                                PROGRAMME_SETTING_ID,
                                PROGRAMME_GROUP_ID,
                                PROGRAMME_LEVEL_ID,
                                PROGRAMME_YEAR_ID,
                                ACADEMIC_YEAR,
                                IS_ACTIVE
                            FROM
                                EXAM_SUPPLEMENTARY_SETTING_FOR_PROGRAMME
                            WHERE
                                PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID
                                    AND PROGRAMME_YEAR_ID = ?PROGRAMME_YEAR_ID
                                    AND ACADEMIC_YEAR = ?AC_YEAR
                                    AND EXAM_SETTING_ID=?EXAM_SETTING_ID
                                    AND IS_ACTIVE = 1
                                    AND IS_DELETED != 1;";
                        break;
                    }
                #region QuizSetting for Admin
                case ExaminationSQLCommands.FetchQuizStaffByClassAndCourse:
                    {
                        query = @"SELECT 
                                    CCS.STAFF_ID,
                                    CONCAT(IFNULL(SPI.FIRST_NAME,''),'',
    
                                    IFNULL(SPI.LAST_NAME,'')) AS FIRST_NAME
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CCS
                                        INNER JOIN
                                        STF_PERSONAL_INFO AS SPI ON SPI.STAFF_ID=CCS.STAFF_ID
                                        AND SPI.IS_LEFT!=1
                                        AND SPI.IS_DELETED!=1
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = CCS.CLASS_ID
                                        AND CC.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                       -- AND CCR.ACADEMIC_YEAR = CCS.ACADEMIC_YEAR
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    QUIZ_SETTING AS QS ON QS.QUIZ_STF_ID = CCS.CLSCRSSTF_ID
                                        AND QS.ACADEMIC_YEAR = CCS.ACADEMIC_YEAR
                                        AND QS.IS_DELETED != 1
                                WHERE
                                    CCS.CLASS_ID =?CLASS_ID
                                        AND CCS.COURSE_ID =?COURSE_ID
                                        AND CCS.ACADEMIC_YEAR =?AC_YEAR
                                        AND CCS.IS_DELETED != 1
                                GROUP BY SPI.STAFF_ID ORDER BY SPI.STAFF_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ListMathTheFollowingQuizForAdmin:
                    {
                        query = @"SELECT 
                                        QQ.QUIZ_ID,
                                        C.CLASS_NAME AS 'CLASS_ID',
                                        UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                        ' ',
                                                        IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                        SS.SEMESTER_NAME AS 'SEMESTER_ID',
                                        QQ.QUESTION,
                                        IFNULL(QQ.MARK,0) AS MARK,
                                        SE.SET_NAME AS 'SET_ID',
                                        QT.QUESTION_TYPE,
                                        QT.QUESTION_TYPE_ID
                                    FROM
                                        QUIZ_MATCH_THE_FOLLOWING_QUESTIONS AS QQ
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = QQ.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = QQ.SEMESTER_ID
                                            LEFT JOIN
                                        SUP_SETS AS SE ON SE.SET_ID = QQ.SET_ID
                                            INNER JOIN
                                        ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QQ.ACADEMIC_YEAR
                                            INNER JOIN
	                                    SUP_QUIZ_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID=QQ.QUESTION_TYPE 
                                    WHERE
                                        QQ.ACADEMIC_YEAR = ?AC_YEAR
                                            AND QQ.SETTING_ID IN (?SETTING_ID)
                                          
                                            AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.ListObjectiveQuizForAdmin:
                    {
                        query = @"
                                        SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QT.QUESTION_TYPE_ID,
                                        QT.QUESTION_TYPE,
                                        CC.CLASS_NAME,
                                        STF.FIRST_NAME,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SE.SET_NAME AS 'SET_ID',
                                        SS.SEMESTER_NAME,
                                        QQ.MARK
                                    FROM
                                        QUIZ_OBJECTIVE_QUESTIONS AS QQ
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS STF ON STF.STAFF_ID = QQ.ENTRY_ID
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = QQ.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
		                                    INNER JOIN
	                                    SUP_QUIZ_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID=QQ.QUESTION_TYPE 
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=CCR.SEMESTER_ID
                                            LEFT JOIN
                                        SUP_SETS AS SE ON SE.SET_ID = QQ.SET_ID
                                    WHERE
                                        QQ.ACADEMIC_YEAR =?AC_YEAR
                                            AND QQ.SETTING_ID IN (?SETTING_ID)
                                            AND QQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.ListFillInBlankQuizForAdmin:
                    {
                        query = @"
                                        SELECT 
                                        QQ.QUIZ_ID,
                                        QQ.QUESTION,
                                        QT.QUESTION_TYPE_ID,
                                        QT.QUESTION_TYPE,
                                        CC.CLASS_NAME,
                                        STF.FIRST_NAME,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SE.SET_NAME AS 'SET_ID',
                                        SS.SEMESTER_NAME,
                                        QQ.MARK
                                    FROM
                                        QUIZ_FILL_IN_BLANK_QUESTIONS AS QQ
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS STF ON STF.STAFF_ID = QQ.ENTRY_ID
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = QQ.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
		                                    INNER JOIN
	                                    SUP_QUIZ_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID=QQ.QUESTION_TYPE 
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=CCR.SEMESTER_ID
                                            LEFT JOIN
                                        SUP_SETS AS SE ON SE.SET_ID = QQ.SET_ID
                                    WHERE
                                        QQ.ACADEMIC_YEAR=?AC_YEAR
                                            AND QQ.SETTING_ID IN (?SETTING_ID)
                                            AND QQ.IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchClassandCourseandSemesterByQuizSetting:
                    {
                        query = @"SELECT 
                                    CCS.CLASS_ID,
                                    CCS.COURSE_ID,
                                    CCR.SEMESTER_ID,
                                    CCS.STAFF_ID
                                    FROM 
                                    QUIZ_SETTING AS QS
                                    INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID=QS.QUIZ_STF_ID
                                    INNER JOIN 
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=CCS.COURSE_ID
                                    WHERE 
                                    QS.SETTING_ID=?SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizSettingByQuizSetting:
                    {
                        query = @"SELECT 
                                    SETTING_ID,
                                    CONCAT(IFNULL(SETTING_NAME, ''),
                                            ' - ',
                                            IFNULL(QS.ACADEMIC_YEAR, '')) AS SETTING_NAME,
                                    TIME,
                                    START_DATE,
                                    END_DATE,
                                    NO_OF_QUESTIONS,
                                    '1' AS ACTIVE_DATE
                                FROM
                                    QUIZ_SETTING AS QS
                                        INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID = QS.QUIZ_STF_ID
                                        AND CCS.ACADEMIC_YEAR=QS.ACADEMIC_YEAR
		                                AND CCS.IS_DELETED!=1
                                WHERE
                                    QS.IS_DELETED != 1
                                      AND QS.SETTING_ID=?SETTING_ID
                                        AND QS.ACADEMIC_YEAR =?AC_YEAR;";
                        break;
                    }
                #endregion

                case ExaminationSQLCommands.FetchRoomListByExamDateandExamSessionForInvigilation:
                    {
                        query = @"SELECT 
                                    ES.ROOM_ID,
                                    SR.ROOM_NO,
                                    COUNT(EA.STUDENT_ID) AS EXAM_CAPACITY
                                FROM
                                    EXAM_SEATING_ALLOTEMENT AS EA
                                        INNER JOIN
                                    EXAM_SEATINGS_?AC_YEAR AS ES ON ES.SEATING_ID = EA.SEATING_ID
                                        AND ES.IS_DELETED != 1
                                        INNER JOIN 
                                        SUP_ROOM AS SR ON SR.ROOM_ID=ES.ROOM_ID
                                        AND SR.IS_DELETED!=1
                                WHERE
                                    EA.EXAM_DATE =?EXAM_DATE
                                        AND EA.EXAM_TYPE=?EXAM_TYPE
                                        AND EA.EXAM_SESSION_ID =?EXAM_SESSION_ID
                                        AND EA.EXAM_SETTING_ID =?EXAM_SETTING_ID
                                        AND EA.ACADEMIC_YEAR=?AC_YEAR
                                GROUP BY ES.ROOM_ID;";
                        break;
                    }
                case ExaminationSQLCommands.AddExamSeatingInvigilator:
                    {
                        query = @"INSERT INTO EXAM_SEATING_INVIGILATOR(ROOM_ID, STAFF_ID, EXAM_DATE, EXAM_SESSION_ID, EXAM_SETTING_ID, EXAM_TYPE, ACADEMIC_YEAR)
                                    VALUES(?ROOM_ID,?STAFF_ID,?EXAM_DATE,?EXAM_SESSION_ID,?EXAM_SETTING_ID,?EXAM_TYPE,?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamSeatingInvigilatorbyId:
                    {
                        query = @"UPDATE EXAM_SEATING_INVIGILATOR SET STAFF_ID=?STAFF_ID WHERE SEATING_INVIGILATOR_ID=?SEATING_INVIGILATOR_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamSeatingInvigilator:
                    {
                        query = @"UPDATE EXAM_SEATING_INVIGILATOR SET IS_DELETED=1 WHERE SEATING_INVIGILATOR_ID=?SEATING_INVIGILATOR_ID;";
                        break;
                    }
                case ExaminationSQLCommands.BindExamSeatingInvigilatorForAssignByExamDate:
                    {
                        query = @"SELECT 
                                    EI.SEATING_INVIGILATOR_ID,
                                    EI.STAFF_ID,
                                    CONCAT(IFNULL(ST.FIRST_NAME,''),' - ',ST.STAFF_CODE) AS FIRST_NAME,
                                    EI.EXAM_DATE,
                                    EI.ROOM_ID,
                                    EI.EXAM_SESSION_ID,
                                    EI.EXAM_SETTING_ID,
                                    EI.EXAM_TYPE
                                FROM
                                    EXAM_SEATING_INVIGILATOR AS EI
                                        INNER JOIN
                                    STF_PERSONAL_INFO AS ST ON ST.STAFF_ID = EI.STAFF_ID
                                WHERE
                                    EI.EXAM_DATE = ?EXAM_DATE
                                        AND EI.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                        AND EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EI.EXAM_TYPE = ?EXAM_TYPE
                                        AND EI.ACADEMIC_YEAR =?AC_YEAR 
                                        AND EI.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSeatingInvigilatorByID:
                    {
                        query = @"SELECT 
                                EI.SEATING_INVIGILATOR_ID,
                                EI.STAFF_ID,
                                CONCAT(IFNULL(ST.FIRST_NAME, ''),
                                        ' - ',
                                        ST.STAFF_CODE) AS FIRST_NAME,
                                DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                EI.ROOM_ID,
                                R.ROOM_NO,
                                EI.EXAM_SESSION_ID,
                                SS.EXAM_SESSION,
                                EI.EXAM_SETTING_ID,
                                EI.EXAM_TYPE
                            FROM
                                EXAM_SEATING_INVIGILATOR AS EI
                                    INNER JOIN
                                STF_PERSONAL_INFO AS ST ON ST.STAFF_ID = EI.STAFF_ID
                                    INNER JOIN
                                SUP_ROOM AS R ON R.ROOM_ID = EI.ROOM_ID
                                    AND R.EXAM_TYPE = EI.EXAM_TYPE
                                    INNER JOIN
                                SUP_EXAM_SESSION AS SS ON SS.EXAM_SESSION_ID = EI.EXAM_SESSION_ID
                            WHERE
                                EI.SEATING_INVIGILATOR_ID IN (?SEATING_INVIGILATOR_ID)
                                    AND EI.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchDummyHallTicketList:
                    {
                        query = @"SELECT 
                                    REGISTRATION_ID,
                                    ER.STUDENT_ID,
                                    CC.COURSE_CODE,
                                    CC.COURSE_TITLE,
                                    IF(ET.IS_ADVANCE = '1',
                                        DATE_FORMAT(ET.ADVANCE_DATE, '%d/%m/%Y'),
                                        IF(ET.IS_POSTPONED = '1',
                                            DATE_FORMAT(ET.POSTPONED_DATE, '%d/%m/%Y'),
                                            DATE_FORMAT(ET.EXAM_DATE, '%d/%m/%Y'))) AS EXAM_DATE,
                                    IF(ET.IS_ADVANCE = '1',
                                        ET.ADVANCE_TIME,
                                        IF(ET.IS_POSTPONED = '1',
                                            ET.POSTPONED_TIME,
                                            ET.EXAM_TIME)) AS EXAM_TIME,
                                    ER.COURSE_ID,
                                    STATUS,
                                    ER.ACADEMIC_YEAR,
                                    S.SEMESTER_NAME AS 'SEMESTER_ID',
                                    ES.M_PASS AS 'MONTH_YEAR',
                                    CC.SEMESTER_ID AS 'SEMESTER',
                                    ESS.SEAT_CODE,
                                    SCB.BLOCK_CODE,
                                    SCB.BLOCK_NAME
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS ER
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = ER.COURSE_ID
                                        LEFT JOIN
                                    EXAM_TIMETABLE AS ET ON ET.COURSE_ID = CC.COURSE_ROOT_ID
                                        AND ET.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                        AND ET.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                        AND ES.IS_ACTIVE = 1
                                        LEFT JOIN
                                    EXAM_SEATING_ALLOTEMENT AS ESA ON ESA.STUDENT_ID = ER.STUDENT_ID
                                        AND ESA.COURSE_ID = ER.COURSE_ID
                                        AND ESA.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                        LEFT JOIN
                                    EXAM_SEATINGS AS ESS ON ESS.SEATING_ID = ESA.SEATING_ID       
                                        INNER JOIN
                                    SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CC.SEMESTER_ID
                                        LEFT JOIN
                                    SUP_ROOM AS SR ON SR.ROOM_ID = ESS.ROOM_ID
                                        LEFT JOIN
                                    SUP_COLLEGE_BLOCK AS SCB ON SCB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                WHERE
                                    ER.STUDENT_ID = ?STUDENT_ID
                                        AND ER.ACADEMIC_YEAR =?AC_YEAR
                                ORDER BY DATE_FORMAT(ET.EXAM_DATE, '%Y-%m-%d') ASC;";
                        break;
                    }
                case ExaminationSQLCommands.Totalstudentlist:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        '',
                                        IFNULL(SP.LAST_NAME, ''),
                                        ' - (',
                                        SP.ROLL_NO,
                                        ')') AS ROLL_NO
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SC.STUDENT_ID = SP.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                            WHERE
                                SC.ACADEMIC_YEAR =?AC_YEAR
                                    AND SC.IS_DELETED != 1 ORDER BY SC.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveDummyHallticketDistributed:
                    {
                        query = @"INSERT 
                                        INTO DUMMY_HALLTICKET_DISTRIBUTED
                                       (STUDENT_ID,DISTRIBUTED_ID,ACADEMIC_YEAR) 
                                        VALUES(?STUDENT_ID,?DISTRIBUTED_ID,?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsStudentExist:
                    {
                        query = @"SELECT 
                                STUDENT_ID, DISTRIBUTED_ID
                            FROM
                                DUMMY_HALLTICKET_DISTRIBUTED
                            WHERE
                                STUDENT_ID = ?STUDENT_ID AND ACADEMIC_YEAR=?ACADEMIC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAcademicYearstudentId:
                    {
                        query = @"SELECT 
                                MAX(SC.ACADEMIC_YEAR) AS ACADEMIC_YEAR_ID
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                    AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                        ACADEMIC_YEAR_ID
                                    FROM
                                        ACADEMIC_YEAR
                                    WHERE
                                        ACTIVE_YEAR = 1 AND IS_DELETED != 1)
                            WHERE
                                SC.STUDENT_ID =?STUDENT_ID
                                    AND SC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentInfoForExamRegistration:
                    {
                        query = @"SELECT 
                                    SP.STUDENT_ID,
                                    SP.ROLL_NO,
                                    CONCAT(UPPER(IFNULL(SP.FIRST_NAME, '')),
                                            ' ',
                                            UPPER(IFNULL(SP.LAST_NAME, ''))) AS 'NAME',
                                    DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS 'DATE_OF_BIRTH',
                                    SP.REGISTER_NO,
                                    D.DEPARTMENT,
                                    IF(SP.STU_MOBILENO IS NULL
                                            || SP.STU_MOBILENO = '',
                                        IF(SP.FR_MOBILE IS NULL
                                                || SP.FR_MOBILE = '',
                                            IF(SP.MO_MOBILE IS NULL
                                                    || SP.MO_MOBILE = '',
                                                '',
                                                SP.MO_MOBILE),
                                            SP.FR_MOBILE),
                                        SP.STU_MOBILENO) AS 'MOBILE_NO',
                                    CONCAT('#',
                                            A.P_DOOR_DETAIL,
                                            ',',
                                            A.P_VILLAGE_AREA,
                                            '(village) ,',
                                            A.P_POST_PLACE_TOWN,
                                            '(POST) ,') AS 'ADDRESS1',
                                    CONCAT(A.P_STREET,
                                            ',',
                                            A.P_DISTRICT,
                                            'D.T ,',
                                            P_PINCODE) AS 'ADDRESS2',
                                    CONCAT(DATE_FORMAT(CURRENT_DATE(), '%M'),
                                            '-',
                                            DATE_FORMAT(CURRENT_DATE(), '%Y')) AS 'YEAR',
                                    DATE_FORMAT(CURRENT_DATE(), '%d/%m/%Y') AS 'DATE',
                                    M_EXAM AS 'MONTH',
                                    ES.EXAM_SETTING_ID,
                                    SS.SEMESTER_NAME
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = CC.DEPARTMENT
                                        LEFT JOIN
                                    STU_ADDRESS AS A ON A.STUDENT_ID = SP.STUDENT_ID
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                        inner JOIN
                                    EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                        AND PT.ACADEMIC_YEAR =?AC_YEAR
                                        inner JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                        AND ES.ACADEMIC_YEAR =?AC_YEAR
                                        AND ES.IS_ACTIVE=1
                                        INNER JOIN
                                    ACADEMIC_YEAR AS AY ON AY.AC_YEAR = SC.ACADEMIC_YEAR
                                        AND AY.IS_DELETED != 1
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = CC.CLASS_YEAR
                                        AND AB.ACADEMIC_YEAR_ID = AY.ACADEMIC_YEAR_ID
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                        AND SEM.BATCH = AB.BATCH_ID
                                        AND SEM.IS_DELETED != 1
                                        AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        INNER JOIN
                                    SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = SEM.SEMESTER
                                WHERE
		                                SC.STUDENT_ID = ?STUDENT_ID
                                        AND SC.ACADEMIC_YEAR =?ACADEMIC_YEAR
                                GROUP BY SP.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamArrearFeeStatus:
                    {
                        query = @" SELECT 
                            FS.ACADEMIC_YEAR,
                            FS.FREQUENCY_ID,
                            FS.HEAD,
                            SUM(IFNULL(FS.CREDIT, 0)) AS CREDIT,
                            SUM(IFNULL(FS.DEBIT, 0)) AS DEBIT,
                            (SUM(IFNULL(FS.CREDIT, 0)) - SUM(IFNULL(FS.DEBIT, 0))) AS BALANCE,
                            FS.TRANSACTION_DATE
                        FROM
                            STU_CLASS AS SC
                                INNER JOIN
                            FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                AND FS.ACADEMIC_YEAR =?AC_YEAR
                                INNER JOIN
                            FEE_FREQUENCY_FEE_MODE AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID
                                INNER JOIN
                            SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                INNER JOIN
                            SUP_FEE_FREQUENCY AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID
                        WHERE
                                SC.STUDENT_ID = ?STUDENT_ID
                                AND SC.ACADEMIC_YEAR =?ACADEMIC_YEAR
                                AND FFF.FEE_MODE =?FEE_MODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSupFeeTransaction:
                    {
                        query = @"SELECT 
                                        SUM(IFNULL(FS.CREDIT, '0')) - SUM(IFNULL(FS.DEBIT, '0')) AS BALANCE,
                                        FS.DEBIT,
                                        SUM(FS.DEBIT) AS DEBIT,
                                        FT.FREQUENCY_TYPE_ID,
                                        FS.STUDENT_ID,
                                        FS.HEAD,
                                        SC.CLASS_ID,
                                        FT.FREQUENCY_TYPE AS FREQUENCY_NAME,
                                        FT.FEE_ROOT_ID
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.ACADEMIC_YEAR =?AC_YEAR
                                            INNER JOIN
                                        fee_frequency_fee_mode AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                            INNER JOIN
                                        sup_fee_frequency AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?ACADEMIC_YEAR
                                    GROUP BY FFF.FEE_MODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSuppleFrequencyWithAmount:
                    {

                        query = @"SELECT 
                                    SP.STUDENT_ID,
                                    SP.ROLL_NO,
                                    SP.REGISTER_NO,
                                    PG.PROGRAMME_GROUP_ID,
                                    FM.FEE_FREQUENCY_FEE_MODE_ID,
                                    MH.FEE_MAIN_HEAD_ID,
                                    MH.MAIN_HEAD_ID,
                                    MH.HEAD_ID,
                                    EH.EXAM_HEAD_ID,
                                    EH.COST
                                FROM
                                    FEE_FREQUENCY_FEE_MODE AS FM 
                                        INNER JOIN
                                    SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FM.FEE_MODE
                                        AND FT.FEE_ROOT_ID =?FEE_ROOT_ID
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID =?STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = SP.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR =?ACADEMIC_YEAR
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                        INNER JOIN
                                    FEE_MAIN_HEADS AS MH ON MH.FREQUENCY_ID = FM.FEE_FREQUENCY_FEE_MODE_ID
                                        AND MH.SHIFT = PG.SHIFT
                                        AND MH.PROGRAMME_MODE = PG.PROGRAMME_MODE
                                        AND MH.APPLICATION_TYPE_ID = PG.APPTYPE_ID
                                        AND MH.ACADEMIC_YEAR =FM.ACADEMIC_YEAR
                                        AND MH.FEE_ROOT_ID =?FEE_ROOT_ID
                                        AND MH.IS_DELETED != 1
                                        LEFT JOIN
                                    EXAM_HEADS AS EH ON EH.FEE_MAIN_HEAD_ID = MH.FEE_MAIN_HEAD_ID
                                        AND EH.PROGRAMME_LEVEL_ID = C.CLASS_YEAR
                                        AND EH.SHIFT_ID = PG.SHIFT
                                        AND EH.FREQUENCY_ID = MH.FREQUENCY_ID
                                        AND EH.IS_DELETED != 1
                                WHERE
		                                FM.FEE_FREQUENCY_FEE_MODE_ID=?FEE_FREQUENCY_FEE_MODE_ID AND FM.ACADEMIC_YEAR=?AC_YEAR;";
                        break;

                        //query = @"SELECT 
                        //            SP.STUDENT_ID,
                        //            SP.ROLL_NO,
                        //            SP.REGISTER_NO,
                        //            PG.PROGRAMME_GROUP_ID,
                        //            FM.FEE_FREQUENCY_FEE_MODE_ID,
                        //            MH.FEE_MAIN_HEAD_ID,
                        //            MH.MAIN_HEAD_ID,
                        //            MH.HEAD_ID,
                        //            EH.EXAM_HEAD_ID,
                        //            EH.COST
                        //        FROM
                        //            SUP_FEE_FREQUENCY AS FF
                        //                INNER JOIN
                        //            SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = FF.SEMESTER_TYPE
                        //                AND ST.IS_ACTIVE = 1
                        //                AND ST.IS_DELETED != 1
                        //                INNER JOIN
                        //            FEE_FREQUENCY_FEE_MODE AS FM ON FM.FREQUENCY_ID = FF.FREQUENCY_ID
                        //                AND FM.FEE_MODE = 1
                        //                AND FM.ACADEMIC_YEAR = FF.ACADEMIC_YEAR
                        //                INNER JOIN
                        //            SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FM.FEE_MODE
                        //                AND FT.FEE_ROOT_ID =?FEE_ROOT_ID
                        //                INNER JOIN
                        //            STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ?STUDENT_ID
                        //                AND SP.IS_DELETED != 1
                        //                AND SP.IS_LEFT != 1
                        //                INNER JOIN
                        //            STU_CLASS AS SC ON SC.STUDENT_ID = SP.STUDENT_ID
                        //                AND SC.ACADEMIC_YEAR = ?ACADEMIC_YEAR
                        //                AND SC.IS_DELETED != 1
                        //                INNER JOIN
                        //            CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                        //                INNER JOIN
                        //            CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                        //                INNER JOIN
                        //            FEE_MAIN_HEADS AS MH ON MH.FREQUENCY_ID = FM.FEE_FREQUENCY_FEE_MODE_ID
                        //                AND MH.SHIFT = PG.SHIFT
                        //                AND MH.PROGRAMME_MODE = PG.PROGRAMME_MODE
                        //                AND MH.APPLICATION_TYPE_ID = PG.APPTYPE_ID
                        //                AND MH.ACADEMIC_YEAR = FF.ACADEMIC_YEAR
                        //                AND MH.FEE_ROOT_ID = ?FEE_ROOT_ID
                        //                AND MH.IS_DELETED != 1
                        //                LEFT JOIN
                        //            EXAM_HEADS AS EH ON EH.FEE_MAIN_HEAD_ID = MH.FEE_MAIN_HEAD_ID
                        //                AND EH.PROGRAMME_LEVEL_ID = C.CLASS_YEAR
                        //                AND EH.SHIFT_ID = PG.SHIFT
                        //                AND EH.FREQUENCY_ID = MH.FREQUENCY_ID
                        //                AND EH.IS_DELETED != 1
                        //        WHERE
                        //          FF.ACADEMIC_YEAR = ?AC_YEAR
                        //                AND FF.IS_DELETED != 1;";
                        //break;
                    }
                case ExaminationSQLCommands.FetchBatchandProgrammeBystudentId:
                    {
                        query = @"SELECT 
                                SC.PROGRAMME_GROUP_ID AS PROGRAMME, SC.BATCH, C.CLASS_YEAR
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                            WHERE
                                STUDENT_ID =?STUDENT_ID
                                    AND SC.ACADEMIC_YEAR =?AC_YEAR
                                    AND SC.IS_DELETED != 1;";
                        break;
                    }

                #region Exam Revaluation
                case ExaminationSQLCommands.FetchExamRevaluationSetting:
                    {
                        query = @"SELECT 
                                    concat(ES.EXAM_NAME,'-',ES.ACADEMIC_YEAR)  AS EXAM_SETTING,
                                    ES.EXAM_SETTING_ID,
                                    ERS.EXAM_REVALUATION_SETTING_ID,
                                    ERS.APPLICATION_TYPE_ID,
                                    IFNULL(SP.APPLICATION_TYPE,'') AS APPLICATION_TYPE,
                                    ERS.MAX_PAPER,
                                    DATE_FORMAT(ERS.START_DATE,'%Y-%m-%d') AS START_DATE,
                                    DATE_FORMAT(ERS.END_DATE,'%Y-%m-%d') AS END_DATE,
                                    ERS.ACADEMIC_YEAR,
                                    ERS.IS_ACTIVE
                                FROM
                                    EXAM_REVALUATION_SETTING AS ERS
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID
                                        AND ES.IS_DELETED != 1
                                        AND ES.IS_ACTIVE = 1
                                        INNER JOIN
                                    SUP_APPLICATION_TYPE AS SP ON SP.APPLICATION_TYPE_ID = ERS.APPLICATION_TYPE_ID
                                        AND SP.IS_DELETED != 1
                                WHERE
                                    -- DATE_FORMAT(ERS.START_DATE, '%Y-%m-%d') <= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                     --   AND DATE_FORMAT(ERS.END_DATE, '%Y-%m-%d') >= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                         ERS.ACADEMIC_YEAR =?AC_YEAR
                                        AND ERS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamRevaluationSetting:
                    {
                        query = @"INSERT INTO 
                                EXAM_REVALUATION_SETTING
                                (`EXAM_SETTING_ID`,
                                `APPLICATION_TYPE_ID`,
                                `MAX_PAPER`,
                                `START_DATE`,
                                `END_DATE`,
                                `ACADEMIC_YEAR`)
                              
                                VALUES
                                (?EXAM_SETTING_ID,
                                ?APPLICATION_TYPE_ID,
                                ?MAX_PAPER,
                                ?START_DATE,
                                ?END_DATE,
                                ?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamRevaluationSettingById:
                    {
                        query = @"UPDATE 
                                    EXAM_REVALUATION_SETTING
                                    SET
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID ,
                                    APPLICATION_TYPE_ID =?APPLICATION_TYPE_ID ,
                                    MAX_PAPER = ?MAX_PAPER ,
                                    START_DATE = ?START_DATE,
                                    END_DATE = ?END_DATE ,
                                    ACADEMIC_YEAR =?AC_YEAR 
                                    WHERE
                                    EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRevaluationSettingByRevalutionSettingId:
                    {
                        query = @"
                                SELECT 
                                    EXAM_REVALUATION_SETTING_ID,
                                    EXAM_SETTING_ID,
                                    APPLICATION_TYPE_ID,
                                    MAX_PAPER,
                                   DATE_FORMAT(START_DATE,'%d/%m/%Y') AS START_DATE,
                                    DATE_FORMAT(END_DATE,'%d/%m/%Y') AS END_DATE,
                                    ACADEMIC_YEAR
                                FROM
                                    EXAM_REVALUATION_SETTING
                                WHERE
                                    EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamRevaluationSettingByRevaluationId:
                    {
                        query = @"UPDATE EXAM_REVALUATION_SETTING 
                                SET 
                                    IS_DELETED = ?IS_DELETED
                                WHERE
                                    EXAM_REVALUATION_SETTING_ID = ?EXAM_REVALUATION_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ActiveandDeactiveExamRevaluationSettingBySettingId:
                    {
                        query = @"UPDATE EXAM_REVALUATION_SETTING 
                                  SET 
                                            IS_ACTIVE = ?IS_ACTIVE
                                        WHERE
                                            EXAM_REVALUATION_SETTING_ID = ?EXAM_REVALUATION_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRevaluationByExamSettingandApplicationTypeandAcademicYear:
                    {
                        query = @"SELECT 
                                    EXAM_REVALUATION_SETTING_ID,
                                    EXAM_SETTING_ID,
                                    APPLICATION_TYPE_ID,
                                    MAX_PAPER,
                                    START_DATE,
                                    END_DATE,
                                    ACADEMIC_YEAR
                                FROM
                                    EXAM_REVALUATION_SETTING
                                WHERE
                                    EXAM_SETTING_ID =?EXAM_SETTING_ID
                                        AND APPLICATION_TYPE_ID =?APPLICATION_TYPE_ID
                                        AND ACADEMIC_YEAR =?AC_YEAR
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRevaluationRegistrationByStudentId:
                    {
                        query = @"SELECT 
                                    ERR.EXAM_REVALUATION_REGISTER_ID,
                                    ERR.EXAM_REVALUATION_SETTING_ID,
                                    ERR.STUDENT_ID,
                                    CR.COURSE_ROOT_ID AS COURSE_ID,
                                    ERR.PAPERS,
                                    CONCAT(IFNULL(CR.COURSE_TITLE, ''),
                                            ' ',
                                            '(',
                                            IFNULL(CR.COURSE_CODE, ''),
                                            ')') AS COURSE_TITLE,
                                    ERR.AMOUNT,
                                    CONCAT(ES.EXAM_NAME, '-', ES.ACADEMIC_YEAR) AS EXAM_SETTING,
                                    ERR.REGISTERED_DATE
                                FROM
                                    EXAM_REVALUATION_REGISTRATION AS ERR
                                        INNER JOIN
                                    EXAM_REVALUATION_SETTING AS ERS ON ERS.EXAM_REVALUATION_SETTING_ID = ERR.EXAM_REVALUATION_SETTING_ID
                                        AND ERS.IS_ACTIVE = 1
                                        AND DATE_FORMAT(ERS.START_DATE, '%Y-%m-%d') <= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                        AND DATE_FORMAT(ERS.END_DATE, '%Y-%m-%d') >= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID
                                        AND ES.IS_ACTIVE = 1
                                        AND ES.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON FIND_IN_SET(CR.COURSE_ROOT_ID, ERR.PAPERS)
                                        AND CR.IS_DELETED != 1
                                WHERE
                                    ERR.STUDENT_ID =?STUDENT_ID
                                        AND ERR.ACADEMIC_YEAR =?AC_YEAR
                                        AND ERR.IS_DELETED != 1
                                GROUP BY CR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchRegularCoursewithmarksByExamRevaluationSettingandStudentId:
                    {
                        query = @"SELECT 
                                SM.COURSE_ID,
                                SM.INTERNAL_MARK,
                                SM.EXTERNAL_MARK,
                                SM.TOTAL,
                                 CONCAT(IFNULL(CR.COURSE_TITLE, ''),
                                        ' ',
                                        '(',
                                        IFNULL(CR.COURSE_CODE, ''),
                                        ')') AS COURSE_TITLE,
    
                                SM.RESULT
                            FROM
                                SEMESTER_MARKS_?AC_YEAR AS SM
                                    INNER JOIN
                                EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.EXAM_SETTING_ID = SM.EXAM_SETTING_ID
                                    AND ER.STUDENT_ID = SM.STUDENT_ID
                                    AND ER.COURSE_ID = SM.COURSE_ID
                                    AND ER.STATUS = 'R'
                                    AND ER.EXAM_SEMESTER = SM.SEMESTER
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                    AND SC.IS_DELETED != 1
                                    AND SC.ACADEMIC_YEAR =?AC_YEAR
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = SC.STUDENT_ID
                                    AND SPI.IS_DELETED != 1
                                    AND SPI.IS_LEFT != 1
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ER.COURSE_ID
                                    AND CR.IS_DELETED != 1
                                    INNER JOIN
                                CP_UGC_COURSE_TYPE AS CC ON CC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    AND CC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS CP ON CP.CLASS_ID = SC.CLASS_ID
                                    AND CP.IS_DELETED != 1
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS CPP ON CPP.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                    AND CPP.IS_DELETED != 1
                                    INNER JOIN
                                CP_PROGRAMME AS CPR ON CPR.PROGRAMME_ID = CPP.PROGRAMME_ID
                                    AND CPR.IS_DELETED != 1
                                    INNER JOIN
                                EXAM_REVALUATION_SETTING AS ERS ON ERS.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                    AND ERS.IS_DELETED != 1
                                    AND ERS.EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID
                                  -- AND ES.IS_ACTIVE = 1
                                    AND ES.IS_DELETED != 1
                                    INNER JOIN
                                SUP_BATCHES AS SB ON BATCH_ID = SC.BATCH
                                    AND SB.IS_DELETED != 1
                               --     INNER JOIN
                              --  ACADEMIC_SEMESTER AS S ON S.BATCH = SB.BATCH_ID
                               --     AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                               --     AND S.PROGRAMME_GROUP_ID = CPP.PROGRAMME_GROUP_ID
                               --     AND S.IS_DELETED != 1
                                --    AND S.SEMESTER = ER.EXAM_SEMESTER
                            WHERE
                                SM.ACADEMIC_YEAR =?AC_YEAR
                                    AND SM.STUDENT_ID =?STUDENT_ID                                  
                            GROUP BY CR.COURSE_ROOT_ID
                            ORDER BY CR.COURSE_ROOT_ID;";
                        break;
                    }


                case ExaminationSQLCommands.FetchRevaluatoinAmountByProgrammeandClassYearAndStudent:
                    {
                        query = @"SELECT 
                                        FEE_STRUCTURE_ID, FS.FREQUENCY, FS.AMOUNT,
                                        FS.HEAD,FS.FEE_MAIN_HEAD_ID
                                    FROM
                                        FEE_STRUCTURE AS FS
    
                                        INNER JOIN
                                        STU_CLASS AS SC ON SC.PROGRAMME_GROUP_ID=FS.PROGRAMME
                                        AND SC.ACADEMIC_YEAR=FS.ACADEMIC_YEAR
                                        AND SC.IS_DELETED!=1
    
                                        INNER JOIN
                                        STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID=SC.STUDENT_ID
                                        AND SPI.IS_DELETED!=1
                                         AND SPI.IS_LEFT!=1
                                         AND SPI.STUDENT_ID=?STUDENT_ID
    
										INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID=SC.CLASS_ID
                                        AND CC.IS_DELETED!=1
    
    
                                        INNER JOIN
                                        CP_PROGRAMME_GROUP AS CPP ON CPP.PROGRAMME_GROUP_ID=SC.PROGRAMME_GROUP_ID
                                        AND CPP.IS_DELETED!=1
    
                                        INNER JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID=CPP.PROGRAMME_ID
                                        AND CP.IS_DELETED!=1
                                        
                                        INNER JOIN
                                        SUP_FREQUENCY_TYPE AS SF ON SF.FREQUENCY_TYPE_ID=?FREQUENCY_TYPE_ID
                                        AND SF.IS_DELETED!=1
                                        
                                        INNER JOIN
                                        
                                        FEE_FREQUENCY_FEE_MODE AS FF ON FF.FEE_MODE=SF.FREQUENCY_TYPE_ID
                                        AND FF.ACADEMIC_YEAR=?AC_YEAR
                                        INNER JOIN
                                        SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID = FF.FREQUENCY_ID
                                            AND SFF.SEMESTER_TYPE = (SELECT 
                                                SST.SEMESTER_TYPE_ID
                                            FROM
                                                SUP_SEMESTER_TYPE AS SST
                                            WHERE
                                                IS_ACTIVE = 1 AND IS_DELETED != 1)
                                        INNER JOIN
                                        FEE_MAIN_HEADS AS FH ON FH.FREQUENCY_ID=FF.FEE_FREQUENCY_FEE_MODE_ID
                                        AND FH.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                        AND FH.APPLICATION_TYPE_ID=CPP.APPTYPE_ID
                                        AND FH.PROGRAMME_MODE=CPP.PROGRAMME_MODE
                                        AND FH.SHIFT=CPP.SHIFT
    
                                    WHERE
										 FS.FEE_MAIN_HEAD_ID=FH.FEE_MAIN_HEAD_ID
                                        AND FS.FREQUENCY=FH.FREQUENCY_ID
                                        AND FS.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                         AND FS.PROGRAMME=CPP.PROGRAMME_GROUP_ID
                                        AND FS.CLASS_YEAR_ID = CC.CLASS_YEAR
                                        AND FS.ACADEMIC_YEAR =?AC_YEAR
                                            group by SC.STUDENT_ID;";
                        break;
                    }

                case ExaminationSQLCommands.SaveExamRevaluationRegistration:
                    {
                        query = @"INSERT INTO EXAM_REVALUATION_REGISTRATION
                                    (EXAM_REVALUATION_SETTING_ID,
                                    STUDENT_ID,
                                    PAPERS,
                                    AMOUNT,
                                    REGISTERED_DATE,
                                    ACADEMIC_YEAR)
                                    VALUES
                                    (?EXAM_REVALUATION_SETTING_ID,
                                    ?STUDENT_ID,
                                    ?PAPERS,
                                    ?AMOUNT,
                                    NOW(),
                                    ?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamRevaluationRegistrationById:
                    {
                        query = @"UPDATE 
                                EXAM_REVALUATION_REGISTRATION
                                SET
                                EXAM_REVALUATION_SETTING_ID=?EXAM_REVALUATION_SETTING_ID,
                                STUDENT_ID=?STUDENT_ID,
                                PAPERS=?PAPERS,
                                AMOUNT=?AMOUNT,
                                REGISTERED_DATE=NOW(),
                                ACADEMIC_YEAR=?AC_YEAR

                                WHERE 

                                EXAM_REVALUATION_REGISTER_ID=?EXAM_REVALUATION_REGISTER_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchExamRevaluationRegistrationByRevaluationSettingandStudentId:
                    {
                        query = @"SELECT 

                            EXAM_REVALUATION_REGISTER_ID,
                            EXAM_REVALUATION_SETTING_ID
                            FROM 
                            EXAM_REVALUATION_REGISTRATION 

                            WHERE 
                            EXAM_REVALUATION_SETTING_ID=?EXAM_REVALUATION_SETTING_ID
                            AND STUDENT_ID=?STUDENT_ID
                            AND ACADEMIC_YEAR=?AC_YEAR
                            AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamRevaluationRegistrationById:
                    {
                        query = @"UPDATE 

                                EXAM_REVALUATION_REGISTRAION

                                SET 
                                IS_DELETED=?IS_DELETED

                                WHERE 
                                EXAM_REVALUATION_REGISTER_ID=?EXAM_REVALUATION_REGISTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchRevaluationRegistrationByRegisterId:
                    {
                        query = @"
                                SELECT 
                                EXAM_REVALUATION_REGISTER_ID,
                                EXAM_REVALUATION_SETTING_ID,
                                PAPERS,
                                AMOUNT

                                FROM 
                                EXAM_REVALUATION_REGISTRATION
                                WHERE 
                                EXAM_REVALUATION_REGISTER_ID=?EXAM_REVALUATION_REGISTER_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchRegularCoursewithmarksByExamRevaluationSettingandStudentIdAndCourse:
                    {
                        query = @"SELECT 
                                SM.COURSE_ID,
                                SM.INTERNAL_MARK,
                                SM.EXTERNAL_MARK,
                                SM.TOTAL,
                                 CONCAT(IFNULL(CR.COURSE_TITLE, ''),
                                        ' ',
                                        '(',
                                        IFNULL(CR.COURSE_CODE, ''),
                                        ')') AS COURSE_TITLE,
    
                                SM.RESULT
                            FROM
                                SEMESTER_MARKS_2018 AS SM
                                    INNER JOIN
                                EXAM_REGISTRATION_2018 AS ER ON ER.EXAM_SETTING_ID = SM.EXAM_SETTING_ID
                                    AND ER.STUDENT_ID = SM.STUDENT_ID
                                    AND ER.COURSE_ID = SM.COURSE_ID
                                    AND ER.STATUS = 'R'
                                    AND ER.EXAM_SEMESTER = SM.SEMESTER
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                    AND SC.IS_DELETED != 1
                                    AND SC.ACADEMIC_YEAR =?AC_YEAR
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = SC.STUDENT_ID
                                    AND SPI.IS_DELETED != 1
                                    AND SPI.IS_LEFT != 1
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ER.COURSE_ID
                                    AND CR.IS_DELETED != 1
                                    INNER JOIN
                                CP_UGC_COURSE_TYPE AS CC ON CC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    AND CC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS CP ON CP.CLASS_ID = SC.CLASS_ID
                                    AND CP.IS_DELETED != 1
                                    INNER JOIN
                                CP_PROGRAMME_GROUP AS CPP ON CPP.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                    AND CPP.IS_DELETED != 1
                                    INNER JOIN
                                CP_PROGRAMME AS CPR ON CPR.PROGRAMME_ID = CPP.PROGRAMME_ID
                                    AND CPR.IS_DELETED != 1
                                    INNER JOIN
                                EXAM_REVALUATION_SETTING AS ERS ON ERS.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                    AND ERS.IS_DELETED != 1
                                    AND ERS.EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID
                                    AND ES.IS_ACTIVE = 1
                                    AND ES.IS_DELETED != 1
                                    INNER JOIN
                                SUP_BATCHES AS SB ON BATCH_ID = SC.BATCH
                                    AND SB.IS_DELETED != 1
                               --     INNER JOIN
                              --  ACADEMIC_SEMESTER AS S ON S.BATCH = SB.BATCH_ID
                               --     AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                               --     AND S.PROGRAMME_GROUP_ID = CPP.PROGRAMME_GROUP_ID
                               --     AND S.IS_DELETED != 1
                                --    AND S.SEMESTER = ER.EXAM_SEMESTER
                            WHERE
                                SM.ACADEMIC_YEAR =?AC_YEAR
                                    AND SM.STUDENT_ID =?STUDENT_ID
                                    AND SM.COURSE_ID IN(?COURSE_ID)
                            GROUP BY CR.COURSE_ROOT_ID
                            ORDER BY CR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFeetructureForRevaluationBytudentIdandFrequency:
                    {
                        query = @"SELECT 
                                SC.STUDENT_ID,
                                FS.FREQUENCY,
                                FS.HEAD,
                                FS.FEE_MAIN_HEAD_ID,
                                FS.ACADEMIC_YEAR
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                                    INNER JOIN
                                CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                FEE_STRUCTURE AS FS ON FS.PROGRAMME = CL.PROGRAMME_GROUP_ID
                                    AND FS.CLASS_YEAR_ID = CL.CLASS_YEAR
                                    AND FS.FREQUENCY = ?FREQUENCY
                                    AND FS.AMOUNT != ''
                                    AND FS.IS_DELETED != 1
                            WHERE
                                SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    AND SC.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateFeeStudentAccountByStudentandFrequencyandHead:
                    {
                        query = @"UPDATE
                                    FEE_STUDENT_ACCOUNT
                                    SET 
                                    FREQUENCY_ID=?FREQUENCY_ID
                                    , HEAD=?HEAD,
                                    CREDIT=?CREDIT,
                                    FEE_MAIN_HEAD_ID=?FEE_MAIN_HEAD_ID
       
                                    WHERE 
                                    STUDENT_ID=?STUDENT_ID
                                    AND FREQUENCY_ID=?FREQUENCY_ID
                                    AND ACADEMIC_YEAR=?AC_YEAR
                                    AND HEAD=?HEAD;";
                        break;
                    }
                case ExaminationSQLCommands.FetchRevaluationSettingDetailsByStudentId:
                    {
                        query = @"
                                SELECT 
                                        CONCAT(ES.EXAM_NAME, '-', ES.ACADEMIC_YEAR) AS EXAM_SETTING,
                                        ES.EXAM_SETTING_ID,
                                        ERS.EXAM_REVALUATION_SETTING_ID,
                                        ERS.APPLICATION_TYPE_ID,
                                        IFNULL(SP.APPLICATION_TYPE, '') AS APPLICATION_TYPE,
                                        ERS.MAX_PAPER,
                                        DATE_FORMAT(ERS.START_DATE, '%Y-%m-%d') AS START_DATE,
                                        DATE_FORMAT(ERS.END_DATE, '%Y-%m-%d') AS END_DATE,
                                        IF(ERR.STUDENT_ID IS NULL OR '0',
                                            '0',
                                            '1') AS STATUS,
                                        ERS.ACADEMIC_YEAR,
                                        ERS.IS_ACTIVE,
                                        ERR.EXAM_REVALUATION_REGISTER_ID,
                                        DATE_FORMAT(ERR.REGISTERED_DATE, '%Y-%m-%d') AS REGISTERED_DATE,
                                        SUM(IFNULL(FSA.CREDIT, 0) - IFNULL(FSA.DEBIT,0)) AS BALANCE
                                    FROM
                                        EXAM_REVALUATION_SETTING AS ERS
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID
                                            AND ES.IS_DELETED != 1
                                            INNER JOIN
                                        sup_application_type AS SP ON SP.APPLICATION_TYPE_ID = ERS.APPLICATION_TYPE_ID
                                            LEFT JOIN
                                        exam_revaluation_registration AS ERR ON ERR.EXAM_REVALUATION_SETTING_ID = ERS.EXAM_REVALUATION_SETTING_ID AND ERR.IS_DELETED!=1
                                            AND ERR.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ERR.STUDENT_ID = ?STUDENT_ID 
                                            LEFT JOIN
                                        FEE_STUDENT_ACCOUNT AS FSA ON FSA.STUDENT_ID = ?STUDENT_ID
                                            AND FSA.FREQUENCY_ID = ERS.FREQUENCY_ID
                                    WHERE
                                     DATE_FORMAT(ERS.START_DATE, '%Y-%m-%d') <= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                                                            AND DATE_FORMAT(ERS.END_DATE, '%Y-%m-%d') >= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                                                            AND ERS.ACADEMIC_YEAR =?AC_YEAR
                                                                            AND ERS.IS_DELETED != 1 AND
                                        ERS.IS_ACTIVE = 1
                                        GROUP BY FSA.FREQUENCY_ID,FSA.STUDENT_ID
                                        ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRevaluationRegistrationDetailsByRevaluationSetting:
                    {
                        query = @"SELECT 
                                    CONCAT(ES.EXAM_NAME, '-', ES.ACADEMIC_YEAR) AS EXAM_SETTING,
                                    ES.EXAM_SETTING_ID,
                                    ERS.EXAM_REVALUATION_SETTING_ID,
                                    ERS.APPLICATION_TYPE_ID,
                                    IFNULL(SP.APPLICATION_TYPE, '') AS APPLICATION_TYPE,
                                    ERS.MAX_PAPER,
                                    DATE_FORMAT(ERS.START_DATE, '%Y-%m-%d') AS START_DATE,
                                    DATE_FORMAT(ERS.END_DATE, '%Y-%m-%d') AS END_DATE,
                                    IF(ERR.STUDENT_ID IS NULL OR '0',
                                        '0',
                                        '1') AS STATUS,
                                    ERS.ACADEMIC_YEAR,
                                    ERS.IS_ACTIVE,
                                    ERR.EXAM_REVALUATION_REGISTER_ID,
                                    DATE_FORMAT(ERR.REGISTERED_DATE, '%Y-%m-%d') AS REGISTERED_DATE,
                                    CONCAT(IFNULL(SPI.FIRST_NAME, ''),
                                            ' ',
                                            IFNULL(SPI.LAST_NAME, '')) AS FIRST_NAME,
                                    SPI.ROLL_NO,
                                    CP.PROGRAMME_NAME,
                                    CC.CLASS_NAME,
                                    ERR.PAPERS,
                                    FSA.CREDIT,
                                    FSA.DEBIT
                                FROM
                                    EXAM_REVALUATION_SETTING AS ERS
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID
                                        AND ES.IS_DELETED != 1                                        
                                        INNER JOIN
                                    SUP_APPLICATION_TYPE AS SP ON SP.APPLICATION_TYPE_ID = ERS.APPLICATION_TYPE_ID
                                        AND SP.IS_DELETED != 1
                                        INNER JOIN
                                    EXAM_REVALUATION_REGISTRATION AS ERR ON ERR.EXAM_REVALUATION_SETTING_ID = ERS.EXAM_REVALUATION_SETTING_ID
                                        AND ERR.ACADEMIC_YEAR =?AC_YEAR
                                        AND ERR.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = ERR.STUDENT_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR = ERR.ACADEMIC_YEAR
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = SC.STUDENT_ID
                                        AND SPI.IS_DELETED != 1
                                        AND SPI.IS_LEFT != 1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS CPP ON CPP.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                                        AND CPP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPP.PROGRAMME_ID
                                        AND CP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON find_in_set(CR.COURSE_ROOT_ID,ERR.PAPERS) 
                                        AND CR.IS_DELETED != 1
                                        INNER JOIN
                                  
                                       SUP_FREQUENCY_TYPE AS SFT ON SFT.frequency_type_id=?FREQUENCY_TYPE_ID
                                        AND SFT.IS_DELETED != 1
                                        
                                       INNER JOIN
                                    FEE_FREQUENCY_FEE_MODE FF ON FF.FEE_MODE = SFT.frequency_type_id
                                  
                                    
                                         INNER JOIN
                                    SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID = FF.FREQUENCY_ID
                                        AND SFF.IS_DELETED != 1
                                        
                                        INNER JOIN
                                        FEE_MAIN_HEADS AS FH ON FH.APPLICATION_TYPE_ID=CPP.APPTYPE_ID
                                        AND FH.PROGRAMME_MODE=CPP.PROGRAMME_MODE
                                        AND FH.SHIFT=CPP.SHIFT
                                        AND FH.ACADEMIC_YEAR=?AC_YEAR
                                        AND FH.FREQUENCY_ID=FF.FEE_FREQUENCY_FEE_MODE_ID
                                        
                                         INNER JOIN
                                    FEE_STRUCTURE AS FS ON FS.FEE_MAIN_HEAD_ID = FH.FEE_MAIN_HEAD_ID
                                     --   AND FS.FREQUENCY = FF.FEE_FREQUENCY_FEE_MODE_ID
                                     AND FS.PROGRAMME=CPP.PROGRAMME_GROUP_ID
                                        AND FS.CLASS_YEAR_ID = CC.CLASS_YEAR
                                        AND FS.ACADEMIC_YEAR =?AC_YEAR
                                         
                                        LEFT JOIN
                                    FEE_STUDENT_ACCOUNT AS FSA ON FSA.STUDENT_ID = SC.STUDENT_ID
                                        AND FSA.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND FSA.FEE_MAIN_HEAD_ID = FS.FEE_MAIN_HEAD_ID
                                       AND FSA.HEAD = FS.HEAD
                                         AND FSA.FREQUENCY_ID = FS.FREQUENCY
                                             AND FSA.DEBIT!=0
                                        AND FSA.IS_DELETED != 1
                                      
                                WHERE
                                    DATE_FORMAT(ERS.START_DATE, '%Y-%m-%d') <= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                        AND DATE_FORMAT(ERS.END_DATE, '%Y-%m-%d') >= DATE_FORMAT(NOW(), '%Y-%m-%d')
                                        AND ERS.EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID
                                        AND ERS.IS_DELETED != 1
                                GROUP BY ERR.EXAM_REVALUATION_REGISTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRevaluationRegistrationStuWiseDetailsByRevaluationSetting:
                    {
                        query = @"SELECT 
                                    SPI.REGISTER_NO,
                                    CONCAT(IFNULL(SPI.FIRST_NAME,''),'',IFNULL(SPI.LAST_NAME,'')) AS FIRST_NAME,
                                    CP.PROGRAMME_NAME,
                                    CONCAT(IFNULL(CR.COURSE_TITLE, ''),
                                            ' ',
                                            '(',
                                            IFNULL(CR.COURSE_CODE, ''),
                                            ')') AS COURSE_TITLE,
                                    CR.COURSE_CODE,
                                      CONCAT(ES.EXAM_NAME, '-', ES.ACADEMIC_YEAR) AS EXAM_SETTING
                                FROM
                                    EXAM_REVALUATION_SETTING AS ERS
                                        INNER JOIN
                                    EXAM_REVALUATION_REGISTRATION AS ERR ON ERR.EXAM_REVALUATION_SETTING_ID = ERS.EXAM_REVALUATION_SETTING_ID
                                        AND ERR.IS_DELETED != 1
                                        AND ERR.ACADEMIC_YEAR =?AC_YEAR
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID                                       
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON FIND_IN_SET(CR.COURSE_ROOT_ID, ERR.PAPERS)
                                        AND CR.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = ERR.STUDENT_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR =?AC_YEAR
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = SC.STUDENT_ID
                                        AND SPI.IS_DELETED != 1
                                        AND SPI.IS_LEFT != 1
									
                                        INNER JOIN
                                        CP_PROGRAMME_GROUP AS CPP ON CPP.PROGRAMME_GROUP_ID=SC.PROGRAMME_GROUP_ID
                                        AND CPP.IS_DELETED!=1
                                        
                                        INNER JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID=CPP.PROGRAMME_ID
                                        AND CP.IS_DELETED!=1
                                        
                                         INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.IS_DELETED != 1
                                        
                                        INNER JOIN
                                        
                                        SUP_FREQUENCY_TYPE AS SFT ON SFT.frequency_type_id=?FREQUENCY_TYPE_ID
                                        AND SFT.IS_DELETED != 1
                                        
                                       INNER JOIN
                                    FEE_FREQUENCY_FEE_MODE FF ON FF.FEE_MODE = SFT.frequency_type_id
                                  
                                    
                                         INNER JOIN
                                    SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID = FF.FREQUENCY_ID
                                        AND SFF.IS_DELETED != 1
                                        
                                        INNER JOIN
                                        FEE_MAIN_HEADS AS FH ON FH.APPLICATION_TYPE_ID=CPP.APPTYPE_ID
                                        AND FH.PROGRAMME_MODE=CPP.PROGRAMME_MODE
                                        AND FH.SHIFT=CPP.SHIFT
                                        AND FH.ACADEMIC_YEAR=?AC_YEAR
                                        AND FH.FREQUENCY_ID=FF.FEE_FREQUENCY_FEE_MODE_ID
                                        
                                         INNER JOIN
                                    FEE_STRUCTURE AS FS ON FS.FEE_MAIN_HEAD_ID = FH.FEE_MAIN_HEAD_ID
                                     --   AND FS.FREQUENCY = FF.FEE_FREQUENCY_FEE_MODE_ID
                                     AND FS.PROGRAMME=CPP.PROGRAMME_GROUP_ID
                                        AND FS.CLASS_YEAR_ID = CC.CLASS_YEAR
                                        AND FS.ACADEMIC_YEAR =?AC_YEAR
                                         
                                        INNER JOIN
                                    FEE_STUDENT_ACCOUNT AS FSA ON FSA.STUDENT_ID = SC.STUDENT_ID
                                        AND FSA.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND FSA.FEE_MAIN_HEAD_ID = FS.FEE_MAIN_HEAD_ID
                                       AND FSA.HEAD = FS.HEAD
                                         AND FSA.FREQUENCY_ID = FS.FREQUENCY
                                             AND FSA.DEBIT!=0
                                        AND FSA.IS_DELETED != 1
                                        
                                        
                                WHERE
                                    ERS.EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID
                                        AND ERS.IS_DELETED != 1
                                GROUP BY ERR.STUDENT_ID,CR.COURSE_ROOT_ID order by ERR.EXAM_REVALUATION_REGISTER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRevaluationRegistrationCourseWiseDetailsByRevaluationSetting:
                    {
                        query = @"SELECT 
                                    SPI.REGISTER_NO,
                                     CONCAT(IFNULL(SPI.FIRST_NAME,''),'',IFNULL(SPI.LAST_NAME,'')) AS FIRST_NAME,
                                    CP.PROGRAMME_NAME,
                                    CONCAT(IFNULL(CR.COURSE_TITLE, ''),
                                            ' ',
                                            '(',
                                            IFNULL(CR.COURSE_CODE, ''),
                                            ')') AS COURSE_TITLE,
                                    CR.COURSE_CODE,
                                      CONCAT(ES.EXAM_NAME, '-', ES.ACADEMIC_YEAR) AS EXAM_SETTING
                                FROM
                                    EXAM_REVALUATION_SETTING AS ERS
                                        INNER JOIN
                                    EXAM_REVALUATION_REGISTRATION AS ERR ON ERR.EXAM_REVALUATION_SETTING_ID = ERS.EXAM_REVALUATION_SETTING_ID
                                        AND ERR.IS_DELETED != 1
                                        AND ERR.ACADEMIC_YEAR =?AC_YEAR
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ERS.EXAM_SETTING_ID                                     
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON FIND_IN_SET(CR.COURSE_ROOT_ID, ERR.PAPERS)
                                        AND CR.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = ERR.STUDENT_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR =?AC_YEAR
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = SC.STUDENT_ID
                                        AND SPI.IS_DELETED != 1
                                        AND SPI.IS_LEFT != 1
                                           INNER JOIN
                                        CP_PROGRAMME_GROUP AS CPP ON CPP.PROGRAMME_GROUP_ID=SC.PROGRAMME_GROUP_ID
                                        AND CPP.IS_DELETED!=1
                                        
                                        INNER JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID=CPP.PROGRAMME_ID
                                        AND CP.IS_DELETED!=1
                                          INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.IS_DELETED != 1
                                        
                                        INNER JOIN
                                        
                                        SUP_FREQUENCY_TYPE AS SFT ON SFT.frequency_type_id=?FREQUENCY_TYPE_ID
                                        AND SFT.IS_DELETED != 1
                                        
                                       INNER JOIN
                                    FEE_FREQUENCY_FEE_MODE FF ON FF.FEE_MODE = SFT.frequency_type_id
                                  
                                    
                                         INNER JOIN
                                    SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID = FF.FREQUENCY_ID
                                        AND SFF.IS_DELETED != 1
                                        
                                        INNER JOIN
                                        FEE_MAIN_HEADS AS FH ON FH.APPLICATION_TYPE_ID=CPP.APPTYPE_ID
                                        AND FH.PROGRAMME_MODE=CPP.PROGRAMME_MODE
                                        AND FH.SHIFT=CPP.SHIFT
                                        AND FH.ACADEMIC_YEAR=?AC_YEAR
                                        AND FH.FREQUENCY_ID=FF.FEE_FREQUENCY_FEE_MODE_ID
                                        
                                         INNER JOIN
                                    FEE_STRUCTURE AS FS ON FS.FEE_MAIN_HEAD_ID = FH.FEE_MAIN_HEAD_ID
                                     --   AND FS.FREQUENCY = FF.FEE_FREQUENCY_FEE_MODE_ID
                                     AND FS.PROGRAMME=CPP.PROGRAMME_GROUP_ID
                                        AND FS.CLASS_YEAR_ID = CC.CLASS_YEAR
                                        AND FS.ACADEMIC_YEAR =?AC_YEAR
                                         
                                        INNER JOIN
                                    FEE_STUDENT_ACCOUNT AS FSA ON FSA.STUDENT_ID = SC.STUDENT_ID
                                        AND FSA.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND FSA.FEE_MAIN_HEAD_ID = FS.FEE_MAIN_HEAD_ID
                                       AND FSA.HEAD = FS.HEAD
                                         AND FSA.FREQUENCY_ID = FS.FREQUENCY
                                             AND FSA.DEBIT!=0
                                        AND FSA.IS_DELETED != 1
                                        
                                        
                                WHERE
                                    ERS.EXAM_REVALUATION_SETTING_ID =?EXAM_REVALUATION_SETTING_ID
                                        AND ERS.IS_DELETED != 1
                                GROUP BY ERR.STUDENT_ID,CR.COURSE_ROOT_ID order by CR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchRevaluationRegisteredCoursePapersByRevaluationRegisterId:
                    {
                        query = @"SELECT
                                      CONCAT(IFNULL(CR.COURSE_TITLE, ''),
                                                ' ',
                                                '(',
                                                IFNULL(CR.COURSE_CODE, ''),
                                                ')') AS COURSE_TITLE,
                                                CR.COURSE_CODE,
                                                COURSE_ROOT_ID
                                    FROM EXAM_REVALUATION_REGISTRATION AS ERR 
                                    INNER JOIN
                                     CP_COURSE_ROOT AS CR ON find_in_set(CR.COURSE_ROOT_ID,ERR.PAPERS)  
                                    AND CR.IS_DELETED!=1

                                    WHERE 
                                    ERR.EXAM_REVALUATION_REGISTER_ID=?EXAM_REVALUATION_REGISTER_ID
                                    AND ERR.IS_DELETED!=1
                                    GROUP BY CR.COURSE_ROOT_ID;";
