                    }
                case ExaminationSQLCommands.FetchExamSettingAcademicYearByRevaluationSettingId:
                    {
                        query = @"SELECT 
                                    ES.academic_year as AC_YEAR
                                    FROM exam_revaluation_setting AS ERS 
                                    INNER JOIN
                                    EXAM_SETTING AS ES ON ES.exam_setting_id=ERS.EXAM_SETTING_ID
                                    AND ES.IS_DELETED!=1

                                    WHERE 
                                    ERS.EXAM_REVALUATION_SETTING_ID=?EXAM_REVALUATION_SETTING_ID
                                    AND ERS.IS_DELETED!=1;";
