                                        AND CC.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CPR ON FIND_IN_SET(CPR.COURSE_ROOT_ID, EPR.PAPERS)
                                        AND CPR.IS_DELETED != 1
                                        INNER JOIN
                                    EXAM_PHOTOCOPY_FILES AS EP ON EP.COURSE_ID = CPR.COURSE_ROOT_ID
                                        AND EP.EXAM_PHOTOCOPY_REGISTER_ID = EPR.EXAM_PHOTOCOPY_REGISTER_ID
                                        AND EP.IS_DELETED != 1
                                WHERE
                                    EPR.EXAM_PHOTOCOPY_REGISTER_ID =?EXAM_PHOTOCOPY_REGISTER_ID
                                        AND EPR.IS_DELETED != 1
                                GROUP BY CPR.COURSE_ROOT_ID;";
                        break;
                    }

                case ExaminationSQLCommands.SaveExamPhotoCopyFiles:
                    {
                        query = @"INSERT INTO 
                                 exam_photocopy_files
                                 (EXAM_PHOTOCOPY_REGISTER_ID,
                                 PHOTOCOPY,
                                 COURSE_ID,
                                 ACADEMIC_YEAR)
                                 VALUES(?EXAM_PHOTOCOPY_REGISTER_ID,
                                 ?PHOTOCOPY,
                                 ?COURSE_ID,
                                 ?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamPhotoCopyFiles:
                    {
                        query = @"UPDATE 
                                 exam_photocopy_files
                                 SET 
                                    EXAM_PHOTOCOPY_REGISTER_ID=?EXAM_PHOTOCOPY_REGISTER_ID,
                                     PHOTOCOPY=?PHOTOCOPY,
	                                 COURSE_ID=?COURSE_ID,
	                                 ACADEMIC_YEAR=?AC_YEAR
	                                WHERE 
                                    EXAM_PHOTOCOPY_FILE_ID=?EXAM_PHOTOCOPY_FILE_ID;";
                        break;
                    }
                #endregion

                case ExaminationSQLCommands.FetchStudentAllYearAndBatchWithSemester:
                    {
                        query = @"SELECT 
                                        SC.ACADEMIC_YEAR AS AC_YEAR,
                                        SC.PROGRAMME_GROUP_ID AS PROGRAMME,
                                        SC.BATCH,
                                        GROUP_CONCAT(SEM.SEMESTER) AS SEMESTER,
                                        SEM.IS_ACTIVE
                                    FROM
                                        STU_CLASS AS SC
		                                    INNER JOIN
	                                    ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID=SC.PROGRAMME_GROUP_ID
		                                    AND SEM.BATCH=SC.BATCH
                                            AND SEM.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND SEM.IS_DELETED!=1
                                    WHERE
                                        STUDENT_ID = ?STUDENT_ID AND SC.IS_DELETED!=1 GROUP BY SC.ACADEMIC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchIndividualComponentMarkForCIA:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        SP.FIRST_NAME,
                                        SP.REGISTER_NO,
                                        SP.ROLL_NO,
                                        GM.COURSE_GROUP_ID,
                                        GC.ORDER_ID,
                                        CONCAT(CC.COMPONENT,'( ',GC.MAX_MARK,' )') AS COMPONENT,
                                        GM.COURSE_GROUP_MARK,GC.MAX_MARK
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
                                        CIA_GROUP_MARKS_?AC_YEAR AS GM ON GM.STUDENT_ID = SC.STUDENT_ID
                                            AND GM.COURSE_ID = ?COURSE_ID
                                           -- AND GM.COURSE_GROUP_ID IN (?COURSE_GROUP_ID)
                                            INNER JOIN
										CIA_GROUP_COMPONENT AS GC ON GC.CIA_GROUP_COMPONENT_ID=GM.COURSE_GROUP_ID
											AND GC.IS_DELETED!=1
                                            INNER JOIN
										CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID=GC.CIA_GROUP_ID 
											INNER JOIN
										SUP_CIA_COMPONENTS AS CC ON CC.COMPONENT_ID=GC.SUP_CIA_COMPONENT_ID
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR AND SC.CLASS_ID=?CLASS_ID
                                            AND SC.IS_DELETED != 1 
                                    UNION SELECT 
                                        SP.STUDENT_ID,
                                        SP.FIRST_NAME,
                                        SP.REGISTER_NO,
                                        SP.ROLL_NO,
                                        GM.COURSE_GROUP_ID,
                                        GC.ORDER_ID,
                                        CONCAT(CC.COMPONENT,'( ',GC.MAX_MARK,' )') AS COMPONENT,
                                        GM.COURSE_GROUP_MARK,GC.MAX_MARK
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
                                        CIA_GROUP_MARKS_?AC_YEAR AS GM ON GM.STUDENT_ID = SC.STUDENT_ID
                                            AND GM.COURSE_ID = ?COURSE_ID
                                            -- AND GM.COURSE_GROUP_ID IN (?COURSE_GROUP_ID)
                                            INNER JOIN
										CIA_GROUP_COMPONENT AS GC ON GC.CIA_GROUP_COMPONENT_ID=GM.COURSE_GROUP_ID
											AND GC.IS_DELETED!=1
                                            INNER JOIN
										CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID=GC.CIA_GROUP_ID 
											INNER JOIN
										SUP_CIA_COMPONENTS AS CC ON CC.COMPONENT_ID=GC.SUP_CIA_COMPONENT_ID
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.COURSE_ID = ?COURSE_ID
                                            AND SC.S_CLASS_ID = ?CLASS_ID
                                            AND SC.IS_DELETED != 1 ORDER BY ORDER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchComponentByCourseId:
                    {
                        query = @"SELECT 
                                        CG.CIA_GROUP_COMPONENT_ID AS COMPONENT_ID,
                                        CONCAT(IFNULL(CC.COMPONENT, ''),
                                                ' ( ',
                                                CG.MAX_MARK,
                                                ' ) ') AS COMPONENT
                                    FROM
                                        cp_course_root AS CCR
                                            INNER JOIN
                                        CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                            INNER JOIN
                                        CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CT.COURSE_TYPE_ID
                                            INNER JOIN
                                        CIA_GROUP_COMPONENT AS CG ON CG.CIA_GROUP_ID = CTG.GROUP_ID
                                            INNER JOIN
                                        SUP_CIA_COMPONENTS AS CC ON CC.COMPONENT_ID = CG.SUP_CIA_COMPONENT_ID
                                    WHERE
                                        COURSE_ROOT_ID = ?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchUrNumberByStudentId:
                    {
                        query = @"SELECT STUDENT_ID,FREQUENCY,FEE_TRANSACTION_BANK FROM FEE_TRANSACTION WHERE STUDENT_ID=?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCoursesWiseCostForExam:
                    {
                        query = @"SELECT 
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        UGC.COST
                                    FROM
                                        CP_COURSE_ROOT AS CCR 
                                            INNER JOIN
                                        EXAM_COURSE_WISE_COST AS EC ON EC.COURSE_CODE = CCR.COURSE_CODE
                                            AND EC.IS_DELETED != 1 AND EC.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                            AND EC.ACADEMIC_YEAR = ?AC_YEAR
                                            INNER JOIN
                                        EXAM_UGC_COURSE_TYPE_COST AS UGC ON UGC.UGC_TYPE_COST_ID = EC.UGC_TYPE_COST_ID
                                            AND UGC.IS_DELETED != 1
                                    WHERE
                                            CCR.IS_DELETED != 1";
                        break;
                    }
                case ExaminationSQLCommands.FetchRegisteredStudentCount:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CONCAT(IFNULL(SP.FIRST_NAME,''),'  ',IFNULL(SP.LAST_NAME,'')) AS FIRST_NAME,
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        COUNT(ER.COURSE_ID) AS 'COURSE'
                                    FROM 
                                        STU_CLASS AS SC
                                            LEFT JOIN
                                        EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.STUDENT_ID = SC.STUDENT_ID
                                            AND ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND ER.IS_DELETED != 1
                                            INNER JOIN
	                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=SC.STUDENT_ID
		                                    AND SP.IS_DELETED!=1
                                    WHERE
                                        SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.CLASS_ID = ?CLASS_ID
                                            AND SC.IS_DELETED != 1
                                            GROUP BY SC.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegisteredListByStudentId:
                    {
                        query = @"SELECT 
                                        ER.REGISTRATION_ID,
                                        ER.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        CCR.SEMESTER_ID,
                                        ER.STATUS
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = ER.COURSE_ID
                                            AND CCR.IS_DELETED != 1
                                    WHERE
                                        ER.IS_DELETED != 1
                                            AND ER.STUDENT_ID = ?STUDENT_ID
                                            AND ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamRegistration:
                    {
                        query = @"INSERT INTO EXAM_REGISTRATION_?AC_YEAR
                                  (
	                                  STUDENT_ID,
	                                  COURSE_ID,
	                                  STATUS,
	                                  ACADEMIC_YEAR,
	                                  EXAM_SEMESTER,
	                                  EXAM_SETTING_ID
                                  )VALUES
                                  (
	                                  ?STUDENT_ID,
	                                  ?COURSE_ID,
	                                  ?STATUS,
	                                  ?AC_YEAR,
	                                  ?EXAM_SEMESTER,
	                                  ?EXAM_SETTING_ID
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegisteredListByClassId:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID,
                                        SC.STUDENT_ID,
                                        CC.COURSE_CODE,
                                        CC.COURSE_TITLE,
                                        ER.COURSE_ID,
                                        STATUS,
                                        ER.ACADEMIC_YEAR,
                                        S.SEMESTER_NAME AS 'SEMESTER_ID',
                                        ES.M_PASS AS 'MONTH_YEAR',
                                        CC.SEMESTER_ID AS 'SEMESTER',
                                        ER.AMOUNT
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.STUDENT_ID = SC.STUDENT_ID
                                            AND ER.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CC.SEMESTER_ID
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE = 1
                                            AND ES.IS_DELETED != 1
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID  
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamHeadsWithFrequencyAndCost:
                    {
                        query = @"SELECT 
                                        PG.PROGRAMME_GROUP_ID,
                                        FM.FEE_FREQUENCY_FEE_MODE_ID,
                                        MH.FEE_MAIN_HEAD_ID,
                                        MH.MAIN_HEAD_ID,
                                        MH.HEAD_ID,
                                        EH.EXAM_HEAD_ID,
                                        EH.COST 
                                    FROM 
                                        SUP_FEE_FREQUENCY AS FF
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = FF.SEMESTER_TYPE
                                            AND ST.IS_ACTIVE = 1
                                            AND ST.IS_DELETED != 1
                                            INNER JOIN
                                        FEE_FREQUENCY_FEE_MODE AS FM ON FM.FREQUENCY_ID = FF.FREQUENCY_ID
                                            AND FM.FEE_MODE = 1
                                            AND FM.ACADEMIC_YEAR = FF.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FM.FEE_MODE
                                            AND FT.FEE_ROOT_ID = ?FEE_ROOT_ID
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = ?CLASS_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        FEE_MAIN_HEADS AS MH ON MH.FREQUENCY_ID = FM.FEE_FREQUENCY_FEE_MODE_ID
                                            AND MH.SHIFT = PG.SHIFT
                                            AND MH.PROGRAMME_MODE = PG.PROGRAMME_MODE
                                            AND MH.APPLICATION_TYPE_ID = PG.APPTYPE_ID
                                            AND MH.ACADEMIC_YEAR = FF.ACADEMIC_YEAR
                                            AND MH.FEE_ROOT_ID = ?FEE_ROOT_ID
                                            AND MH.IS_DELETED != 1
                                            LEFT JOIN
                                        EXAM_HEADS AS EH ON EH.FEE_MAIN_HEAD_ID = MH.FEE_MAIN_HEAD_ID
                                            AND EH.PROGRAMME_LEVEL_ID = C.CLASS_YEAR
                                            AND EH.SHIFT_ID = PG.SHIFT
                                            AND EH.FREQUENCY_ID = MH.FREQUENCY_ID
		                                    AND EH.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                            AND EH.IS_DELETED != 1 
                                    WHERE
                                        FF.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FF.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamFeedetailsByHeadAndStudentId:
                    {
                        query = @"SELECT 
                                        FS.F_STUDENT_AC_ID,FS.STUDENT_ID,SUM(FS.CREDIT - ?CREDIT) AS CREDIT
                                    FROM
                                        FEE_STUDENT_ACCOUNT AS FS
		                                    INNER JOIN
	                                    FEE_MAIN_HEADS AS FM ON FM.FEE_MAIN_HEAD_ID=FS.FEE_MAIN_HEAD_ID
		                                    AND FM.IS_DELETED!=1
                                            INNER JOIN
	                                    FEE_FREQUENCY_FEE_MODE AS FF ON FF.FEE_FREQUENCY_FEE_MODE_ID=FM.FREQUENCY_ID
		                                    AND FF.ACADEMIC_YEAR=?AC_YEAR
                                            AND FF.FEE_MODE=1
                                            INNER JOIN
	                                    SUP_FEE_FREQUENCY AS SF ON SF.FREQUENCY_ID=FF.FREQUENCY_ID
		                                    INNER JOIN
	                                    SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID=SF.SEMESTER_TYPE
		                                    AND SST.IS_ACTIVE=1
                                    WHERE
                                        FS.STUDENT_ID = ?STUDENT_ID
                                            AND FS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FS.HEAD = ?HEAD;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFeeStudentAccountCreditById:
                    {
                        query = @"UPDATE FEE_STUDENT_ACCOUNT SET CREDIT=?CREDIT WHERE F_STUDENT_AC_ID=?F_STUDENT_AC_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseCostFromExamRegistration:
                    {
                        query = @"SELECT 
                                        ER.COURSE_ID,
                                        UGC.COST
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER 
                                            INNER JOIN
                                        EXAM_COURSE_WISE_COST AS CC ON CC.COURSE_ID = ER.COURSE_ID
                                            AND CC.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                            AND CC.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            AND CC.IS_DELETED != 1
                                            INNER JOIN
                                        EXAM_UGC_COURSE_TYPE_COST AS UGC ON UGC.UGC_TYPE_COST_ID = CC.UGC_TYPE_COST_ID
                                    WHERE
                                            ER.ACADEMIC_YEAR = ?AC_YEAR 
                                            AND ER.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                            AND ER.IS_DELETED != 1
                                    GROUP BY ER.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamFeeDetailsByClassId:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        H.HEAD,
                                        FS.CREDIT
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
		                                    AND FS.DEBIT IS NULL
                                            INNER JOIN
	                                    FEE_FREQUENCY_FEE_MODE AS FF ON FF.FEE_FREQUENCY_FEE_MODE_ID=FS.FREQUENCY_ID
		                                    AND FF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            AND FF.FEE_MODE=?FEE_MODE
                                            INNER JOIN
	                                    SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID=FF.FREQUENCY_ID
		                                    AND SFF.SEMESTER_TYPE=(SELECT SEMESTER_TYPE_ID FROM SUP_SEMESTER_TYPE WHERE IS_ACTIVE=1)
                                            INNER JOIN
                                        SUP_HEAD AS H ON H.HEAD_ID = FS.HEAD
                                    WHERE
                                        SC.CLASS_ID = ?CLASS AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.IsExamRegistrationExistByStudentId:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID, 
                                        STUDENT_ID, 
                                        COURSE_ID, 
                                        STATUS
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR
                                    WHERE
                                        STUDENT_ID = ?STUDENT_ID
                                            AND EXAM_SETTING_ID = ?EXAM_SETTING_ID AND IS_DELETED!=1;";
                        break;
                    }
                #region Seating Allotement For SJC
                case ExaminationSQLCommands.FetchExamTimeTableBySettingId:
                    {
                        query = @"SELECT 
                                        TIMETABLE_ID, 
                                        DATE_FORMAT(EXAM_DATE,'%Y-%m-%d') AS EXAM_DATE,
                                        EXAM_TIME,
                                        GROUP_CONCAT(COURSE_ID) COURSE_ID,
                                        COURSE_CODE,
                                        ACADEMIC_YEAR,
                                        EXAM_SETTING_ID,
                                        EXAM_SESSION_ID
                                    FROM
                                        EXAM_TIMETABLE AS TT
                                    WHERE
                                        TT.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND TT.ACADEMIC_YEAR = ?AC_YEAR
                                            AND TT.IS_DELETED != 1 
                                    GROUP BY EXAM_DATE,EXAM_SESSION_ID ORDER BY EXAM_DATE,EXAM_SESSION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseFromExamRegistrationByCourseAndSettingId:
                    {
                        query = @"SELECT 
                                        ER.STUDENT_ID,
                                        SP.ROLL_NO,
                                        ER.COURSE_ID,
                                        ER.STATUS,
                                        ER.EXAM_SETTING_ID,
                                        C.CLASS_ID,
                                        C.SHIFT
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                    WHERE
                                        ER.EXAM_SETTING_ID =?EXAM_SETTING_ID
                                            AND ER.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ER.COURSE_ID IN (?COURSE_ID)
                                            AND ER.IS_DELETED != 1 
        
                                    UNION SELECT 
                                        ER.STUDENT_ID,
                                        SP.ROLL_NO,
                                        ER.COURSE_ID,
                                        ER.STATUS,
                                        ER.EXAM_SETTING_ID,
                                        '1' AS CLASS_ID,
                                        '1' AS SHIFT
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ER.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                    WHERE
                                        ER.EXAM_SETTING_ID = ?ARREAR_SETTING_ID
                                            AND ER.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ER.COURSE_ID IN (?COURSE_ID)
                                            AND ER.IS_DELETED != 1
                                    ORDER BY COURSE_ID,CLASS_ID,ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSeating:
                    {
                        query = @"SELECT 
                                        SEATING_ID,
                                        ROOM_ID,
                                        COLUMN_NO,
                                        ROW_NO,
                                        SEAT_CODE,
                                        SEAT_POSITION,
                                        SEATING_ALLOTEMENT_ID
                                    FROM
                                        (SELECT 
                                            ES.SEATING_ID,
                                                ES.ROOM_ID,
                                                ES.COLUMN_NO,
                                                ES.ROW_NO,
                                                ES.SEAT_CODE,
                                                ES.SEAT_POSITION,
                                                SA.SEATING_ALLOTEMENT_ID
                                        FROM
                                            EXAM_SEATINGS AS ES
                                                LEFT JOIN 
                                            EXAM_SEATING_ALLOTEMENT AS SA ON SA.SEATING_ID = ES.SEATING_ID
                                                AND SA.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                                AND SA.EXAM_DATE = ?EXAM_DATE
                                                AND SA.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                                AND SA.ACADEMIC_YEAR = ?AC_YEAR
                                                AND SA.IS_DELETED != 1) AS T
                                    WHERE
                                        T.SEATING_ALLOTEMENT_ID IS NULL
                                    ORDER BY T.ROOM_ID ,  T.COLUMN_NO , T.ROW_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseAndStudentCount:
                    {
                        query = @"SELECT 
                                        COURSE_ID,
                                        COUNT(STUDENT_ID) AS STUDENT_COUNT,
                                        STATUS
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR
                                    WHERE
                                        EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                            AND IS_DELETED != 1
                                            AND COURSE_ID IN (?COURSE_ID)
                                    GROUP BY COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSeatingAllotementForSJC:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        UPPER(CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                        ' ',
                                                        IFNULL(SP.LAST_NAME, ''))) AS FIRST_NAME,
                                        UPPER(IFNULL(SP.REGISTER_NO, SP.ROLL_NO)) AS REGISTER_NO,
                                        UPPER(SP.ROLL_NO) AS ROLL_NO,
                                        SA.COURSE_ID,
                                        IF(SA.IS_ARREAR='1',CONCAT('*',CCR.COURSE_CODE),CCR.COURSE_CODE) AS COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS DATE_OF_BIRTH,
                                        DATE_FORMAT(SA.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                        ES.SEAT_CODE,
                                        ES.ROOM_ID,
                                        SR.ROOM_NO,
                                        CB.BLOCK_NAME,
                                        SUM(SR.ROW * SPACE_COLUMN) AS ROW,
                                        IF(SEAT_CODE LIKE '%A%',
                                            'A',
                                            IF(SEAT_CODE LIKE '%B%',
                                                'B',
                                                IF(SEAT_CODE LIKE '%C%', 'C', ''))) AS SEAT_CODE_ID,
                                        CONCAT(SESSION_NAME, ' - ', DESCRIPTION) AS SESSION_NAME
                                    FROM
                                        EXAM_SEATING_ALLOTEMENT AS SA
                                            INNER JOIN
                                        EXAM_SEATINGS_?AC_YEAR AS ES ON ES.SEATING_ID = SA.SEATING_ID
                                            AND ES.IS_DELETED != 1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SA.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SA.COURSE_ID
                                            AND CCR.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_ROOM AS SR ON SR.ROOM_ID = ES.ROOM_ID
                                            INNER JOIN
                                        SUP_COLLEGE_BLOCK AS CB ON CB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                            INNER JOIN
                                        SUP_SESSION AS SS ON SS.SESSION_ID = SA.EXAM_SESSION_ID
                                    WHERE
                                        SA.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SA.EXAM_DATE = ?EXAM_DATE
                                            AND SA.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                            AND SA.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                            AND SA.IS_DELETED != 1 GROUP BY SP.STUDENT_ID
                                    ORDER BY ES.ROOM_ID , ES.COLUMN_NO , ES.ROW_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemHallTicketByClassId:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID,
                                        ER.STUDENT_ID,
                                        IF(ER.STATUS!='R',CONCAT('*',CC.COURSE_CODE),CC.COURSE_CODE) AS COURSE_CODE,
                                        CC.COURSE_TITLE,
                                        IF(ET.IS_ADVANCE = '1',
                                            DATE_FORMAT(ET.ADVANCE_DATE, '%d/%m/%Y'),
                                            IF(ET.IS_POSTPONED = '1',
                                                DATE_FORMAT(ET.POSTPONED_DATE, '%d/%m/%Y'),
                                                DATE_FORMAT(ET.EXAM_DATE, '%d/%m/%Y'))) AS EXAM_DATE,
                                        IF(ET.IS_ADVANCE = '1',
                                            ET.ADVANCE_TIME,
                                            IF(ET.IS_POSTPONED = '1',
                                                ET.POSTPONED_TIME,
                                                ET.EXAM_TIME)) AS EXAM_TIME,
                                        ER.COURSE_ID,
                                        STATUS,
                                        ER.ACADEMIC_YEAR,
                                        S.SEMESTER_NAME AS 'SEMESTER_ID',
                                        ES.M_PASS AS 'MONTH_YEAR',
                                        CC.SEMESTER_ID AS 'SEMESTER',
                                        CONCAT(IFNULL(SCB.BLOCK_CODE,''),' : ',IFNULL(SR.ROOM_NO,''),' : ',IFNULL(ESS.SEAT_CODE,'')) AS SEAT_CODE,
                                        SCB.BLOCK_CODE,
                                        SCB.BLOCK_NAME,
										SS.SESSION_NAME
                                    FROM
                                       EXAM_REGISTRATION_?AC_YEAR AS ER
										   INNER JOIN
									   STU_CLASS AS SC ON SC.STUDENT_ID=ER.STUDENT_ID
										   AND SC.ACADEMIC_YEAR= ER.ACADEMIC_YEAR
										   AND SC.IS_DELETED!=1
                                           INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID 
                                            AND ES.IS_ACTIVE = 1
                                            LEFT JOIN
                                        EXAM_SEATING_ALLOTEMENT AS ESA ON ESA.STUDENT_ID = ER.STUDENT_ID
                                            AND ESA.COURSE_ID = ER.COURSE_ID AND  ESA.EXAM_TYPE=ES.EXAM_TYPE
                                            LEFT JOIN
                                        EXAM_SEATINGS AS ESS ON ESS.SEATING_ID = ESA.SEATING_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = ER.COURSE_ID
                                            AND CC.SUBJECT_TYPE!=2
                                            AND CC.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CC.SEMESTER_ID
                                            LEFT JOIN
                                        EXAM_TIMETABLE AS ET ON ET.COURSE_ID = CC.COURSE_ROOT_ID
                                            AND ET.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                            AND ET.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            LEFT JOIN
                                        SUP_ROOM AS SR ON SR.ROOM_ID = ESS.ROOM_ID
                                            LEFT JOIN
                                        SUP_COLLEGE_BLOCK AS SCB ON SCB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                            LEFT JOIN
										SUP_SESSION AS SS ON SS.SESSION_ID=ET.EXAM_SESSION_ID
                                    WHERE
                                        SC.CLASS_ID=?CLASS_ID
                                            AND ER.ACADEMIC_YEAR = ?AC_YEAR AND ER.IS_DELETED!=1
                                    ORDER BY DATE_FORMAT(ET.EXAM_DATE, '%Y-%m-%d') ASC;";
                        break;
                    }

                case ExaminationSQLCommands.FetchHallTicketValidation:
                    {
                        query = @"SELECT 
                                        STUDENT_ID, 
                                        REASON
                                    FROM
                                        HALL_TICKET_VALIDATION
                                    WHERE
                                        EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND ACADEMIC_YEAR = ?AC_YEAR
                                            AND IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchSemHallTicketByExamSettingId:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID,
                                        ER.STUDENT_ID,
                                        IF(ER.STATUS!='R',CONCAT('*',CC.COURSE_CODE),CC.COURSE_CODE) AS COURSE_CODE,
                                        CC.COURSE_TITLE,
                                        IF(ET.IS_ADVANCE = '1',
                                            DATE_FORMAT(ET.ADVANCE_DATE, '%d/%m/%Y'),
                                            IF(ET.IS_POSTPONED = '1',
                                                DATE_FORMAT(ET.POSTPONED_DATE, '%d/%m/%Y'),
                                                DATE_FORMAT(ET.EXAM_DATE, '%d/%m/%Y'))) AS EXAM_DATE,
                                        IF(ET.IS_ADVANCE = '1',
                                            ET.ADVANCE_TIME,
                                            IF(ET.IS_POSTPONED = '1',
                                                ET.POSTPONED_TIME,
                                                ET.EXAM_TIME)) AS EXAM_TIME,
                                        ER.COURSE_ID,
                                        STATUS,
                                        ER.ACADEMIC_YEAR,
                                        S.SEMESTER_NAME AS 'SEMESTER_ID',
                                        ES.M_PASS AS 'MONTH_YEAR',
                                        CC.SEMESTER_ID AS 'SEMESTER',
                                        CONCAT(IFNULL(SCB.BLOCK_CODE,''),' : ',IFNULL(SR.ROOM_NO,''),' : ',IFNULL(ESS.SEAT_CODE,'')) AS SEAT_CODE,
                                        SCB.BLOCK_CODE,
                                        SCB.BLOCK_NAME,
										SS.SESSION_NAME
                                    FROM
                                       EXAM_REGISTRATION_?AC_YEAR AS ER
                                           INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID 
                                            AND ES.IS_ACTIVE = 1 
                                            LEFT JOIN
                                        EXAM_SEATING_ALLOTEMENT AS ESA ON ESA.STUDENT_ID = ER.STUDENT_ID
                                            AND ESA.COURSE_ID = ER.COURSE_ID 
                                            LEFT JOIN
                                        EXAM_SEATINGS AS ESS ON ESS.SEATING_ID = ESA.SEATING_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = ER.COURSE_ID
                                            AND CC.SUBJECT_TYPE!=2
                                            AND CC.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CC.SEMESTER_ID
                                            LEFT JOIN
                                        EXAM_TIMETABLE AS ET ON ET.COURSE_ID = CC.COURSE_ROOT_ID
                                            AND ET.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                            LEFT JOIN
                                        SUP_ROOM AS SR ON SR.ROOM_ID = ESS.ROOM_ID
                                            LEFT JOIN
                                        SUP_COLLEGE_BLOCK AS SCB ON SCB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                            LEFT JOIN
										SUP_SESSION AS SS ON SS.SESSION_ID=ET.EXAM_SESSION_ID
                                    WHERE
                                        ER.ACADEMIC_YEAR = ?AC_YEAR 
                                        AND ER.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                        AND ER.IS_DELETED!=1
                                        ORDER BY DATE_FORMAT(ET.EXAM_DATE, '%Y-%m-%d') ASC;";
                        break;
                    }
                #endregion

                #region Display CIA Marks For Student
                case ExaminationSQLCommands.FetchCIAMarksByCourseIdAndStudentId:
                    {
                        query = @"SELECT 
                                        GM.STUDENT_ID,
                                        GM.COURSE_ID,
                                        GM.COURSE_GROUP_ID,
                                        GM.COURSE_GROUP_MARK,
                                        GM.SEMESTER_ID,
                                        CC.COMPONENT_ID,GC.MAX_MARK, 
                                        CONCAT(CC.COMPONENT, ' ( ', GC.MAX_MARK, ' ) ') AS COMPONENT
                                    FROM
                                        CIA_GROUP_MARKS_?AC_YEAR AS GM
                                            INNER JOIN
                                        CIA_GROUP_COMPONENT AS GC ON GC.CIA_GROUP_COMPONENT_ID = GM.COURSE_GROUP_ID
                                            INNER JOIN
                                        CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = GC.CIA_GROUP_ID
                                            INNER JOIN
                                        SUP_CIA_COMPONENTS AS CC ON CC.COMPONENT_ID = GC.SUP_CIA_COMPONENT_ID
                                    WHERE
                                        GM.COURSE_ID = ?COURSE_ID
                                            AND GM.STUDENT_ID = ?STUDENT_ID
                                    ORDER BY GC.ORDER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.GetStudentDetailsByRollNo:
                    {
                        query = @"SELECT STUDENT_ID,ROLL_NO,FIRST_NAME, DATE_FORMAT(DATE_OF_BIRTH,'%d/%m/%Y') AS DATE_OF_BIRTH FROM STU_PERSONAL_INFO WHERE ROLL_NO=?ROLL_NO AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllCourseByClassId:
                    {
                        query = @"SELECT 
                                        C.CLASS_ID, 
                                        CCR.COURSE_ROOT_ID AS COURSE_ID, 
                                        CCR.COURSE_CODE, 
                                        CCR.COURSE_TITLE
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                ACTIVE_YEAR = 1)
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            AND SEM.SEMESTER = CCR.SEMESTER_ID
                                            AND AB.BATCH_ID = SEM.BATCH
                                            AND SEM.IS_DELETED != 1
                                    WHERE
                                        CCP.IS_DELETED != 1
                                            AND SEM.IS_ACTIVE = 1 AND CCP.ACADEMIC_YEAR=?AC_YEAR
                                            AND C.CLASS_ID = ?CLASS_ID ORDER BY CCR.PART;";
                        break;
                    }
                #endregion

                #region Display Exam TimeTable Course Count
                case ExaminationSQLCommands.FetchExamTimeTableCourseCount:
                    {
                        query = @"SELECT 
                                        DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                        TT.EXAM_SESSION_ID,
                                        ER.COURSE_ID,
                                        CCR.COURSE_CODE,
                                        COUNT(ER.STUDENT_ID) AS STUDENT_COUNT,
                                        ER.STATUS
                                    FROM
                                        EXAM_TIMETABLE AS TT
                                            INNER JOIN
                                        EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.COURSE_ID = TT.COURSE_ID
		                                    AND ER.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                            AND ER.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = TT.COURSE_ID
                                    GROUP BY TT.EXAM_DATE , TT.COURSE_ID , TT.EXAM_SESSION_ID , ER.STATUS
                                    ORDER BY TT.EXAM_DATE , TT.EXAM_SESSION_ID, TT.COURSE_CODE, ER.STATUS;";
                        break;
                    }

                #endregion

                case ExaminationSQLCommands.FetchMphillProjectByStudentId:
                    {
                        query = @"SELECT 
                                M.STUDENT_ID,
                                M.COURSE_ID,
                                CR.COURSE_CODE,
                                CONCAT(IF(UGC.UGC_COURSE_TYPE IS NULL,
                                            '',
                                            CONCAT(UGC.UGC_COURSE_TYPE, ': ')),
                                        CR.CONS_COURSE_TITLE,
                                        '<br/>',
                                        M.PROJECT_TITLE) PROJECT_TITLE
                            FROM
                                MPHILL_STUDENT_PROJECT AS M
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = M.COURSE_ID
                                    INNER JOIN
                                CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = M.UGC_COURSE_TYPE
                            WHERE
                                M.STUDENT_ID IN (?STUDENT_ID);";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluatorStaffInfo:
                    {
                        query = @"SELECT 
                                EXAM_EVALUATOR_STAFF_ID,
                                NAME,
                                PHONE,
                                USERNAME,
                                PASSWORD,
                                IF(ROLE = 1, 'EXTERNAL', 'INTERNAL') AS ROLE,
                                IS_ACTIVE
                            FROM
                                EXAM_EVALUATOR_STAFF_INFO
                            WHERE
                                IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluatorStaffinfoById:
                    {
                        query = @"SELECT 
                                    EXAM_EVALUATOR_STAFF_ID,
                                    NAME,
                                    PHONE,
                                    USERNAME,
                                    PASSWORD,
                                    ROLE,IS_ACTIVE
                                FROM
                                    EXAM_EVALUATOR_STAFF_INFO
                                WHERE
                                    EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID
                                        AND IS_DELETED != 1
                                        ;";
                        break;
                    }
                case ExaminationSQLCommands.SaveEvaluatorStaffInfo:
                    {
                        query = @"INSERT INTO EXAM_EVALUATOR_STAFF_INFO(NAME, PHONE, PASSWORD, ROLE) VALUES(?NAME, ?PHONE, ?PHONE, ?ROLE);";
                        break;
                    }
                case ExaminationSQLCommands.SaveUserAccountForEvaluator:
                    {
                        query = @"INSERT INTO USER_ACCOUNT(USERNAME,PASSWORD,ROLE,NAME,MOBILE,USER_ID) VALUES(?USERNAME,SHA2(?PASSWORD,256),?ROLE,?NAME,?MOBILE,?USER_ID);";
                        break;
                    }
                case ExaminationSQLCommands.FetchInternalStaffInfo:
                    {
                        query = @"SELECT 
                                    STAFF_ID,
                                    STAFF_CODE,
                                    CONCAT(IFNULL(FIRST_NAME, IFNULL(LAST_NAME, ''))) AS FIRST_NAME
                                FROM
                                    STF_PERSONAL_INFO
                                WHERE
                                    STAFF_ID IN (?STAFF_ID);";
                        break;
                    }
                case ExaminationSQLCommands.DeleteEvaluatorInfo:
                    {
                        query = @"UPDATE EXAM_EVALUATOR_STAFF_INFO 
                                SET 
                                    IS_DELETED = 1
                                WHERE
                                    EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID;
                                ";
                        break;
                    }
                case ExaminationSQLCommands.UpdateUserAccountForEvaluator:
                    {
                        query = @"UPDATE USER_ACCOUNT SET PASSWORD=SHA2(?PASSWORD,256),NAME=?NAME,MOBILE=?PHONE WHERE USER_ACCOUNT_ID=?USER_ACCOUNT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateEvaluatorStaffInfo:
                    {
                        query = @"UPDATE EXAM_EVALUATOR_STAFF_INFO SET NAME=?NAME,PHONE=?PHONE,PASSWORD=?PASSWORD,ROLE=?ROLE WHERE EXAM_EVALUATOR_STAFF_ID=?EXAM_EVALUATOR_STAFF_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateIsActiveInEvaluatorInfo:
                    {
                        query = @"UPDATE EXAM_EVALUATOR_STAFF_INFO 
                                SET 
                                    IS_ACTIVE = ?IS_ACTIVE
                                WHERE
                                    EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteUserAccountForEvaluator:
                    {
                        query = @"UPDATE USER_ACCOUNT 
                            SET 
                                IS_DELETED = 1
                            WHERE
                                USER_ACCOUNT_ID = ?USER_ACCOUNT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateIsDeletedInUserAccount:
                    {
                        query = @"UPDATE USER_ACCOUNT 
                            SET 
                                IS_DELETED = 0
                            WHERE
                                USER_ACCOUNT_ID = ?USER_ACCOUNT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationCourseSetting:
                    {
                        query = @"SELECT
	                    ECS.EVALUATION_COURSE_SETTING_ID,
                        ECS.EXAM_SETTING_ID,
                        ECS.COURSE_ID,
                        CPR.COURSE_CODE,
                        CPR.COURSE_TITLE,
                        IF(ECS.IS_EXTERNAL_INTERNAL=1,'EXTERNAL','INTERNAL') as IS_EXTERNAL_INTERNAL,
                        ES.EXAM_NAME, DATE_FORMAT(ECS.EVALUATION_DATE,'%d/%m/%Y') as EVALUATION_DATE
                    FROM
                        EXAM_EVALUATION_COURSE_SETTING AS ECS
                            INNER JOIN
                        CP_COURSE_ROOT AS CPR ON ECS.COURSE_ID = CPR.COURSE_ROOT_ID
                            INNER JOIN
                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ECS.EXAM_SETTING_ID
                    WHERE
                        ECS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationCourseSettingById:
                    {
                        query = @"SELECT 
                                ECS.EVALUATION_COURSE_SETTING_ID,
                                ECS.EXAM_SETTING_ID,
                                ECS.COURSE_ID,
                                CPR.COURSE_CODE,
                                CPR.COURSE_TITLE,
                                ECS.IS_EXTERNAL_INTERNAL,
                                ES.EXAM_NAME,DATE_FORMAT(ECS.EVALUATION_DATE,'%d/%m/%Y') as EVALUATION_DATE
                            FROM
                                EXAM_EVALUATION_COURSE_SETTING AS ECS
                                    INNER JOIN
                                CP_COURSE_ROOT AS CPR ON ECS.COURSE_ID = CPR.COURSE_ROOT_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ECS.EXAM_SETTING_ID
                            WHERE
                                ECS.IS_DELETED != 1
                                    AND EVALUATION_COURSE_SETTING_ID = ?EVALUATION_COURSE_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveEvaluationCourseInfo:
                    {
                        query = @"INSERT INTO EXAM_EVALUATION_COURSE_SETTING(EXAM_SETTING_ID, COURSE_ID, EVALUATION_DATE, IS_EXTERNAL_INTERNAL) VALUES(?EXAM_SETTING_ID, ?COURSE_ID, ?EVALUATION_DATE, ?IS_EXTERNAL_INTERNAL);";
                        break;
                    }
                case ExaminationSQLCommands.DeleteEvaluationCourseSetting:
                    {
                        query = @"UPDATE EXAM_EVALUATION_COURSE_SETTING 
                                    SET 
                                        IS_DELETED = 1
                                    WHERE
                                        EVALUATION_COURSE_SETTING_ID = ?EVALUATION_COURSE_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateEvaluationCourseSetting:
                    {
                        query = @"UPDATE EXAM_EVALUATION_COURSE_SETTING 
                        SET 
                            EXAM_SETTING_ID = ?EXAM_SETTING_ID,
                            COURSE_ID =?COURSE_ID,
                            EVALUATION_DATE = ?EVALUATION_DATE,
                            IS_EXTERNAL_INTERNAL = ?IS_EXTERNAL_INTERNAL
                        WHERE
                            EVALUATION_COURSE_SETTING_ID = ?EVALUATION_COURSE_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsCourseExist:
                    {
                        query = @"SELECT 
                                EVALUATION_COURSE_SETTING_ID
                            FROM
                                EXAM_EVALUATION_COURSE_SETTING
                            WHERE
                                EXAM_SETTING_ID =?EXAM_SETTING_ID AND COURSE_ID = ?COURSE_ID
                                    AND EVALUATION_DATE = ?EVALUATION_DATE
                                    AND IS_EXTERNAL_INTERNAL = ?IS_EXTERNAL_INTERNAL AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsEvaluatorExist:
                    {
                        query = @"SELECT 
                            EXAM_EVALUATOR_STAFF_ID
                        FROM
                            EXAM_EVALUATOR_STAFF_INFO
                        WHERE
                            PHONE =?PHONE AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationCourseByEvaluationDate:
                    {
                        query = @"SELECT 
                                    ECS.EVALUATION_COURSE_SETTING_ID,
                                    ECS.COURSE_ID,
                                    CR.COURSE_CODE,
                                    DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE,
                                    COURSE_TITLE,
                                    PROGRAMME_LEVEL_ID
                                FROM
                                    EXAM_EVALUATION_COURSE_SETTING AS ECS
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ECS.COURSE_ID
                                WHERE
                                    ECS.IS_DELETED != 1
                                        AND EVALUATION_DATE = ?EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationCourseByEvaluationDateAndEvaluation:
                    {
                        query = @"SELECT 
                            ECS.EVALUATION_COURSE_SETTING_ID,
                            ECS.COURSE_ID,
                            CR.COURSE_CODE,
                            DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE,
                            COURSE_TITLE,
                            PROGRAMME_LEVEL_ID
                        FROM
                            EXAM_EVALUATION_COURSE_SETTING AS ECS
                                INNER JOIN
                            CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = ECS.COURSE_ID
                        WHERE
                            ECS.IS_DELETED != 1 AND EVALUATION=?EVALUATION
                                AND EVALUATION_DATE = ?EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluatorForddl:
                    {
                        query = @"SELECT 
                                    EXAM_EVALUATOR_STAFF_ID,
                                    CONCAT(IFNULL(NAME, ''),
                                            ' - ',
                                            IFNULL(PHONE, '')) AS PHONE
                                FROM
                                    EXAM_EVALUATOR_STAFF_INFO
                                WHERE
                                    IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupEvaluationDateForddl:
                    {
                        query = @"SELECT 
                                        EVALUATION_COURSE_SETTING_ID, DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE
                                    FROM
                                        EXAM_EVALUATION_COURSE_SETTING
                                    GROUP BY EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupEvaluationDateByEvaluationAndExamSettingId:
                    {
                        query = @"SELECT 
                                EVALUATION_COURSE_SETTING_ID,
                                DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE
                            FROM
                                EXAM_EVALUATION_COURSE_SETTING
                            WHERE
                                EVALUATION = ?EVALUATION AND EXAM_SETTING_ID = ?EXAM_SETTING_ID
                            GROUP BY EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationStudentBetweenRegisterNo:
                    {
                        query = @"SELECT 
                                SP.STUDENT_ID,
                                R.EXAM_SETTING_ID,
                                SP.REGISTER_NO,
                                R.COURSE_ID
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR AS R
                                    INNER JOIN
                                EXAM_SETTING AS ST ON ST.EXAM_SETTING_ID = R.EXAM_SETTING_ID
                                    AND R.ACADEMIC_YEAR = ST.ACADEMIC_YEAR
                                    AND ST.IS_ACTIVE = 1
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = R.STUDENT_ID
                            WHERE
                                R.COURSE_ID = ?COURSE_ID
                                    AND SP.STUDENT_ID NOT IN (SELECT 
                                        STUDENT_ID
                                    FROM
                                        EXAM_EVALUATION_STUDENT_MARK AS EM
                                            INNER JOIN
                                        EXAM_EVALUATION_COURSE_SETTING AS ECT ON ECT.EVALUATION_COURSE_SETTING_ID = EM.EVALUATION_COURSE_SETTING_ID
                                    WHERE
                                        EM.COURSE_ID = ?COURSE_ID AND EM.IS_DELETED!=1)
                                    AND SP.REGISTER_NO BETWEEN ?FROM_REGISTER_NO AND ?TO_REGISTER_NO
                            ORDER BY SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupEvaluationDateByEvalautorForddl:
                    {
                        query = @"SELECT 
                                ECS.EVALUATION_COURSE_SETTING_ID, date_format(ECS.EVALUATION_DATE,'%d/%m/%Y') EVALUATION_DATE
                            FROM
                                EXAM_EVALUATION_STUDENT_MARK AS EM
                                    INNER JOIN
                                EXAM_EVALUATION_COURSE_SETTING AS ECS ON ECS.EVALUATION_COURSE_SETTING_ID = EM.EVALUATION_COURSE_SETTING_ID
                            WHERE
                                EM.EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID
                            GROUP BY ECS.EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationCourseByEvaluationDateEvaluatorForddl:
                    {
                        query = @"SELECT 
                                        EM.COURSE_ID, CR.COURSE_CODE,ECS.IS_DATE_VALIDATION,ECS.EVALUATION
                                    FROM
                                        EXAM_EVALUATION_STUDENT_MARK AS EM
                                            INNER JOIN
                                        EXAM_EVALUATION_COURSE_SETTING AS ECS ON ECS.EVALUATION_COURSE_SETTING_ID = EM.EVALUATION_COURSE_SETTING_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EM.COURSE_ID
                                    WHERE
                                        EM.EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID
                                            AND ECS.EVALUATION_DATE = ?EVALUATION_DATE
                                    GROUP BY EM.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationStudenByEvaluatorAndCourseAndDate:
                    {
                        query = @"SELECT 
                                SM.EXAM_EV_STU_MARK_ID,
                                SM.EVALUATION_COURSE_SETTING_ID,
                                SM.STUDENT_ID,
                                SM.EXAM_EVALUATOR_STAFF_ID,
                                SM.COURSE_ID,
                                SM.EVALUATION_1,
                                SM.EVALUATION_2,
                                SM.EVALUATION_3,
                                SM.TOTAL,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                CR.INTERNAL,
                                CR.EXTERNAL,
                                CR.TOTAL AS MAX_MARK,
                                CR.PROGRAMME_LEVEL_ID,
                                CR.EXAM_MARK,
                                CS.IS_EXTERNAL_INTERNAL,
                                CS.EVALUATION_DATE,
                                ST.`NAME`,
                                ST.PHONE,
                                S.M_EXAM,
                                SP.REGISTER_NO,
                                ST.ROLE
                            FROM
                                EXAM_EVALUATION_STUDENT_MARK AS SM
                                    INNER JOIN
                                EXAM_EVALUATION_COURSE_SETTING AS CS ON CS.EVALUATION_COURSE_SETTING_ID = SM.EVALUATION_COURSE_SETTING_ID
                                    INNER JOIN
                                EXAM_EVALUATOR_STAFF_INFO AS ST ON ST.EXAM_EVALUATOR_STAFF_ID = SM.EXAM_EVALUATOR_STAFF_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SM.STUDENT_ID
                                    INNER JOIN
                                EXAM_SETTING AS S ON S.EXAM_SETTING_ID = CS.EXAM_SETTING_ID
                            WHERE
                                SM.EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID
                                    AND CS.EVALUATION_DATE = ?EVALUATION_DATE
                                    AND SM.COURSE_ID = ?COURSE_ID AND SM.IS_DELETED!=1 ORDER BY SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationStudenByEvaluatorAndCourseAndByCurrentDate:
                    {
                        query = @"SELECT 
                                SM.EXAM_EV_STU_MARK_ID,
                                SM.EVALUATION_COURSE_SETTING_ID,
                                SM.STUDENT_ID,
                                SM.EXAM_EVALUATOR_STAFF_ID,
                                SM.COURSE_ID,
                                SM.EVALUATION_1,
                                SM.EVALUATION_2,
                                SM.EVALUATION_3,
                                SM.TOTAL,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                CR.INTERNAL,
                                CR.EXTERNAL,
                                CR.TOTAL AS MAX_MARK,
                                CR.PROGRAMME_LEVEL_ID,
                                CR.EXAM_MARK,
                                CS.IS_EXTERNAL_INTERNAL,
                                CS.EVALUATION_DATE,
                                ST.`NAME`,
                                ST.PHONE,
                                S.M_EXAM,
                                SP.REGISTER_NO,
                                ST.ROLE
                            FROM
                                EXAM_EVALUATION_STUDENT_MARK AS SM
                                    INNER JOIN
                                EXAM_EVALUATION_COURSE_SETTING AS CS ON CS.EVALUATION_COURSE_SETTING_ID = SM.EVALUATION_COURSE_SETTING_ID
                                    INNER JOIN
                                EXAM_EVALUATOR_STAFF_INFO AS ST ON ST.EXAM_EVALUATOR_STAFF_ID = SM.EXAM_EVALUATOR_STAFF_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SM.STUDENT_ID
                                    INNER JOIN
                                EXAM_SETTING AS S ON S.EXAM_SETTING_ID = CS.EXAM_SETTING_ID
                            WHERE
                                SM.EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID
                                    AND CS.EVALUATION_DATE = CURDATE()
                                    AND SM.COURSE_ID = ?COURSE_ID AND SM.IS_DELETED!=1 ORDER BY SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.SaveEvaluationMarkByEvStuMarkId:
                    {
                        query = @"UPDATE EXAM_EVALUATION_STUDENT_MARK SET EVALUATION_MARK=?EVALUATION_MARK WHERE EXAM_EV_STU_MARK_ID=?EXAM_EV_STU_MARK_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveEvaluation2ByEvStuMarkId:
                    {
                        query = @"UPDATE EXAM_EVALUATION_STUDENT_MARK SET EVALUATION_2=?EVALUATION_2 WHERE EXAM_EV_STU_MARK_ID=?EXAM_EV_STU_MARK_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteEvaluationMarkEntry:
                    {
                        query = @"UPDATE EXAM_EVALUATION_STUDENT_MARK SET IS_DELETED=1 WHERE EXAM_EV_STU_MARK_ID=?EXAM_EV_STU_MARK_ID;";
                        break;
                    }

                case ExaminationSQLCommands.SaveEvaluationMarkCOEByStuMarkId:
                    {
                        query = @"UPDATE EXAM_EVALUATION_STUDENT_MARK SET EVALUATION_1=?EVALUATION_1,EVALUATION_2=?EVALUATION_2,TOTAL=?TOTAL WHERE EXAM_EV_STU_MARK_ID=?EXAM_EV_STU_MARK_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAMarkNotSubmissionList:
                    {
                        query = @"SELECT 
                                    CC.CLSCRSSTF_ID,
                                    CC.CLASS_ID,
                                    CC.COURSE_ID,
                                    SP.FIRST_NAME,
                                    SP.STAFF_CODE,
                                    DEP.DEPARTMENT,
                                    CCR.COURSE_TITLE,
                                    CCR.COURSE_CODE,
                                    CIA_GROUP_MARK_ID,
                                    CC.STAFF_ID,                                 
                                    SCC.COMPONENT,
                                    CPC.CLASS_NAME
                                FROM
                                    CP_CLASS_COURSE_STAFF AS CC
                                     INNER JOIN
                                    CP_CLASSES AS CPC ON CPC.CLASS_ID = CC.CLASS_ID
                                        INNER JOIN
                                    STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CC.STAFF_ID
                                        LEFT JOIN
                                    CP_DEPARTMENT AS DEP ON DEP.DEPARTMENT_ID = SP.DEPARTMENT
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CC.COURSE_ID
                                        AND CCR.IS_COMPULSORY = 1
                                        INNER JOIN
                                    CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                        INNER JOIN
                                    CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CT.COURSE_TYPE_ID
                                        INNER JOIN
                                    CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
                                        INNER JOIN
                                    SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        LEFT JOIN
                                    (SELECT 
                                        COURSE_ID,
                                            SEMESTER_ID,
                                            CLASS_ID,
                                            COURSE_GROUP_ID,
                                            CIA_GROUP_MARK_ID
                                    FROM
                                        CIA_GROUP_MARKS_?AC_YEAR AS CM
                                    INNER JOIN STU_CLASS AS SC ON SC.STUDENT_ID = CM.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    WHERE
                                        SEMESTER_ID IN (?SEMESTER_NAME)
                                    GROUP BY COURSE_ID , COURSE_GROUP_ID , SEMESTER_ID) AS T ON CC.COURSE_ID = T.COURSE_ID
                                        AND CC.CLASS_ID = T.CLASS_ID
                                        AND T.COURSE_GROUP_ID = CGC.CIA_GROUP_COMPONENT_ID
                                WHERE
                                    CC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CC.SEMESTER_TYPE_ID = (SELECT 
                                            SEMESTER_TYPE_ID
                                        FROM
                                            SUP_SEMESTER_TYPE
                                        WHERE
                                            IS_ACTIVE = 1)
                                        AND CC.IS_DELETED != 1
                                      
                                ORDER BY CC.STAFF_ID , CC.COURSE_ID , CGC.SUP_CIA_COMPONENT_ID;";
                        break;
                    }
                #region OBE
                case ExaminationSQLCommands.FetchOBEQuestionStructures:
                    {
                        query = @"SELECT 
                                QS.QUESTION_STRUCTURE_ID,
                                QS.SECTION,
                                QS.QUESTION_NO,
                                QS.MARK_PER_QUESTION,
                                QS.APPLICATION_TYPE_ID,
                                SAT.APPLICATION_TYPE
                            FROM
                                OBE_QUESTION_STRUCTURE AS QS
                                    INNER JOIN
                                SUP_APPLICATION_TYPE AS SAT ON SAT.APPLICATION_TYPE_ID = QS.APPLICATION_TYPE_ID
                            WHERE
                                QS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOBEQuestionStructuresById:
                    {
                        query = @"SELECT 
                                QS.QUESTION_STRUCTURE_ID,
                                QS.SECTION,
                                QS.QUESTION_NO,
                                QS.MARK_PER_QUESTION,
                                QS.APPLICATION_TYPE_ID,
                                SAT.APPLICATION_TYPE
                            FROM
                                OBE_QUESTION_STRUCTURE AS QS
                                    INNER JOIN
                                SUP_APPLICATION_TYPE AS SAT ON SAT.APPLICATION_TYPE_ID = QS.APPLICATION_TYPE_ID
                            WHERE
	                            QS.QUESTION_STRUCTURE_ID=?QUESTION_STRUCTURE_ID AND
                                QS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateOBEQuestionStructure:
                    {
                        query = @"UPDATE OBE_QUESTION_STRUCTURE
                                 SET SECTION=?SECTION, 
                                 QUESTION_NO=?QUESTION_NO, 
                                 APPLICATION_TYPE_ID=?APPLICATION_TYPE_ID,
                                 MARK_PER_QUESTION=?MARK_PER_QUESTION 
                                 WHERE QUESTION_STRUCTURE_ID=?QUESTION_STRUCTURE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOBEQuestionStructure:
                    {
                        query = @"INSERT INTO OBE_QUESTION_STRUCTURE(SECTION,QUESTION_NO,
                                    APPLICATION_TYPE_ID,MARK_PER_QUESTION) 
                                    VALUES(?SECTION,?QUESTION_NO,?APPLICATION_TYPE_ID,
                                    ?MARK_PER_QUESTION);";
                        break;
                    }
                case ExaminationSQLCommands.DeleteOBEQuestionStructure:
                    {
                        query = @"UPDATE OBE_QUESTION_STRUCTURE 
                                    SET 
                                        IS_DELETED = 1
                                    WHERE
                                        QUESTION_STRUCTURE_ID =?QUESTION_STRUCTURE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuestionStructureByAppId:
                    {
                        query = @"SELECT 
                                    QUESTION_STRUCTURE_ID,
                                    SECTION,
                                    QUESTION_NO,
                                    APPLICATION_TYPE_ID,
                                    MARK_PER_QUESTION
                                FROM
                                    OBE_QUESTION_STRUCTURE
                                WHERE
                                    APPLICATION_TYPE_ID = ?APPLICATION_TYPE_ID AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuestionsByExamIdandCourseId:
                    {
                        query = @"SELECT 
                                QUESTION_ID,
                                QUESTION_STRUCTURE_ID,
                                QUESTION_LEVEL_ID,
                                COURSE_ID,
                                EXAM_ID,
                                IS_DELETED,
                                IS_ACTIVE,
                                QUESTION
                            FROM
                                OBE_QUESTIONS
                            WHERE
                                EXAM_ID =?EXAM_ID AND COURSE_ID =?COURSE_ID
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOBEQuestions:
                    {
                        query = @"INSERT INTO OBE_QUESTIONS
                                (QUESTION_STRUCTURE_ID, QUESTION_LEVEL_ID,
                                 COURSE_ID, EXAM_ID, QUESTION)
                                 VALUES(?QUESTION_STRUCTURE_ID,
                                 ?QUESTION_LEVEL_ID, ?COURSE_ID, 
                                 ?EXAM_ID, ?QUESTION);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateOBEQuestions:
                    {
                        query = @"UPDATE OBE_QUESTIONS 
                                SET 
                                    QUESTION_LEVEL_ID =?QUESTION_LEVEL_ID,
                                    QUESTION =?QUESTION
                                WHERE
                                    QUESTION_ID =?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemsterMarksByExamIdandCourseId:
                    {
                        query = @"SELECT 
                            SM.SEMESTER_MARK_ID,
                            SM.STUDENT_ID,
                            SM.COURSE_ID,
                            SM.EXTERNAL_MARK,
                            SM.ACADEMIC_YEAR,
                            SM.EXAM_SETTING_ID,
                            SM.RESULT,
                            CR.EXTERNAL,
                            CR.PROGRAMME_LEVEL_ID
                        FROM
                            SEMESTER_MARKS_2019 AS SM
                                INNER JOIN
                            CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                        WHERE
                            SM.EXAM_SETTING_ID =?EXAM_SETTING_ID
                                AND SM.COURSE_ID IN (?COURSE_ID);";
                        break;
                    }
                case ExaminationSQLCommands.SaveOBEScoreSheet:
                    {
                        query = @"INSERT INTO OBE_SCORESHEET(QUESTION_STRUCTRE_ID, QUESTION_ID, 
                                COURSE_ID, STUDENT_ID, MARK, ACTUAL_MARK, 
                                EXAM_SETTING_ID, ACADEMIC_YEAR) 
                                VALUES(?QUESTION_STRUCTRE_ID, ?QUESTION_ID, ?COURSE_ID, ?STUDENT_ID,
                                 ?MARK, ?ACTUAL_MARK, ?EXAM_SETTING_ID,
                                 ?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentScoreSheets:
                    {
                        query = @"SELECT 
                                OS.SCORE_SHEET_ID,
                                OS.QUESTION_STRUCTRE_ID,
                                OS.QUESTION_ID,
                                OS.COURSE_ID,
                                OS.STUDENT_ID,
                                ROUND(SUM(OS.MARK)) AS MARK,
                                OQ.QUESTION_LEVEL_ID,
                                QL.QUESTION_LEVEL,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                SP.FIRST_NAME,
                                SP.ROLL_NO,
                                SP.REGISTER_NO
                            FROM
                                OBE_SCORESHEET AS OS
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = OS.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = OS.COURSE_ID
                                    INNER JOIN
                                OBE_QUESTION_STRUCTURE AS OQS ON OQS.QUESTION_STRUCTURE_ID = OS.QUESTION_STRUCTRE_ID
                                    INNER JOIN
                                OBE_QUESTIONS AS OQ ON OQ.QUESTION_ID = OS.QUESTION_ID
                                    INNER JOIN
                                OBE_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID = OQ.QUESTION_LEVEL_ID
                            WHERE
                                OS.IS_DELETED != 1
                                    AND OS.EXAM_SETTING_ID =?EXAM_SETTING_ID
                                    AND OS.STUDENT_ID =?STUDENT_ID
                            GROUP BY OS.COURSE_ID , OQ.QUESTION_LEVEL_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClasswiseScoreSheets:
                    {
                        query = @"SELECT 
                                OS.SCORE_SHEET_ID,
                                OS.QUESTION_STRUCTRE_ID,
                                OS.QUESTION_ID,
                                OS.COURSE_ID,
                                OS.STUDENT_ID,
                                ROUND(SUM(OS.MARK)) AS MARK,
                                OQ.QUESTION_LEVEL_ID,
                                QL.QUESTION_LEVEL,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                CC.CLASS_NAME
                            FROM
                                OBE_SCORESHEET AS OS
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = OS.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR =?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                cp_course_pattern AS CP ON CP.PROGRAMME_GROUP_ID = CC.PROGRAMME_GROUP_ID
                                    INNER JOIN
                                cp_course_structure AS CS ON CS.COURSE_STRUCTURE_ID = CP.COURSE_STRUCTURE_ID
                                    AND CC.CLASS_YEAR = CS.PROGRAMME_YEAR
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = OS.COURSE_ID
                                    AND CP.COURSE_ID = CR.COURSE_ROOT_ID
                                    INNER JOIN
                                OBE_QUESTION_STRUCTURE AS OQS ON OQS.QUESTION_STRUCTURE_ID = OS.QUESTION_STRUCTRE_ID
                                    INNER JOIN
                                OBE_QUESTIONS AS OQ ON OQ.QUESTION_ID = OS.QUESTION_ID
                                    INNER JOIN
                                OBE_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID = OQ.QUESTION_LEVEL_ID
                            WHERE
                                OS.IS_DELETED != 1 AND SC.CLASS_ID =?CLASS_ID
                                    AND OS.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                            GROUP BY SC.CLASS_ID , OS.COURSE_ID , OQ.QUESTION_LEVEL_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchDepartmentwiseScoreSheets:
                    {
                        query = @"SELECT 
                                OS.SCORE_SHEET_ID,
                                OS.QUESTION_STRUCTRE_ID,
                                OS.QUESTION_ID,
                                OS.COURSE_ID,
                                OS.STUDENT_ID,
                                ROUND(SUM(OS.MARK)) AS MARK,
                                OQ.QUESTION_LEVEL_ID,
                                QL.QUESTION_LEVEL,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                DEP.DEPARTMENT_ID,
                                DEP.DEPARTMENT
                            FROM
                                OBE_SCORESHEET AS OS
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = OS.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR =?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                    AND CC.IS_DELETED != 1
                                    INNER JOIN
                                cp_department AS DEP ON DEP.DEPARTMENT_ID = CC.DEPARTMENT
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = OS.COURSE_ID
                                    INNER JOIN
                                OBE_QUESTION_STRUCTURE AS OQS ON OQS.QUESTION_STRUCTURE_ID = OS.QUESTION_STRUCTRE_ID
                                    INNER JOIN
                                OBE_QUESTIONS AS OQ ON OQ.QUESTION_ID = OS.QUESTION_ID
                                    INNER JOIN
                                OBE_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID = OQ.QUESTION_LEVEL_ID
                            WHERE
                                OS.IS_DELETED != 1
                                    AND CC.DEPARTMENT =?DEPARTMENT
                                    AND OS.EXAM_SETTING_ID =?EXAM_SETTING_ID
                            GROUP BY OQ.QUESTION_LEVEL_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentsMarks:
                    {
                        query = @"SELECT 
                                CR.PART,
                                P.PART AS PART_NAME,
                                CR.COURSE_CODE,
                                CONCAT(UGC.UGC_COURSE_TYPE,
                                        ': ',
                                        CR.COURSE_TITLE) COURSE_TITLE,
                                UGC.COURSE_ORDER,
                                SEM.SEMESTER,
                                SS.SEMESTER_NAME,
                                SEM.INTERNAL_MARK,
                                SEM.EXTERNAL_MARK,
                                SEM.COURSE_ID,
                                SEM.TOTAL,
                                IFNULL(CR.TOTAL, 100) AS MAXIMUM,
                                CR.CREDITS AS CREDIT,
                                SEM.GRADE_POINT,
                                SEM.M_PASS,
                                SEM.RESULT,
                                ES.M_EXAM,
                                DATE_FORMAT(ES.START_DATE, '%d/%m/%Y') AS START_DATE,
                                CR.UGC_COURSE_TYPE,
                                SEM.EXAM_SETTING_ID,
                                SEM.STUDENT_ID
                            FROM
                                SEMESTER_MARKS_?AC_YEAR AS SEM
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SEM.COURSE_ID
                                    LEFT JOIN
                                CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    LEFT JOIN
                                CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                    LEFT JOIN
                                SUP_PART AS P ON P.PART_ID = CR.PART
                                    LEFT JOIN
                                SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CR.SEMESTER_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = SEM.EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassWiseStudentsMarks:
                    {
                        query = @"SELECT 
                                CR.PART,
                                P.PART AS PART_NAME,
                                CR.COURSE_CODE,
                                CONCAT(UGC.UGC_COURSE_TYPE,
                                        ': ',
                                        CR.COURSE_TITLE) COURSE_TITLE,
                                UGC.COURSE_ORDER,
                                SEM.SEMESTER,
                                SS.SEMESTER_NAME,
                                SEM.INTERNAL_MARK,
                                SEM.EXTERNAL_MARK,
                                SEM.COURSE_ID,
                                SEM.TOTAL,
                                IFNULL(CR.TOTAL, 100) AS MAXIMUM,
                                CR.CREDITS AS CREDIT,
                                SEM.GRADE_POINT,
                                SEM.M_PASS,
                                SEM.RESULT,
                                ES.M_EXAM,
                                DATE_FORMAT(ES.START_DATE, '%d/%m/%Y') AS START_DATE,
                                CR.UGC_COURSE_TYPE,
                                SEM.EXAM_SETTING_ID,
                                SEM.STUDENT_ID,
                                CPC.CLASS_NAME
                            FROM
                                SEMESTER_MARKS_?AC_YEAR AS SEM
                                    INNER JOIN
                                stu_class AS SC ON SC.STUDENT_ID = SEM.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR =?AC_YEAR
                                    INNER JOIN
                                cp_classes AS CPC ON CPC.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SEM.COURSE_ID
                                    LEFT JOIN
                                CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                    LEFT JOIN
                                CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                                    LEFT JOIN
                                SUP_PART AS P ON P.PART_ID = CR.PART
                                    LEFT JOIN
                                SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CR.SEMESTER_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = SEM.EXAM_SETTING_ID
                            WHERE
                                SC.CLASS_ID =?CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchDepartWiseStudentsMarks:
                    {
                        query = @"SELECT 
                        CR.PART,
                        P.PART AS PART_NAME,
                        CR.COURSE_CODE,
                        CONCAT(UGC.UGC_COURSE_TYPE,
                                ': ',
                                CR.COURSE_TITLE) COURSE_TITLE,
                        UGC.COURSE_ORDER,
                        SEM.SEMESTER,
                        SS.SEMESTER_NAME,
                        SEM.INTERNAL_MARK,
                        SEM.EXTERNAL_MARK,
                        SEM.COURSE_ID,
                        SEM.TOTAL,
                        IFNULL(CR.TOTAL, 100) AS MAXIMUM,
                        CR.CREDITS AS CREDIT,
                        SEM.GRADE_POINT,
                        SEM.M_PASS,
                        SEM.RESULT,
                        ES.M_EXAM,
                        DATE_FORMAT(ES.START_DATE, '%d/%m/%Y') AS START_DATE,
                        CR.UGC_COURSE_TYPE,
                        SEM.EXAM_SETTING_ID,
                        SEM.STUDENT_ID,
                        CPC.CLASS_NAME,
                        DEP.DEPARTMENT
                    FROM
                        SEMESTER_MARKS_?AC_YEAR AS SEM
                            INNER JOIN
                        stu_class AS SC ON SC.STUDENT_ID = SEM.STUDENT_ID
                            AND SC.ACADEMIC_YEAR =?AC_YEAR
                            INNER JOIN
                        cp_classes AS CPC ON CPC.CLASS_ID = SC.CLASS_ID
                            INNER JOIN
                        CP_DEPARTMENT AS DEP ON DEP.DEPARTMENT_ID = CPC.DEPARTMENT
                            INNER JOIN
                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SEM.COURSE_ID
                            LEFT JOIN
                        CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                            LEFT JOIN
                        CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID = CR.COURSE_TYPE
                            LEFT JOIN
                        SUP_PART AS P ON P.PART_ID = CR.PART
                            LEFT JOIN
                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CR.SEMESTER_ID
                            INNER JOIN
                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = SEM.EXAM_SETTING_ID
                    WHERE
                        CPC.DEPARTMENT =?DEPARTMENT;";
                        break;
                    }
                #endregion
                #region CIA Cumulative For SJC
                case ExaminationSQLCommands.BindCIAMarksForCOESJC:
                    {

                        query = @"SELECT 
                                    IF(SUM(IFNULL(INSTANT, 0)) != 0,
                                        SUM(IFNULL(INSTANT, 0)),
                                        SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
                                    PROGRAMME_GROUP_ID,
                                    UPPER(NAME) AS 'NAME',
                                    COURSE_ID,
                                    CLASS_ID
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN CIA.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN CIA.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            IF(CIA.COMPONENT = 'INSTANT', COURSE_GROUP_MARK, 0) AS INSTANT,
                                            C.CLASS_ID,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO,
                                            SP.REGISTER_NO,
                                            CCP.PROGRAMME_GROUP_ID,
                                            CCP.COURSE_ID,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                    INNER JOIN CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                    INNER JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                    INNER JOIN CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                    INNER JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
                                    INNER JOIN SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED != 1
                                    INNER JOIN STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                        AND SC.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    INNER JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = CCP.COURSE_ID
                                        AND CGM.COURSE_GROUP_ID = CGC.CIA_GROUP_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    WHERE
                                        C.CLASS_ID = ?CLASS_ID AND CCP.COURSE_ID = ?COURSE_ID
                                            AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            AND SP.IS_DELETED != 1
                                    GROUP BY SP.STUDENT_ID , CCP.COURSE_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID , COURSE_ID;";
