                case ExaminationSQLCommands.BindYearWishOptionalCourseCIAFailMarksForCOESJC:
                    {
                        query = @"SELECT
                                    IF(SUM(IFNULL(INSTANT,0))!=0,SUM(IFNULL(INSTANT,0)),SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    CLASS_ID,
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
									CLASS_NAME,
                                    UPPER(NAME) AS 'NAME',
                                    COURSE_ID,
                                    COURSE_CODE
                                FROM
                                    (SELECT
                                        ((SUM(IF(COURSE_GROUP_MARK = -1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
											IF(CIA.COMPONENT='INSTANT',COURSE_GROUP_MARK,0) AS INSTANT,
                                            CC.CLASS_ID,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO,
                                            SP.REGISTER_NO,
                                            CC.CLASS_NAME,
                                            SC.COURSE_ID,
                                            CCR.COURSE_CODE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                     STU_COURSE_INFO AS SC
										INNER JOIN
									CP_CLASSES AS CC ON CC.CLASS_ID=SC.CLASS_ID
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
										INNER JOIN
									CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
										INNER JOIN
									CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
										INNER JOIN
									CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
										INNER JOIN 
                                     SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID=CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED!=1
										INNER JOIN 
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID 
										INNER JOIN 
                                    CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = SC.COURSE_ID
										AND CGM.COURSE_GROUP_ID=CGC.CIA_GROUP_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    WHERE
                                       SC.S_CLASS_ID=?CLASS_ID
										AND SC.COURSE_ID=C.COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            AND SP.IS_DELETED != 1
                                    GROUP BY SP.STUDENT_ID ,SC.COURSE_ID, CGC.CIA_GROUP_ID) AS T
                                GROUP BY ROLL_NO ,COURSE_ID;";
                        break;
                    }
                #endregion

                #region  Year Wish CIA Cumulative For SJC

                /// <summary>
                /// Author : yesudass
                /// Date: 2025-04-15 
                /// Title: CIA calculation: If CIA and CIA Instant both have marks, the higher mark will be considered.
                /// </summary>
                /// <returns></returns>

                case ExaminationSQLCommands.BindYearCIAMarksForCOESJC:
                    {
                        query = @"SELECT
                                    IF(SUM(IFNULL(INSTANT,0))!=0,SUM(IFNULL(INSTANT,0)),SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
                                    PROGRAMME_GROUP_ID,
                                    UPPER(NAME) AS 'NAME',
                                    COURSE_ID,
                                    CLASS_ID,
                                    COURSE_CODE
                                FROM
                                    (SELECT
                                        (SUM(
                                        CASE
                                            WHEN CIA.COMPONENT_ID = 1 THEN
                                                -- For component 1, check if component 63 exists
                                                CASE
                                                    WHEN EXISTS (
                                                        SELECT 1 
                                                        FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                        JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                            AND cgc63.IS_DELETED != 1
                                                        JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                            AND scom63.COMPONENT_ID = 63
                                                        WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                            AND cm.COURSE_ID = CGM.COURSE_ID
                                                            AND cm.COURSE_GROUP_MARK != '-1'
                                                            AND cm.COURSE_GROUP_MARK != 0
                                                    ) THEN
                                                        -- Both components exist, take the max mark
                                                        GREATEST(
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                            COALESCE((
                                                                SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                    AND cgc63.IS_DELETED != 1
                                                                JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                    AND scom63.COMPONENT_ID = 63
                                                                WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                    AND cm.COURSE_ID = CGM.COURSE_ID
                                                                    AND cm.COURSE_GROUP_MARK != '-1'
                                                                    AND cm.COURSE_GROUP_MARK != 0
                                                                LIMIT 1
                                                            ), 0)
                                                        )
                                                    ELSE
                                                        -- Only component 1 exists, take its mark
                                                        IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                END
                                            WHEN CIA.COMPONENT_ID = 63 THEN
                                                -- For component 63, we've already handled it with component 1, so skip
                                                0
                                            ELSE
                                                -- For all other components, take the mark normally
                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                        END
                                    ) / SUM(MAX_MARK)) * (
                                        SELECT GROUP_MARK
                                        FROM CP_COURSE_TYPE_GROUP AS CTG
                                        WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                        LIMIT 1
                                    ) AS CUMULATIVE,
											IF(CIA.COMPONENT='INSTANT',COURSE_GROUP_MARK,0) AS INSTANT,
                                            C.CLASS_ID,
                                            SP.STUDENT_ID,
                                            CCR.COURSE_CODE,
                                            SP.ROLL_NO,
                                            SP.REGISTER_NO,
                                            CCP.PROGRAMME_GROUP_ID,
                                            CCP.COURSE_ID,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                     CP_COURSE_PATTERN AS CCP
										INNER JOIN
									CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
										INNER JOIN
									CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
										INNER JOIN
									CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
										INNER JOIN
									CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
										INNER JOIN 
                                     SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID=CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED!=1
										INNER JOIN
									STU_CLASS AS SC ON SC.CLASS_ID=C.CLASS_ID
										AND SC.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
										INNER JOIN 
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
										INNER JOIN 
                                    CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.SEMESTER_ID IN (?SEMESTER_ID) 
                                        AND CGM.COURSE_ID = CCP.COURSE_ID
										AND CGM.COURSE_GROUP_ID=CGC.CIA_GROUP_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    WHERE
                                      C.CLASS_LEVEL=?APPLICATION_TYPE_ID
										    AND C.CLASS_YEAR=?CLASS_YEAR
                                            AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCP.IS_DELETED!=1
                                            AND SP.IS_LEFT != 1
                                            AND SP.IS_DELETED != 1
                                    GROUP BY SP.STUDENT_ID ,CCP.COURSE_ID, CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID ,COURSE_ID;";
                        break;
                    }

                case ExaminationSQLCommands.BindYearWishOptionalCourseCIAMarksForCOESJC:
                    {

                        query = @"SELECT
