                        //                               AND CGC.IS_DELETED != 1
                        //                           WHERE
                        //                              -- SC.S_CLASS_ID=?CLASS_ID
                        //                                   CC.CLASS_LEVEL= ?APPLICATION_TYPE_ID
                        //     	AND CC.CLASS_YEAR= ?CLASS_YEAR
                        //	 --   AND SC.COURSE_ID=C.COURSE_ID
                        //                                   AND SC.ACADEMIC_YEAR = ?AC_YEAR
                        //                                   AND SC.IS_DELETED != 1
                        //                                   AND SP.IS_LEFT != 1
                        //                                   AND SP.IS_DELETED != 1
                        //                           GROUP BY SP.STUDENT_ID ,SC.COURSE_ID, CGC.CIA_GROUP_ID) AS T
                        //                       GROUP BY ROLL_NO ,COURSE_ID;";
                        //               break;
                    }

                #endregion

                #region Semester Result
                case ExaminationSQLCommands.FetchSemesterResultbyStudentId:
                    {
                        query = @"SELECT
                                        CCR.SEMESTER_ID, 
                                        SEM.STUDENT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SEM.INTERNAL_MARK,
                                        SEM.EXTERNAL_MARK,
                                        SEM.TOTAL,
                                        SEM.RESULT,
                                        SEM.M_PASS
                                    FROM
                                        SEMESTER_MARKS_?AC_YEAR AS SEM
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SEM.COURSE_ID
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = SEM.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE = 1
                                            AND ES.IS_DELETED != 1
                                    WHERE
                                        SEM.STUDENT_ID IN (?STUDENT_ID) -- AND SEM.RESULT!='W'
                                    ORDER BY CCR.SEMESTER_ID , CCR.PART;";
                        break;
                    }
                #endregion

                #region Fetch Odd And Even Sem Course By Student
                case ExaminationSQLCommands.FetchOddAndEvenSemCourseByStudent:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CS.COURSE_STRUCTURE_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                        CCR.IS_COMPULSORY,
                                        SC.CLASS_ID,
                                        CCR.SEMESTER_ID,
                                        IFNULL(CPT.IS_STUDENT_VIEW_CIA_MARK, 1) AS IS_STUDENT_VIEW_CIA_MARK
                                    FROM
                                        CP_COURSE_STRUCTURE AS CS
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                            AND CP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                            AND CCR.IS_DELETED != 1
                                            LEFT JOIN
                                        CP_COURSE_TYPE AS CPT ON CPT.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                            AND CPT.IS_DELETED != 1
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                            AND PG.IS_DELETED != 1
                                            INNER JOIN
                                        CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                            AND P.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                            AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                            AND SC.IS_DELETED != 1
                                    WHERE
                                        CP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FIND_IN_SET(CCR.SEMESTER_ID,
                                                IF(C.CLASS_YEAR = '1',
                                                    '1,2',
                                                    IF(C.CLASS_YEAR = '2',
                                                        '3,4',
                                                        IF(C.CLASS_YEAR = '3', '5,6', ''))))
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY CCR.SEMESTER_ID,CCR.PART,CCR.COURSE_CODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOddAndEvenSemOptionalCourseByStudent:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                        CCR.IS_COMPULSORY,
                                        SC.S_CLASS_ID,
                                        S.CLASS_ID,
                                        CCR.SEMESTER_ID,
                                        IFNULL(CPT.IS_STUDENT_VIEW_CIA_MARK, 1) AS IS_STUDENT_VIEW_CIA_MARK
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        STU_CLASS AS S ON S.STUDENT_ID = SC.STUDENT_ID
                                            AND S.IS_DELETED != 1
                                            AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                            LEFT JOIN
                                        CP_COURSE_TYPE AS CPT ON CPT.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                            AND CPT.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            AND C.IS_DELETED != 1
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID
                                            AND FIND_IN_SET(CCR.SEMESTER_ID,
                                                IF(C.CLASS_YEAR = '1',
                                                    '1,2',
                                                    IF(C.CLASS_YEAR = '2',
                                                        '3,4',
                                                        IF(C.CLASS_YEAR = '3', '5,6', ''))))
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCR.IS_DELETED != 1
                                            AND SC.IS_DELETED != 1
                                     GROUP BY CCR.SEMESTER_ID,CCR.PART,CCR.COURSE_CODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIATotalByStudentAndCourseId:
                    {
                        query = @"SELECT
                                    IF(SUM(IFNULL(INSTANT,0))!=0,SUM(IFNULL(INSTANT,0)),SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,COURSE_ID,
                                    REGISTER_NO,COURSE_CODE,COURSE_TITLE,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                         (SUM(
                                            CASE
                                                WHEN CIA.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN CIA.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            IF(CIA.COMPONENT='INSTANT',COURSE_GROUP_MARK,0) AS INSTANT,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,CGM.COURSE_ID,
                                            SP.REGISTER_NO,CCR.COURSE_CODE,CCR.COURSE_TITLE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_CLASS AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = ?COURSE_ID 
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN 
                                     SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID=CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED!=1
                                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.COURSE_ID = ?COURSE_ID
                                        AND CC.IS_DELETED != 1
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID AND CGM.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                UNION SELECT
                                    IF(SUM(IFNULL(INSTANT,0))!=0,SUM(IFNULL(INSTANT,0)),SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    STUDENT_ID,
                                    ADMISSION_NO,COURSE_ID,
                                    REGISTER_NO,COURSE_CODE,COURSE_TITLE,
                                    UPPER(NAME) AS 'NAME'
                                FROM
                                    (SELECT
                                        (SUM(
                                            CASE
                                                WHEN CIA.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN CIA.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            IF(CIA.COMPONENT='INSTANT',COURSE_GROUP_MARK,0) AS INSTANT,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,CGM.COURSE_ID,
                                            SP.REGISTER_NO,CCR.COURSE_CODE,CCR.COURSE_TITLE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        STU_COURSE_INFO AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN 
                                     SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID=CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED!=1
                                    WHERE
                                        SC.STUDENT_ID = ?STUDENT_ID AND SC.COURSE_ID = ?COURSE_ID
                                             AND SC.ACADEMIC_YEAR=?AC_YEAR
                                             AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY REGISTER_NO;";
                        //query = @"SELECT
                        //            IF(SUM(IFNULL(INSTANT,0))!=0,SUM(IFNULL(INSTANT,0)),SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                        //            STUDENT_ID,
                        //            ADMISSION_NO,COURSE_ID,
                        //            REGISTER_NO,COURSE_CODE,COURSE_TITLE,
                        //            UPPER(NAME) AS 'NAME'
