                #endregion

                #region Student Course Wise Remark For Parent
                case ExaminationSQLCommands.FetchCourseWiseRemarkByStudentAndCourseId:
                    {
                        query = @"SELECT 
                                    COURSE_GROUP_ID,
                                    STUDENT_ID,
                                    COURSE_ID,
                                    REMARK
                                FROM
                                    STU_COURSE_REMARK
                                WHERE
                                    STUDENT_ID = ?STUDENT_ID 
                                        AND COURSE_ID = ?COURSE_ID
                                        AND ACADEMIC_YEAR = ?AC_YEAR
                                        AND IS_DELETED != 1;";
                        break;
                    }
                #endregion

                #region Exam Setting 
                case ExaminationSQLCommands.FetchExamSettingList:
                    {
                        query = @"SELECT 
                                    EXAM_SETTING_ID,
                                    EXAM_NAME,
                                    ACADEMIC_YEAR,
                                    M_EXAM,
                                    M_PASS,
                                    IS_ACTIVE,
                                    SEMESTER,
                                    SEMESTER_TYPE,
                                    EXAM_TYPE,
                                   DATE_FORMAT(LAST_DATE_FOR_EXAM_FEE,'%d/%m/%Y')AS LAST_DATE_FOR_EXAM_FEE,
                                   DATE_FORMAT(START_DATE,'%d/%m/%Y')AS START_DATE,
                                   DATE_FORMAT(END_DATE,'%d/%m/%Y')AS END_DATE,
                                   DATE_FORMAT(HALL_TICKET_PUBLICATION_DATE,'%d/%m/%Y')AS HALL_TICKET_PUBLICATION_DATE
                                FROM
                                    EXAM_SETTING WHERE IS_DELETED!=1 order by EXAM_SETTING_ID desc;";
                              

                        break;
                    }

                case ExaminationSQLCommands.UpdateExamSetting:
                    {
                        query = @"UPDATE EXAM_SETTING
                                  SET
                                    EXAM_NAME = ?EXAM_NAME,
                                    ACADEMIC_YEAR = ?ACADEMIC_YEAR,
                                    M_EXAM = ?M_EXAM,
                                    M_PASS = ?M_PASS,
                                    SEMESTER_TYPE = ?SEMESTER_TYPE,
                                    EXAM_TYPE = ?EXAM_TYPE,
                                    LAST_DATE_FOR_EXAM_FEE = ?LAST_DATE_FOR_EXAM_FEE,
                                    START_DATE = ?START_DATE,
                                    END_DATE = ?END_DATE,
                                    IS_ACTIVE=?IS_ACTIVE,
                                    HALL_TICKET_PUBLICATION_DATE=?HALL_TICKET_PUBLICATION_DATE
                                    WHERE 
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.InsertExamSetting:
                    {
                        query = @"INSERT INTO EXAM_SETTING
                                  (
	                                  EXAM_NAME,
	                                  ACADEMIC_YEAR,
                                      M_EXAM,
                                      M_PASS,
                                      SEMESTER_TYPE,
                                      START_DATE,
                                      END_DATE,
                                      EXAM_TYPE,
                                      LAST_DATE_FOR_EXAM_FEE,
                                      HALL_TICKET_PUBLICATION_DATE,
                                      IS_ACTIVE
                                  )
                                  VALUES
                                  (
                                      ?EXAM_NAME,
	                                  ?ACADEMIC_YEAR,
                                      ?M_EXAM,
                                      ?M_PASS,
                                      ?SEMESTER_TYPE,
                                      ?START_DATE,
                                      ?END_DATE,
                                      ?EXAM_TYPE,
                                      ?LAST_DATE_FOR_EXAM_FEE,
                                      ?HALL_TICKET_PUBLICATION_DATE,
                                      ?IS_ACTIVE
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingById:
                    {
                        query = @"SELECT 
                                        EXAM_SETTING_ID,
                                        EXAM_NAME,
                                        ACADEMIC_YEAR,
                                        M_EXAM,
                                        M_PASS,
                                        IS_ACTIVE,
                                        SEMESTER_TYPE,
                                        EXAM_TYPE,
                                        DATE_FORMAT(LAST_DATE_FOR_EXAM_FEE,'%d/%m/%Y')AS LAST_DATE_FOR_EXAM_FEE,
                                        DATE_FORMAT(START_DATE,'%d/%m/%Y')AS START_DATE,
                                        DATE_FORMAT(END_DATE,'%d/%m/%Y')AS END_DATE,
                                        DATE_FORMAT(HALL_TICKET_PUBLICATION_DATE,'%d/%m/%Y')AS HALL_TICKET_PUBLICATION_DATE
                                    FROM
                                        EXAM_SETTING
                                    WHERE
                                        EXAM_SETTING_ID = ?EXAM_SETTING_ID AND IS_DELETED != 1 ;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamSetting:
                    {
                        query = @"UPDATE EXAM_SETTING SET IS_DELETED=?IS_DELETED WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateIsActiveExamSetting:
                    {
                        query = @"UPDATE EXAM_SETTING SET IS_ACTIVE=?IS_ACTIVE WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.IsExamSettingExist:
                    {
                        query = @"";
                        break;
                    }
                #endregion

                #region Exam Application Print
                case ExaminationSQLCommands.FetchStudentInfoByAppTypeAndShiftId:
                    {
                        query = @"SELECT 
                                        SP.STUDENT_ID,
                                        UPPER(SP.ROLL_NO) AS ROLL_NO,
                                        UPPER(SP.REGISTER_NO) AS REGISTER_NO,
                                        UPPER(CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                        '  ',
                                                        IFNULL(SP.LAST_NAME, ''))) AS NAME,
                                        DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS DATE_OF_BIRTH,
                                        P.PROGRAMME_NAME AS DEPARTMENT,
                                        M_EXAM AS 'MONTH',
                                        ES.EXAM_SETTING_ID,
                                        SS.SEMESTER_NAME AS SEMESTER_ID
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                            INNER JOIN
                                        EXAM_PROGRAMME_TYPE_SETTING AS PT ON PT.PROGRAMME_TYPE_ID = PG.APPTYPE_ID
                                            AND PT.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND PT.IS_ACTIVE = 1
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = PT.EXAM_SETTING_ID
                                            AND ES.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        ACADEMIC_YEAR AS AY ON AY.AC_YEAR = SC.ACADEMIC_YEAR
                                            AND AY.ACTIVE_YEAR = 1
                                            AND AY.IS_DELETED != 1
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = AY.ACADEMIC_YEAR_ID
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = SP.PROGRAM_ID
                                            AND SEM.BATCH = AB.BATCH_ID
                                            AND SEM.IS_ACTIVE = 1
                                            AND SEM.IS_DELETED != 1
                                            AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = SEM.SEMESTER
                                    WHERE
                                        SC.IS_DELETED != 1
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND C.CLASS_LEVEL = ?CLASS_LEVEL
                                            AND C.SHIFT = ?SHIFT
                                    ORDER BY C.PROGRAMME_GROUP_ID , C.CLASS_YEAR , SP.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamCourseInfoByAppTypeShiftAndExamSettingId:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        S.SEMESTER_NAME AS SEMESTER_ID,
                                        ER.STATUS,
                                        UGC.COST
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.STUDENT_ID = SC.STUDENT_ID
                                            AND ER.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND ER.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CCR.SEMESTER_ID
                                            LEFT JOIN
                                        EXAM_COURSE_WISE_COST AS EC ON EC.COURSE_ID = ER.COURSE_ID
                                            AND EC.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND EC.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            AND EC.IS_DELETED != 1
                                            LEFT JOIN
                                        EXAM_UGC_COURSE_TYPE_COST AS UGC ON UGC.UGC_TYPE_COST_ID = EC.UGC_TYPE_COST_ID
                                            AND UGC.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            AND UGC.IS_DELETED != 1
                                    WHERE
                                        SC.IS_DELETED != 1 AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND C.SHIFT = ?SHIFT
                                            AND C.CLASS_LEVEL = ?CLASS_LEVEL;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamFeeInfoByAppTypeAndShiftId:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID, 
                                        H.HEAD, 
                                        FS.CREDIT
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.DEBIT IS NULL
                                            INNER JOIN
                                        FEE_FREQUENCY_FEE_MODE AS FF ON FF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID
                                            AND FF.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND FF.FEE_MODE = ?FEE_MODE
                                            INNER JOIN
                                        SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID = FF.FREQUENCY_ID
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID = SFF.SEMESTER_TYPE
                                            AND SST.IS_ACTIVE = 1
                                            INNER JOIN
                                        SUP_HEAD AS H ON H.HEAD_ID = FS.HEAD
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                    WHERE
                                        C.CLASS_LEVEL = ?CLASS_LEVEL AND C.SHIFT = ?SHIFT
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                    ORDER BY STUDENT_ID,FS.CREDIT;";
                        break;
                    }
                #endregion
                #region  StaffBased CIA Mark Entry
                case ExaminationSQLCommands.FetchStaffBasedClassList:
                    {
                        query = @"SELECT 
                                CS.CLASS_ID,
                                CLS.CLASS_NAME,
                                CLS.PROGRAMME_GROUP_ID,
                                CLS.CLASS_LEVEL,
                                CLS.SHIFT,
                                CLS.PROGRAMME_MODE,
                                CLS.DEPARTMENT
                            FROM
                                CP_CLASS_COURSE_STAFF AS CS
                                    INNER JOIN
                                CP_CLASSES AS CLS ON CLS.CLASS_ID = CS.CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS RT ON RT.COURSE_ROOT_ID = CS.COURSE_ID
                                   
                                    INNER JOIN
                                SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CS.SEMESTER_TYPE_ID
                                    AND ST.IS_ACTIVE = 1
                            WHERE
                                CS.STAFF_ID = ?STAFF_ID AND CS.IS_DELETED != 1
                                    AND CS.ACADEMIC_YEAR = ?AC_YEAR  AND RT.PAPER_TYPE = ?PAPER_TYPE
                            GROUP BY CS.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIAComponentsByCourseIdandStaffId:
                    {
                        query = @"SELECT 
                                '' AS COURSE_GROUP_MARK,
                                '' AS CIA_GROUP_MARK_ID,
                                CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SC.IS_DELETED != 1
                                INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                    AND CT.IS_DELETED != 1
                                INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                    AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.STAFF_ID=?STAFF_ID
                                    AND SP.IS_LEFT != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIA_Marks_InfoByCourseIdandStaffId:
                    {
                        query = @"SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_COURSE_INFO AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                            WHERE
		                            CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.STAFF_ID = ?STAFF_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStaffBasedCIA_Marks:
                    {
                        query = @"SELECT 
                                CGM.CIA_GROUP_MARK_ID,
                                SP.STUDENT_ID,
                                UPPER(CONCAT(IF(SP.FIRST_NAME IS NULL,
                                                    '',
                                                    SP.FIRST_NAME),
                                                ' ',
                                                IF(SP.LAST_NAME IS NULL,
                                                    '',
                                                    SP.LAST_NAME))) AS 'NAME',
                                SP.REGISTER_NO,
                                SP.ROLL_NO AS ADMISSION_NO,
                                CCR.COURSE_ROOT_ID,
                                CGC.MAX_MARK,
                                CGC.ORDER_ID,
                                CGC.CIA_GROUP_ID,
                                COURSE_GROUP_ID,
                                CGC.SUP_CIA_COMPONENT_ID AS 'COMPONENT_ID',
                                SCC.COMPONENT,
                                IF(CGM.COURSE_GROUP_MARK = 0,
                                    '',
                                    CGM.COURSE_GROUP_MARK) AS COURSE_GROUP_MARK,
                                CGM.SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS SC
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN
                                CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                    LEFT JOIN
                                SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SCC.IS_DELETED != 1
                                    LEFT JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                            WHERE
		                            SC.S_CLASS_ID = ?CLASS_ID
                                    AND SC.COURSE_ID = ?COURSE_ID
                                    AND SC.STAFF_ID =?STAFF_ID
                                    AND SC.IS_DELETED != 1
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                            ORDER BY ORDER_ID , REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStaffBasedCIATotal:
                    {
                        query = @"SELECT 
                                SUM(IFNULL(CUMULATIVE, 0)) TOTAL,
                                STUDENT_ID,
                                ADMISSION_NO,
                                COURSE_ID,
                                REGISTER_NO,
                                COURSE_CODE,
                                COURSE_TITLE,
                                UPPER(NAME) AS 'NAME'
                            FROM
                                (SELECT 
                                    ((SUM(IF(COURSE_GROUP_MARK = - 1, 0, COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT 
                                                GROUP_MARK
                                            FROM
                                                CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE
                                                CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1)) AS CUMULATIVE,
                                        SP.STUDENT_ID,
                                        SP.ROLL_NO AS ADMISSION_NO,
                                        CGM.COURSE_ID,
                                        SP.REGISTER_NO,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                FROM
                                    STU_COURSE_INFO AS SC
                                INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_LEFT != 1
                                    AND SP.IS_DELETED != 1
                                LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                    AND SC.COURSE_ID = CGM.COURSE_ID
                                LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    AND CGC.IS_DELETED != 1
                                LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                    AND CCR.IS_DELETED != 1
                                WHERE
			                            SC.S_CLASS_ID = ?CLASS_ID
                                        AND SC.COURSE_ID = ?COURSE_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SC.STAFF_ID=?STAFF_ID
                                        AND SC.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                            GROUP BY STUDENT_ID
                            ORDER BY REGISTER_NO;";
                        break;
                    }
                #endregion

                #region Exam External Staff
                case ExaminationSQLCommands.FetchExamExternalStaff:
                    {
                        query = @"SELECT 
                                    EXTERNAL_USER_ID,
                                    EXTERNAL_USER_CODE,
                                    CONCAT(IFNULL(FIRST_NAME,''),' ',IFNULL(LAST_NAME,'')) AS FIRST_NAME,
                                    DATE_FORMAT(DOB,'d%/%m/%Y') AS DOB,
                                    MOBILE_NO,
                                    MAIL_ID,
                                    COLLEGE_NAME,
                                    D.DESIGNATION
                                FROM
                                    EXAM_EXTERNAL_USERS AS ES
                                        INNER JOIN
                                    SUP_DESIGNATION AS D ON D.DESIGNATIONID = ES.DESIGNATION
                                WHERE
                                    IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamExternalStaffById:
                    {
                        query = @"SELECT 
                                        EXTERNAL_USER_ID,
                                        EXTERNAL_USER_CODE,
                                        FIRST_NAME,
                                        LAST_NAME,
                                        DATE_FORMAT(DOB,'d%/%m/%Y') AS DOB,
                                        MOBILE_NO,
                                        MAIL_ID,
                                        COLLEGE_NAME,
                                        DESIGNATION
                                    FROM 
	                                    EXAM_EXTERNAL_USERS 
                                    WHERE EXTERNAL_USER_ID=?EXTERNAL_USER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamExternalStaff:
                    {
                        query = @"INSERT INTO EXAM_EXTERNAL_USERS
                                  (
	                                  EXTERNAL_USER_CODE,
	                                  FIRST_NAME,
	                                  LAST_NAME,
	                                  DOB,
	                                  MOBILE_NO,
	                                  MAIL_ID,
	                                  COLLEGE_NAME,
	                                  DESIGNATION,
	                                  ACADEMIC_YEAR,
	                                  ROLE,
	                                  USER_TYPE
                                  )
                                  VALUES
                                  (
                                      ?EXTERNAL_USER_CODE,
	                                  ?FIRST_NAME,
	                                  ?LAST_NAME,
	                                  ?DOB,
	                                  ?MOBILE_NO,
	                                  ?MAIL_ID,
	                                  ?COLLEGE_NAME,
	                                  ?DESIGNATION,
	                                  ?AC_YEAR,
	                                  14,
	                                  14
                                  )";
                        break;
                    }

                case ExaminationSQLCommands.UpdateExamExternalStaff:
                    {
                        query = @"UPDATE EXAM_EXTERNAL_USERS
                                    SET
	                                    EXTERNAL_USER_CODE = ?EXTERNAL_USER_CODE,
	                                    FIRST_NAME = ?FIRST_NAME,
	                                    LAST_NAME = ?LAST_NAME,
	                                    DOB = ?DOB,
	                                    MOBILE_NO = ?MOBILE_NO,
	                                    MAIL_ID = ?MAIL_ID,
	                                    COLLEGE_NAME = ?COLLEGE_NAME,
	                                    DESIGNATION = ?DESIGNATION
                                    WHERE EXTERNAL_USER_ID = ?EXTERNAL_USER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamExternalStaff:
                    {
                        query = @"UPDATE EXAM_EXTERNAL_USERS SET  IS_DELETED=1 WHERE EXTERNAL_USER_ID = ?EXTERNAL_USER_ID;";
                        break;
                    }
                #endregion

                #region Syllabus
                case ExaminationSQLCommands.FetchSyllabusList:
                    {
                        query = @"SELECT 
                                        COURSE_SYLLABUS_ID,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCA.COURSE_APPROVAL_ID,
                                        CS.COURSE_CODE,
                                        IFNULL(CCR.COURSE_TITLE,CCA.COURSE_TITLE) AS COURSE_TITLE,
                                        CONCAT('UNIT - ',UNIT_ID) UNIT_ID,
                                        TOPIC
                                    FROM 
                                        COURSE_SYLLABUS AS CS
		                                    LEFT JOIN
	                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_CODE=CS.COURSE_CODE
		                                    AND CCR.IS_DELETED!=1
                                            LEFT JOIN
	                                    cp_course_approval AS CCA ON CCA.COURSE_CODE=CS.COURSE_CODE
		                                    AND CCA.IS_DELETED!=1
                                    WHERE
                                        CS.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSYllabusById:
                    {
                        query = @"SELECT 
                                        COURSE_SYLLABUS_ID,
                                        COURSE_ID,
                                        COURSE_APPROVAL_ID,
                                        COURSE_CODE,
                                        UNIT_ID,
                                        TOPIC,
                                        ACADEMIC_YEAR
                                    FROM
                                        COURSE_SYLLABUS 
                                    WHERE COURSE_SYLLABUS_ID=?COURSE_SYLLABUS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveSyllabus:
                    {
                        query = @"INSERT INTO COURSE_SYLLABUS
                                    (
	                                    COURSE_ID,
	                                    COURSE_APPROVAL_ID,
	                                    COURSE_CODE,
	                                    UNIT_ID,
	                                    TOPIC,
	                                    ACADEMIC_YEAR
                                    )
                                    VALUES
                                    (
	                                    ?COURSE_ID,
	                                    ?COURSE_APPROVAL_ID,
	                                    ?COURSE_CODE,
	                                    ?UNIT_ID,
	                                    ?TOPIC,
	                                    ?AC_YEAR
                                    );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateSyllabus:
                    {
                        query = @"UPDATE COURSE_SYLLABUS
                                  SET
	                                  COURSE_ID = ?COURSE_ID,
	                                  COURSE_APPROVAL_ID = ?COURSE_APPROVAL_ID,
	                                  COURSE_CODE = ?COURSE_CODE,
	                                  UNIT_ID = ?UNIT_ID,
	                                  TOPIC = ?TOPIC
                                  WHERE COURSE_SYLLABUS_ID = ?COURSE_SYLLABUS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteSyllabus:
                    {
                        query = @"UPDATE COURSE_SYLLABUS SET IS_DELETED=1 WHERE COURSE_SYLLABUS_ID = ?COURSE_SYLLABUS_ID;";
                        break;
                    }
                #endregion

                #region Course Approval
                case ExaminationSQLCommands.FetchCourseApprovalList:
                    {
                        query = @"SELECT 
                                    COURSE_APPROVAL_ID,
                                    PL.PROGRAMME_LEVEL,
                                    D.DEPARTMENT,
                                    P.PART,
                                    HRS_PER_WEEK,
                                    CA.CREDITS,
                                    COURSE_TITLE,
                                    COURSE_CODE,
                                    SEMESTER_ID,
                                    IS_NME_SUBJECT,
                                    IS_ALLIED_SUBJECT,
                                    IS_COMPULSORY,
                                    IS_APPROVED,
                                    CA.INTERNAL,
                                    CA.EXTERNAL,
                                    CA.TOTAL,
                                    CA.EXAM_MARK,
                                    UGC.UGC_COURSE_TYPE,
                                    CT.COURSE_TYPE,
                                    PT.PAPER_TYPE,
                                    ST.SUBJECT_TYPE
                                FROM
                                    CP_COURSE_APPROVAL AS CA
		                                INNER JOIN
	                                SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID=CA.PROGRAMME_LEVEL_ID
		                                INNER JOIN
	                                CP_DEPARTMENT AS D ON D.DEPARTMENT_ID=CA.DEPARTMENT_ID
		                                INNER JOIN
                                    SUP_PART AS P ON P.PART_ID = CA.PART
		                                INNER JOIN
	                                CP_UGC_COURSE_TYPE AS UGC ON UGC.UGC_COURSE_TYPE_ID=CA.UGC_COURSE_TYPE
		                                INNER JOIN
	                                CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE_ID=CA.COURSE_TYPE
		                                INNER JOIN
	                                SUP_PAPER_TYPE AS PT ON PT.PAPER_TYPE_ID=CA.PAPER_TYPE
		                                INNER JOIN
	                                SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID=CA.SUBJECT_TYPE
                                WHERE
                                    CA.IS_DELETED != 1 ORDER BY CA.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseApprovalById:
                    {
                        query = @"SELECT COURSE_APPROVAL_ID,
                                    PROGRAMME_LEVEL_ID,
                                    DEPARTMENT_ID,
                                    ACADEMIC_YEAR,
                                    PART,
                                    HRS_PER_WEEK,
                                    CREDITS,
                                    COURSE_TITLE,
                                    COURSE_CODE,
                                    SEMESTER_ID,
                                    COURSE_ORDER,
                                    IS_NME_SUBJECT,
                                    IS_ALLIED_SUBJECT,
                                    IS_COMPULSORY,
                                    IS_APPROVED,
                                    INTERNAL,
                                    EXTERNAL,
                                    TOTAL,
                                    EXAM_MARK,
                                    UGC_COURSE_TYPE,
                                    COURSE_TYPE,
                                    PAPER_TYPE,
                                    SUBJECT_TYPE,
                                    IS_ACTIVE,
                                    IS_DELETED
                                FROM cp_course_approval WHERE COURSE_APPROVAL_ID=?COURSE_APPROVAL_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveCourseApproval:
