                case ExaminationSQLCommands.UpdateCourseApproval:
                    {
                        query = @"UPDATE cp_course_approval
                                    SET
	                                    PROGRAMME_LEVEL_ID = ?PROGRAMME_LEVEL_ID,
	                                    DEPARTMENT_ID = ?DEPARTMENT_ID,
