                    }
                case ExaminationSQLCommands.DeleteCourseApproval:
                    {
                        query = @"UPDATE CP_COURSE_APPROVAL SET IS_DELETED=1 WHERE COURSE_APPROVAL_ID = ?COURSE_APPROVAL_ID;";
                        break;
                    }

                case ExaminationSQLCommands.UpdateCourseApproved:
                    {
                        query = @"UPDATE CP_COURSE_APPROVAL SET IS_APPROVED=1 WHERE COURSE_APPROVAL_ID IN (?COURSE_APPROVAL_ID);";
                        break;
                    }
                case ExaminationSQLCommands.SelectInsertApprovedCourse:
                    {
                        query = @"INSERT INTO CP_COURSE_ROOT 
    (
		PROGRAMME_LEVEL_ID, 
        DEPARTMENT, 
        ACADEMIC_YEAR, 
        PART, 
        HRS_PER_WEEK, 
        CREDITS, 
        COURSE_TITLE, 
        COURSE_CODE, 
        SEMESTER_ID, 
        COURSE_ORDER, 
        IS_NME_SUBJECT, 
        IS_ALLIED_SUBJECT, 
        IS_COMPULSORY,
        INTERNAL, 
        EXTERNAL, 
        TOTAL,
        EXAM_MARK, 
        UGC_COURSE_TYPE, 
        COURSE_TYPE, 
        PAPER_TYPE, 
        SUBJECT_TYPE
	) 
    SELECT 
		PROGRAMME_LEVEL_ID, 
        DEPARTMENT_ID, 
        ACADEMIC_YEAR, 
        PART, 
        HRS_PER_WEEK, 
        CREDITS, 
        COURSE_TITLE, 
        COURSE_CODE, 
        SEMESTER_ID, 
        COURSE_ORDER, 
        IS_NME_SUBJECT, 
        IS_ALLIED_SUBJECT, 
        IS_COMPULSORY,
        INTERNAL, 
        EXTERNAL, 
        TOTAL,
        EXAM_MARK, 
        UGC_COURSE_TYPE, 
        COURSE_TYPE, 
        PAPER_TYPE, 
        SUBJECT_TYPE
    FROM CP_COURSE_APPROVAL WHERE COURSE_APPROVAL_ID IN (?COURSE_APPROVAL_ID);";
                        break;
                    }
                #endregion
                #region Component Based CIA Entry
                case ExaminationSQLCommands.FetchCIAComponentsByCourseAndComponentId:
                    {
                        query = @"SELECT 
                                ''AS COURSE_GROUP_MARK,'' AS CIA_GROUP_MARK_ID, CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_CLASS AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SC.IS_DELETED != 1
                                INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                    AND CT.IS_DELETED != 1
                                INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                    AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1 AND CGC.CIA_GROUP_COMPONENT_ID=?COURSE_GROUP_ID
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                            INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID=CLS.CLASS_ID AND CC.COURSE_ID=?COURSE_ID AND CC.IS_DELETED!=1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR 
                                    AND CLS.IS_DELETED != 1   AND SP.IS_LEFT!=1
                            UNION SELECT 
                               ''AS COURSE_GROUP_MARK,'' AS CIA_GROUP_MARK_ID,  CLS.STUDENT_ID,
                                CONCAT(IF(SP.FIRST_NAME IS NULL,
                                            '',
                                            SP.FIRST_NAME),
                                        ' ',
                                        IF(SP.LAST_NAME IS NULL,
                                            '',
                                            SP.LAST_NAME)) NAME,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                SP.ADMISSION_NO,                               
                                COURSE_ROOT_ID,
                                MAX_MARK,
                                ORDER_ID,
                                CIA_GROUP_ID,
                                CIA_GROUP_COMPONENT_ID AS COURSE_GROUP_ID,
                                SUP_CIA_COMPONENT_ID AS COMPONENT_ID,
                                COMPONENT,
                                SEMESTER_ID
                            FROM
                                STU_COURSE_INFO AS CLS
                                    JOIN
                                (SELECT 
                                    CIA_GROUP_COMPONENT_ID,
                                        CIA_GROUP_ID,
                                        SUP_CIA_COMPONENT_ID,
                                        MAX_MARK,
                                        MIN_MARK,
                                        CGC.ORDER_ID,
                                        SC.COMPONENT,
                                        CR.SEMESTER_ID,
                                        CR.COURSE_ROOT_ID
                                FROM
                                    CIA_GROUP_COMPONENT AS CGC
                                INNER JOIN SUP_CIA_COMPONENTS AS SC ON SC.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    AND SC.IS_DELETED != 1
                                INNER JOIN CP_COURSE_TYPE_GROUP AS CT ON CT.GROUP_ID = CGC.CIA_GROUP_ID
                                    AND CT.IS_DELETED != 1
                                INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_TYPE = CT.COURSE_TYPE_ID
                                    AND CR.COURSE_ROOT_ID = ?COURSE_ID
                                    AND CR.IS_DELETED != 1
                                WHERE
                                    CGC.IS_DELETED != 1 AND CGC.CIA_GROUP_COMPONENT_ID=?COURSE_GROUP_ID
                                ORDER BY CGC.ORDER_ID) AS CIA_COMPONENT
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND COURSE_ID = ?COURSE_ID 
                                    AND CLS.IS_DELETED != 1  AND SP.IS_LEFT!=1 ;";
                        break;
                    }

                case ExaminationSQLCommands.FetchCIA_Marks_InfoByComponentId:
                    {
                        query = @"SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_CLASS AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID AND CGM.COURSE_GROUP_ID=?COURSE_GROUP_ID
                                    INNER JOIN
                                CP_CLASS_COURSE AS CC ON CC.CLASS_ID = CLS.CLASS_ID
                                    AND CC.COURSE_ID = ?COURSE_ID
                                    AND CC.IS_DELETED != 1
                            WHERE
                                CLS.CLASS_ID = ?CLASS_ID
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CLS.IS_DELETED != 1 
                            UNION SELECT 
                                CLS.STUDENT_ID,
                                CIA_GROUP_MARK_ID,
                                COURSE_GROUP_ID,
                                COURSE_GROUP_MARK
                            FROM
                                STU_COURSE_INFO AS CLS
                                    LEFT JOIN
                                CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CLS.STUDENT_ID = CGM.STUDENT_ID
                                    AND CGM.COURSE_ID = ?COURSE_ID AND CGM.COURSE_GROUP_ID=?COURSE_GROUP_ID
                            WHERE
                                CLS.S_CLASS_ID = ?CLASS_ID
                                    AND CLS.COURSE_ID = ?COURSE_ID
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                #endregion



                case ExaminationSQLCommands.FetchStaffBySupervisiontype:
                    {
                        query = @"SELECT 
                                ST.STAFF_ID,
                                UPPER(CONCAT(IFNULL(ST.FIRST_NAME, ''),
                                                ' ',
                                                IFNULL(ST.LAST_NAME, ''))) AS FIRST_NAME,
                                UPPER(ST.STAFF_CODE) AS STAFF_CODE,ST.DEPARTMENT
                            FROM
                                STF_PERSONAL_INFO AS ST
                                    INNER JOIN
                                CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = ST.DEPARTMENT
                            WHERE
                                SUPERVISION_TYPE IN (?SUPERVISION_TYPE)
                            ORDER BY ST.DEPARTMENT;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalRoomsForIndividualSupervision:
                    {
                        query = @"SELECT 
                                    ROOM_ID,DATE_FORMAT(EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE, EXAM_SESSION_ID
                                FROM
                                    (SELECT 
                                        R.ROOM_ID,
                                            ST.EXAM_DATE,
                                            ST.EXAM_SESSION_ID,
                                            COUNT(ST.STUDENT_ID) AS STUDENT_COUNT
                                    FROM
                                        EXAM_SEATING_ALLOTEMENT AS ST
                                    INNER JOIN EXAM_SEATINGS AS SE ON SE.SEATING_ID = ST.SEATING_ID
                                    INNER JOIN SUP_ROOM AS R ON R.ROOM_ID = SE.ROOM_ID
                                    WHERE
                                        ST.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND ST.EXAM_TYPE = ?EXAM_TYPE
                                    GROUP BY ST.EXAM_DATE , ST.EXAM_SESSION_ID , R.ROOM_ID) AS T
                                WHERE
                                    STUDENT_COUNT <= 56;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalRoomsForSupervision:
                    {
                        query = @"SELECT 
                                R.ROOM_ID,
                                DATE_FORMAT(ST.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                ST.EXAM_SESSION_ID,
                                COUNT(ST.STUDENT_ID) AS STUDENT_COUNT
                            FROM
                                EXAM_SEATING_ALLOTEMENT AS ST
                                    INNER JOIN
                                EXAM_SEATINGS AS SE ON SE.SEATING_ID = ST.SEATING_ID
                                    INNER JOIN
                                SUP_ROOM AS R ON R.ROOM_ID = SE.ROOM_ID
                            WHERE
                                ST.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND ST.EXAM_TYPE = ?EXAM_TYPE
                            GROUP BY ST.EXAM_DATE , ST.EXAM_SESSION_ID , R.ROOM_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalStaffCountForSupervision:
                    {
                        query = @"SELECT 
                                COUNT(ST.STAFF_ID) AS TOTAL_STAFF, ST.DEPARTMENT
                            FROM
                                STF_PERSONAL_INFO AS ST
                                    INNER JOIN
                                CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = ST.DEPARTMENT
                            WHERE
                                SUPERVISION_TYPE IN (1)
                            GROUP BY ST.DEPARTMENT
                            ORDER BY TOTAL_STAFF DESC ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllSupervisionStaffByDepartment:
                    {
                        query = @"SELECT 
                                    ST.STAFF_ID,
                                    UPPER(CONCAT(IFNULL(ST.FIRST_NAME, ''),
                                                    ' ',
                                                    IFNULL(ST.LAST_NAME, ''))) AS FIRST_NAME,
                                    UPPER(ST.STAFF_CODE) AS STAFF_CODE,
                                    ST.DEPARTMENT,
                                    COUNT(I.STAFF_ID) AS SUPERVISION_COUNT
                                FROM
                                    STF_PERSONAL_INFO AS ST
                                        INNER JOIN
                                    CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = ST.DEPARTMENT
                                        LEFT JOIN
                                    EXAM_SEATING_INVIGILATOR AS I ON I.STAFF_ID = ST.STAFF_ID
                                        AND I.EXAM_SETTING_ID = 4
                                        AND I.EXAM_TYPE = 1
                                WHERE
                                    SUPERVISION_TYPE IN (1)
                                        AND ST.DEPARTMENT = ?DEPARTMENT
                                GROUP BY ST.STAFF_ID
                                ORDER BY SUPERVISION_COUNT , ST.STAFF_CODE DESC;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSeatinAllotedRoomByExamdateandExamSession:
                    {
                        query = @"SELECT 
                                    R.ROOM_ID, R.ROOM_NO, ST.EXAM_DATE, ST.EXAM_SESSION_ID
                                FROM
                                    EXAM_SEATING_ALLOTEMENT AS ST
                                        INNER JOIN
                                    EXAM_SEATINGS AS S ON S.SEATING_ID = ST.SEATING_ID
                                        INNER JOIN
                                    SUP_ROOM AS R ON R.ROOM_ID = S.ROOM_ID
                                WHERE
                                    ST.EXAM_SETTING_ID = 4
                                        AND ST.EXAM_DATE = ?EXAM_DATE
                                        AND ST.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                        AND ST.EXAM_TYPE = ?EXAM_TYPE
                                        AND R.ROOM_ID NOT IN (SELECT 
                                            ROOM_ID
                                        FROM
                                            EXAM_SEATING_INVIGILATOR AS I
                                        WHERE
                                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND EXAM_TYPE = ?EXAM_TYPE
                                                AND EXAM_DATE = ?EXAM_DATE
                                                AND EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                                AND IS_DELETED != 1)
                                GROUP BY R.ROOM_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalRoomsForDoubleSupervision:
                    {
                        query = @"SELECT 
                                 ROOM_ID, DATE_FORMAT(EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE, EXAM_SESSION_ID
                            FROM
                                (SELECT 
                                    R.ROOM_ID,
                                        ST.EXAM_DATE,
                                        ST.EXAM_SESSION_ID,
                                        COUNT(ST.STUDENT_ID) AS STUDENT_COUNT
                                FROM
                                    EXAM_SEATING_ALLOTEMENT AS ST
                                INNER JOIN EXAM_SEATINGS AS SE ON SE.SEATING_ID = ST.SEATING_ID
                                INNER JOIN SUP_ROOM AS R ON R.ROOM_ID = SE.ROOM_ID
                                WHERE
                                    ST.EXAM_SETTING_ID = 4
                                        AND ST.EXAM_TYPE = 1
                                GROUP BY ST.EXAM_DATE , ST.EXAM_SESSION_ID , R.ROOM_ID) AS T
                            WHERE
                                STUDENT_COUNT > 56;";
                        break;
                    }
                case ExaminationSQLCommands.CheckForMaximumAllotementForStaff:
                    {
                        query = @"SELECT 
                                (COUNT(STAFF_ID))>=?INDIVIDUAL_HOUR AS STAFF_ID
                            FROM
                                EXAM_SEATING_INVIGILATOR
                            WHERE
                                STAFF_ID = ?STAFF_ID AND EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EXAM_TYPE = ?EXAM_TYPE
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamInvigilatorListByDateSession:
                    {
                        query = @"SELECT 
                                    I.SEATING_INVIGILATOR_ID,
                                    UPPER(CONCAT(IFNULL(ST.FIRST_NAME, ''),
                                                    ' ',
                                                    IFNULL(ST.LAST_NAME, ''))) AS FIRST_NAME,
                                    UPPER(ST.STAFF_CODE) AS STAFF_CODE,
                                    DP.DEPARTMENT,
                                    SS.SHIFT_NAME AS SHIFT,
                                    R.ROOM_ID,
                                    R.ROOM_NO,
                                    R.EXAM_CAPACITY,
                                    DATE_FORMAT(I.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    B.BLOCK_NAME,
                                    I.EXAM_SESSION_ID
                                FROM
                                    EXAM_SEATING_INVIGILATOR AS I
                                        INNER JOIN
                                    STF_PERSONAL_INFO AS ST ON ST.STAFF_ID = I.STAFF_ID
                                        LEFT JOIN
                                    CP_DEPARTMENT AS DP ON DP.DEPARTMENT_ID = ST.DEPARTMENT
                                        LEFT JOIN
                                    SUP_SHIFT AS SS ON SS.SHIFT_ID = ST.SHIFT
                                        INNER JOIN
                                    SUP_ROOM AS R ON R.ROOM_ID = I.ROOM_ID
                                        INNER JOIN
                                    SUP_COLLEGE_BLOCK AS B ON B.COLLEGE_BLOCK_ID = R.COLLEGE_BLOCK_ID
                                        INNER JOIN
                                    SUP_EXAM_SESSION AS S ON S.EXAM_SESSION_ID = I.EXAM_SESSION_ID
                                WHERE
                                    I.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                     AND I.EXAM_TYPE = ?EXAM_TYPE
                                        AND I.EXAM_DATE = ?EXAM_DATE
                                        AND I.EXAM_SESSION_ID = ?EXAM_SESSION_ID       
                                ORDER BY R.ROOM_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.ListExamTTGrouping:
                    {
                        query = @"SELECT 
	                                GR.TT_GROUP_ID,
                                    ST.EXAM_NAME,
                                    SS.EXAM_SESSION,
                                    PL.APPLICATION_TYPE AS PROGRAMME_LEVEL,
                                    PR.CLASS_YEAR AS PROGRAMME_YEAR,
                                    S.SET_NAME,
                                    GR.GROUP_ORDER
                                FROM
                                    EXAM_TT_GROUPING AS GR
                                        INNER JOIN
                                    EXAM_SETTING AS ST ON ST.EXAM_SETTING_ID = GR.EXAM_SETTING_ID
										INNER JOIN
									SUP_EXAM_SESSION AS SS ON SS.EXAM_SESSION_ID=GR.EXAM_SESSION_ID
                                        INNER JOIN
                                    SUP_APPLICATION_TYPE AS PL ON PL.APPLICATION_TYPE_ID = GR.PROGRAMME_LEVEL
                                        INNER JOIN
                                    SUP_CLASS_YEAR AS PR ON PR.CLASS_YEAR_ID = GR.PROGRAMME_YEAR
                                        INNER JOIN
                                    SUP_SETS AS S ON S.SET_ID = GR.SET_ID
                                WHERE
                                    GR.ACADEMIC_YEAR = ?AC_YEAR
                                        AND GR.IS_DELETED != 1
                                ORDER BY GR.EXAM_SETTING_ID , GR.GROUP_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTGroupingById:
                    {
                        query = @"SELECT 
                                    TT_GROUP_ID,
                                    EXAM_SETTING_ID,
                                    PROGRAMME_LEVEL,
                                    PROGRAMME_YEAR,
                                    EXAM_SESSION_ID,
                                    SET_ID,
                                    GROUP_ORDER
                                FROM
                                    EXAM_TT_GROUPING
                                WHERE
                                    IS_DELETED != 1  AND TT_GROUP_ID=?TT_GROUP_ID AND ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.InsertExamTTGrouping:
                    {
                        query = @"INSERT INTO EXAM_TT_GROUPING (EXAM_SETTING_ID, PROGRAMME_LEVEL, PROGRAMME_YEAR, EXAM_SESSION_ID, SET_ID, GROUP_ORDER,ACADEMIC_YEAR)
                                  VALUES(?EXAM_SETTING_ID,?PROGRAMME_LEVEL,?PROGRAMME_YEAR,?EXAM_SESSION_ID,?SET_ID,?GROUP_ORDER,?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamTTGrouping:
                    {
                        query = @"UPDATE EXAM_TT_GROUPING SET EXAM_SETTING_ID=?EXAM_SETTING_ID,PROGRAMME_LEVEL=?PROGRAMME_LEVEL,PROGRAMME_YEAR=?PROGRAMME_YEAR,EXAM_SESSION_ID=?EXAM_SESSION_ID,SET_ID=?SET_ID,GROUP_ORDER=?GROUP_ORDER WHERE TT_GROUP_ID=?TT_GROUP_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamTTGrouping:
                    {
                        query = @"UPDATE EXAM_TT_GROUPING SET IS_DELETED=1 WHERE TT_GROUP_ID=?TT_GROUP_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTLeaveBySettingid:
                    {
                        query = @"SELECT 
                                    EXAM_LEAVE_ID, EXAM_SETTING_ID, DATE_FORMAT(LEAVE_DATE, '%d/%m/%Y') AS LEAVE_DATE, LEAVE_REASON
                                FROM
                                    EXAM_TT_LEAVE
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND ACADEMIC_YEAR = ?AC_YEAR
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTGroupingBySettingid:
                    {
                        query = @"SELECT 
                                TT_GROUP_ID,
                                EXAM_SETTING_ID,
                                PROGRAMME_LEVEL,
                                PROGRAMME_YEAR,
                                EXAM_SESSION_ID,
                                SET_ID,
                                GROUP_ORDER
                            FROM
                                EXAM_TT_GROUPING
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID AND IS_DELETED != 1
                                    AND ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExternalExamSettingBySettingid:
                    {
                        query = @"SELECT 
                                EXAM_SETTING_ID,
                                EXAM_NAME,
                                ACADEMIC_YEAR,
                                M_EXAM,
                                M_PASS,
                                IS_ACTIVE,
                                SEMESTER,
                                EXAM_TYPE,
                                LAST_DATE_FOR_EXAM_FEE,
                              DATE_FORMAT(START_DATE, '%d/%m/%Y') AS START_DATE,
                                DATE_FORMAT(END_DATE, '%d/%m/%Y') AS END_DATE,
                                PROGRAMME_TYPE_IDS
                            FROM
                                EXAM_SETTING
                            WHERE
                                IS_DELETED != 1 AND EXAM_SETTING_ID = ?EXAM_SETTING_ID AND ACADEMIC_YEAR=?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchInternalExamSettingBySettingid:
                    {
                        query = @"SELECT 
                                EXAM_SETTING_ID,
                                EXAM_NAME,
                                ACADEMIC_YEAR,
                                M_EXAM,
                                M_PASS,
                                IS_ACTIVE,
                                SEMESTER,
                                EXAM_TYPE,
                                LAST_DATE_FOR_EXAM_FEE,
                                DATE_FORMAT(START_DATE, '%d/%m/%Y') AS START_DATE,
                                DATE_FORMAT(END_DATE, '%d/%m/%Y') AS END_DATE,
                                PROGRAMME_TYPE_IDS
                            FROM
                                CIA_EXAM_SETTING
                            WHERE
                                IS_DELETED != 1 AND EXAM_SETTING_ID = ?EXAM_SETTING_ID AND ACADEMIC_YEAR=?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSessionByExamtype:
                    {
                        query = @"SELECT 
                                EXAM_SESSION_ID, EXAM_SESSION, EXAM_TYPE, IS_ACTIVE
                            FROM
                                SUP_EXAM_SESSION
                            WHERE
                                EXAM_TYPE = ?EXAM_TYPE AND IS_ACTIVE = 1
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamDatesFromCalender:
                    {
                        query = @"SELECT 
                                    DAY_ID,
                                    DATE_FORMAT(DAY_ORDER_DATE, '%d/%m/%Y') AS DAY_ORDER_DATE,
                                    DAY_TYPE,
                                    DAY_ORDER
                                FROM
                                    CALENDER
                                WHERE
                                    DAY_ORDER_DATE BETWEEN ?START_DATE AND ?END_DATE
                                        AND IS_HOLIDAY != 1
                                        AND ACADEMIC_YEAR = ?AC_YEAR
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTStructrureBySettingid:
                    {
                        query = @"SELECT 
                                    EXAM_TT_STRUCTURE_ID,
                                    EXAM_SETTING_ID,
                                    EXAM_TYPE,
                                    DATE_FORMAT(EXAM_DATE,'%d/%m/%Y') as EXAM_DATE,
                                    EXAM_SESSION_ID,
                                    EXAM_TIME,
                                       ST.UGC_COURSE_TYPE AS UGC_COURSE_TYPE_ID,
                                        CT.UGC_COURSE_TYPE AS UGC_COURSE_TYPE,
                                        ST.PROGRAMME_LEVEL,
                                        ST.PROGRAMME_YEAR
                                    FROM
                                        EXAM_TT_STRUCTURE AS ST
                                            INNER JOIN
                                        CP_UGC_COURSE_TYPE AS CT ON CT.UGC_COURSE_TYPE_ID = ST.UGC_COURSE_TYPE
                                WHERE
                                    ST.ACADEMIC_YEAR = ?AC_YEAR AND ST.IS_DELETED != 1
                                        AND ST.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND ST.EXAM_TYPE = ?EXAM_TYPE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseStructureByProgrammeLevelForExamTT:
                    {
                        query = @"SELECT 
                                    CT.UGC_COURSE_TYPE_ID,
                                    CT.UGC_COURSE_TYPE,
                                    CS.PROGRAMME_LEVEL,
                                    CS.PROGRAMME_YEAR,
                                    GROUP_CONCAT(CS.FACULTY_ID) AS FACULTY_ID
                                FROM
                                    CP_COURSE_STRUCTURE AS CS
                                        INNER JOIN
                                    CP_UGC_COURSE_TYPE AS CT ON CT.UGC_COURSE_TYPE_ID = CS.UGC_TYPE_ID
                                WHERE
                                    CS.PROGRAMME_LEVEL = ?PROGRAMME_LEVEL
                                        AND CS.PROGRAMME_YEAR = ?PROGRAMME_YEAR
                                        AND CS.SEMESTER_ID IN (2,4,6)
                                        AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CS.IS_DELETED != 1
                                GROUP BY CS.PROGRAMME_LEVEL , CS.PROGRAMME_YEAR , CT.UGC_COURSE_TYPE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ListExamTTLeave:
                    {
                        query = @"SELECT 
                                EXAM_LEAVE_ID,
                                EL.EXAM_SETTING_ID,
                                DATE_FORMAT(LEAVE_DATE, '%d/%m/%Y') AS LEAVE_DATE,
                                LEAVE_REASON,
                                EXAM_NAME
                            FROM
                                EXAM_TT_LEAVE AS EL
                                    INNER JOIN
                                EXAM_SETTING AS ST ON ST.EXAM_SETTING_ID = EL.EXAM_SETTING_ID
                            WHERE
                                EL.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTLeaveById:
                    {
                        query = @"SELECT 
                                EXAM_LEAVE_ID,
                                EL.EXAM_SETTING_ID,
                                DATE_FORMAT(LEAVE_DATE, '%d/%m/%Y') AS LEAVE_DATE,
                                LEAVE_REASON
                            FROM
                                EXAM_TT_LEAVE AS EL
                            WHERE
                                EL.IS_DELETED != 1 AND EXAM_LEAVE_ID=?EXAM_LEAVE_ID
                                    AND EL.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.InsertExamTTLeave:
                    {
                        query = @"INSERT INTO EXAM_TT_LEAVE (EXAM_SETTING_ID, LEAVE_DATE, LEAVE_REASON, ACADEMIC_YEAR) VALUES
                                   (?EXAM_SETTING_ID,?LEAVE_DATE,?LEAVE_REASON,?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamTTLeave:
                    {
                        query = @"UPDATE EXAM_TT_LEAVE SET EXAM_SETTING_ID=?EXAM_SETTING_ID,LEAVE_DATE=?LEAVE_DATE,LEAVE_REASON=?LEAVE_REASON WHERE EXAM_LEAVE_ID=?EXAM_LEAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamTTLeave:
                    {
                        query = @"UPDATE EXAM_TT_LEAVE SET IS_DELETED=1 WHERE EXAM_LEAVE_ID=?EXAM_LEAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTSettingByExamSettingId:
                    {
                        query = @"SELECT 
                                EXAM_TT_SETTING_ID,
                                EXAM_SETTING_ID,
                                ALLOW_ARREAR_LAST,
                                ALLOW_STATIC_SESSION,
                                ARREAR_POSITION
                            FROM
                                EXAM_TT_SETTING
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;
                    }
                #region Internal Exam Registration
                case ExaminationSQLCommands.CheckCIARegistrationIsExist:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID,
                                    FROM
                                        CIA_REGISTRATION_?AC_YEAR
                                    WHERE
                                        STUDENT_ID = ?STUDENT_ID
                                            AND EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterMarksByStudentId:
                    {
                        query = @"SELECT 
                                        CC.COURSE_ROOT_ID,
                                        CC.COURSE_CODE,
                                        UPPER(CC.COURSE_TITLE) AS 'COURSE_TITLE',
                                        IF(SM.RESULT != 'F',
                                            IF(SM.RESULT != 'A', 'PASS', 'AAA'),
                                            'A') AS RESULT,
                                        SM.STUDENT_ID,
                                        SM.CIA_RESULT,
                                        CC.SEMESTER_ID AS SEMESTER,
                                        SS.SUBJECT_TYPE
                                    FROM
                                        SEMESTER_MARKS_?AC_YEAR SM
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = SM.COURSE_ID
                                            LEFT JOIN
                                        SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CC.SUBJECT_TYPE
                                            AND SS.IS_DELETED != 1
                                    WHERE
                                        SM.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveCIARegistration:
                    {
                        query = @"INSERT INTO CIA_REGISTRATION_?AC_YEAR
                                  (
                                      STUDENT_ID,
                                      COURSE_ID,
                                      STATUS,
                                      ACADEMIC_YEAR,
                                      EXAM_SEMESTER,
                                      EXAM_SETTING_ID,
                                      ENTRY_DATE
                                  )
                                  VALUES
                                  (
	                                  ?STUDENT_ID,
                                      ?COURSE_ROOT_ID,
                                      ?STATUS,
                                      ?AC_YEAR,
                                      ?SEMESTER,
                                      ?EXAM_SETTING_ID,
                                      NOW()
                                  );";
                        break;
                    }
                #endregion

                #region External Exam Registration For PassedOut
                case ExaminationSQLCommands.FetchPassedOutStudentForExamByIdRegistration:
                    {
                        query = @"SELECT 
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
                                    UPPER(CONCAT(IFNULL(SP.FIRST_NAME,''),' ',IFNULL(SP.LAST_NAME,''))) AS 'NAME',
                                    P.PROGRAMME_NAME AS DEPARTMENT,
                                    SP.BATCH,
                                    PG.APPTYPE_ID AS 'APPLICATION_TYPE_ID',
                                    DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS 'DATE_OF_BIRTH',
                                    IF(SP.STU_MOBILENO IS NULL
			                                || SP.STU_MOBILENO = '',
		                                IF(SP.FR_MOBILE IS NULL
			                                || SP.FR_MOBILE = '',
		                                IF(SP.MO_MOBILE IS NULL
			                                || SP.MO_MOBILE = '',
			                                '',
			                                SP.MO_MOBILE),
			                                SP.FR_MOBILE),
		                                SP.STU_MOBILENO) AS 'MOBILE_NO'
                                FROM
                                    STU_PERSONAL_INFO AS SP
		                                INNER JOIN
	                                CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID=SP.PROGRAM_ID
		                                INNER JOIN
	                                CP_PROGRAMME AS P ON P.PROGRAMME_ID=PG.PROGRAMME_ID
                                WHERE
                                    SP.STUDENT_ID = ?STUDENT_ID AND SP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchSemesterResultByStudentIdForPassedOut:
                    {
                        query = @"SELECT 
                                        CC.COURSE_ROOT_ID,
                                        CC.COURSE_CODE,
                                        UPPER(CC.COURSE_TITLE) AS 'COURSE_TITLE',
	                                    IF(SM.RESULT='P','PASS',IF(SM.RESULT='M','MODERATE',IF(SM.RESULT='A','AAA','A'))) AS RESULT,
                                        SM.STUDENT_ID,
                                        SM.SEMESTER AS WRITTEN_SEMESTER,
                                        CC.SEMESTER_ID AS SEMESTER,
                                        CC.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                        SS.SUBJECT_TYPE,
                                        CC.COURSE_TYPE
                                    FROM
                                        SEMESTER_MARKS_?AC_YEAR SM
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = SM.COURSE_ID
                                            LEFT JOIN
                                        SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CC.SUBJECT_TYPE
                                            AND SS.IS_DELETED != 1
                                    WHERE
                                        SM.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                #endregion

                #region Question Bank

                #region Exam Dept Question Setting
                case ExaminationSQLCommands.FetchExamDeptQuestionSettingList:
                    {
                        query = @"SELECT 
                                    QUESTION_PAPER_SETTING_ID,
                                    SS.SECTION AS SECTION_ID,
                                    D.DEPARTMENT AS 'DEPARTMENT_ID',
                                    PL.PROGRAMME_LEVEL AS 'PROGRAMME_LEVEL_ID',
                                    TOPIC,
                                    IF(IS_EITHEROR='1','YES','NO') AS IS_EITHEROR,
                                    TOTAL_QUESTIONS,MAX_QUESTION,
                                    MARK_PER_QUESTION,
                                    TOTAL_MARK
                                FROM
                                    EXAM_DEPT_QUESTION_PAPER_SETTING AS QS
                                        INNER JOIN
                                    CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = QS.DEPARTMENT_ID
                                        INNER JOIN
                                    SUP_PROGRAMME_LEVEL AS PL ON PL.PROGRAMME_LEVEL_ID = QS.PROGRAMME_LEVEL_ID
                                        INNER JOIN
									SUP_SECTION AS SS ON SS.SECTION_ID=QS.SECTION_ID
                                WHERE
                                    QS.IS_DELETED != 1
                                ORDER BY QS.DEPARTMENT_ID , QS.SECTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamDeptQuestionSettingById:
                    {
                        query = @"SELECT 
                                    QUESTION_PAPER_SETTING_ID,
	                                SECTION_ID,
	                                DEPARTMENT_ID,
	                                PROGRAMME_LEVEL_ID,
	                                TOPIC,
                                    IS_EITHEROR,
	                                MAX_QUESTION,
	                                TOTAL_QUESTIONS,
	                                MARK_PER_QUESTION,
	                                TOTAL_MARK
                                FROM 
	                                EXAM_DEPT_QUESTION_PAPER_SETTING 
                                WHERE 
	                                QUESTION_PAPER_SETTING_ID=?QUESTION_PAPER_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamDeptQuestionSetting:
                    {
                        query = @"INSERT INTO EXAM_DEPT_QUESTION_PAPER_SETTING
                                  (
	                                  SECTION_ID,
	                                  DEPARTMENT_ID,
	                                  PROGRAMME_LEVEL_ID,
                                      TOPIC,
                                      IS_EITHEROR,
                                      MAX_QUESTION,
	                                  TOTAL_QUESTIONS,
	                                  MARK_PER_QUESTION,
	                                  TOTAL_MARK,
	                                  ACADEMIC_YEAR
                                  )
                                  VALUES
                                  (
                                      ?SECTION_ID,
	                                  ?DEPARTMENT_ID,
	                                  ?PROGRAMME_LEVEL_ID,
                                      ?TOPIC,
                                      ?IS_EITHEROR,
                                      ?MAX_QUESTION,
	                                  ?TOTAL_QUESTIONS,
	                                  ?MARK_PER_QUESTION,
	                                  ?TOTAL_MARK,
	                                  ?AC_YEAR
                                  );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamDeptQuestionSetting:
                    {
                        query = @"UPDATE EXAM_DEPT_QUESTION_PAPER_SETTING
                                  SET
	                                  SECTION_ID = ?SECTION_ID,
	                                  DEPARTMENT_ID = ?DEPARTMENT_ID,
	                                  PROGRAMME_LEVEL_ID = ?PROGRAMME_LEVEL_ID,
	                                  TOPIC = ?TOPIC,
	                                  IS_EITHEROR = ?IS_EITHEROR,
	                                  MAX_QUESTION = ?MAX_QUESTION,
	                                  TOTAL_QUESTIONS = ?TOTAL_QUESTIONS,
	                                  MARK_PER_QUESTION = ?MARK_PER_QUESTION,
	                                  TOTAL_MARK = ?TOTAL_MARK,
	                                  ACADEMIC_YEAR = ?ACADEMIC_YEAR
                                  WHERE QUESTION_PAPER_SETTING_ID = ?QUESTION_PAPER_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamDeptQuestionSetting:
                    {
                        query = @"UPDATE EXAM_DEPT_QUESTION_PAPER_SETTING SET IS_DELETED=1 WHERE QUESTION_PAPER_SETTING_ID = ?QUESTION_PAPER_SETTING_ID;";
                        break; ;
                    }
                #endregion

                #region Exam Questions
                case ExaminationSQLCommands.FetchExamQuestionsList:
                    {
                        query = @"SELECT 
                                    QUESTION_ID,
                                    SS.SECTION AS 'SECTION_ID',
                                    QL.QUESTION_LEVEL,
                                    EQ.QUESTION,
                                    EQ.EITHER_OR_QUESTION,
                                    SU.UNIT_NAME AS 'UNIT_ID',
                                    IF(IS_REPEAT='1','YES','NO') AS IS_REPEAT,
	                                REPEAT_YEAR,
	                                NOT_REPEAT_YEAR
                                FROM
                                    EXAM_QUESTIONS AS EQ
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EQ.COURSE_ID
                                        INNER JOIN
                                    SUP_UNIT AS SU ON SU.UNIT_ID = EQ.UNIT_ID
                                        INNER JOIN
                                    SUP_SECTION AS SS ON SS.SECTION_ID = EQ.SECTION_ID
                                        INNER JOIN 
                                    SUP_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID=EQ.QUESTION_LEVEL
                                WHERE
                                    EQ.IS_DELETED != 1 AND EQ.COURSE_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamQuestionsById:
                    {
                        query = @"SELECT 
	                                    QUESTION_ID,
	                                    COURSE_ID,
										CCR.DEPARTMENT,
                                        IF(CCR.SEMESTER_ID %2=0,'2','1') AS SEMESTER,
	                                    SECTION_ID,
	                                    QUESTION_LEVEL,
	                                    QUESTION,
                                        EITHER_OR_QUESTION,
	                                    UNIT_ID,
	                                    IS_REPEAT,
	                                    REPEAT_YEAR,
	                                    NOT_REPEAT_YEAR
                                    FROM 
	                                    EXAM_QUESTIONS AS EQ
											INNER JOIN
										CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID=EQ.COURSE_ID
                                    WHERE 
	                                    QUESTION_ID=?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamQuestions:
                    {
                        query = @"INSERT INTO EXAM_QUESTIONS
                                 (
	                                 COURSE_ID,
	                                 SECTION_ID,
	                                 QUESTION_LEVEL,
	                                 QUESTION,
	                                 EITHER_OR_QUESTION,
	                                 UNIT_ID,
	                                 IS_REPEAT,
	                                 REPEAT_YEAR,
	                                 NOT_REPEAT_YEAR,
	                                 ACADEMIC_YEAR,
	                                 ENTRY_ID,
	                                 ENTRY_DATE
                                 )
                                 VALUES
                                 (
                                     ?COURSE_ID,
	                                 ?SECTION_ID,
	                                 ?QUESTION_LEVEL,
	                                 ?QUESTION,
	                                 ?EITHER_OR_QUESTION,
	                                 ?UNIT_ID,
	                                 ?IS_REPEAT,
	                                 ?REPEAT_YEAR,
	                                 ?NOT_REPEAT_YEAR,
	                                 ?AC_YEAR,
	                                 ?ENTRY_ID,
	                                 CURDATE()
                                 );";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamQuestions:
                    {
                        query = @"UPDATE EXAM_QUESTIONS
                                  SET
	                                  COURSE_ID = ?COURSE_ID,
	                                  SECTION_ID = ?SECTION_ID,
	                                  QUESTION_LEVEL = ?QUESTION_LEVEL,
	                                  QUESTION = ?QUESTION,
	                                  EITHER_OR_QUESTION  = ?EITHER_OR_QUESTION,
	                                  UNIT_ID = ?UNIT_ID,
	                                  IS_REPEAT = ?IS_REPEAT,
	                                  REPEAT_YEAR = ?REPEAT_YEAR,
	                                  NOT_REPEAT_YEAR = ?NOT_REPEAT_YEAR
                                  WHERE QUESTION_ID = ?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamQuestions:
                    {
                        query = @"UPDATE EXAM_QUESTIONS SET IS_DELETED=1 WHERE QUESTION_ID=?QUESTION_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchDeptSettingByCourseId:
                    {
                        query = @"SELECT 
                                        IS_EITHEROR,
                                        TOPIC,
                                        TOTAL_QUESTIONS,
                                        MARK_PER_QUESTION,
                                        TOTAL_MARK
                                    FROM
                                        CP_COURSE_ROOT AS CCR
                                            INNER JOIN
                                        EXAM_DEPT_QUESTION_PAPER_SETTING AS EQ ON EQ.DEPARTMENT_ID = CCR.DEPARTMENT
                                            AND EQ.PROGRAMME_LEVEL_ID = CCR.PROGRAMME_LEVEL_ID
                                            AND EQ.IS_DELETED != 1
                                    WHERE
                                        CCR.COURSE_ROOT_ID = ?COURSE_ID
                                            AND EQ.SECTION_ID = ?SECTION_ID;";
                        break;
                    }
                #endregion

                #region Exam Question Paper
                case ExaminationSQLCommands.FetchCourseByExamSetting:
                    {
                        query = @"SELECT 
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE
                                    FROM
                                        EXAM_TIMETABLE AS ET
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = ET.COURSE_ID
		                                    AND CCR.IS_DELETED!=1
                                    WHERE
                                        ET.EXAM_SETTING_ID = ?EXAM_SETTING_ID AND ET.IS_DELETED!=1
                                    ORDER BY ET.EXAM_DATE,ET.EXAM_SESSION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchDeptSettingByCourseIdForddl:
                    {
                        query = @"SELECT 
                                        SS.SECTION_ID,
                                        SS.SECTION,
                                        ES.TOPIC,
                                        ES.MAX_QUESTION,
                                        ES.MARK_PER_QUESTION,
                                        ES.TOTAL_QUESTIONS,
                                        ES.TOTAL_MARK
                                    FROM
	                                    CP_COURSE_ROOT AS CCR 
		                                    INNER JOIN
                                        EXAM_DEPT_QUESTION_PAPER_SETTING AS ES ON ES.DEPARTMENT_ID=CCR.DEPARTMENT
		                                    AND ES.PROGRAMME_LEVEL_ID=CCR.PROGRAMME_LEVEL_ID
                                            AND ES.IS_DELETED!=1
                                            INNER JOIN
                                        SUP_SECTION AS SS ON SS.SECTION_ID = ES.SECTION_ID
                                    WHERE 
	                                    CCR.COURSE_ROOT_ID IN(?COURSE_ID) 
                                        AND CCR.IS_DELETED!=1
                                    ORDER BY SS.SECTION_ID;";
                        break;
                    }
                #endregion
                #endregion

                case ExaminationSQLCommands.FetchStudentCountbyProgrammeLevel:
                    {
                        query = @"SELECT 
                            CP.PROGRAMME_LEVEL,
                            CL.CLASS_YEAR AS PROGRAMME_YEAR,
                            CL.CLASS_YEAR AS BATCH,
                            COUNT(SC.STUDENT_ID) AS STUDENT_COUNT
                        FROM
                            STU_CLASS AS SC
                                INNER JOIN
                            STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                AND SP.IS_DELETED != 1
                                AND SP.IS_LEFT != 1
                                INNER JOIN
                            CP_CLASSES AS CL ON CL.CLASS_ID = SC.CLASS_ID
                                INNER JOIN
                            CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CL.PROGRAMME_GROUP_ID
                                INNER JOIN
                            CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = PG.PROGRAMME_ID
                        WHERE
                            SC.ACADEMIC_YEAR = ?AC_YEAR
                                AND SC.IS_DELETED != 1
                        GROUP BY CP.PROGRAMME_LEVEL , CL.CLASS_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFailQueryConstruction1:
                    {
                        query = @"SELECT 
                                SM.SEMESTER_MARK_ID,
                                    SM.STUDENT_ID,
                                    SM.COURSE_ID,
                                    CR.COURSE_CODE,
                                    SM.RESULT,
                                    SM.M_PASS
                            FROM
                                SEMESTER_MARKS_?AC_YEAR AS SM
                            INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                AND CR.SEMESTER_ID IN (2 , 4, 6)
                            WHERE
                                SM.RESULT != 'P' ";
                        break;
                    }
                case ExaminationSQLCommands.FetchPassQueryConstruction1:
                    {
                        query = @"SELECT 
                                SM.SEMESTER_MARK_ID,
                                    SM.STUDENT_ID,
                                    SM.COURSE_ID,
                                    CR.COURSE_CODE,
                                    SM.RESULT,
                                    SM.M_PASS
                            FROM
                                SEMESTER_MARKS_?AC_YEAR AS SM
                            INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                AND CR.SEMESTER_ID IN (2 , 4, 6)
                            WHERE
                                SM.RESULT = 'P' ";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamTTCourseByActiveExamSetting:
                    {
                        query = @"SELECT 
                                TT.COURSE_ID,
                                CR.COURSE_CODE,
                                CR.CONS_COURSE_TITLE,
                                CR.SEMESTER_ID,
                                CR.UGC_COURSE_TYPE,
                                CR.SUBJECT_TYPE
                            FROM
                                EXAM_TIMETABLE AS TT
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = TT.COURSE_ID
                            WHERE
                                EXAM_SETTING_ID = (SELECT 
                                        EXAM_SETTING_ID
                                    FROM
                                        EXAM_SETTING
                                    WHERE
                                        EXAM_SETTING_ID AND IS_ACTIVE = 1
                                            AND ACADEMIC_YEAR = ?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.FetchRegularExamStudentByCourseIdForBundling:
                    {
                        query = @"SELECT 
                                STUDENT_ID, COURSE_ID, STATUS, EXAM_SETTING_ID
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID AND COURSE_ID = ?COURSE_ID
                                    AND STATUS = 'R';";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearExamStudentByCourseIdForBundling:
                    {
                        query = @"SELECT 
                                STUDENT_ID, COURSE_ID, STATUS, EXAM_SETTING_ID
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID AND COURSE_ID = ?COURSE_ID
                                    AND STATUS != 'R';";
                        break;
                    }
                case ExaminationSQLCommands.FetchBundleSheetStudents:
                    {
                        query = @"SELECT 
                                SP.REGISTER_NO,
                                CR.COURSE_CODE,
                                MA.COURSE_ID,
                                CR.COURSE_TITLE,
                                MA.DUMMY_NO
                            FROM
                                EXAM_EVALUATION_STUDENT_MARK AS MA
                                    INNER JOIN
                                stu_personal_info AS SP ON SP.STUDENT_ID = MA.STUDENT_ID
                                    INNER JOIN
                                cp_course_root AS CR ON CR.COURSE_ROOT_ID = MA.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStaffBundlesAssignByCourseId:
                    {
                        query = @"SELECT 
                                    BD.EXAM_BUNDLE_ID,
                                    BD.EXAM_BUNDLE_NO,
                                    BD.POCKET_NO,
                                    BD.POCKET_CATEGORY,
                                    BD.COURSE_ID,
                                    BD.IS_ARREAR,
                                    BD.EXAM_SETTING_ID,
                                    MA.EXAM_EVALUATOR_STAFF_ID,
                                    ST.STAFF_CODE,
                                    ST.`NAME`
                                FROM
                                    EXAM_BUNDLES AS BD
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = BD.COURSE_ID
                                        LEFT JOIN
                                    EXAM_EVALUATION_STUDENT_MARK AS MA ON MA.BUNDLE_ID = BD.EXAM_BUNDLE_ID
                                        LEFT JOIN
                                    EXAM_EVALUATOR_STAFF_INFO AS ST ON ST.EXAM_EVALUATOR_STAFF_ID = MA.EXAM_EVALUATOR_STAFF_ID
                                WHERE
                                    BD.COURSE_ID IN (?COURSE_ID)
                                        AND BD.ACADEMIC_YEAR = ?AC_YEAR
                                GROUP BY BD.EXAM_BUNDLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteBundleStaffAssignedByBundleId:
                    {
                        query = @"UPDATE EXAM_EVALUATION_STUDENT_MARK SET EXAM_EVALUATOR_STAFF_ID=NULL WHERE BUNDLE_ID=?BUNDLE_ID AND EXAM_EV_STU_MARK_ID!=0;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStaffBundlesAssignByCourseIdForAssign:
                    {
                        query = @"SELECT 
                                BD.EXAM_BUNDLE_ID,
                                BD.EXAM_BUNDLE_NO,
                                BD.POCKET_NO,
                                BD.POCKET_CATEGORY,
                                BD.COURSE_ID,
                                BD.IS_ARREAR,
                                BD.EXAM_SETTING_ID,
                                MA.EXAM_EVALUATOR_STAFF_ID,
                                ST.STAFF_CODE,
                                ST.`NAME`
                            FROM
                                EXAM_BUNDLES AS BD
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = BD.COURSE_ID
                                    LEFT JOIN
                                EXAM_EVALUATION_COURSE_SETTING AS ECT ON ECT.EVALUATION_COURSE_SETTING_ID = ECT.EVALUATION_COURSE_SETTING_ID
                                    AND ECT.EVALUATION = ?EVALUATION
                                    LEFT JOIN                                    
                                EXAM_EVALUATION_STUDENT_MARK AS MA ON MA.BUNDLE_ID = BD.EXAM_BUNDLE_ID
                                    LEFT JOIN
                                EXAM_EVALUATOR_STAFF_INFO AS ST ON ST.EXAM_EVALUATOR_STAFF_ID = MA.EXAM_EVALUATOR_STAFF_ID
                            WHERE
                                BD.COURSE_ID IN (?COURSE_ID)
                                    AND BD.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                    AND BD.ACADEMIC_YEAR = ?AC_YEAR                                   
                            GROUP BY BD.EXAM_BUNDLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationStudenByEvaluatorAndBundlesAndCourseAndDate:
                    {
                        query = @"SELECT 
                                SM.EXAM_EV_STU_MARK_ID,
                                SM.EVALUATION_COURSE_SETTING_ID,
                                SM.STUDENT_ID,
                                SM.EXAM_EVALUATOR_STAFF_ID,
                                SM.COURSE_ID,
                                CS.EVALUATION,
                                SM.EVALUATION_MARK,
                                CR.COURSE_CODE,
                                CR.COURSE_TITLE,
                                CR.INTERNAL,
                                CR.EXTERNAL,
                                CR.TOTAL AS MAX_MARK,
                                CR.PROGRAMME_LEVEL_ID,
                                CR.EXAM_MARK,
                                SP.REGISTER_NO,
                                ST.ROLE,
                                BD.EXAM_BUNDLE_NO,
                                BD.POCKET_NO,
                                BD.POCKET_CATEGORY,
                                BD.IS_ARREAR,
                                BDS.DUMMY_NO,
                                SM.BUNDLE_ID,
                                SM.BUNDLE_STUDENT_ID
                            FROM
                                EXAM_EVALUATION_STUDENT_MARK AS SM
                                    INNER JOIN
                                EXAM_EVALUATION_COURSE_SETTING AS CS ON CS.EVALUATION_COURSE_SETTING_ID = SM.EVALUATION_COURSE_SETTING_ID
                                    INNER JOIN
                                EXAM_EVALUATOR_STAFF_INFO AS ST ON ST.EXAM_EVALUATOR_STAFF_ID = SM.EXAM_EVALUATOR_STAFF_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = SM.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SM.STUDENT_ID
                                    INNER JOIN
                                EXAM_BUNDLES AS BD ON BD.EXAM_BUNDLE_ID = SM.BUNDLE_ID
                                    AND BD.COURSE_ID = ?COURSE_ID
                                    INNER JOIN
                                EXAM_BUNDLE_STUDENTS AS BDS ON BDS.BUNDLE_ID = BD.EXAM_BUNDLE_ID
                                    AND SM.STUDENT_ID = BDS.STUDENT_ID
                                    INNER JOIN
                                EXAM_SETTING AS S ON S.EXAM_SETTING_ID = CS.EXAM_SETTING_ID
                            WHERE
                                SM.EXAM_EVALUATOR_STAFF_ID = ?EXAM_EVALUATOR_STAFF_ID
                                    AND CS.EVALUATION_DATE = ?EVALUATION_DATE
                                    AND SM.COURSE_ID = ?COURSE_ID
                                    AND SM.IS_DELETED != 1
                                    AND SM.EVALUATION = ?EVALUATION
                            ORDER BY BDS.BUNDLE_ID , BDS.DUMMY_NO;";
                        break;
                    }
                case ExaminationSQLCommands.SaveStudentsAssignForStaffByBundles:
                    {
                        query = @"INSERT INTO  EXAM_EVALUATION_STUDENT_MARK (EVALUATION_COURSE_SETTING_ID, STUDENT_ID, EXAM_EVALUATOR_STAFF_ID, COURSE_ID,EVALUATION, IS_ACTIVE, ACDEMIC_YEAR,BUNDLE_STUDENT_ID, BUNDLE_ID )
                                        SELECT
                                            '?EVALUATION_COURSE_SETTING_ID' AS EVALUATION_COURSE_SETTING_ID,
                                            BDS.STUDENT_ID,
                                            '?EXAM_EVALUATOR_STAFF_ID' AS EXAM_EVALUATOR_STAFF_ID,
                                            BD.COURSE_ID,          
                                            '?EVALUATION' AS EVALUATION                                  
                                            1 AS IS_ACTIVE,
                                            BD.ACADEMIC_YEAR,
                                            BDS.EXAM_BUNDLE_STUDENT_ID AS BUNDLE_STUDENT_ID,
                                            BDS.BUNDLE_ID
                                        FROM
                                            EXAM_BUNDLE_STUDENTS AS BDS
                                                INNER JOIN
                                            EXAM_BUNDLES AS BD ON BD.EXAM_BUNDLE_ID = BDS.BUNDLE_ID
                                        WHERE
                                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND COURSE_ID = ?COURSE_ID
 
                                                 AND EXAM_BUNDLE_ID =?EXAM_BUNDLE_ID
 
                                                 AND BD.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSeatingAttendanceForEntry:
                    {
                        query = @"SELECT 
                                EXAM_ATTENDANCE_ID,
                                STA.STUDENT_ID,
                                STA.COURSE_ID,
                                ST.ROW_NO,                                
                                ST.COLUMN_NO,
                                CR.COURSE_CODE,
                                I.STAFF_ID,
                                DATE_FORMAT(STA.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,                               
                                STA.EXAM_TYPE,
                                STA.EXAM_SESSION_ID,
                                STA.EXAM_SETTING_ID,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                ST.ROOM_ID
                            FROM
                                EXAM_SEATING_ALLOTEMENT AS STA
                                    INNER JOIN
                                EXAM_SEATINGS AS ST ON ST.SEATING_ID = STA.SEATING_ID
                                    AND ST.IS_DELETED != 1
                                    INNER JOIN CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID=STA.COURSE_ID
                                    INNER JOIN 
                                EXAM_SEATING_INVIGILATOR AS I ON I.EXAM_DATE = STA.EXAM_DATE
                                    AND I.ROOM_ID = ST.ROOM_ID
                                    AND I.EXAM_SESSION_ID = STA.EXAM_SESSION_ID
                                    AND I.EXAM_SETTING_ID = STA.EXAM_SETTING_ID
                                    AND I.EXAM_TYPE = STA.EXAM_TYPE
                                    AND I.IS_DELETED != 1
                                    AND I.STAFF_ID = ?STAFF_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = STA.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                                    LEFT JOIN
                                EXAM_SEATING_ATTENDANCE AS EATT ON EATT.STUDENT_ID = STA.STUDENT_ID
                                    AND EATT.COURSE_ID = STA.COURSE_ID
                                    AND EATT.STAFF_ID = I.STAFF_ID
                                    AND EATT.EXAM_DATE = STA.EXAM_DATE
                                    AND EATT.EXAM_SESSION_ID = STA.EXAM_SESSION_ID
                                    AND EATT.EXAM_SETTING_ID = STA.EXAM_SETTING_ID
                                    AND EATT.EXAM_TYPE = STA.EXAM_TYPE
                                    AND EATT.IS_DELETED!=1
                            WHERE
                                STA.EXAM_DATE = CURDATE()
                                    AND STA.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND STA.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                    AND STA.EXAM_TYPE = ?EXAM_TYPE ORDER BY ST.SEATING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSeatingByRoomId:
                    {
                        query = @"SELECT 
                                SEATING_ID,
                                ST.ROOM_ID,
                                COLUMN_NO,
                                ROW_NO,
                                SEAT_CODE,
                                SEAT_POSITION,
                                ST.EXAM_TYPE,
                                R.ROOM_NO,
                                R.`COLUMN`,
                                R.`ROW`,
                                R.SPACE_COLUMN,
                                BL.BLOCK_NAME,
                                BL.BLOCK_CODE
                            FROM
                                EXAM_SEATINGS AS ST
                                INNER JOIN
                                SUP_ROOM AS R ON R.ROOM_ID=ST.ROOM_ID
                                INNER JOIN
                                SUP_COLLEGE_BLOCK AS BL ON BL.COLLEGE_BLOCK_ID=R.COLLEGE_BLOCK_ID
                            WHERE
                                ST.EXAM_TYPE = ?EXAM_TYPE AND ST.ROOM_ID = ?ROOM_ID;";
                        break;
                    }
                case ExaminationSQLCommands.InsertExamSeatingAttendanceAbsentees:
                    {
                        query = @"INSERT INTO EXAM_SEATING_ATTENDANCE (STUDENT_ID, COURSE_ID, STAFF_ID, EXAM_DATE, EXAM_TYPE, EXAM_SESSION_ID, EXAM_SETTING_ID,ACADEMIC_YEAR) VALUES 
                                (?STUDENT_ID, ?COURSE_ID, ?STAFF_ID, ?EXAM_DATE, ?EXAM_TYPE, ?EXAM_SESSION_ID, ?EXAM_SETTING_ID,?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamSeatingAttendanceAbsentees:
                    {
                        query = @"UPDATE EXAM_SEATING_ATTENDANCE SET IS_DELETED=1 WHERE  EXAM_ATTENDANCE_ID=?EXAM_ATTENDANCE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ListExamMalpracticeStudents:
                    {
                        query = @"SELECT 
                                ML.EXM_MALPRACTICE_STU_ID,
                                SP.STUDENT_ID,
                                ML.EXAM_TYPE,
                                ET.EXAM_TYPE_NAME,
                                ML.EXAM_SETTING_ID,
                                DATE_FORMAT(ML.MALPRACTICE_DATE,'%d/%m/%Y') AS MALPRACTICE_DATE,
                                ML.DESCRIPTION,
                                ML.CURRENT_SEMESTER,
                                ML.INTERVAL_SEMESTER,
                                SP.REGISTER_NO,
                                SP.FIRST_NAME,
                                SP.ROLL_NO,
                                PG.PROGRAMME_GROUP_ID,
                                CP.PROGRAMME_NAME
                            FROM
                                EXAM_MALPRACTICE_STUDENTS AS ML
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ML.STUDENT_ID    
									INNER JOIN
								CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID=SP.PROGRAM_ID
									INNER JOIN
								CP_PROGRAMME AS CP ON CP.PROGRAMME_ID=PG.PROGRAMME_ID
									INNER JOIN
								SUP_EXAM_TYPE AS ET ON ET.EXAM_TYPE=ML.EXAM_TYPE
                            WHERE
                                ML.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamMalpracticeStudent:
                    {
                        query = @"UPDATE EXAM_MALPRACTICE_STUDENTS SET IS_DELETED=1 WHERE EXM_MALPRACTICE_STU_ID=?EXM_MALPRACTICE_STU_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamMalpracticeStudentById:
                    {
                        query = @"SELECT 
                                ML.EXM_MALPRACTICE_STU_ID,
                                SP.STUDENT_ID,
                                ML.EXAM_TYPE,
                                ML.EXAM_SETTING_ID,
                                DATE_FORMAT(ML.MALPRACTICE_DATE,'%d/%m/%Y') AS MALPRACTICE_DATE, 
                                ML.DESCRIPTION,
                                ML.CURRENT_SEMESTER,
                                ML.INTERVAL_SEMESTER,
                                SP.REGISTER_NO,
                                SP.FIRST_NAME,
                                SP.ROLL_NO
                            FROM
                                EXAM_MALPRACTICE_STUDENTS AS ML
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ML.STUDENT_ID 
                            WHERE
                                ML.IS_DELETED != 1  AND EXM_MALPRACTICE_STU_ID =?EXM_MALPRACTICE_STU_ID;";
                        break;
                    }
                case ExaminationSQLCommands.InsertExamMalpracticeStudents:
                    {
                        query = @"INSERT INTO EXAM_MALPRACTICE_STUDENTS(STUDENT_ID, EXAM_TYPE, EXAM_SETTING_ID, MALPRACTICE_DATE,PROGRAMME_GROUP_ID,BATCH, DESCRIPTION, CURRENT_SEMESTER, INTERVAL_SEMESTER, ACADEMIC_YEAR)VALUES
                                (?STUDENT_ID, ?EXAM_TYPE, ?EXAM_SETTING_ID, ?MALPRACTICE_DATE, ?PROGRAMME_GROUP_ID,?BATCH, ?DESCRIPTION, ?CURRENT_SEMESTER, ?INTERVAL_SEMESTER, ?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamMalpracticeStudents:
                    {
                        query = @"UPDATE EXAM_MALPRACTICE_STUDENTS SET MALPRACTICE_DATE=?MALPRACTICE_DATE,DESCRIPTION=?DESCRIPTION,CURRENT_SEMESTER=?CURRENT_SEMESTER,INTERVAL_SEMESTER=?INTERVAL_SEMESTER WHERE EXM_MALPRACTICE_STU_ID=?EXM_MALPRACTICE_STU_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CheckExamTTProgrammeLevelExist:
                    {
                        query = @"SELECT 
                                    DATE_FORMAT(EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,EXAM_SESSION_ID
                                FROM
                                    EXAM_TIMETABLE AS TT
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = TT.COURSE_ID AND CR.SEMESTER_ID IN (?SEMESTER_ID)
                                        AND CR.PROGRAMME_LEVEL_ID = ?PROGRAMME_LEVEL_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID GROUP BY EXAM_DATE,EXAM_SESSION_ID ORDER BY EXAM_DATE DESC;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupCourseByCourseOrderProgrameLevelAndYearForAutoamticTT:
                    {
                        query = @"SELECT 
                                    COURSE_ID, COURSE_CODE
                                FROM
                                    CP_COURSE_PATTERN AS CP
                                        INNER JOIN
                                    CP_COURSE_STRUCTURE AS CS ON CS.COURSE_STRUCTURE_ID = CP.COURSE_STRUCTURE_ID
                                        AND CS.PROGRAMME_LEVEL = ?PROGRAMME_LEVEL
                                        AND CS.PROGRAMME_YEAR = ?PROGRAMME_YEAR
                                        AND CS.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CP.COURSE_ID
                                        AND CR.SEMESTER_ID IN (1,2,4,6)
                                        AND CR.IS_DELETED != 1
                                WHERE
                                    cp.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CP.IS_DELETED != 1
                                        AND CP.COURSE_ORDER = ?COURSE_ORDER
                                GROUP BY COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEquivalentCourseGroupByCourseId:
                    {
                        query = @"SELECT 
                                EQUIVALENT_COURSE_ID, COURSE_ID, EQUIVALENT_COURSE, EQUIVALENT_TYPE, CR.COURSE_CODE
                                FROM
                                    CP_EQUIVALENT_COURSE AS EQ
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EQ.COURSE_ID
                            WHERE
                                EQ.EQUIVALENT_COURSE IN (?EQUIVALENT_COURSE)
                                    AND EQ.EQUIVALENT_TYPE = ?EQUIVALENT_TYPE
                                    AND EQ.IS_DELETED!=1
                            GROUP BY EQ.COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllExamQuestionsByCourseId:
                    {
                        query = @"SELECT 
                                EQ.QUESTION_ID,
                                EQ.QUESTION,
                                EQ.COURSE_ID,
                                EQ.REPEAT_YEAR,
                                EQ.NOT_REPEAT_YEAR,
                                EQ.IS_REPEAT,
                                EQ.SECTION_ID,
                                EQ.QUESTION_LEVEL,
                                EQ.UNIT_ID,
                                EQ.ACADEMIC_YEAR,
                                EQ.EITHER_OR_QUESTION
                                
                            FROM
                                EXAM_QUESTIONS AS EQ
                                    INNER JOIN
                                SUP_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID = EQ.QUESTION_LEVEL
                                    INNER JOIN
                                SUP_SECTION AS SS ON SS.SECTION_ID = EQ.SECTION_ID
                            WHERE
                                EQ.COURSE_ID = ?COURSE_ID
                                    AND EQ.QUESTION_LEVEL =?QUESTION_LEVEL_ID
                                    AND EQ.SECTION_ID =?SECTION_ID AND EQ.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamQuestionpapersBySettingandCourseId:
                    {
                        query = @"SELECT 
                                EQP.QUESTION_PAPER_ID,
                                EQP.COURSE_ID,
                                EQ.QUESTION_ID,
                                EQ.QUESTION,
                                EQ.REPEAT_YEAR,
                                EQ.NOT_REPEAT_YEAR,
                                EQ.IS_REPEAT,
                                EQ.SECTION_ID,
                                EQ.QUESTION_LEVEL,
                                EQ.UNIT_ID,
                                EQ.ACADEMIC_YEAR,
                                EQ.EITHER_OR_QUESTION
                            FROM
                                EXAM_QUESTION_PAPER AS EQP
                                    INNER JOIN
                                EXAM_QUESTIONS AS EQ ON EQP.QUESTION_ID = EQ.QUESTION_ID
                                    INNER JOIN
                                SUP_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID = EQ.QUESTION_LEVEL
                                    INNER JOIN
                                SUP_SECTION AS SS ON SS.SECTION_ID = EQ.SECTION_ID
                            WHERE
                                EQP.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EQP.COURSE_ID = ?COURSE_ID
                                    AND EQP.QUESTION_LEVEL_ID =?QUESTION_LEVEL_ID AND EQP.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamQuestionpapersByCourseId:
                    {
                        query = @"SELECT 
                                EQP.QUESTION_PAPER_ID,
                                EQP.COURSE_ID,
                                EQ.QUESTION_ID,
                                EQ.QUESTION,
                                EQ.REPEAT_YEAR,
                                EQ.NOT_REPEAT_YEAR,
                                EQ.IS_REPEAT,
                                EQ.SECTION_ID,
                                EQ.QUESTION_LEVEL,
                                EQ.UNIT_ID,
                                EQ.ACADEMIC_YEAR,
                                EQ.EITHER_OR_QUESTION,
                                EQP.EXAM_SETTING_ID
                            FROM
                                EXAM_QUESTION_PAPER AS EQP
                                    INNER JOIN
                                EXAM_QUESTIONS AS EQ ON EQP.QUESTION_ID = EQ.QUESTION_ID
                                    INNER JOIN
                                SUP_QUESTION_LEVEL AS QL ON QL.QUESTION_LEVEL_ID = EQ.QUESTION_LEVEL
                                    INNER JOIN
                                SUP_SECTION AS SS ON SS.SECTION_ID = EQ.SECTION_ID
                            WHERE
                                EQP.COURSE_ID IN(?COURSE_ID)
                                    AND EQP.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamQuestionsPaper:
                    {
                        query = @"INSERT INTO 
                                    EXAM_QUESTION_PAPER
                                    (COURSE_ID,QUESTION_LEVEL_ID,
                                    QUESTION_ID,EXAM_SETTING_ID) 
                                    VALUES";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamQuestionsPaper:
                    {
                        query = @"UPDATE EXAM_QUESTION_PAPER 
                                    SET 
                                        COURSE_ID =?COURSE_ID,
                                        QUESTION_LEVEL_ID =?QUESTION_LEVEL_ID,
                                        QUESTION_ID =?QUESTION_ID,
                                        EXAM_SETTING_ID =?EXAM_SETTING_ID
                                    WHERE
                                        QUESTION_PAPER_ID =?QUESTION_PAPER_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMarkSheetRequestedByStudentId:
                    {
                        query = @"SELECT 
                                MSD.MARKSHEET_DISTRIBUTION_ID,
                                MSD.STUDENT_ID,
                                MSD.STATUS,
                                MSD.REASON,
                                IFNULL(S.STATUS_NAME, 'Pending') AS STATUS_NAME,
                                SS.SEMESTER_NAME,
                                DATE_FORMAT(REQUEST_DATE, '%Y/%m/%d') AS REQUEST_DATE,
                                DATE_FORMAT(APPROVED_DATE, '%Y/%m/%d') AS APPROVED_DATE
                            FROM
                                CEO_MARKSHEET_DISTRIBUTION AS MSD
                                    INNER JOIN
                                SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = MSD.SEMESTER_ID
                                    LEFT JOIN
                                SUP_STATUS AS S ON S.STATUS_ID = MSD.STATUS
                            WHERE
                                MSD.IS_DELETED != 1 AND MSD.STUDENT_ID=?STUDENT_ID
                                    AND MSD.ACADEMIC_YEAR = (SELECT max(ACADEMIC_YEAR) AS ACADEMIC_YEAR FROM STU_CLASS WHERE STUDENT_ID=?STUDENT_ID AND IS_DELETED!=1);";
                        break;
                    }
                case ExaminationSQLCommands.FetchMarkSheetRquestInfoById:
                    {
                        query = @"SELECT 
                                MSD.MARKSHEET_DISTRIBUTION_ID,
                                MSD.STUDENT_ID,
                                MSD.STATUS,
                                MSD.REASON,
                                IFNULL(S.STATUS_NAME, 'Pending') AS STATUS_NAME,
                                SS.SEMESTER_NAME,
                                DATE_FORMAT(REQUEST_DATE, '%Y/%m/%d') AS REQUEST_DATE,
                                DATE_FORMAT(APPROVED_DATE, '%Y/%m/%d') AS APPROVED_DATE,
                                MSD.SEMESTER_ID
                            FROM
                                CEO_MARKSHEET_DISTRIBUTION AS MSD
                                    INNER JOIN
                                SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = MSD.SEMESTER_ID
                                    LEFT JOIN
                                SUP_STATUS AS S ON S.STATUS_ID = MSD.STATUS
                            WHERE
                                MSD.IS_DELETED != 1
                                    AND MARKSHEET_DISTRIBUTION_ID = ?MARKSHEET_DISTRIBUTION_ID
                                    AND MSD.ACADEMIC_YEAR =2019;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateMarkSheetRequest:
                    {
                        query = @"UPDATE CEO_MARKSHEET_DISTRIBUTION 
                                SET 
                                    SEMESTER_ID = ?SEMESTER_ID,
                                    REASON = ?REASON
                                WHERE
                                    MARKSHEET_DISTRIBUTION_ID = ?MARKSHEET_DISTRIBUTION_ID;";
                        break;
                    }
              
                case ExaminationSQLCommands.SaveMarkSheetRequest:
                    {
                        query = @"INSERT INTO 
                                    CEO_MARKSHEET_DISTRIBUTION(
                                    STUDENT_ID,SEMESTER_ID,REASON,ACADEMIC_YEAR) 
                                    VALUES(?STUDENT_ID,?SEMESTER_ID,?REASON,(SELECT max(ACADEMIC_YEAR) AS ACADEMIC_YEAR FROM STU_CLASS WHERE STUDENT_ID=?STUDENT_ID AND IS_DELETED!=1));";
                        break;
                    }
                case ExaminationSQLCommands.DeleteMarkSheetRequested:
                    {
                        query = @"UPDATE CEO_MARKSHEET_DISTRIBUTION 
                                    SET 
                                        IS_DELETED = 1
                                    WHERE
                                        MARKSHEET_DISTRIBUTION_ID = ?MARKSHEET_DISTRIBUTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMarkSheetRequestedList:
                    {
                        query = @"SELECT 
                                SP.FIRST_NAME,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CC.CLASS_ID,
                                CC.CLASS_NAME,
                                MSD.MARKSHEET_DISTRIBUTION_ID,
                                MSD.STUDENT_ID,
                                MSD.REASON,
                                MSD.STATUS,
                                IFNULL(S.STATUS_NAME, 'Pending') AS STATUS_NAME,
                                SS.SEMESTER_NAME,
                                DATE_FORMAT(MSD.REQUEST_DATE, '%Y/%m/%d') AS REQUEST_DATE,
                                DATE_FORMAT(MSD.APPROVED_DATE, '%Y/%m/%d') AS APPROVED_DATE,
                                MSD.EXAM_SETTING_ID
                            FROM
                                CEO_MARKSHEET_DISTRIBUTION AS MSD
                                    INNER JOIN
                                stu_class AS SC ON SC.STUDENT_ID = MSD.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR =2019
                                    INNER JOIN
                                cp_classes AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    INNER JOIN
                                SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = MSD.SEMESTER_ID
                                    LEFT JOIN
                                SUP_STATUS AS S ON S.STATUS_ID = MSD.STATUS
                            WHERE
                                MSD.IS_DELETED != 1
                                    AND MSD.ACADEMIC_YEAR =2019 AND SC.PROGRAMME_GROUP_ID IN (?PROGRAMME_GROUP_ID);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateMarkSheetRequestedStatus:
                    {
                        query = @"UPDATE CEO_MARKSHEET_DISTRIBUTION 
                                SET 
                                    EXAM_SETTING_ID =?EXAM_SETTING_ID,
                                    STATUS =?STATUS,
                                    APPROVED_DATE=?APPROVED_DATE,
                                    APPROVER_ID=?APPROVER_ID
                                WHERE
                                    MARKSHEET_DISTRIBUTION_ID = ?MARKSHEET_DISTRIBUTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAcademicInfoBystudentId:
                    {
                        query = @"SELECT 
                                SC.STUDENT_ID,
                                SC.PROGRAMME_GROUP_ID AS PROGRAMME,
                                SC.BATCH,
                                C.CLASS_YEAR,
                                CPG.APPTYPE_ID,
                                SC.ACADEMIC_YEAR
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                cp_programme_group AS CPG ON CPG.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                            WHERE
                                STUDENT_ID =?STUDENT_ID
                                    AND SC.ACADEMIC_YEAR=(SELECT max(ACADEMIC_YEAR) AS ACADEMIC_YEAR FROM STU_CLASS WHERE STUDENT_ID=?STUDENT_ID AND IS_DELETED!=1)
                                    AND SC.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMarkSheetrequestapprovedByStudentId:
                    {
                        query = @"SELECT 
