                            IF(QQ.ANSWER_ID = OP.OPTION_ID,
                                OP.OPTION,
                                '') AS ANSWER
                        FROM
                            EXAM_EITHER_OR_QUESTIONS AS QQ
                                INNER JOIN
                            EXAM_EITHER_OR_OPTIONS AS OP ON OP.QUIZ_ID = QQ.QUIZ_ID
                                INNER JOIN
                            exam_question_pattern_section AS EQPS ON EQPS.PATTERN_SECTION_ID = QQ.PATTERN_SECTION_ID 
                        WHERE
                            QQ.QUIZ_ID = ?QUIZ_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchAllExamQuestionsByExamsettingandsetId:
                    {
                        query = @"SELECT 
                                    QQ.QUIZ_ID,
                                    UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                    ' ',
                                                    IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                    QQ.QUESTION,
                                    QT.QUESTION_TYPE,
                                    QT.QUESTION_TYPE_ID,
                                    EOP.OPTION_ID,
                                    EOP.OPTION,
                                    '' AS ANSWER,
                                    ES.SECTION_ID,
                                    ES.SECTION_NAME,
                                    QQ.ANSWER_ID
                                FROM
                                    EXAM_OBJECTIVE_QUESTIONS AS QQ
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QQ.COURSE_ID
                                        INNER JOIN
                                    ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QQ.ACADEMIC_YEAR
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS QP ON QP.PATTERN_SECTION_ID = QQ.PATTERN_SECTION_ID
                                        INNER JOIN
                                    EXAM_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID = QP.QUESTION_TYPE
                                        INNER JOIN
                                    EXAM_OBJECTIVE_OPTIONS AS EOP ON EOP.QUIZ_ID = QQ.QUIZ_ID
                                    INNER JOIN EXAM_SECTION AS ES ON ES.SECTION_ID=QP.SECTION_ID
                                WHERE
                                    QQ.ACADEMIC_YEAR = ?AC_YEAR
                                        AND QQ.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                        AND QQ.COURSE_ID = ?COURSE_ID
                                        AND QQ.SET_ID = ?SET_ID
                                        AND QQ.IS_DELETED != 1 
                                UNION ALL SELECT 
                                    QM.QUIZ_ID,
                                    UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                    ' ',
                                                    IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                    QM.QUESTION,
                                    QT.QUESTION_TYPE,
                                    QT.QUESTION_TYPE_ID,
                                    EMFO.OPTION_ID,
                                    EMFO.OPTION,
                                    EMFO.ANSWER,
                                    ES.SECTION_ID,
                                    ES.SECTION_NAME,
                                    QM.ANSWER_ID
                                FROM
                                    EXAM_MATCH_THE_FOLLOWING_QUESTIONS AS QM
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QM.COURSE_ID
                                        INNER JOIN
                                    ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QM.ACADEMIC_YEAR
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS QP ON QP.PATTERN_SECTION_ID = QM.PATTERN_SECTION_ID
                                        INNER JOIN
                                    EXAM_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID = QP.QUESTION_TYPE
                                        INNER JOIN
                                    exam_match_the_following_options AS EMFO ON EMFO.QUIZ_ID = QM.QUIZ_ID
                                    INNER JOIN EXAM_SECTION AS ES ON ES.SECTION_ID=QP.SECTION_ID
                                WHERE
                                    QM.ACADEMIC_YEAR = ?AC_YEAR
                                        AND QM.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                        AND QM.COURSE_ID = ?COURSE_ID
                                        AND QM.SET_ID = ?SET_ID
                                        AND QM.IS_DELETED != 1 
                                UNION ALL SELECT 
                                    QF.QUIZ_ID,
                                    UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                    ' ',
                                                    IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                    QF.QUESTION,
                                    QT.QUESTION_TYPE,
                                    QT.QUESTION_TYPE_ID,
                                    EFBO.OPTION_ID,
                                    EFBO.OPTION,
                                    '' AS ANSWER,
                                    ES.SECTION_ID,
                                    ES.SECTION_NAME,
                                    QF.ANSWER_ID
                                FROM
                                    EXAM_FILL_IN_BLANK_QUESTIONS AS QF
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QF.COURSE_ID
                                        INNER JOIN
                                    ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QF.ACADEMIC_YEAR
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS QP ON QP.PATTERN_SECTION_ID = QF.PATTERN_SECTION_ID
                                        INNER JOIN
                                    EXAM_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID = QP.QUESTION_TYPE
                                        INNER JOIN
                                    EXAM_FILL_IN_BLANK_OPTIONS AS EFBO ON EFBO.QUIZ_ID = QF.QUIZ_ID
                                    INNER JOIN EXAM_SECTION AS ES ON ES.SECTION_ID=QP.SECTION_ID
                                WHERE
                                    QF.ACADEMIC_YEAR = ?AC_YEAR
                                        AND QF.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                        AND QF.COURSE_ID = ?COURSE_ID
                                        AND QF.SET_ID = ?SET_ID
                                        AND QF.IS_DELETED != 1 
                                UNION ALL SELECT 
                                    QE.QUIZ_ID,
                                    UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                    ' ',
                                                    IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                    QE.QUESTION,
                                    QT.QUESTION_TYPE,
                                    QT.QUESTION_TYPE_ID,
                                    EEP.OPTION_ID,
                                    EEP.OPTION,
                                    '' AS ANSWER,
                                     ES.SECTION_ID,
                                    ES.SECTION_NAME,
                                    QE.ANSWER_ID
                                FROM
                                    EXAM_EITHER_OR_QUESTIONS AS QE
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QE.COURSE_ID
                                        INNER JOIN
                                    ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QE.ACADEMIC_YEAR
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS QP ON QP.PATTERN_SECTION_ID = QE.PATTERN_SECTION_ID
                                        INNER JOIN
                                    EXAM_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID = QP.QUESTION_TYPE
                                        LEFT JOIN
                                    EXAM_EITHER_OR_OPTIONS AS EEP ON EEP.QUIZ_ID = QE.QUIZ_ID
                                    INNER JOIN EXAM_SECTION AS ES ON ES.SECTION_ID=QP.SECTION_ID
                                WHERE
                                    QE.ACADEMIC_YEAR = ?AC_YEAR
                                        AND QE.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                        AND QE.COURSE_ID = ?COURSE_ID
                                        AND QE.SET_ID = ?SET_ID
                                        AND QE.IS_DELETED != 1
                                     UNION ALL SELECT                                      
                                    QE.QUIZ_ID,
                                    UPPER(CONCAT(IFNULL(CCR.COURSE_TITLE, ''),
                                                    ' ',
                                                    IFNULL(CCR.COURSE_CODE, ''))) AS 'COURSE_ID',
                                    QE.QUESTION,
                                    QT.QUESTION_TYPE,
                                    QT.QUESTION_TYPE_ID,
                                    '' AS OPTION_ID,
                                    '' AS `OPTION`,
                                    '' AS ANSWER,
                                    ES.SECTION_ID,
                                    ES.SECTION_NAME,
                                    QE.ANSWER_ID
                                FROM
                                    EXAM_CHOICE_BASED_QUESTIONS AS QE
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = QE.COURSE_ID
                                        INNER JOIN
                                    ACADEMIC_YEAR AS AC ON AC.AC_YEAR = QE.ACADEMIC_YEAR
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS QP ON QP.PATTERN_SECTION_ID = QE.PATTERN_SECTION_ID
                                        INNER JOIN
                                    EXAM_QUESTION_TYPE AS QT ON QT.QUESTION_TYPE_ID = QP.QUESTION_TYPE
                                        INNER JOIN
                                    EXAM_SECTION AS ES ON ES.SECTION_ID = QP.SECTION_ID
                                WHERE
                                    QE.ACADEMIC_YEAR = ?AC_YEAR
                                        AND QE.EXAM_SETTING_ID IN (?EXAM_SETTING_ID)
                                        AND QE.COURSE_ID = ?COURSE_ID
                                        AND QE.SET_ID = ?SET_ID
                                        AND QE.IS_DELETED != 1;";
                        break;
                    }
                #endregion

                case ExaminationSQLCommands.FetchCIAMarksByStudentAndAcademicYear:
                    {
                        query = @"SELECT
                                    IF(SUM(IFNULL(INSTANT,0))!=0,SUM(IFNULL(INSTANT,0)),SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
									CLASS_NAME,
                                    UPPER(NAME) AS 'NAME',
                                    COURSE_ID,
                                    COURSE_CODE,
                                    CIA_GROUP_MARK_CHECKING_ID,
                                    STATUS,
                                    COURSE_GROUP_MARK,
								    COURSE_GROUP_ID,
									SEMESTER_ID
                                FROM
                                    (SELECT
                                        ((SUM(IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)) / SUM(MAX_MARK)) * (SELECT
                                                    GROUP_MARK
                                                FROM
                                                    CP_COURSE_TYPE_GROUP AS CTG
                                                WHERE
                                                    CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                                LIMIT 1)) AS CUMULATIVE,
											IF(CIA.COMPONENT='INSTANT',CGM.COURSE_GROUP_MARK,0) AS INSTANT,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO,
                                            SP.REGISTER_NO,
                                            CC.CLASS_NAME,
                                            SC.COURSE_ID,
                                            CCR.COURSE_CODE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME',
                                            CMC.CIA_GROUP_MARK_CHECKING_ID,
                                            CMC.STATUS,
                                            CGM.COURSE_GROUP_MARK,
                                            CGM.COURSE_GROUP_ID,
                                            CGM.SEMESTER_ID
                                    FROM
                                     STU_COURSE_INFO AS SC
										INNER JOIN
									CP_CLASSES AS CC ON CC.CLASS_ID=SC.CLASS_ID
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID = SC.S_CLASS_ID
                                       
										INNER JOIN
									CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
										INNER JOIN
									CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
										INNER JOIN
									CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
										INNER JOIN 
                                     SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID=CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED!=1
										INNER JOIN 
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID 
										INNER JOIN 
                                    CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = SC.COURSE_ID
										AND CGM.COURSE_GROUP_ID=CGC.CIA_GROUP_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                        
                                        LEFT JOIN
                                        
                                        cia_group_mark_checking AS CMC ON CMC.COURSE_ID=CGM.COURSE_ID
                                        AND CMC.COURSE_GROUP_ID=CGM.COURSE_GROUP_ID
                                        AND CMC.STUDENT_ID=CGM.STUDENT_ID
                                        AND CMC.ACADEMIC_YEAR=?AC_YEAR
                                    WHERE
                                       SC.STUDENT_ID=?STUDENT_ID
									-- AND SC.COURSE_ID=C.COURSE_ID
                                            AND SC.ACADEMIC_YEAR =?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            AND SP.IS_DELETED != 1
                                    GROUP BY SP.STUDENT_ID ,SC.COURSE_ID, CGC.CIA_GROUP_ID) AS T
                                GROUP BY ROLL_NO ,COURSE_ID;";
                        break;
                    }

                case ExaminationSQLCommands.AddCiaGroupMarkChecking:
                    {
                        query = @"INSERT INTO CIA_GROUP_MARK_CHECKING
                                (STUDENT_ID,
                                 ACADEMIC_YEAR, 
                                 COURSE_ID,
                                 COURSE_GROUP_ID, 
                                 COURSE_GROUP_MARK,
                                 SEMESTER_ID, 
                                 STATUS)
 
                                 VALUES(
                                 ?STUDENT_ID,
                                 ?ACADEMIC_YEAR,
                                 ?COURSE_ID,
                                 ?COURSE_GROUP_ID,
                                 ?COURSE_GROUP_MARK,
                                 ?SEMESTER_ID,
                                 ?STATUS);";
                        break;
                    }

                case ExaminationSQLCommands.UpdateCiaGroupMarkChecking:
                    {
                        query = @"UPDATE 
                                    CIA_GROUP_MARK_CHECKING
                                    SET 
                                    STATUS=?STATUS 
                                    WHERE
                                    CIA_GROUP_MARK_CHECKING_ID=?CIA_GROUP_MARK_CHECKING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.IsCiaMarkVerifiedByCourseAndStudentId:
                    {
                        query = @"SELECT CIA_GROUP_MARK_CHECKING_ID FROM CIA_GROUP_MARK_CHECKING WHERE STUDENT_ID=?STUDENT_ID AND ACADEMIC_YEAR=?AC_YEAR AND  COURSE_ID=?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CiaMarkCheckingByCourse:
                    {
                        query = @"SELECT 
                                    CONCAT(IFNULL(SPI.FIRST_NAME, ''),
                                            ' ',
                                            IFNULL(SPI.LAST_NAME, '')) AS FIRST_NAME,
                                    SPI.ROLL_NO,
                                    CC.CLASS_NAME,
                                    CCR.COURSE_TITLE,
                                    SS.SEMESTER_NAME AS SEMESTER,
                                    CGC.CIA_GROUP_MARK_CHECKING_ID,
                                    CGC.STATUS
                                FROM
                                    CIA_GROUP_MARK_CHECKING AS CGC
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = CGC.STUDENT_ID
                                        AND SPI.IS_DELETED != 1
                                        AND SPI.IS_LEFT != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = SPI.STUDENT_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR =?AC_YEAR
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGC.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CGC.SEMESTER_ID
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    CGC.ACADEMIC_YEAR =?AC_YEAR
                                        AND CGC.COURSE_ID =?COURSE_ID order by SPI.ROLL_NO;";
                        break;
                    }
                #region Online Exam for SJC
                case ExaminationSQLCommands.FetchCourseBySemesterandStaff:
                    {
                        query = @"SELECT 
                                        COURSE_ROOT_ID,
                                       
                                        UPPER(CONCAT(CCR.COURSE_CODE,'-',CCR.COURSE_TITLE)) AS 'COURSE_TITLE'
                                    FROM
                                        
                                        CP_COURSE_ROOT AS CCR 
                                           
                                    WHERE
                                        CCR.SEMESTER_ID = ?SEMESTER ;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamObjectiveQUestions:
                    {
                        query = @"SELECT 
                                    OQ.QUESTION_ID,
                                    OQ.QUESTION,
                                    OQ.PARTWISE_STAFF_ID,
                                    OQ.ANSWER_ID,
                                    OP.OPTION_ID,
                                    OP.OPTIONS,
                                    CR.COURSE_CODE,
                                    CR.COURSE_TITLE,
                                    ST.SUBJECT_TYPE,
                                    CT.COURSE_TYPE,
                                    UCT.UGC_COURSE_TYPE,
                                    SP.PART,
                                    SP.PART_ID,
                                    SU.UNIT_ID,
                                    SU.UNIT_NAME,
                                    EPS.STAFF_ID,
                                    SPI.STAFF_CODE,
                                    SPI.FIRST_NAME,
                                    DEP.DEPARTMENT
    
                                FROM
                                    ONLINE_EXAM_PARTWISE_STAFF AS EPS
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EPS.COURSE_ID                                    
                                        LEFT JOIN
                                    CP_UGC_COURSE_TYPE AS UCT ON UCT.UGC_COURSE_TYPE_ID = CR.UGC_COURSE_TYPE
                                        LEFT JOIN
                                    CP_COURSE_TYPE AS CT ON CT.COURSE_TYPE = CR.COURSE_TYPE
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS ST ON ST.SUBJECT_TYPE_ID = CR.SUBJECT_TYPE
                                        LEFT JOIN
                                    CP_DEPARTMENT AS DEP ON DEP.DEPARTMENT_ID = CR.DEPARTMENT
                                        LEFT JOIN
                                    STF_PERSONAL_INFO AS SPI ON SPI.STAFF_ID = EPS.STAFF_ID
                                        INNER JOIN
                                    SUP_PART AS SP ON SP.PART_ID = EPS.PART_ID
                                        INNER JOIN
                                    SUP_UNIT AS SU ON SU.UNIT_ID = EPS.UNIT_ID
                                        INNER JOIN
                                    ONLINE_OBJECTIVE_QUESTIONS AS OQ ON EPS.PARTWISE_STAFF_ID = OQ.PARTWISE_STAFF_ID
                                        AND OQ.IS_DELETED != 1
                                        INNER JOIN
                                    ONLINE_OBJECTIVE_OPTIONS AS OP ON OP.QUESTION_ID = OQ.QUESTION_ID
                                        AND OP.IS_DELETED != 1
                                WHERE
                                    EPS.STAFF_ID = ?STAFF_ID
                                        AND EPS.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EPS.COURSE_ID = ?COURSE_ID
                                        AND EPS.ACADEMIC_YEAR = ?ACADEMIC_YEAR
                                        AND EPS.IS_DELETED != 1; ";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuestionDetailsByPartandUnitId:
                    {
                        query = @"SELECT 
                                EPS.PARTWISE_STAFF_ID,EPS.TOTAL_QUESTIONS, OQ.QUESTION_ID
                            FROM
                                ONLINE_EXAM_PARTWISE_STAFF AS EPS
                                    LEFT JOIN
                                ONLINE_OBJECTIVE_QUESTIONS AS OQ ON OQ.PARTWISE_STAFF_ID = EPS.PARTWISE_STAFF_ID
                            WHERE
                                EPS.PART_ID = ?PART_ID AND EPS.UNIT_ID = ?UNIT_ID
                                    AND EPS.STAFF_ID = ?STAFF_ID
                                    AND EPS.COURSE_ID = ?COURSE_ID
                                    AND EPS.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EPS.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineExamQuestions:
                    {
                        query = @"INSERT INTO 
                                ONLINE_OBJECTIVE_QUESTIONS
                                (PARTWISE_STAFF_ID,
                                 QUESTION, ACADEMIC_YEAR) 
                                VALUES(?PARTWISE_STAFF_ID, 
                                ?QUESTION, ?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineQuestionOptions:
                    {
                        query = @"INSERT INTO 
                                ONLINE_OBJECTIVE_OPTIONS
                                (QUESTION_ID,
                                 OPTIONS, ACADEMIC_YEAR) 
                                VALUES(?QUESTION_ID,
                                 ?OPTIONS, ?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamQuestionsOptionIdByOption:
                    {
                        query = @"SELECT 
                                OPTION_ID, OPTIONS, QUESTION_ID
                            FROM
                                ONLINE_OBJECTIVE_OPTIONS
                            WHERE
                                OPTIONS = ?ANSWER_ID 
                                AND QUESTION_ID = ?QUESTION_ID
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateAnswerForObjectiveQuestions:
                    {
                        query = @"UPDATE ONLINE_OBJECTIVE_QUESTIONS 
                                    SET 
                                        ANSWER_ID = ?ANSWER_ID
                                    WHERE
                                        QUESTION_ID =?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchPartByStaff:
                    {
                        query = @"SELECT 
                                    SP.PART_ID, SP.PART
                                FROM
                                    ONLINE_EXAM_PARTWISE_STAFF AS EPS
                                        INNER JOIN
                                    SUP_PART AS SP ON SP.PART_ID = EPS.PART_ID
                                WHERE
                                    EPS.STAFF_ID = ?STAFF_ID AND EPS.COURSE_ID = ?COURSE_ID
                                        AND EPS.EXAM_SETTING_ID = ?EXAM_SETTING_ID 
                                        AND EPS.ACADEMIC_YEAR=?AC_YEAR
                                        AND EPS.IS_DELETED != 1
                                GROUP BY EPS.PART_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchUnitByStaff:
                    {
                        query = @"SELECT 
                                    SU.UNIT_ID, SU.UNIT_NAME
                                FROM
                                    ONLINE_EXAM_PARTWISE_STAFF AS EPS
                                        INNER JOIN
                                    SUP_UNIT AS SU ON SU.UNIT_ID = EPS.UNIT_ID
                                WHERE
                                    EPS.STAFF_ID = ?STAFF_ID AND EPS.COURSE_ID = ?COURSE_ID
                                        AND EPS.EXAM_SETTING_ID = ?EXAM_SETTING_ID 
                                        AND EPS.ACADEMIC_YEAR=?AC_YEAR
                                        AND EPS.IS_DELETED != 1
                                GROUP BY EPS.UNIT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamQuestionAndAnswerByQuizId:
                    {
                        query = @"SELECT 
                                OQ.QUESTION_ID,
                                OQ.QUESTION,
                                OP.OPTION_ID,
                                OPTIONS,
                                IF(OQ.ANSWER_ID = OP.OPTION_ID,
                                    OP.OPTIONS,
                                    '') AS ANSWER
                            FROM
                                ONLINE_OBJECTIVE_QUESTIONS AS OQ
                                    INNER JOIN
                                ONLINE_OBJECTIVE_OPTIONS AS OP ON OQ.QUESTION_ID = OP.QUESTION_ID
                            WHERE
                                OQ.IS_DELETED != 1
                                    AND OQ.QUESTION_ID = ?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateObjectiveOnlineQuestionByQuizId:
                    {
                        query = @"UPDATE ONLINE_OBJECTIVE_QUESTIONS 
                                    SET 
                                        QUESTION =?QUESTION
                                    WHERE
                                        QUESTION_ID =?QUESTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateOnlineQuestionOptions:
                    {
                        query = @"UPDATE 
                        ONLINE_OBJECTIVE_OPTIONS
                                  SET
                                OPTIONS = ?OPTION                                   
                                WHERE OPTION_ID =?OPTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineQuestionOption:
                    {
                        query = @"INSERT INTO 
                                ONLINE_OBJECTIVE_OPTIONS(QUESTION_ID,OPTIONS,ACADEMIC_YEAR) 
                                VALUES(?QUESTION_ID,?OPTION,?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.DeleteOnlineExamObjectiveQuestions:
                    {
                        query = @"UPDATE ONLINE_OBJECTIVE_QUESTIONS 
                                SET 
                                    IS_DELETED = 1
                                WHERE
                                    QUESTION_ID = ?QUESTION_ID;";
                        break;
                    }
                #endregion

                #region Exam For 3rd year (corona Issue)
                case ExaminationSQLCommands.FetchNewExamSeating:
                    {
                        query = @"SELECT 
                                        SEATING_ID,
                                        ROOM_ID,
                                        COLUMN_NO,
                                        ROW_NO,
                                        SEAT_CODE,
                                        SEAT_POSITION,
                                        SEATING_ALLOTEMENT_ID
                                    FROM
                                        (SELECT 
                                            ES.SEATING_ID,
                                                ES.ROOM_ID,
                                                ES.COLUMN_NO,
                                                ES.ROW_NO,
                                                ES.SEAT_CODE,
                                                ES.SEAT_POSITION,
                                                SA.SEATING_ALLOTEMENT_ID
                                        FROM
                                            EXAM_SEATINGS_?AC_YEAR AS ES
                                                LEFT JOIN 
                                            EXAM_SEATING_ALLOTEMENT AS SA ON SA.SEATING_ID = ES.SEATING_ID
                                                AND SA.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                                AND SA.EXAM_DATE = ?EXAM_DATE
                                                AND SA.EXAM_SESSION_ID = ?EXAM_SESSION_ID
                                                AND SA.ACADEMIC_YEAR = ?AC_YEAR
                                                AND SA.IS_DELETED != 1) AS T
                                    WHERE
                                        T.SEATING_ALLOTEMENT_ID IS NULL
                                    ORDER BY T.ROOM_ID ,  T.COLUMN_NO , T.ROW_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamRegistrationOnlyRegular:
                    {
                        query = @"SELECT 
                                        ER.STUDENT_ID,
                                        ER.COURSE_ID,
                                        ER.STATUS,
                                        SP.ROLL_NO,
                                        C.SHIFT
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
		                                    INNER JOIN
	                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID=ER.STUDENT_ID
		                                    AND SP.IS_DELETED!=1
                                            INNER JOIN
	                                    STU_CLASS AS SC ON SC.STUDENT_ID=SP.STUDENT_ID
		                                    AND SC.ACADEMIC_YEAR=ER.ACADEMIC_YEAR
                                            AND SC.IS_DELETED!=1
                                            INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
                                    WHERE
                                        ER.EXAM_SETTING_ID = 9 
                                        AND ER.STATUS='R' 
                                        AND ER.COURSE_ID IN (?COURSE_ID)
                                        AND ER.IS_DELETED!=1
                                    ORDER BY SP.ROLL_NO; ";
                        break;
                    }

                case ExaminationSQLCommands.FetchHallTicketListForSJC:
                    {
                        query = @"SELECT 
                                        REGISTRATION_ID,
                                        ER.STUDENT_ID,
                                        CC.COURSE_CODE,
                                        CC.COURSE_TITLE,
                                        IF(ET.IS_ADVANCE = '1',
                                            DATE_FORMAT(ET.ADVANCE_DATE, '%d/%m/%Y'),
                                            IF(ET.IS_POSTPONED = '1',
                                                DATE_FORMAT(ET.POSTPONED_DATE, '%d/%m/%Y'),
                                                DATE_FORMAT(ET.EXAM_DATE, '%d/%m/%Y'))) AS EXAM_DATE,
                                        IF(ET.IS_ADVANCE = '1',
                                            ET.ADVANCE_TIME,
                                            IF(ET.IS_POSTPONED = '1',
                                                ET.POSTPONED_TIME,
                                                ET.EXAM_TIME)) AS EXAM_TIME,
                                        ER.COURSE_ID,
                                        STATUS,
                                        ER.ACADEMIC_YEAR,
                                        S.SEMESTER_NAME AS 'SEMESTER_ID',
                                        ES.M_PASS AS 'MONTH_YEAR',
                                        CC.SEMESTER_ID AS 'SEMESTER',
                                        CONCAT(IFNULL(SCB.BLOCK_CODE,''),'( ',IFNULL(SR.ROOM_NO,''),' - ',IFNULL(ESS.SEAT_CODE,''),' )') AS SEAT_CODE,
                                        SCB.BLOCK_CODE,
                                        SCB.BLOCK_NAME
    
                                    FROM
                                       EXAM_REGISTRATION_?AC_YEAR AS ER
                                        INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID 
                                            AND ES.IS_ACTIVE = 1
                                            LEFT JOIN
                                        EXAM_SEATING_ALLOTEMENT AS ESA ON ESA.STUDENT_ID = ER.STUDENT_ID
                                            AND ESA.COURSE_ID = ER.COURSE_ID AND  ESA.EXAM_TYPE=ES.EXAM_TYPE
                                            LEFT JOIN
                                        EXAM_SEATINGS_?AC_YEAR AS ESS ON ESS.SEATING_ID = ESA.SEATING_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CC ON CC.COURSE_ROOT_ID = ER.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER AS S ON S.SUP_SEMESTER_ID = CC.SEMESTER_ID
                                            LEFT JOIN
                                        EXAM_TIMETABLE AS ET ON ET.COURSE_ID = CC.COURSE_ROOT_ID
                                            AND ET.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                            AND ET.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            LEFT JOIN
                                        SUP_ROOM AS SR ON SR.ROOM_ID = ESS.ROOM_ID
                                            LEFT JOIN
                                        SUP_COLLEGE_BLOCK AS SCB ON SCB.COLLEGE_BLOCK_ID = SR.COLLEGE_BLOCK_ID
                                    WHERE
                                        ER.STUDENT_ID = ?STUDENT_ID  AND ER.STATUS='R'
                                            AND ER.ACADEMIC_YEAR = ?AC_YEAR 
                                            AND ER.IS_DELETED!=1
                                    ORDER BY DATE_FORMAT(ET.EXAM_DATE, '%Y-%m-%d') ASC;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizcountStatus:
                    {
                        query = @"SELECT 
                                COUNT(QUIZ_ID) AS COUNT, QS.SETTING_ID, QS.NO_OF_QUESTIONS
                            FROM
                                (SELECT 
                                    QUIZ_ID, SETTING_ID
                                FROM
                                    QUIZ_SAVE_OBJECTIVES
                                WHERE
                                    SETTING_ID = ?SETTING_ID AND STUDENT_ID = ?STUDENT_ID
                                        AND IS_DELETED != 1 GROUP BY QUIZ_ID UNION ALL SELECT 
                                    QUIZ_ID, SETTING_ID
                                FROM
                                    QUIZ_SAVE_FILL_IN_BLANKS
                                WHERE
                                    SETTING_ID = ?SETTING_ID AND STUDENT_ID = ?STUDENT_ID
                                        AND IS_DELETED != 1 GROUP BY QUIZ_ID UNION ALL SELECT 
                                    QUIZ_ID, SETTING_ID
                                FROM
                                    QUIZ_SAVE_MATCH_THE_FOLLOWING
                                WHERE
                                    SETTING_ID = ?SETTING_ID AND STUDENT_ID = ?STUDENT_ID
                                        AND IS_DELETED != 1 GROUP BY QUIZ_ID) AS T
                                    JOIN
                                QUIZ_SETTING AS QS
                            WHERE
                                QS.SETTING_ID = ?SETTING_ID;";

                        break;
                    }
                case ExaminationSQLCommands.FetchTimestatus:
                    {
                        query = @"SELECT 
                                COUNT(QUIZ_ID) AS COUNT,
                                QS.SETTING_ID,
                                QS.NO_OF_QUESTIONS,
                                MIN(MINUTES) AS MINUTES
                            FROM
                                (SELECT 
                                    QUIZ_ID, SETTING_ID, IFNULL(MIN(MINUTES),NULL) AS MINUTES
                                FROM
                                    QUIZ_SAVE_OBJECTIVES
                                WHERE
                                    SETTING_ID = ?SETTING_ID  AND STUDENT_ID = ?STUDENT_ID
                                        AND IS_DELETED != 1 UNION ALL SELECT 
                                    QUIZ_ID, SETTING_ID, MIN(MINUTES) AS MINUTES
                                FROM
                                    QUIZ_SAVE_FILL_IN_BLANKS
                                WHERE
                                    SETTING_ID = ?SETTING_ID  AND STUDENT_ID = ?STUDENT_ID
                                        AND IS_DELETED != 1 UNION ALL SELECT 
                                    QUIZ_ID, SETTING_ID, MIN(MINUTES) AS MINUTES
                                FROM
                                    QUIZ_SAVE_MATCH_THE_FOLLOWING
                                WHERE
                                    SETTING_ID = ?SETTING_ID AND STUDENT_ID = ?STUDENT_ID
                                        AND IS_DELETED != 1) AS T
                                    JOIN
                                QUIZ_SETTING AS QS
                            WHERE
                                QS.SETTING_ID = ?SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentQuizResultsForCertificate:
                    {
                        query = @"SELECT 
                                    QS.SETTING_ID,
                                    QS.SETTING_NAME,
                                    QS.TOTAL_MARK,
                                    SUM(T.OBTAINED_MARK) AS SCORE_MARK,
                                    ROUND((SUM(T.OBTAINED_MARK) / QS.TOTAL_MARK) * 100,
                                            2) AS PERCENTAGE
                                FROM
                                    QUIZ_SETTING QS
                                        INNER JOIN
                                    (SELECT 
                                        QSO.SETTING_ID,
                                            SUM(IF(QSO.STATUS = 1, 1, 0)) * QS_INNER.EACH_QUESTION_MARKS AS OBTAINED_MARK
                                    FROM
                                        QUIZ_SAVE_OBJECTIVES QSO
                                    JOIN QUIZ_SETTING QS_INNER ON QS_INNER.SETTING_ID = QSO.SETTING_ID
                                    WHERE
                                        QSO.STUDENT_ID =  ?STUDENT_ID
                                            AND QSO.IS_DELETED != 1
                                    GROUP BY QSO.SETTING_ID UNION ALL SELECT 
                                        QSF.SETTING_ID,
                                            SUM(IF(QSF.STATUS = 1, 1, 0)) * QS_INNER.EACH_QUESTION_MARKS AS OBTAINED_MARK
                                    FROM
                                        QUIZ_SAVE_FILL_IN_BLANKS QSF
                                    JOIN QUIZ_SETTING QS_INNER ON QS_INNER.SETTING_ID = QSF.SETTING_ID
                                    WHERE
                                        QSF.STUDENT_ID =  ?STUDENT_ID
                                            AND QSF.IS_DELETED != 1
                                    GROUP BY QSF.SETTING_ID UNION ALL SELECT 
                                        MF_INNER.SETTING_ID, SUM(MARK) AS OBTAINED_MARK
                                    FROM
                                        (SELECT 
                                        QSM.SETTING_ID,
                                            IF(COUNT(QSM.QUIZ_ID) = SUM(IF(QSM.STATUS = 1, 1, 0)), QS_INNER.EACH_QUESTION_MARKS, 0) AS MARK
                                    FROM
                                        QUIZ_SAVE_MATCH_THE_FOLLOWING QSM
                                    JOIN QUIZ_SETTING QS_INNER ON QS_INNER.SETTING_ID = QSM.SETTING_ID
                                    WHERE
                                        QSM.STUDENT_ID =  ?STUDENT_ID
                                            AND QSM.IS_DELETED != 1
                                    GROUP BY QSM.SETTING_ID , QSM.QUIZ_ID) AS MF_INNER
                                    GROUP BY SETTING_ID) AS T ON T.SETTING_ID = QS.SETTING_ID
                                        INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID = QS.QUIZ_STF_ID
                                        AND CCS.IS_DELETED != 1
                                WHERE
                                    QS.ACADEMIC_YEAR =  ?AC_YEAR
                                        AND CCS.COURSE_ID =  ?COURSE_ID
                                        AND QS.IS_DELETED != 1
                                GROUP BY QS.SETTING_ID , QS.SETTING_NAME , QS.TOTAL_MARK;";
                        break;
                    }
                case ExaminationSQLCommands.FetchDetailedQuizResultForStudent:
                    {
                        query = @"SELECT 
                                            'Objective' AS Q_TYPE,
                                            QQ.QUIZ_ID,
                                            QQ.QUESTION AS QUESTION,
                                            QO_CORRECT.OPTION AS CORRECT_ANSWER,
                                            QO_SELECTED.OPTION AS SELECTED_ANSWER,
                                            QS.STATUS
                                        FROM
                                            QUIZ_SAVE_OBJECTIVES QS
                                                JOIN
                                            QUIZ_OBJECTIVE_QUESTIONS QQ ON QQ.QUIZ_ID = QS.QUIZ_ID
                                                JOIN
                                            QUIZ_OBJECTIVE_OPTIONS QO_CORRECT ON QO_CORRECT.OPTION_ID = QQ.ANSWER_ID
                                                LEFT JOIN
                                            QUIZ_OBJECTIVE_OPTIONS QO_SELECTED ON QO_SELECTED.OPTION_ID = QS.OPTION_ID
                                        WHERE
                                            QS.SETTING_ID = ?SETTING_ID
                                                AND QS.STUDENT_ID = ?STUDENT_ID
                                                AND QS.IS_DELETED != 1 
                                        UNION ALL SELECT 
                                            'Fill in Blanks' AS Q_TYPE,
                                            QQ.QUIZ_ID,
                                            QQ.QUESTION AS QUESTION,
                                            QQ.ANSWER_ID AS CORRECT_ANSWER,
                                            QS.ANSWER_ID AS SELECTED_ANSWER,
                                            QS.STATUS
                                        FROM
                                            QUIZ_SAVE_FILL_IN_BLANKS QS
                                                JOIN
                                            QUIZ_FILL_IN_BLANK_QUESTIONS QQ ON QQ.QUIZ_ID = QS.QUIZ_ID
                                        WHERE
                                            QS.SETTING_ID = ?SETTING_ID
                                                AND QS.STUDENT_ID = ?STUDENT_ID
                                                AND QS.IS_DELETED != 1;";
                        break;
                    }
                #endregion
                case ExaminationSQLCommands.FetchAllFeeTransaction:
                    {
                        query = @"SELECT 
                                        SUM(IFNULL(FS.CREDIT, '0')) - SUM(IFNULL(FS.DEBIT, '0')) AS BALANCE,
                                        FS.DEBIT,
                                        SUM(FS.DEBIT) AS DEBIT,
                                        FT.FREQUENCY_TYPE_ID,
                                        FS.STUDENT_ID,
                                        FS.HEAD,
                                        SC.CLASS_ID,
                                        FS.FREQUENCY_ID,
                                        FT.FREQUENCY_TYPE ,
                                        FT.FEE_ROOT_ID,FF.ACADEMIC_YEAR,CONCAT(FF.FREQUENCY_NAME,'-',FF.ACADEMIC_YEAR) AS FREQUENCY_NAME
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        fee_frequency_fee_mode AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID AND FFF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                            INNER JOIN
                                        sup_fee_frequency AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID AND FF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    WHERE
                                            SC.STUDENT_ID = ?STUDENT_ID
                                           -- AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY FFF.FEE_MODE,FREQUENCY_ID
                                    ;";
                        break;
                    }

                case ExaminationSQLCommands.FetchAllFeeTransactionByFrequency:
                    {
                        query = @"SELECT 
                                        SUM(IFNULL(FS.CREDIT, '0')) - SUM(IFNULL(FS.DEBIT, '0')) AS BALANCE,
                                        FS.DEBIT,
                                        SUM(FS.DEBIT) AS DEBIT,
                                        FT.FREQUENCY_TYPE_ID,
                                        FS.STUDENT_ID,
                                        FS.HEAD,
                                        SC.CLASS_ID,
                                        FS.FREQUENCY_ID,
                                        FT.FREQUENCY_TYPE ,
                                        FT.FEE_ROOT_ID,FF.ACADEMIC_YEAR,CONCAT(FF.FREQUENCY_NAME,'-',FF.ACADEMIC_YEAR) AS FREQUENCY_NAME
                                    FROM
                                        STU_CLASS AS SC
                                            INNER JOIN
                                        FEE_STUDENT_ACCOUNT AS FS ON FS.STUDENT_ID = SC.STUDENT_ID
                                            AND FS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        fee_frequency_fee_mode AS FFF ON FFF.FEE_FREQUENCY_FEE_MODE_ID = FS.FREQUENCY_ID AND FFF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        SUP_FREQUENCY_TYPE AS FT ON FT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                            INNER JOIN
                                        sup_fee_frequency AS FF ON FF.FREQUENCY_ID = FFF.FREQUENCY_ID AND FF.ACADEMIC_YEAR=SC.ACADEMIC_YEAR
                                    WHERE
                                            SC.STUDENT_ID = ?STUDENT_ID
                                             AND FF.FREQUENCY_ID IN (1,2,3)
                                           -- AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY FFF.FEE_MODE,FREQUENCY_ID
                                    ;";
                        break;
                    }

                case ExaminationSQLCommands.FetchExamregisteredCourseByTimetable:
                    {
                        query = @"SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                EI.STUDENT_ID,
                                SP.FIRST_NAME,
                                CCR.COURSE_TITLE,
                                CCR.COURSE_CODE,
                                DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                ES.ONLINE_EXAM_SETTING_ID AS EXAM_SETTING_ID,
                                ES.SETTING_NAME AS EXAM_NAME,
                                EI.SET AS SET_ID,
                                TIME_FORMAT(EI.START_TIME, '%h:%i %p') AS START_TIME,
                                TIME_FORMAT(EI.END_TIME, '%h:%i %p') AS END_TIME,
                                EI.COURSE_ID,
                                EI.IS_ACTIVE
                            FROM
                                EXAM_INVIGILATION AS EI
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                EXAM_ONLINE_EXAM_SETTING AS ES ON ES.ONLINE_EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                            WHERE
                                EI.IS_DELETED != 1
                                    AND EI.EXAM_SETTING_ID IN (SELECT 
                                        ONLINE_EXAM_SETTING_ID
                                    FROM
                                        EXAM_ONLINE_EXAM_SETTING
                                    WHERE
                                        IS_DELETED != 1 AND IS_ACTIVE = 1)
                                    AND EI.EXAM_DATE = CURDATE()
                                    AND EI.STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoForOnlineExam:
                    {
                        query = @"SELECT 
                                    EI.EXAM_INVIGILATION_ID,
                                    EI.STUDENT_ID,
                                    SP.FIRST_NAME,
                                    EI.COURSE_ID,
                                    CCR.COURSE_TITLE,
                                    CCR.COURSE_CODE,
                                    DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    ES.ONLINE_EXAM_SETTING_ID AS EXAM_SETTING_ID,
                                    ES.SETTING_NAME AS EXAM_NAME,
                                    EI.SET AS SET_ID,
                                    TIME(EI.START_TIME) AS START_TIME,
                                    TIME(EI.END_TIME) AS END_TIME,
                                    SI.FIRST_NAME AS INVIGILATOR,
                                    SI.MOBILE_NO,
                                    SI.STAFF_ID,
                                    CC.CLASS_NAME,
                                    TOTAL_HOURS,
                                    MINUTES_SECONDS
                                FROM
                                    EXAM_INVIGILATION AS EI
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = EI.STUDENT_ID
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                        INNER JOIN
                                    EXAM_ONLINE_EXAM_SETTING AS ES ON ES.ONLINE_EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                                        LEFT JOIN
                                    STF_PERSONAL_INFO AS SI ON SI.STAFF_ID = EI.EXAM_INVIGILATOR_ID
                                WHERE
                                    EI.IS_DELETED != 1
                                        AND EI.EXAM_SETTING_ID IN (SELECT 
                                            ONLINE_EXAM_SETTING_ID
                                        FROM
                                            EXAM_ONLINE_EXAM_SETTING
                                        WHERE
                                            IS_DELETED != 1 AND IS_ACTIVE = 1)
                                        AND EI.EXAM_DATE = CURDATE()
                                        AND EI.STUDENT_ID = ?STUDENT_ID
                                        AND EI.COURSE_ID IN (?COURSE_ID)
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSections:
                    {
                        query = @"SELECT 
                            SECTION_ID, SECTION_NAME
                        FROM
                            EXAM_SECTION
                        WHERE
                            IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingExamQuestionsandoptions:
                    {
                        query = @"SELECT 
                                    OMF.QUIZ_ID,
                                    OMF.QUESTION,
                                    OMF.ANSWER_ID,
                                    EQP.SECTION_ID,
                                    EQP.QUESTION_TYPE,
                                    OMF.SET_ID,
                                    OMF.EXAM_SETTING_ID
                                FROM
                                    EXAM_MATCH_THE_FOLLOWING_QUESTIONS AS OMF
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS EQP ON EQP.PATTERN_SECTION_ID = OMF.PATTERN_SECTION_ID
                                        AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    OMF.IS_DELETED != 1
                                        AND OMF.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND OMF.COURSE_ID = ?COURSE_ID
                                        AND OMF.SET_ID = ?SET_ID
                                        AND OMF.QUIZ_ID NOT IN (SELECT 
                                            QUIZ_ID
                                        FROM
                                            EXAM_SAVE_MATCH_THE_FOLLOWING
                                        WHERE
                                            IS_DELETED != 1 AND STUDENT_ID=?STUDENT_ID AND COURSE_ID=?COURSE_ID ) LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectivesExamQuestionsandoptions:
                    {
                        query = @"SELECT 
                                    OQ.QUIZ_ID,
                                    OQ.QUESTION,
                                    OQ.ANSWER_ID,
                                    EQP.SECTION_ID,
                                    EQP.QUESTION_TYPE,
                                    OQ.SET_ID,
                                    OQ.EXAM_SETTING_ID
                                FROM
                                    EXAM_OBJECTIVE_QUESTIONS AS OQ
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS EQP ON EQP.PATTERN_SECTION_ID = OQ.PATTERN_SECTION_ID
                                        AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    OQ.IS_DELETED != 1
                                        AND OQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND OQ.COURSE_ID = ?COURSE_ID
                                        AND OQ.SET_ID = ?SET_ID
                                        AND OQ.QUIZ_ID NOT IN (SELECT 
                                            QUIZ_ID
                                        FROM
                                            EXAM_SAVE_OBJECTIVES
                                        WHERE
                                            IS_DELETED != 1 AND STUDENT_ID=?STUDENT_ID AND COURSE_ID=?COURSE_ID) LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankExamQuestionsandoptions:
                    {
                        query = @"SELECT 
                                    OF.QUIZ_ID,
                                    OF.QUESTION,
                                    OF.ANSWER_ID,                                   
                                    EQP.SECTION_ID,
                                    EQP.QUESTION_TYPE,
                                    OF.SET_ID,
                                    OF.EXAM_SETTING_ID
                                FROM
                                    EXAM_FILL_IN_BLANK_QUESTIONS AS OF
                                        INNER JOIN								
                                    EXAM_QUESTION_PATTERN_SECTION AS EQP ON EQP.PATTERN_SECTION_ID = OF.PATTERN_SECTION_ID
                                        AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    OF.IS_DELETED != 1
                                        AND OF.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND OF.COURSE_ID = ?COURSE_ID
                                        AND OF.SET_ID = ?SET_ID
                                        AND OF.QUIZ_ID NOT IN (SELECT 
                                            QUIZ_ID
                                        FROM
                                            EXAM_SAVE_FILL_IN_BLANKS
                                        WHERE
                                            IS_DELETED != 1 AND STUDENT_ID=?STUDENT_ID AND COURSE_ID=?COURSE_ID) LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEitherExamQuestionsandoptions:
                    {
                        query = @"SELECT 
                                    EQ.QUIZ_ID,
                                    EQ.QUESTION,
                                    EQ.ANSWER_ID,
                                    EQP.SECTION_ID,
                                    EQP.QUESTION_TYPE,
                                    EQ.SET_ID,
                                    EQ.EXAM_SETTING_ID
                                FROM
                                    EXAM_EITHER_OR_QUESTIONS AS EQ
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS EQP ON EQP.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                                        AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    EQ.IS_DELETED != 1
                                        AND EQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EQ.COURSE_ID = ?COURSE_ID
                                        AND EQ.SET_ID = ?SET_ID
                                        AND EQ.QUIZ_ID NOT IN (SELECT 
                                            QUIZ_ID
                                        FROM
                                            EXAM_SAVE_EITHERQUESTIONS
                                        WHERE
                                            IS_DELETED != 1 AND COURSE_ID=?COURSE_ID AND STUDENT_ID=?STUDENT_ID) LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingExamOptions:
                    {
                        query = @"SELECT 
                                MFO.OPTION_ID, MFO.OPTION, MFO.QUIZ_ID, MFO.ANSWER
                            FROM
                                EXAM_MATCH_THE_FOLLOWING_OPTIONS AS MFO
                            WHERE
                                MFO.QUIZ_ID = ?QUIZ_ID AND MFO.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankOptions:
                    {
                        query = @"SELECT 
                                FBQ.OPTION_ID, FBQ.OPTION, FBQ.QUIZ_ID
                            FROM
                                EXAM_FILL_IN_BLANK_OPTIONS AS FBQ
                            WHERE
                                FBQ.QUIZ_ID = ?QUIZ_ID AND FBQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectivesExamOptions:
                    {
                        query = @"SELECT 
                                EOP.OPTION_ID, EOP.OPTION, EOP.QUIZ_ID
                            FROM
                                EXAM_OBJECTIVE_OPTIONS AS EOP
                            WHERE
                                EOP.QUIZ_ID = ?QUIZ_ID AND EOP.IS_DELETED != 1;";
                        break;
                    }

                case ExaminationSQLCommands.FetchEitherOptions:
                    {
                        query = @"SELECT 
                                EQO.OPTION_ID, EQO.OPTION, EQO.QUIZ_ID
                            FROM
                                EXAM_EITHER_OR_OPTIONS AS EQO
                            WHERE
                                EQO.QUIZ_ID = ?QUIZ_ID AND EQO.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineExamMatchTheFollowingByStudent:
                    {
                        query = @"INSERT INTO EXAM_SAVE_MATCH_THE_FOLLOWING
                                 (                               
                                     COURSE_ID,
                                     STUDENT_ID,
                                     QUIZ_ID,
                                     OPTION_ID,
                                     ANSWER_ID,
                                     STATUS,                                                                       
                                     ACADEMIC_YEAR,MINUTES
                                 )
                                 VALUES";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineExamFillInTheBlankByStudent:
                    {
                        query = @"INSERT INTO EXAM_SAVE_FILL_IN_BLANKS
                                 (                               
                                     COURSE_ID,
                                     STUDENT_ID,
                                     QUIZ_ID,
                                     OPTION_ID,
                                     ANSWER_ID,
                                     STATUS,                                                                       
                                     ACADEMIC_YEAR,MINUTES
                                 )
                                 VALUES";
                        break;
                    }
                case ExaminationSQLCommands.SaveOnlineExamObjectiveQuizByStudent:
                    {
                        query = @"INSERT INTO EXAM_SAVE_OBJECTIVES
                                 (                               
                                     COURSE_ID,
                                     STUDENT_ID,
                                     QUIZ_ID,
                                     OPTION_ID,
                                     ANSWER_ID,
                                     STATUS,                                                                       
                                     ACADEMIC_YEAR,MINUTES
                                 )
                                 VALUES";
                        break;
                    }
                case ExaminationSQLCommands.SaveEitherQuestionandAnswer:
                    {
                        query = @"INSERT INTO EXAM_SAVE_EITHERQUESTIONS
                                (COURSE_ID,
                                STUDENT_ID,
                                QUIZ_ID,
                                OPTION_ID,
                                IMAGE_PATH,
                                ACADEMIC_YEAR,
                                MINUTES)
                                VALUES(?COURSE_ID,
                                ?STUDENT_ID,
                                ?QUIZ_ID,
                                ?OPTION_ID,
                                ?IMAGE_PATH,
                                ?ACADEMIC_YEAR,
                                ?MINUTES);";
                        break;
                    }
                case ExaminationSQLCommands.FetchuploadedimageByQuestionandoptionId:
                    {
                        query = @"SELECT 
                                    QUIZ_SAVE_ID, QUIZ_ID, OPTION_ID, IMAGE_PATH
                                FROM
                                    EXAM_SAVE_EITHERQUESTIONS
                                WHERE
                                    QUIZ_ID = ?QUIZ_ID AND STUDENT_ID = ?STUDENT_ID
                                        AND OPTION_ID = ?OPTION_ID
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchuploadedimageByQuestionId:
                    {
                        query = @"SELECT 
                                QUIZ_SAVE_ID, QUIZ_ID, OPTION_ID, IMAGE_PATH
                            FROM
                                EXAM_SAVE_EITHERQUESTIONS
                            WHERE
                                QUIZ_ID = ?QUIZ_ID AND STUDENT_ID = ?STUDENT_ID
       
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteEitherAnswerImage:
                    {
                        query = @"UPDATE EXAM_SAVE_EITHERQUESTIONS 
                                SET 
                                    IS_DELETED = 1
                                WHERE
                                    QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAttendedQuestionCount:
                    {
                        query = @"SELECT 
                                SUM(QUIZ_SAVE_ID) AS QUIZ_SAVE_ID
                            FROM
                                (SELECT 
                                    TO_BE_ATTEND AS TO_BE_ATTEND,
                                        COUNT(DISTINCT EO.QUIZ_ID) AS QUIZ_SAVE_ID
                                FROM
                                    EXAM_SAVE_OBJECTIVES AS EO
                                INNER JOIN EXAM_OBJECTIVE_QUESTIONS AS EOQ ON EOQ.QUIZ_ID = EO.QUIZ_ID
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EOQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    EO.IS_DELETED != 1
                                        AND EOQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EO.COURSE_ID = ?COURSE_ID
                                        AND EO.STUDENT_ID=?STUDENT_ID
                                GROUP BY EO.QUIZ_ID UNION ALL SELECT 
                                    TO_BE_ATTEND AS TO_BE_ATTEND,
                                        COUNT(DISTINCT EO.QUIZ_ID) AS QUIZ_SAVE_ID
                                FROM
                                    EXAM_SAVE_EITHERQUESTIONS AS EO
                                INNER JOIN EXAM_EITHER_OR_QUESTIONS AS EOQ ON EOQ.QUIZ_ID = EO.QUIZ_ID
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EOQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    EO.IS_DELETED != 1
                                        AND EOQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EO.COURSE_ID = ?COURSE_ID
                                        AND EO.STUDENT_ID = ?STUDENT_ID
                                GROUP BY EO.QUIZ_ID UNION ALL SELECT 
                                    TO_BE_ATTEND AS TO_BE_ATTEND,
                                        COUNT(DISTINCT EO.QUIZ_ID) AS QUIZ_SAVE_ID
                                FROM
                                    EXAM_SAVE_FILL_IN_BLANKS AS EO
                                INNER JOIN EXAM_FILL_IN_BLANK_QUESTIONS AS EOQ ON EOQ.QUIZ_ID = EO.QUIZ_ID
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EOQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    EO.IS_DELETED != 1
                                        AND EOQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EO.COURSE_ID = ?COURSE_ID
                                        AND EO.STUDENT_ID = ?STUDENT_ID
                                GROUP BY EO.QUIZ_ID UNION ALL SELECT 
                                    TO_BE_ATTEND AS TO_BE_ATTEND,
                                        COUNT(DISTINCT EO.QUIZ_ID) AS QUIZ_SAVE_ID
                                FROM
                                    EXAM_SAVE_MATCH_THE_FOLLOWING AS EO
                                INNER JOIN EXAM_MATCH_THE_FOLLOWING_QUESTIONS AS EOQ ON EOQ.QUIZ_ID = EO.QUIZ_ID
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EOQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    EO.IS_DELETED != 1
                                        AND EOQ.EXAM_SETTING_ID =?EXAM_SETTING_ID
                                        AND EO.COURSE_ID = ?COURSE_ID
                                        AND EO.STUDENT_ID = ?STUDENT_ID
                                GROUP BY EO.QUIZ_ID UNION ALL SELECT 
                                    TO_BE_ATTEND AS TO_BE_ATTEND,
                                        COUNT(DISTINCT EO.QUIZ_ID) AS QUIZ_SAVE_ID
                                FROM
                                    EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS AS EO
                                INNER JOIN EXAM_CHOICE_BASED_QUESTIONS AS EOQ ON EOQ.QUIZ_ID = EO.QUIZ_ID
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EOQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                                WHERE
                                    EO.IS_DELETED != 1
                                        AND EOQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EO.COURSE_ID = ?COURSE_ID
                                        AND EO.STUDENT_ID = ?STUDENT_ID
                                GROUP BY EO.QUIZ_ID) AS T;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTotalQuestionCount:
                    {
                        query = @"SELECT 
                            EPS.TO_BE_ATTEND,EPS.MARK_FOR_EACH_QUESTION,EPS.TOTAL_MARK_FOR_EACH_SECTION,EPS.SECTION_DECRIPTION
                        FROM
                            EXAM_OBJECTIVE_QUESTIONS AS EO
                                INNER JOIN
                            EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                            AND EPS.SECTION_ID=?SECTION_ID
                        WHERE
                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID AND EO.IS_DELETED!=1
                                AND COURSE_ID = ?COURSE_ID GROUP BY EPS.PATTERN_SECTION_ID
        
                          UNION ALL
                          SELECT 
                            EPS.TO_BE_ATTEND,EPS.MARK_FOR_EACH_QUESTION,EPS.TOTAL_MARK_FOR_EACH_SECTION,EPS.SECTION_DECRIPTION
                        FROM
                            EXAM_MATCH_THE_FOLLOWING_QUESTIONS AS EO
                                INNER JOIN
                            EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                AND EPS.SECTION_ID = ?SECTION_ID
                        WHERE
                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                AND COURSE_ID = ?COURSE_ID AND EO.IS_DELETED!=1
                        GROUP BY EPS.PATTERN_SECTION_ID
                        UNION ALL
                        SELECT 
                            EPS.TO_BE_ATTEND,EPS.MARK_FOR_EACH_QUESTION,EPS.TOTAL_MARK_FOR_EACH_SECTION,EPS.SECTION_DECRIPTION
                        FROM
                            EXAM_FILL_IN_BLANK_QUESTIONS AS EO
                                INNER JOIN
                            EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                AND EPS.SECTION_ID = ?SECTION_ID
                        WHERE
                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                AND COURSE_ID = ?COURSE_ID AND EO.IS_DELETED!=1
                        GROUP BY EPS.PATTERN_SECTION_ID
                        UNION ALL
                        SELECT 
                            EPS.TO_BE_ATTEND,EPS.MARK_FOR_EACH_QUESTION,EPS.TOTAL_MARK_FOR_EACH_SECTION,EPS.SECTION_DECRIPTION
                        FROM
                            EXAM_EITHER_OR_QUESTIONS AS EO
                                INNER JOIN
                            EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                AND EPS.SECTION_ID = ?SECTION_ID
                        WHERE
                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                AND COURSE_ID = ?COURSE_ID AND EO.IS_DELETED!=1
                        GROUP BY EPS.PATTERN_SECTION_ID 
                        UNION ALL
                            SELECT 
                                EPS.TO_BE_ATTEND,EPS.MARK_FOR_EACH_QUESTION,EPS.TOTAL_MARK_FOR_EACH_SECTION,EPS.SECTION_DECRIPTION
                            FROM
                                EXAM_CHOICE_BASED_QUESTIONS AS EO
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                    AND EPS.SECTION_ID = ?SECTION_ID
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                    AND COURSE_ID = ?COURSE_ID
                                    AND EO.IS_DELETED != 1
                            GROUP BY EPS.PATTERN_SECTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamInvigilationId:
                    {
                        query = @"SELECT 
                                EXAM_INVIGILATION_ID,STUDENT_ID,COURSE_ID
                            FROM
                                EXAM_INVIGILATION
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND COURSE_ID = ?COURSE_ID
                                    AND STUDENT_ID = ?STUDENT_ID AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveTimeSpend:
                    {
                        query = @"UPDATE EXAM_INVIGILATION 
                                SET 
                                    MINUTES_SECONDS = ?MINUTES_SECONDS
                                WHERE
                                    EXAM_INVIGILATION_ID =?EXAM_INVIGILATION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveTimeSpendandStatus:
                    {
                        query = @"UPDATE EXAM_INVIGILATION 
                                SET 
                                    MINUTES_SECONDS = ?MINUTES_SECONDS,COMPLETE=1
                                WHERE
                                    EXAM_INVIGILATION_ID =?EXAM_INVIGILATION_ID";
                        break;
                    }
                case ExaminationSQLCommands.FetchEitherExamChooseBasedQuestions:
                    {
                        query = @"SELECT 
                                EQ.QUIZ_ID,
                                EQ.QUESTION,
                                EQ.ANSWER_ID,
                                EQP.SECTION_ID,
                                EQP.QUESTION_TYPE,
                                EQ.SET_ID,
                                EQ.EXAM_SETTING_ID
                            FROM
                                EXAM_CHOICE_BASED_QUESTIONS AS EQ
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS EQP ON EQP.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                            WHERE
                                EQ.IS_DELETED != 1
                                    AND EQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EQ.COURSE_ID = ?COURSE_ID
                                    AND EQ.SET_ID = ?SET_ID
                                    AND EQ.QUIZ_ID NOT IN (SELECT 
                                        QUIZ_ID
                                    FROM
                                        EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS
                                    WHERE
                                        IS_DELETED != 1 AND COURSE_ID=?COURSE_ID AND STUDENT_ID=?STUDENT_ID);";
                        break;
                    }
                case ExaminationSQLCommands.SaveChooseBasedQuestionandAnswer:
                    {
                        query = @"INSERT INTO 
                                EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS
                                (COURSE_ID,
                                 STUDENT_ID, 
                                 QUIZ_ID, 
                                 IMAGE_PATH, 
                                 ACADEMIC_YEAR,
                                 MINUTES) 
                                VALUES
                                (?COURSE_ID, 
                                ?STUDENT_ID, 
                                ?QUIZ_ID, 
                                ?IMAGE_PATH, 
                                ?ACADEMIC_YEAR,
                                 ?MINUTES);";
                        break;
                    }
                case ExaminationSQLCommands.FetchChoosebaseduploadedimageByQuestionId:
                    {
                        query = @"SELECT 
                            QUIZ_SAVE_ID, QUIZ_ID, IMAGE_PATH
                        FROM
                            EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS
                        WHERE
                            QUIZ_ID = ?QUIZ_ID AND STUDENT_ID = ?STUDENT_ID
                                AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamInvigilationforStaff:
                    {
                        query = @"SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                EI.COURSE_ID,
                                CONCAT(CCR.COURSE_CODE, '-', CCR.COURSE_TITLE) AS COURSE_CODE,
                                EI.EXAM_INVIGILATOR_ID,
                                CONCAT(TIME_FORMAT(EI.START_TIME, '%h:%m:%s'),
                                        ' to ',
                                        TIME_FORMAT(EI.END_TIME, '%h:%m:%s')) AS START_TIME,
                                EI.EXAM_SETTING_ID,
                                ES.SETTING_NAME AS EXAM_NAME,
                                EI.IS_ACTIVE,
                                EI.TIMETABLE_ID
                            FROM
                                EXAM_INVIGILATION AS EI
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                    INNER JOIN
                                EXAM_ONLINE_EXAM_SETTING AS ES ON ES.ONLINE_EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                            WHERE
                                ES.IS_ACTIVE = 1 AND EI.IS_DELETED != 1
                                    AND EI.EXAM_DATE = CURDATE()
                                    AND EI.EXAM_INVIGILATOR_ID = ?EXAM_INVIGILATOR_ID
		                            -- AND TIME(NOW()) BETWEEN TIME(START_TIME) AND TIME(END_TIME) 
                                    AND ES.IS_DELETED != 1
                            GROUP BY EI.EXAM_SETTING_ID , EI.COURSE_ID,EI.TIMETABLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentsForInvigilator:
                    {
                        //query = @"SELECT 
                        //        SP.FIRST_NAME,
                        //        SP.ROLL_NO,
                        //        SP.REGISTER_NO,
                        //        EI.EXAM_INVIGILATION_ID,
                        //        EI.STUDENT_ID,
                        //        EI.COURSE_ID,
                        //        COUNT(ESL.INVIGILATION_ID) AS VIOLATION_COUNT,
                        //        CCR.COURSE_TITLE,
                        //        EI.COMPLETE,
                        //        EI.MINUTES_SECONDS,
                        //        EI.SUSPECTIONS,
                        //        EI.TOTAL_HOURS,
                        //        ESL.PUBLIC_IP,
                        //        ESL.DEVICE,
                        //        ESL.BROWSER,
                        //        CONCAT(TIME_FORMAT(EI.START_TIME, '%h:%m:%s'),
                        //                    ' to ',
                        //                    TIME_FORMAT(EI.END_TIME, '%h:%m:%s')) AS START_TIME,
                        //        EI.EXAM_INVIGILATOR_ID
                        //    FROM
                        //        EXAM_INVIGILATION AS EI
                        //            INNER JOIN
                        //        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                        //            INNER JOIN
                        //        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                        //            LEFT JOIN
                        //        EXAM_STUDENT_LOG_INFO AS ESL ON ESL.INVIGILATION_ID = EI.EXAM_INVIGILATION_ID
                        //    WHERE
                        //        EI.IS_DELETED != 1
                        //            AND EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                        //            AND EI.COURSE_ID = ?COURSE_ID
                        //            AND EI.EXAM_INVIGILATOR_ID = ?EXAM_INVIGILATOR_ID
                        //    GROUP BY ESL.INVIGILATION_ID ORDER BY VIOLATION_COUNT DESC;";
                        query = @"SELECT 
                                FIRST_NAME,
                                ROLL_NO,
                                REGISTER_NO,
                                T.EXAM_INVIGILATION_ID,
                                STUDENT_ID,
                                COURSE_ID,
                                VIOLATION_COUNT,
                                COURSE_TITLE,
                                COMPLETE,
                                MINUTES_SECONDS,
                                SUSPECTIONS,
                                TOTAL_HOURS,
                                PUBLIC_IP,
                                DEVICE,
                                BROWSER,
                                START_TIME,
                                EXAM_INVIGILATOR_ID,
                                COUNT(CM.EXAM_INVIGILATION_ID) AS MSGCOUNT,
                                MOBILE_NO
                            FROM
                                (SELECT 
                                    SP.FIRST_NAME,
                                        SP.ROLL_NO,
                                        SP.STU_MOBILENO AS MOBILE_NO,
                                        SP.REGISTER_NO,
                                        EI.EXAM_INVIGILATION_ID,
                                        EI.STUDENT_ID,
                                        EI.COURSE_ID,
                                        COUNT(ESL.INVIGILATION_ID) AS VIOLATION_COUNT,
                                        CCR.COURSE_TITLE,
                                        EI.COMPLETE,
                                        EI.MINUTES_SECONDS,
                                        EI.SUSPECTIONS,
                                        EI.TOTAL_HOURS,
                                        ESL.PUBLIC_IP,
                                        ESL.DEVICE,
                                        ESL.BROWSER,
                                        CONCAT(TIME_FORMAT(EI.START_TIME, '%h:%m:%s'), ' to ', TIME_FORMAT(EI.END_TIME, '%h:%m:%s')) AS START_TIME,
                                        EI.EXAM_INVIGILATOR_ID
                                FROM
                                    EXAM_INVIGILATION AS EI
                                INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                INNER JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                LEFT JOIN EXAM_STUDENT_LOG_INFO AS ESL ON ESL.INVIGILATION_ID = EI.EXAM_INVIGILATION_ID
                                WHERE
                                    EI.IS_DELETED != 1
                                        AND EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND EI.COURSE_ID = ?COURSE_ID
                                        AND EI.EXAM_INVIGILATOR_ID = ?EXAM_INVIGILATOR_ID
                                        AND EI.TIMETABLE_ID=?TIMETABLE_ID
                                GROUP BY EI.EXAM_INVIGILATION_ID
                                ORDER BY VIOLATION_COUNT DESC) AS T
                                    LEFT JOIN
                                EXAM_CHAT_MESSAGE AS CM ON CM.EXAM_INVIGILATION_ID = T.EXAM_INVIGILATION_ID
                            GROUP BY T.EXAM_INVIGILATION_ID ORDER BY VIOLATION_COUNT DESC;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentviolationlog:
                    {
                        query = @"SELECT 
                                ESL.PUBLIC_IP,
                                ESL.DEVICE,
                                ESL.BROWSER,
                                ESL.IMAGE_PATH,
                                ESL.LATITUDE,
                                ESL.LONGITUDE,
                                ESL.DATETIME,ESL.DESCRIPTION
                            FROM
                                EXAM_STUDENT_LOG_INFO AS ESL
                            WHERE
                                ESL.IS_DELETED != 1
                                    AND ESL.INVIGILATION_ID = ?EXAM_INVIGILATION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateCompleteStatus:
                    {
                        query = @"UPDATE EXAM_INVIGILATION 
                                SET 
                                    COMPLETE = ?COMPLETE
                                WHERE
                                    EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateSuspectedStatus:
                    {
                        query = @"UPDATE EXAM_INVIGILATION 
                            SET 
                                SUSPECTIONS = ?SUSPECTIONS
                            WHERE
                                EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSectionsByquestionpattern:
                    {
                        query = @"SELECT 
                                ES.SECTION_ID, ES.SECTION_NAME
                            FROM
                                (SELECT 
                                    EPS.SECTION_ID
                                FROM
                                    EXAM_OBJECTIVE_QUESTIONS AS EO
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                        AND EO.IS_DELETED != 1
                                        AND COURSE_ID = ?COURSE_ID UNION ALL SELECT 
                                    EPS.SECTION_ID
                                FROM
                                    EXAM_MATCH_THE_FOLLOWING_QUESTIONS AS EO
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                        AND COURSE_ID = ?COURSE_ID
                                        AND EO.IS_DELETED != 1 UNION ALL SELECT 
                                    EPS.SECTION_ID
                                FROM
                                    EXAM_FILL_IN_BLANK_QUESTIONS AS EO
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                        AND COURSE_ID = ?COURSE_ID
                                        AND EO.IS_DELETED != 1 UNION ALL SELECT 
                                    EPS.SECTION_ID
                                FROM
                                    EXAM_EITHER_OR_QUESTIONS AS EO
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                        AND COURSE_ID = ?COURSE_ID
                                        AND EO.IS_DELETED != 1 UNION ALL SELECT 
                                    EPS.SECTION_ID
                                FROM
                                    EXAM_CHOICE_BASED_QUESTIONS AS EO
                                INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS EPS ON EO.PATTERN_SECTION_ID = EPS.PATTERN_SECTION_ID
                                WHERE
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID AND SET_ID = ?SET_ID
                                        AND COURSE_ID = ?COURSE_ID
                                        AND EO.IS_DELETED != 1) AS T
                                    INNER JOIN
                                EXAM_SECTION AS ES ON ES.SECTION_ID = T.SECTION_ID
                            GROUP BY T.SECTION_ID;";
                        break;
                    }

                #region Invigilation
                case ExaminationSQLCommands.BindShuffleStudentInvigilation:
                    {
                        query = @"SELECT 
	                                    EI.EXAM_INVIGILATION_ID,
                                        TT.TIMETABLE_ID,
                                        SP.STUDENT_ID,
                                        SP.REGISTER_NO AS ROLL_NO,
                                        SP.FIRST_NAME,
                                        DATE_FORMAT(SP.DATE_OF_BIRTH,'%d/%m/%Y') AS DATE_OF_BIRTH,
                                        DATE_FORMAT(TT.EXAM_DATE,'%d/%m/%Y') AS EXAM_DATE,
                                        TIMESTAMPDIFF(MINUTE,TT.START_TIME,TT.END_TIME) AS TOTAL_HOURS,
                                        TT.ACADEMIC_YEAR,
                                        TT.START_TIME,
                                        TT.END_TIME,
                                        C.CLASS_NAME,
                                        ER.COURSE_ID
                                    FROM
                                        EXAM_REGISTRATION_?AC_YEAR AS ER
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ER.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
	                                    EXAM_TIMETABLE AS TT ON TT.COURSE_ID=ER.COURSE_ID
		                                    AND TT.EXAM_SETTING_ID=ER.EXAM_SETTING_ID
                                            AND TT.IS_DELETED!=1 AND TT.TIMETABLE_ID=?TIMETABLE_ID
                                            LEFT JOIN
                                        EXAM_INVIGILATION AS EI ON EI.STUDENT_ID = ER.STUDENT_ID
                                            AND EI.COURSE_ID = ER.COURSE_ID
                                            AND EI.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                            AND EI.IS_DELETED != 1
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID=ER.STUDENT_ID
                                            AND SC.ACADEMIC_YEAR=?AC_YEAR
                                            AND SC.IS_DELETED!=1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
                                    WHERE
                                        ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND EI.EXAM_INVIGILATION_ID IS NULL
                                            AND ER.IS_DELETED != 1
                                            AND ER.COURSE_ID = ?COURSE_ID
                                    ORDER BY C.CLASS_NAME,SP.REGISTER_NO;";
                        break;
                    }

                case ExaminationSQLCommands.FetchCoursebyExamSettingId:
                    {
                        query = @"SELECT 
                                        CCR.COURSE_ROOT_ID,
                                        CONCAT(CCR.COURSE_CODE,'( ',DATE_FORMAT(EXAM_DATE,'%d/%m/%Y'),' ) - ','( ',TIME_FORMAT(TT.START_TIME, '%h:%m:%s'),' to ',TIME_FORMAT(TT.END_TIME, '%h:%m:%s'),' ) ') AS COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        TT.TIMETABLE_ID
                                        
                                    FROM
                                        CP_COURSE_ROOT AS CCR
                                            INNER JOIN
                                        EXAM_TIMETABLE AS TT ON TT.COURSE_ID=CCR.COURSE_ROOT_ID
		                                    AND TT.IS_DELETED != 1
                                    WHERE TT.EXAM_SETTING_ID=?EXAM_SETTING_ID
	                                      AND CCR.IS_DELETED!=1
                                    ORDER BY CCR.PART;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseRootInfoByCourseId:
                    {
                        query = @"SELECT 
                                        UPPER(CCR.COURSE_CODE) AS COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS COURSE_TITLE,
                                        UPPER(D.DEPARTMENT) AS DEPARTMENT
                                    FROM
                                        CP_COURSE_ROOT AS CCR
                                            LEFT JOIN
                                        CP_DEPARTMENT AS D ON D.DEPARTMENT_ID = CCR.DEPARTMENT
                                    WHERE
                                        CCR.IS_DELETED != 1
                                            AND CCR.COURSE_ROOT_ID = ?COURSE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchShuffledStudentCountbyCourseAndSettingId:
                    {
                        query = @"SELECT 
                                        COUNT(EI.STUDENT_ID) AS STUDENT_ID
                                    FROM
                                        EXAM_INVIGILATION AS EI
                                    WHERE
                                        EI.COURSE_ID = ?COURSE_ID
                                            AND EI.EXAM_SETTING_ID = ?ONLINE_EXAM_SETTING_ID
                                            AND EI.IS_DELETED != 1;";
                        break;
                    }

                #endregion

                case ExaminationSQLCommands.SaveExamChatMessage:
                    {
                        query = @"INSERT INTO 
                                EXAM_CHAT_MESSAGE
                                (EXAM_INVIGILATION_ID,
                                MESSAGE,
                                MESSAGE_TYPE,
                                FROM_ID,TO_ID) 

                                VALUES(?EXAM_INVIGILATION_ID,
                                ?MESSAGE,
                                ?MESSAGE_TYPE,
                                ?FROM_ID,
                                ?TO_ID);";
                        break;
                    }
                case ExaminationSQLCommands.FetchChatMessagesByInvigilationId:
                    {
                        query = @"SELECT 
                                EXAM_CHAT_MESSAGE_ID,
                                EXAM_INVIGILATION_ID,
                                MESSAGE,
                                MESSAGE_TYPE,
                                FROM_ID,
                                TO_ID,
                                IS_READ,
                                DATE_FORMAT(DATE, '%d/%m/%Y') AS DATE,
                                TIME_FORMAT(DATE, '%h:%m') AS TIME
                            FROM
                                EXAM_CHAT_MESSAGE WHERE IS_DELETED!=1 AND EXAM_INVIGILATION_ID=?EXAM_INVIGILATION_ID
                            ORDER BY DATE;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamStudentLogInfo:
                    {
                        query = @"INSERT INTO `EXAM_STUDENT_LOG_INFO`
                                        (
                                        `STUDENT_ID`,
                                        `INVIGILATION_ID`,
                                        `EXAM_ID`,
                                        `COURSE_ID`,
                                        `PUBLIC_IP`,
                                        `LATITUDE`,
                                        `LONGITUDE`,
                                        `IS_VIOLATION`,
                                        `DESCRIPTION`,
                                        `IMAGE_PATH`,
                                        `DEVICE`,
                                        `BROWSER`,
                                        `ACADEMIC_YEAR`)
                                        VALUES
                                        (?STUDENT_ID,
                                        ?INVIGILATION_ID,
                                        ?EXAM_ID,
                                        ?COURSE_ID,
                                        ?PUBLIC_IP,
                                        ?LATITUDE,
                                        ?LONGITUDE,
                                        ?IS_VIOLATION,
                                        ?DESCRIPTION,
                                        ?IMAGE_PATH,
                                        ?DEVICE,
                                        ?BROWSER,
                                        ?ACADEMIC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsUserSquad:
                    {
                        query = @"SELECT 
                                    ES.EXAM_SQUAD_ID, ES.EXAM_SETTING_ID, ES.STAFF_ID
                                FROM
                                    EXAM_SQUAD AS ES
                                WHERE
                                    ES.IS_ACTIVE != 1
                                        AND ES.EXAM_SETTING_ID = (SELECT 
                                            EXAM_SETTING_ID
                                        FROM
                                            EXAM_SETTING
                                        WHERE
                                            IS_ACTIVE = 1);";
                        break;
                    }
                case ExaminationSQLCommands.FetchInvigilatorForSquad:
                    {
                        query = @"SELECT 
                            EXAM_INVIGILATION_ID,
                            EXAM_INVIGILATOR_ID,
                            FIRST_NAME,
                            STAFF_CODE,
                            MOBILE_NO,
                            EXAM_SETTING_ID,
                            EXAM_NAME,
                            COURSE_ID,
                            COURSE_CODE,
                            COURSE_TITLE,
                            EXAM_DATE,
                            SUM(COUNT) AS STUDENT_COUNT
                        FROM
                            (SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                    EI.EXAM_INVIGILATOR_ID,
                                    SP.FIRST_NAME,
                                    SP.STAFF_CODE,
                                    SP.MOBILE_NO,
                                    EI.EXAM_SETTING_ID,
                                    ES.SETTING_NAME AS EXAM_NAME,
                                    EI.COURSE_ID,
                                    CCR.COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    COUNT(EI.EXAM_INVIGILATION_ID) AS COUNT
                            FROM
                                EXAM_INVIGILATION AS EI
                            INNER JOIN STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = EI.EXAM_INVIGILATOR_ID
                            INNER JOIN EXAM_ONLINE_EXAM_SETTING  AS ES ON ES.ONLINE_EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                            INNER JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                            WHERE
                                EI.IS_DELETED != 1
                                    AND EI.EXAM_DATE = CURDATE()
                                    AND EI.EXAM_SETTING_ID IN (SELECT 
                                                        ONLINE_EXAM_SETTING_ID
                                                    FROM
                                                        EXAM_ONLINE_EXAM_SETTING
                                                    WHERE
                                                        IS_ACTIVE = 1)
                            GROUP BY EI.EXAM_INVIGILATION_ID) T
                        GROUP BY T.EXAM_INVIGILATOR_ID , T.EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentMoniterlog:
                    {
                        query = @"SELECT 
                                ESL.PUBLIC_IP,
                                ESL.DEVICE,
                                ESL.BROWSER,
                                ESL.IMAGE_PATH,
                                ESL.LATITUDE,
                                ESL.LONGITUDE,
                                ESL.DATETIME,
                                ESL.DESCRIPTION
                            FROM
                                EXAM_STUDENT_LOG_INFO AS ESL
                            WHERE
                                ESL.IS_DELETED != 1
                                    AND ESL.INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                    AND ESL.MONITER = 1;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsStudentSuspended:
                    {
                        query = @"SELECT 
                            EI.EXAM_INVIGILATION_ID,EI.STUDENT_ID,EI.COURSE_ID
                        FROM
                            EXAM_INVIGILATION AS EI
                        WHERE
                            EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                AND EI.COURSE_ID =?COURSE_ID
                                AND EI.STUDENT_ID =?STUDENT_ID
                                AND EI.SUSPECTIONS = 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAnswerSheetsByInvigilationId:
                    {
                        query = @"SELECT
                                        EI.EXAM_INVIGILATION_ID,
                                        EI.EXAM_SETTING_ID,
                                        EI.COURSE_ID,
                                        EIQ.QUIZ_ID,
                                        EQS.QUIZ_SAVE_ID,
                                        EQS.IMAGE_PATH,
                                        EQS.STUDENT_ID,
                                        IF(EQO.OPTION_ID IS NULL,
                                        EIQ.QUESTION,
                                        EQO.OPTION) AS QUESTION,
                                        '4' AS QUESTION_TYPE_ID

                                        FROM
                                        EXAM_INVIGILATION AS EI
                                        INNER JOIN
                                        EXAM_EITHER_OR_QUESTIONS AS EIQ ON EI.EXAM_SETTING_ID = EIQ.EXAM_SETTING_ID
                                        AND EI.COURSE_ID = EIQ.COURSE_ID
                                        INNER JOIN
                                        EXAM_SAVE_EITHERQUESTIONS AS EQS ON EQS.QUIZ_ID = EIQ.QUIZ_ID
                                        LEFT JOIN
                                        EXAM_EITHER_OR_OPTIONS AS EQO ON EQO.QUIZ_ID = EQS.QUIZ_ID
                                        AND EQO.OPTION_ID = EQS.OPTION_ID
                                        WHERE
                                        EI.EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                        AND EI.EXAM_SETTING_ID = (SELECT 
          ONLINE_EXAM_SETTING_ID 
        FROM
            EXAM_ONLINE_EXAM_SETTING
        WHERE
            IS_ACTIVE = 1)
                                        AND EQS.STUDENT_ID = ?STUDENT_ID
                                        AND EQS.IS_DELETED != 1
                                        AND EI.IS_DELETED != 1
                                        UNION ALL SELECT
                                        EI.EXAM_INVIGILATION_ID,
                                        EI.EXAM_SETTING_ID,
                                        EI.COURSE_ID,
                                        EIQ.QUIZ_ID,
                                        EQS.QUIZ_SAVE_ID,
                                        EQS.IMAGE_PATH,
                                        EQS.STUDENT_ID,
                                        EIQ.QUESTION,
                                        '5' AS QUESTION_TYPE_ID
                                        FROM
                                        EXAM_INVIGILATION AS EI
                                        INNER JOIN
                                        EXAM_CHOICE_BASED_QUESTIONS AS EIQ ON EI.EXAM_SETTING_ID = EIQ.EXAM_SETTING_ID
                                        AND EI.COURSE_ID = EIQ.COURSE_ID
                                        INNER JOIN
                                        EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS AS EQS ON EQS.QUIZ_ID = EIQ.QUIZ_ID
                                        WHERE
                                        EI.EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                        AND EI.EXAM_SETTING_ID = (SELECT 
          ONLINE_EXAM_SETTING_ID 
        FROM
            EXAM_ONLINE_EXAM_SETTING
        WHERE
            IS_ACTIVE = 1)
                                        AND EQS.STUDENT_ID = ?STUDENT_ID
                                        AND EQS.IS_DELETED != 1
                                        AND EI.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdatePreviewFlagInEitherType:
                    {
                        query = @"UPDATE EXAM_SAVE_EITHERQUESTIONS 
                                SET 
                                    IS_PREVIEW = ?IS_PREVIEW
                                WHERE
                                    QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdatePreviewFlagInChoiceBased:
                    {
                        query = @"UPDATE EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS 
                                SET 
                                    IS_PREVIEW = ?IS_PREVIEW
                                WHERE
                                    QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentInfoForSMS:
                    {

                        query = @"SELECT 
                                SP.FIRST_NAME,
                                CCR.COURSE_CODE,
                                CCR.COURSE_TITLE,
                                IFNULL(SP.STU_MOBILENO,
                                        IFNULL(SP.FR_MOBILE, '')) AS MOBILE_NO
                            FROM
                                EXAM_INVIGILATION AS EI
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                            WHERE
                                EI.EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                    AND EI.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchReloadingAnswerSheetsByInvigilationId:
                    {
                        query = @"SELECT
                                        EI.EXAM_INVIGILATION_ID,
                                        EI.EXAM_SETTING_ID,
                                        EI.COURSE_ID,
                                        EIQ.QUIZ_ID,
                                        EQS.QUIZ_SAVE_ID,
                                        EQS.IMAGE_PATH,
                                        EQS.STUDENT_ID,
                                        IF(EQO.OPTION_ID IS NULL,
                                        EIQ.QUESTION,
                                        EQO.OPTION) AS QUESTION,
                                        '4' AS QUESTION_TYPE_ID
                                        FROM
                                        EXAM_INVIGILATION AS EI
                                        INNER JOIN
                                        EXAM_EITHER_OR_QUESTIONS AS EIQ ON EI.EXAM_SETTING_ID = EIQ.EXAM_SETTING_ID
                                        AND EI.COURSE_ID = EIQ.COURSE_ID
                                        INNER JOIN
                                        EXAM_SAVE_EITHERQUESTIONS AS EQS ON EQS.QUIZ_ID = EIQ.QUIZ_ID
                                        LEFT JOIN
                                        EXAM_EITHER_OR_OPTIONS AS EQO ON EQO.QUIZ_ID = EQS.QUIZ_ID
                                        AND EQO.OPTION_ID = EQS.OPTION_ID
                                        WHERE
                                        EI.EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                        AND EI.EXAM_SETTING_ID = (SELECT 
          ONLINE_EXAM_SETTING_ID 
        FROM
            EXAM_ONLINE_EXAM_SETTING
        WHERE
            IS_ACTIVE = 1)
                                        AND EQS.STUDENT_ID = ?STUDENT_ID
                                        AND EQS.IS_DELETED != 1
                                        AND EQS.IS_PREVIEW=1
                                        AND EI.IS_DELETED != 1
                                        UNION ALL SELECT
                                        EI.EXAM_INVIGILATION_ID,
                                        EI.EXAM_SETTING_ID,
                                        EI.COURSE_ID,
                                        EIQ.QUIZ_ID,
                                        EQS.QUIZ_SAVE_ID,
                                        EQS.IMAGE_PATH,
                                        EQS.STUDENT_ID,
                                        EIQ.QUESTION,
                                        '5' AS QUESTION_TYPE_ID
                                        FROM
                                        EXAM_INVIGILATION AS EI
                                        INNER JOIN
                                        EXAM_CHOICE_BASED_QUESTIONS AS EIQ ON EI.EXAM_SETTING_ID = EIQ.EXAM_SETTING_ID
                                        AND EI.COURSE_ID = EIQ.COURSE_ID
                                        INNER JOIN
                                        EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS AS EQS ON EQS.QUIZ_ID = EIQ.QUIZ_ID
                                        WHERE
                                        EI.EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                        AND EI.EXAM_SETTING_ID = (SELECT 
          ONLINE_EXAM_SETTING_ID 
        FROM
            EXAM_ONLINE_EXAM_SETTING
        WHERE
            IS_ACTIVE = 1)
                                        AND EQS.STUDENT_ID = ?STUDENT_ID
                                        AND EQS.IS_DELETED != 1
                                        AND EQS.IS_PREVIEW=1
                                        AND EI.IS_DELETED != 1;
";
                        break;
                    }
                case ExaminationSQLCommands.FetchAnswerSheetsEitherQuestiontype:
                    {
                        query = @"SELECT 
                                EIQ.QUIZ_ID,
                                EIQ.QUESTION,
                                SE.QUIZ_SAVE_ID,
                                SE.STUDENT_ID,
                                '4' AS QUESTION_TYPE_ID
                            FROM
                                EXAM_SAVE_EITHERQUESTIONS AS SE
                                    INNER JOIN
                                EXAM_EITHER_OR_QUESTIONS AS EIQ ON EIQ.QUIZ_ID = SE.QUIZ_ID
                            WHERE
                                SE.QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAnswerSheetsChoicebasedQuestiontype:
                    {
                        query = @"SELECT 
                                    EIQ.QUIZ_ID,
                                    EIQ.QUESTION,
                                    SE.QUIZ_SAVE_ID,
                                    SE.STUDENT_ID,
                                    '5' AS QUESTION_TYPE_ID
                                FROM
                                    EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS AS SE
                                        INNER JOIN
                                    EXAM_CHOICE_BASED_QUESTIONS AS EIQ ON EIQ.QUIZ_ID = SE.QUIZ_ID
                                WHERE
                                    SE.QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateEitherQuestionandAnswer:
                    {
                        query = @"UPDATE EXAM_SAVE_EITHERQUESTIONS 
                                    SET 
                                        IMAGE_PATH = ?IMAGE_PATH
                                    WHERE
                                        QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateChooseBasedQuestionandAnswer:
                    {
                        query = @"UPDATE EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS 
                                SET 
                                    IMAGE_PATH = ?IMAGE_PATH
                                WHERE
                                    QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteChoiceBasedAnswerImage:
                    {
                        query = @"UPDATE EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS 
                                SET 
                                    IS_DELETED = 1
                                WHERE
                                    QUIZ_SAVE_ID = ?QUIZ_SAVE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsExamActive:
                    {
                        query = @"SELECT 
                            EXAM_INVIGILATION_ID,IS_ACTIVE
                        FROM
                            EXAM_INVIGILATION
                        WHERE
                            EXAM_SETTING_ID = ?EXAM_SETTING_ID AND STUDENT_ID = ?STUDENT_ID
                                AND COURSE_ID = ?COURSE_ID AND IS_ACTIVE=1
                                AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamEvaluationByEvaluators:
                    {
                        query = @"SELECT 
                                EE.EXAM_EVALUATION_ID,
                                EE.INVIGILATION_ID,
                                EE.DUMMY_NO,
                                EE.EVALUATOR_ID,
                                EE.EVALUATION_TYPE,
                                EI.EXAM_SETTING_ID,
                                EI.COURSE_ID,
                                CCR.COURSE_TITLE,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                CCR.COURSE_CODE,
                                EI.SET,
                                ES.SETTING_NAME AS EXAM_NAME,
                                DATE_FORMAT(EE.EVALUATION_DATE, '%Y/%m/%d') AS EVALUATION_DATE,
                                ET.EXAM_EVALUATION AS EXAM_EVALUATION_TYPE,
                                EE.IS_COMPLETED
                            FROM
                                EXAM_EVALUATION AS EE
                                    INNER JOIN
                                EXAM_INVIGILATION AS EI ON EE.INVIGILATION_ID = EI.EXAM_INVIGILATION_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                EXAM_ONLINE_EXAM_SETTING AS ES ON ES.ONLINE_EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                                    INNER JOIN
                                EXAM_SUP_EVALUATION_TYPE AS ET ON ET.EXAM_EVALUATION_TYPE_ID = EE.EVALUATION_TYPE
                            WHERE
                                EE.IS_DELETED != 1
                                    AND EE.EVALUATION_DATE =?EVALUATION_DATE
                                    AND EE.EVALUATOR_ID = (SELECT 
                                        EXAM_EVALUATOR_ID
                                    FROM
                                        EXAM_EVALUATOR AS E
                                    WHERE
                                        EXAM_SETTING_ID = (SELECT 
                                                ONLINE_EXAM_SETTING_ID
                                            FROM
                                                EXAM_ONLINE_EXAM_SETTING
                                            WHERE
                                                IS_ACTIVE = 1)
                                            AND E.STAFF_ID = ?STAFF_ID) ORDER BY SP.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoForByInvigilationId:
                    {
                        query = @"SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                EI.STUDENT_ID,
                                SP.FIRST_NAME,
                                EI.COURSE_ID,
                                CCR.COURSE_TITLE,
                                CCR.COURSE_CODE,
                                DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                ES.ONLINE_EXAM_SETTING_ID AS EXAM_SETTING_ID,
                                ES.SETTING_NAME AS EXAM_NAME,
                                EI.SET AS SET_ID,
                                TIME(EI.START_TIME) AS START_TIME,
                                TIME(EI.END_TIME) AS END_TIME,
                                SI.FIRST_NAME AS INVIGILATOR,
                                SI.MOBILE_NO,
                                SI.STAFF_ID,
                                CC.CLASS_NAME,
                                TOTAL_HOURS,
                                MINUTES_SECONDS
                            FROM
                                EXAM_INVIGILATION AS EI
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                EXAM_ONLINE_EXAM_SETTING AS ES ON ES.ONLINE_EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                                    LEFT JOIN
                                STF_PERSONAL_INFO AS SI ON SI.STAFF_ID = EI.EXAM_INVIGILATOR_ID
                            WHERE
                                EI.IS_DELETED != 1
                                    AND EI.EXAM_SETTING_ID IN (SELECT 
                                        ONLINE_EXAM_SETTING_ID
                                    FROM
                                        EXAM_ONLINE_EXAM_SETTING
                                    WHERE
                                        IS_DELETED != 1 AND IS_ACTIVE = 1)
                                    AND EI.EXAM_INVIGILATION_ID = ?EXAM_INVIGILATION_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectivesQuestionsandAnswer:
                    {
                        query = @"SELECT 
                                EOQ.QUIZ_ID,
                                EOQ.COURSE_ID,
                                ESO.STUDENT_ID,
                                ESO.STATUS,
                                EOQ.QUESTION,
                                EOO.OPTION,
                                EOO.OPTION_ID,
                                EQPS.TOTAL_MARK_FOR_EACH_SECTION,
                                EQPS.MARK_FOR_EACH_QUESTION,
                                EOQ.EXAM_SETTING_ID,
                                EQPS.QUESTION_TYPE,
                                EQPS.TO_BE_ATTEND,
                                EM.TOTAL_MARK,
                                EM.SECURED_MARK
                            FROM
                                EXAM_OBJECTIVE_QUESTIONS AS EOQ
                                    LEFT JOIN
                                EXAM_SAVE_OBJECTIVES AS ESO ON EOQ.QUIZ_ID = ESO.QUIZ_ID
                                    AND ESO.STUDENT_ID = ?STUDENT_ID
                                    LEFT JOIN
                                EXAM_OBJECTIVE_OPTIONS AS EOO ON EOO.OPTION_ID = ESO.OPTION_ID
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EOQ.PATTERN_SECTION_ID
                                    LEFT JOIN
                                EXAM_EVALUATION_MARKS AS EM ON EM.QUESTION_ID = EOQ.QUIZ_ID
                                    AND EM.QUESTION_TYPE = EQPS.QUESTION_TYPE
                                    AND EM.EVALUATION_TYPE = ?EVALUATION_TYPE
                                    AND EM.INVIGILATION_ID=?INVIGILATION_ID                                    
                            WHERE
                                    EOQ.COURSE_ID = ?COURSE_ID
                                    AND EOQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EOQ.SET_ID = ?SET_ID
                                    AND EOQ.ACADEMIC_YEAR=?AC_YEAR
                                    AND EOQ.IS_DELETED != 1
                                    AND EQPS.SECTION_ID = ?SECTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFillInTheBlankQuestionsandAnswer:
                    {
                        query = @"SELECT 
                                FBQ.QUIZ_ID,
                                FBQ.COURSE_ID,
                                ESFB.STUDENT_ID,
                                ESFB.STATUS,
                                FBQ.QUESTION,
                                FBO.OPTION,
                                FBO.OPTION_ID,
                                EQPS.TOTAL_MARK_FOR_EACH_SECTION,
                                EQPS.MARK_FOR_EACH_QUESTION,
                                EQPS.TO_BE_ATTEND,
                                FBQ.EXAM_SETTING_ID,
                                EQPS.QUESTION_TYPE,
                                EM.TOTAL_MARK,
                                EM.SECURED_MARK
                            FROM
                                EXAM_FILL_IN_BLANK_QUESTIONS AS FBQ
                                    LEFT JOIN
                                EXAM_SAVE_FILL_IN_BLANKS AS ESFB ON FBQ.QUIZ_ID = ESFB.QUIZ_ID
                                    AND ESFB.STUDENT_ID = ?STUDENT_ID
                                    LEFT JOIN
                                EXAM_FILL_IN_BLANK_OPTIONS AS FBO ON FBO.OPTION_ID = FBQ.ANSWER_ID
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = FBQ.PATTERN_SECTION_ID
                                    LEFT JOIN
                                EXAM_EVALUATION_MARKS AS EM ON EM.QUESTION_ID = FBQ.QUIZ_ID
                                    AND EM.QUESTION_TYPE = EQPS.QUESTION_TYPE
                                    AND EM.EVALUATION_TYPE = ?EVALUATION_TYPE
                                    AND EM.INVIGILATION_ID=?INVIGILATION_ID
                            WHERE
		                            FBQ.COURSE_ID = ?COURSE_ID 
		                            AND FBQ.SET_ID = ?SET_ID
                                    AND FBQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND FBQ.ACADEMIC_YEAR=?AC_YEAR
                                    AND FBQ.IS_DELETED != 1
                                    AND EQPS.SECTION_ID = ?SECTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEitherExamQuestionsandAnswer:
                    {
                        query = @"SELECT 
                                EEQ.QUIZ_ID,
                                SE.OPTION_ID,
                                SE.COURSE_ID,
                                SE.STUDENT_ID,
                                EEQ.QUESTION,
                                EQPS.TOTAL_MARK_FOR_EACH_SECTION,
                                EQPS.MARK_FOR_EACH_QUESTION,
                                EEQ.EXAM_SETTING_ID,
                                EQPS.QUESTION_TYPE,
                                EQPS.TO_BE_ATTEND,
                                EM.TOTAL_MARK,
                                EM.SECURED_MARK,
                                SE.IMAGE_PATH,
                                AK.ANSWER_KEY_PATH
                            FROM
                                EXAM_EITHER_OR_QUESTIONS AS EEQ
                                    LEFT JOIN
                                EXAM_SAVE_EITHERQUESTIONS AS SE ON EEQ.QUIZ_ID = SE.QUIZ_ID
                                    AND SE.STUDENT_ID = ?STUDENT_ID
                                    LEFT JOIN
                                EXAM_EITHER_OR_OPTIONS AS EEO ON EEO.QUIZ_ID = EEQ.QUIZ_ID
                                    AND SE.OPTION_ID = EEO.OPTION_ID
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = EEQ.PATTERN_SECTION_ID
                                    LEFT JOIN
                                EXAM_EVALUATION_MARKS AS EM ON EM.QUESTION_ID = SE.QUIZ_ID
                                    AND EM.OPTION_ID = SE.OPTION_ID
                                    AND EM.QUESTION_TYPE = EQPS.QUESTION_TYPE
                                    AND EM.EVALUATION_TYPE = ?EVALUATION_TYPE
                                    AND EM.INVIGILATION_ID=?INVIGILATION_ID
                                    LEFT JOIN
                                EXAM_ANSWER_KEYS AS AK ON AK.COURSE_ID = EEQ.COURSE_ID
                                    AND EEQ.EXAM_SETTING_ID = AK.EXAM_SETTING_ID
                                    AND AK.SET_ID = EEQ.SET_ID
                            WHERE
		                            EEQ.COURSE_ID = ?COURSE_ID
                                    AND EEQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EEQ.SET_ID = ?SET_ID
                                    AND EEQ.ACADEMIC_YEAR=?AC_YEAR
                                    AND EEQ.IS_DELETED != 1
                                    AND EQPS.SECTION_ID = ?SECTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchChooseBasedQuestionsandAnswer:
                    {
                        query = @"SELECT 
                                    ECBQ.QUIZ_ID,
                                    ECBQ.COURSE_ID,
                                    SCBQ.STUDENT_ID,
                                    ECBQ.QUESTION,
                                    EQPS.TOTAL_MARK_FOR_EACH_SECTION,
                                    EQPS.MARK_FOR_EACH_QUESTION,
                                    ECBQ.EXAM_SETTING_ID,
                                    EQPS.QUESTION_TYPE,
                                    EQPS.TO_BE_ATTEND,
                                    EM.TOTAL_MARK,
                                    EM.SECURED_MARK,
                                    SCBQ.IMAGE_PATH,
                                    AK.ANSWER_KEY_PATH
                                FROM
                                    EXAM_CHOICE_BASED_QUESTIONS AS ECBQ
                                        LEFT JOIN
                                    EXAM_SAVE_EXAM_CHOICE_BASED_QUESTIONS AS SCBQ ON ECBQ.QUIZ_ID = SCBQ.QUIZ_ID
                                        AND SCBQ.STUDENT_ID = ?STUDENT_ID
                                        INNER JOIN
                                    EXAM_QUESTION_PATTERN_SECTION AS EQPS ON EQPS.PATTERN_SECTION_ID = ECBQ.PATTERN_SECTION_ID
                                        LEFT JOIN
                                    EXAM_EVALUATION_MARKS AS EM ON EM.QUESTION_ID = SCBQ.QUIZ_ID
                                        AND EM.QUESTION_TYPE = EQPS.QUESTION_TYPE
                                        AND EM.EVALUATION_TYPE = ?EVALUATION_TYPE
                                        AND EM.INVIGILATION_ID=?INVIGILATION_ID
                                        LEFT JOIN
                                    EXAM_ANSWER_KEYS AS AK ON AK.COURSE_ID = ECBQ.COURSE_ID
                                        AND ECBQ.EXAM_SETTING_ID = AK.EXAM_SETTING_ID
                                        AND AK.SET_ID = ECBQ.SET_ID
                                WHERE
		                                ECBQ.COURSE_ID = ?COURSE_ID
                                        AND ECBQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND ECBQ.ACADEMIC_YEAR = ?AC_YEAR
                                        AND EQPS.SECTION_ID = ?SECTION_ID
                                        AND ECBQ.SET_ID = ?SET_ID
                                        AND ECBQ.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchMatchTheFollowingQuestionandAnswer:
                    {
                        query = @"";
                        break;
                    }
                case ExaminationSQLCommands.FetchEitherOptionsByQuestionId:
                    {
                        query = @"SELECT 
                                EQO.OPTION_ID, EQO.OPTION, EQO.QUIZ_ID
                            FROM
                                EXAM_EITHER_OR_OPTIONS AS EQO
                            WHERE
                                EQO.QUIZ_ID IN(?QUIZ_ID) AND EQO.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamEvaluationMarks:
                    {
                        query = @"INSERT INTO 
                                EXAM_EVALUATION_MARKS
                                (INVIGILATION_ID,
                                 EVALUATION_ID,
                                 QUESTION_ID,
                                 QUESTION_TYPE, 
                                 TOTAL_MARK, 
                                 SECURED_MARK, 
                                 EXAM_SETTING_ID,
                                 EVALUATION_TYPE,
                                 OPTION_ID, 
                                 ACADEMIC_YEAR)
                                VALUES(?INVIGILATION_ID,
                                 ?EVALUATION_ID,
                                 ?QUESTION_ID,
                                 ?QUESTION_TYPE, 
                                 ?TOTAL_MARK, 
                                 ?SECURED_MARK, 
                                 ?EXAM_SETTING_ID,
                                 ?EVALUATION_TYPE,
                                 ?OPTION_ID, 
                                 ?AC_YEAR);";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsEvaluationMarksExist:
                    {
                        query = @"SELECT 
                                EXAM_EVALUATION_MARK_ID
                            FROM
                                EXAM_EVALUATION_MARKS AS EEM
                            WHERE
		                            EEM.INVIGILATION_ID = ?INVIGILATION_ID
                                    AND EEM.QUESTION_TYPE = ?QUESTION_TYPE
                                    AND EEM.EVALUATION_ID = ?EVALUATION_ID
                                    AND EEM.EVALUATION_TYPE = ?EVALUATION_TYPE
                                    AND EEM.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EEM.QUESTION_ID=?QUESTION_ID
                                    AND EEM.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateEvaluationStatus:
                    {
                        query = @"UPDATE EXAM_EVALUATION SET IS_COMPLETED=?IS_COMPLETED WHERE EXAM_EVALUATION_ID=?EXAM_EVALUATION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchAllChoiceBasedQuestions:
                    {
                        query = @"SELECT 
                                EQ.QUIZ_ID,
                                EQ.QUESTION,						
                                EQP.SECTION_ID,
                                EQP.QUESTION_TYPE,
                                EQ.SET_ID,
                                EQ.EXAM_SETTING_ID
                            FROM
                                EXAM_CHOICE_BASED_QUESTIONS AS EQ
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS EQP ON EQP.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                                    AND SECTION_ID = ?SECTION_ID
                            WHERE
                                    EQ.IS_DELETED != 1
                                    AND EQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EQ.COURSE_ID = ?COURSE_ID
                                    AND EQ.SET_ID = ?SET_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchExamEvaluatorByExamSetting:
                    {
                        query = @"SELECT 
                                EV.EXAM_EVALUATOR_ID,
                                EV.EXAM_SETTING_ID,
                                CONCAT(`FIRST_NAME`, ' - ', STAFF_CODE) AS `STAFF_CODE`,
                                EV.STAFF_ID,
                                EV.IS_EXTERNAL
                            FROM
                                EXAM_EVALUATOR AS EV
                                    INNER JOIN
                                STF_PERSONAL_INFO AS ESTF ON ESTF.STAFF_ID = EV.STAFF_ID
                                    AND ESTF.IS_DELETED != 1
                            WHERE
                                EV.IS_DELETED != 1
                                    AND EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchBindExamEvaluationEntry:
                    {
                        //query = @"SELECT 
                        //        I.EXAM_INVIGILATION_ID AS INVIGILATION_ID,
                        //        I.TIMETABLE_ID,
                        //        SP.REGISTER_NO,
                        //        SP.STUDENT_ID,
                        //        DATE_FORMAT(I.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                        //        TIMESTAMPDIFF(MINUTE,
                        //            I.START_TIME,
                        //            I.END_TIME) AS TOTAL_HOURS,
                        //        TIME_FORMAT(I.START_TIME, '%h:%i:%s-%p') AS START_TIME,
                        //        TIME_FORMAT(I.END_TIME, '%h:%i:%s-%p') AS END_TIME,
                        //        I.ACADEMIC_YEAR
                        //    FROM
                        //        EXAM_INVIGILATION AS I
                        //            INNER JOIN
                        //        EXAM_TIMETABLE AS TT ON TT.TIMETABLE_ID = I.TIMETABLE_ID
                        //            LEFT JOIN
                        //        EXAM_EVALUATION AS EV ON EV.INVIGILATION_ID = I.EXAM_INVIGILATION_ID
                        //            AND EVALUATION_TYPE = ?EVALUATION_TYPE
                        //            INNER JOIN
                        //        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = I.STUDENT_ID
                        //    WHERE
                        //        I.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                        //            AND EV.EXAM_EVALUATION_ID IS NULL
                        //            AND I.IS_DELETED != 1                                    
                        //            AND I.TIMETABLE_ID = ?TIMETABLE_ID ORDER BY SP.REGISTER_NO;";
                        query = @"SELECT 
                                I.EXAM_INVIGILATION_ID AS INVIGILATION_ID,
                                I.TIMETABLE_ID,
                                SP.REGISTER_NO,
                                SP.ROLL_NO,
                                CC.CLASS_NAME AS SECTION_ID,
                                SP.STUDENT_ID,
                                DATE_FORMAT(I.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                TIMESTAMPDIFF(MINUTE,
                                    I.START_TIME,
                                    I.END_TIME) AS TOTAL_HOURS,
                                TIME_FORMAT(I.START_TIME, '%h:%i:%s-%p') AS START_TIME,
                                TIME_FORMAT(I.END_TIME, '%h:%i:%s-%p') AS END_TIME,
                                I.ACADEMIC_YEAR
                            FROM
                                EXAM_INVIGILATION AS I
                                    INNER JOIN
                                EXAM_TIMETABLE AS TT ON TT.TIMETABLE_ID = I.TIMETABLE_ID
                                    LEFT JOIN
                                EXAM_EVALUATION AS EV ON EV.INVIGILATION_ID = I.EXAM_INVIGILATION_ID
                                    AND EVALUATION_TYPE = ?EVALUATION_TYPE
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = I.STUDENT_ID
                                    INNER JOIN
                                stu_class AS SC ON SC.STUDENT_ID = SP.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    INNER JOIN
                                cp_classes AS CC ON CC.CLASS_ID = SC.CLASS_ID
                            WHERE
                                I.EXAM_SETTING_ID =?EXAM_SETTING_ID
                                    AND EV.EXAM_EVALUATION_ID IS NULL
                                    AND I.IS_DELETED != 1
                                    AND I.TIMETABLE_ID = ?TIMETABLE_ID
                            ORDER BY SP.REGISTER_NO;";


                        break;
                    }
                case ExaminationSQLCommands.FetchAssignedEvaluationStudentCount:
                    {
                        query = @"SELECT 
                             COUNT(EV.INVIGILATION_ID) AS STUDENT_ID
                            FROM
                                EXAM_INVIGILATION AS EI
                                    INNER JOIN
                                EXAM_EVALUATION AS EV ON EV.INVIGILATION_ID = EI.EXAM_INVIGILATION_ID  AND EVALUATION_TYPE = ?EVALUATION_TYPE
                            WHERE
                                EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID                                   
                                    AND EI.IS_DELETED != 1
                                    AND EI.TIMETABLE_ID = ?TIMETABLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupExamEvaluationDate:
                    {
                        query = @"SELECT 
                                EXAM_EVALUATION_ID,
                                DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE
                            FROM
                                EXAM_EVALUATION
                            WHERE
                                IS_DELETED != 1 AND ACADEMIC_YEAR=?AC_YEAR
                            GROUP BY EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupExamEvaluationDatebyEvaluatorId:
                    {
                        query = @"SELECT 
                                        EXAM_EVALUATION_ID,
                                        DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE
                                    FROM
                                        EXAM_EVALUATION AS EV 
                                        INNER JOIN
	                                    EXAM_EVALUATOR AS ER ON ER.EXAM_EVALUATOR_ID=EV.EVALUATOR_ID
										  AND ER.STAFF_ID = ?EVALUATOR_ID
                                    WHERE
                                        EV.IS_DELETED != 1 AND EV.ACADEMIC_YEAR = ?AC_YEAR                                           
                                    GROUP BY EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamEvaluationEntryList:
                    {
                        query = @"SELECT 
                                    EV.EXAM_EVALUATION_ID,
                                    EV.INVIGILATION_ID,
                                    EV.EVALUATOR_ID,
                                    E.STAFF_ID,
                                    CONCAT(ST.FIRST_NAME, ' - ', ST.STAFF_CODE) AS STAFF_CODE,
                                    EV.DUMMY_NO,
                                    SP.REGISTER_NO,
                                    CR.COURSE_CODE,
                                    DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    TIME_FORMAT(EI.START_TIME, '%h:%i:%s-%p') AS START_TIME,
                                    TIME_FORMAT(EI.END_TIME, '%h:%i:%s-%p') AS END_TIME
                                FROM
                                    EXAM_EVALUATION AS EV
                                        INNER JOIN
                                    EXAM_INVIGILATION AS EI ON EI.EXAM_INVIGILATION_ID = EV.INVIGILATION_ID
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EI.COURSE_ID
                                        INNER JOIN
                                    EXAM_TIMETABLE AS TT ON TT.TIMETABLE_ID = EI.TIMETABLE_ID
                                        AND TT.IS_DELETED != 1
                                        INNER JOIN
                                    EXAM_EVALUATOR AS E ON E.EXAM_EVALUATOR_ID = EV.EVALUATOR_ID
                                        AND E.IS_DELETED != 1
                                        AND E.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        INNER JOIN
                                    STF_PERSONAL_INFO AS ST ON ST.STAFF_ID = E.STAFF_ID
                                        AND ST.IS_DELETED != 1
                                WHERE
                                  EVALUATION_DATE =?EVALUATION_DATE
                                    AND EVALUATION_TYPE = ?EVALUATION_TYPE
                                    AND EV.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchLastUpdateDummyNo:
                    {
                        query = @"SELECT 
                                        EXAM_SETTING_ID, DUMMY_NO
                                    FROM
                                        EXAM_SETTING
                                    WHERE
                                        EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateLastDummyNoByExamSetting:
                    {
                        query = @"UPDATE EXAM_SETTING SET DUMMY_NO=?DUMMY_NO WHERE EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.ActiveOrDeActiveInvigilation:
                    {
                        query = @"UPDATE EXAM_INVIGILATION SET IS_ACTIVE=?IS_ACTIVE WHERE EXAM_SETTING_ID=?EXAM_SETTING_ID AND COURSE_ID=?COURSE_ID AND EXAM_INVIGILATOR_ID=?EXAM_INVIGILATOR_ID AND TIMETABLE_ID=?TIMETABLE_ID AND EXAM_INVIGILATION_ID!=0;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTimeTableByTimetableId:
                    {
                        query = @"SELECT 
                                            TIMETABLE_ID, 
                                            COURSE_ID, COURSE_CODE, 
                                            EXAM_SETTING_ID 																			
                                            from EXAM_TIMETABLE as t where t.TIMETABLE_ID=?TIMETABLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamEvaluaionGroupMarkByEvaluator:
                    {
                        query = @"SELECT 
                                    EM.INVIGILATION_ID,
                                    EM.EVALUATION_ID,
                                    SUM(IF(EM.TOTAL_MARK IS NULL,
                                        '0',
                                        EM.TOTAL_MARK)) AS TOTAL_MARK,
                                    SUM(IF(EM.SECURED_MARK IS NULL,
                                        '0',
                                        EM.SECURED_MARK)) AS SECURED_MARK,
                                    SP.REGISTER_NO,
                                    CR.COURSE_CODE,
                                    CR.COURSE_TITLE,
                                    EV.DUMMY_NO,
                                    EI.STUDENT_ID
                                FROM
                                    EXAM_EVALUATION AS EV                                     
                                        INNER JOIN
                                    EXAM_INVIGILATION AS EI ON EI.EXAM_INVIGILATION_ID = EV.INVIGILATION_ID
                                        INNER JOIN
									EXAM_EVALUATOR AS ET ON ET.EXAM_EVALUATOR_ID=EV.EVALUATOR_ID
										INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EI.COURSE_ID
                                    LEFT JOIN
                                    EXAM_EVALUATION_MARKS AS EM ON EV.EXAM_EVALUATION_ID = EM.EVALUATION_ID
                                WHERE
                                    ET.STAFF_ID =?EVALUATOR_ID
                                        AND EV.EVALUATION_DATE = ?EVALUATION_DATE
                                        AND EV.EVALUATION_TYPE=?EVALUATION_TYPE
                                GROUP BY EV.INVIGILATION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamMarksByEvaluationId:
                    {
                        query = @"SELECT 
                                    EXAM_EVALUATION_MARK_ID,
                                    QUESTION,
                                    MARK_FOR_EACH_QUESTION,
                                    TOTAL_MARK,
                                    SECURED_MARK,
                                    SECTION_NAME
                                FROM
                                    (SELECT 
                                        EM.EXAM_EVALUATION_MARK_ID,
                                            OQ.QUESTION,
                                            QS.MARK_FOR_EACH_QUESTION,
                                            EM.TOTAL_MARK,
                                            EM.SECURED_MARK,
                                            S.SECTION_NAME
                                    FROM
                                        EXAM_EVALUATION_MARKS AS EM
                                    INNER JOIN EXAM_OBJECTIVE_QUESTIONS AS OQ ON OQ.QUIZ_ID = EM.QUESTION_ID
                                        AND EM.QUESTION_TYPE = 1
                                        AND OQ.IS_DELETED != 1
                                    INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS QS ON QS.PATTERN_SECTION_ID = OQ.PATTERN_SECTION_ID
                                    INNER JOIN EXAM_SECTION AS S ON S.SECTION_ID = QS.SECTION_ID
                                    WHERE
                                        EM.EVALUATION_ID = ?EVALUATION_ID UNION SELECT 
                                        EM.EXAM_EVALUATION_MARK_ID,
                                            EQ.QUESTION,
                                            QS.MARK_FOR_EACH_QUESTION,
                                            EM.TOTAL_MARK,
                                            EM.SECURED_MARK,
                                            S.SECTION_NAME
                                    FROM
                                        EXAM_EVALUATION_MARKS AS EM
                                    INNER JOIN EXAM_EITHER_OR_QUESTIONS AS EQ ON EQ.QUIZ_ID = EM.QUESTION_ID
                                        AND EM.QUESTION_TYPE = 4
                                        AND EQ.IS_DELETED != 1
                                    INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS QS ON QS.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                                    INNER JOIN EXAM_SECTION AS S ON S.SECTION_ID = QS.SECTION_ID
                                    WHERE
                                        EM.EVALUATION_ID = ?EVALUATION_ID   
                                        AND (EM.OPTION_ID IS NULL || EM.OPTION_ID = '' ) UNION SELECT 
                                        EM.EXAM_EVALUATION_MARK_ID,
                                            EQ.QUESTION,
                                            QS.MARK_FOR_EACH_QUESTION,
                                            EM.TOTAL_MARK,
                                            EM.SECURED_MARK,
                                            S.SECTION_NAME
                                    FROM
                                        EXAM_EVALUATION_MARKS AS EM
                                    INNER JOIN EXAM_CHOICE_BASED_QUESTIONS AS EQ ON EQ.QUIZ_ID = EM.QUESTION_ID
                                        AND EM.QUESTION_TYPE = 5
                                        AND EQ.IS_DELETED != 1
                                    INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS QS ON QS.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                                    INNER JOIN EXAM_SECTION AS S ON S.SECTION_ID = QS.SECTION_ID
                                    WHERE
                                        EM.EVALUATION_ID = ?EVALUATION_ID UNION SELECT 
                                        EM.EXAM_EVALUATION_MARK_ID,
                                            OP.OPTION AS QUESTION,
                                            QS.MARK_FOR_EACH_QUESTION,
                                            EM.TOTAL_MARK,
                                            EM.SECURED_MARK,
                                            S.SECTION_NAME
                                    FROM
                                        EXAM_EVALUATION_MARKS AS EM
                                    INNER JOIN EXAM_EITHER_OR_QUESTIONS AS EQ ON EQ.QUIZ_ID = EM.QUESTION_ID
                                        AND EM.QUESTION_TYPE = 4
                                        AND EQ.IS_DELETED != 1
                                    INNER JOIN EXAM_EITHER_OR_OPTIONS AS OP ON OP.QUIZ_ID = EQ.QUIZ_ID
                                        AND OP.OPTION_ID = EM.OPTION_ID
                                        AND OP.IS_DELETED != 1
                                    INNER JOIN EXAM_QUESTION_PATTERN_SECTION AS QS ON QS.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                                    INNER JOIN EXAM_SECTION AS S ON S.SECTION_ID = QS.SECTION_ID
                                    WHERE
                                        EM.EVALUATION_ID = ?EVALUATION_ID) AS t
                                ORDER BY t.section_name;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamEvaluatorByDateandtype:
                    {
                        query = @"SELECT 
                                    EES.STAFF_ID AS EXAM_EVALUATOR_ID,
                                    CONCAT(SPI.FIRST_NAME, '- ', SPI.STAFF_CODE) AS STAFF_CODE
                                FROM
                                    EXAM_EVALUATION AS EE
                                        INNER JOIN
                                    EXAM_EVALUATOR AS EES ON EE.EVALUATOR_ID = EES.EXAM_EVALUATOR_ID
                                        INNER JOIN
                                    STF_PERSONAL_INFO AS SPI ON SPI.STAFF_ID = EES.STAFF_ID
                                WHERE
                                    EE.IS_DELETED != 1
                                        AND EE.EVALUATION_DATE = ?EVALUATION_DATE
                                        AND EE.EVALUATION_TYPE = ?EVALUATION_TYPE
                                GROUP BY EE.EVALUATOR_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchGroupExamEvaluationDates:
                    {
                        query = @"SELECT 
                                    EXAM_EVALUATION_ID,
                                    DATE_FORMAT(EVALUATION_DATE, '%d/%m/%Y') AS EVALUATION_DATE
                                FROM
                                    EXAM_EVALUATION
                                WHERE
                                    IS_DELETED != 1 AND ACADEMIC_YEAR = ?AC_YEAR                                      
                                GROUP BY EVALUATION_DATE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizsettingByQuiztype:
                    {
                        query = @"SELECT 
                                CCS.COURSE_ID,
                                CCS.CLASS_ID,
                                CCS.STAFF_ID,
                                QS.SETTING_ID,
                                QS.SETTING_NAME,
                                QS.NO_OF_QUESTIONS,
                                QS.EACH_QUESTION_MARKS,
                                QS.TOTAL_MARK,
                                QS.QUIZ_STF_ID,
                                QS.TIME,
                                DATE_FORMAT(QS.ENTRY_DATE, '%d/%m/%Y') AS ENTRY_DATE,
                                QS.ACADEMIC_YEAR,
                                DATE_FORMAT(QS.START_DATE, '%d/%m/%Y') AS START_DATE,
                                DATE_FORMAT(QS.END_DATE, '%d/%m/%Y') AS END_DATE,
                                IFNULL(QS.IS_ACTIVE, '0') AS IS_ACTIVE,
                                C.CLASS_NAME,
                                CONCAT(IFNULL(CCR.COURSE_CODE, ''),
                                        ' - ',
                                        IFNULL(CCR.COURSE_TITLE, '')) AS COURSE,
                                CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                        ' ',
                                        IFNULL(SP.LAST_NAME, '')) AS FIRST_NAME
                            FROM
                                QUIZ_SETTING AS QS
                                    INNER JOIN
                                CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLSCRSSTF_ID = QS.QUIZ_STF_ID
                                    AND CCS.IS_DELETED != 1
                                    AND CCS.ACADEMIC_YEAR = QS.ACADEMIC_YEAR
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = CCS.CLASS_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                    INNER JOIN
                                STF_PERSONAL_INFO AS SP ON SP.STAFF_ID = CCS.STAFF_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                            WHERE
                                QS.IS_DELETED != 1
                                    AND QS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND QS.QUIZ_TYPE_ID = ?QUIZ_TYPE_ID
                                    AND QS.START_DATE = ?START_DATE;";
                        break;
                    }

                case ExaminationSQLCommands.FetchExamInvigilationList:
                    {
                        query = @"SELECT 
	                                    DATE_FORMAT(ET.EXAM_DATE,'%d/%m/%Y') as EXAM_DATE,
                                        CONCAT(ET.START_TIME,' to ' , ET.END_TIME) AS EXAM_TIME,
                                        UPPER(CONCAT(CCR.COURSE_TITLE, ' ( ',CCR.COURSE_CODE,' )')) AS COURSE_CODE,
                                        C.CLASS_NAME,
                                        UPPER(CONCAT(SP.FIRST_NAME, ' ( ',SP.REGISTER_NO,' )')) AS REGISTER_NO,
                                        UPPER(CONCAT(STF.FIRST_NAME, ' ( ',STF.STAFF_CODE,' )')) AS STAFF_CODE,
                                        SS.SET_NAME
                                    FROM
                                        EXAM_INVIGILATION AS EI
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                            INNER JOIN
                                        EXAM_TIMETABLE AS ET ON ET.TIMETABLE_ID = EI.TIMETABLE_ID
                                            AND ET.IS_DELETED != 1
                                            AND ET.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            INNER JOIN
	                                    STF_PERSONAL_INFO AS STF ON STF.STAFF_ID=EI.EXAM_INVIGILATOR_ID
		                                    AND STF.IS_DELETED!=1
                                            INNER JOIN
	                                    sup_sets AS SS ON SS.SET_ID=EI.SET
		                                    INNER JOIN
	                                    STU_CLASS AS SC ON SC.STUDENT_ID=SP.STUDENT_ID
		                                    AND SC.IS_DELETED!=1
                                            AND SC.ACADEMIC_YEAR=?AC_YEAR
                                            INNER JOIN
	                                    CP_CLASSES AS C ON C.CLASS_ID=SC.CLASS_ID
                                    WHERE
                                        EI.IS_DELETED != 1
                                            AND EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND EI.ACADEMIC_YEAR = ?AC_YEAR
                                    ORDER BY C.CLASS_LEVEL,C.CLASS_YEAR,SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamSettings:
                    {
                        query = @"SELECT 
                                OES.ONLINE_EXAM_SETTING_ID,
                                OES.SETTING_NAME,
                                OES.EXAM_SETTING_ID,
                                OES.IS_NEED_CAMERA,
                                OES.IS_NEED_CHAT,
                                OES.IS_NEED_LOG,
                                OES.IS_AUTO_EVALUATION,
                                OES.IS_AUTO_START,
                                OES.ACADEMIC_YEAR,
                                OES.IS_ACTIVE,
                                ES.EXAM_NAME,
                                ET.QUIZ_TYPE_NAME AS EXAM_TYPE
                            FROM
                                EXAM_ONLINE_EXAM_SETTING AS OES
                                    INNER JOIN
                                EXAM_SETTING AS ES ON OES.EXAM_SETTING_ID = ES.EXAM_SETTING_ID
                                INNER JOIN SUP_QUIZ_TYPE AS ET ON ET.QUIZ_TYPE_ID=OES.EXAM_TYPE
                            WHERE
                                OES.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamSettingBySettingId:
                    {
                        query = @"SELECT 
                                OES.ONLINE_EXAM_SETTING_ID,
                                OES.SETTING_NAME,
                                OES.EXAM_SETTING_ID,
                                OES.IS_NEED_CAMERA,
                                OES.IS_NEED_CHAT,
                                OES.IS_NEED_LOG,
                                OES.IS_AUTO_EVALUATION,
                                OES.IS_AUTO_START,
                                OES.ACADEMIC_YEAR,
                                OES.IS_ACTIVE,
                                ES.EXAM_NAME,
                                OES.EXAM_TYPE
                            FROM
                                EXAM_ONLINE_EXAM_SETTING AS OES
                                    INNER JOIN
                                EXAM_SETTING AS ES ON OES.EXAM_SETTING_ID = ES.EXAM_SETTING_ID
                            WHERE
                                OES.IS_DELETED != 1
                                    AND OES.ONLINE_EXAM_SETTING_ID = ?ONLINE_EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveExamOnlineExamSetting:
                    {
                        query = @"INSERT INTO 
                                EXAM_ONLINE_EXAM_SETTING
                                (SETTING_NAME,EXAM_SETTING_ID,ACADEMIC_YEAR,EXAM_TYPE) 
                                VALUES(?SETTING_NAME,?EXAM_SETTING_ID,?AC_YEAR,?EXAM_TYPE);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamOnlineExamSetting:
                    {
                        query = @"UPDATE EXAM_ONLINE_EXAM_SETTING 
                                SET 
                                    SETTING_NAME = ?SETTING_NAME,
                                    EXAM_SETTING_ID = ?EXAM_SETTING_ID,
                                    EXAM_TYPE=?EXAM_TYPE
                                WHERE
                                    ONLINE_EXAM_SETTING_ID = ?ONLINE_EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteExamOnlineExamSetting:
                    {
                        query = @"UPDATE 
                                EXAM_ONLINE_EXAM_SETTING 
                                SET IS_DELETED=1 WHERE 
                                ONLINE_EXAM_SETTING_ID=?ONLINE_EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassessByTimetable:
                    {
                        query = @"SELECT 
                                C.CLASS_ID,
                                CONCAT(C.CLASS_NAME, '-', COUNT(C.CLASS_ID)) AS CLASS_NAME
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR AS ER
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ER.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    INNER JOIN
                                EXAM_TIMETABLE AS TT ON TT.COURSE_ID = ER.COURSE_ID
                                    AND TT.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                    AND TT.IS_DELETED != 1
                                    AND TT.TIMETABLE_ID = ?TIMETABLE_ID
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                            WHERE
                                ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND ER.IS_DELETED != 1
                                    AND ER.COURSE_ID = ?COURSE_ID
                            GROUP BY C.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchTimetableInfoById:
                    {
                        query = @"SELECT
                        TT.TIMETABLE_ID,
                        DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                        TIMESTAMPDIFF(MINUTE,
                            TT.START_TIME,
                            TT.END_TIME) AS TOTAL_HOURS,
                        TT.ACADEMIC_YEAR,
                        TT.START_TIME,
                        TT.END_TIME,
                        C.CLASS_NAME,
                        ER.COURSE_ID
                    FROM
                        EXAM_REGISTRATION_?AC_YEAR AS ER
                            INNER JOIN
                        STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ER.STUDENT_ID
                            AND SP.IS_DELETED != 1
                            INNER JOIN
                        EXAM_TIMETABLE AS TT ON TT.COURSE_ID = ER.COURSE_ID
                            AND TT.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                            AND TT.IS_DELETED != 1
                            AND TT.TIMETABLE_ID = ?TIMETABLE_ID
                            INNER JOIN
                        STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                            AND SC.IS_DELETED != 1
                            INNER JOIN
                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                    WHERE
                        ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                            AND ER.IS_DELETED != 1
                            AND ER.COURSE_ID =?COURSE_ID LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentForInvigilationByClassId:
                    {
                        query = @"SELECT 
                                ER.STUDENT_ID,
                                TT.TIMETABLE_ID,
                                DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                TIMESTAMPDIFF(MINUTE,
                                TT.START_TIME,
                                TT.END_TIME) AS TOTAL_HOURS,
                                TT.ACADEMIC_YEAR,
                                TT.START_TIME,
                                TT.END_TIME,
                                C.CLASS_NAME,
                                ER.COURSE_ID
                            FROM
                                EXAM_REGISTRATION_?AC_YEAR AS ER
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = ER.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    INNER JOIN
                                EXAM_TIMETABLE AS TT ON TT.COURSE_ID = ER.COURSE_ID
                                    AND TT.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                    AND TT.IS_DELETED != 1
                                    AND TT.TIMETABLE_ID = ?TIMETABLE_ID
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                    AND SC.IS_DELETED != 1
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                            WHERE
                                ER.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND ER.IS_DELETED != 1
                                    AND ER.COURSE_ID = ?COURSE_ID
                                    AND SC.CLASS_ID IN(?CLASS_ID)
                            ORDER BY C.CLASS_NAME , SP.REGISTER_NO;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsStudentExistInvigilation:
                    {
                        query = @"SELECT 
                                EXAM_INVIGILATION_ID
                            FROM
                                EXAM_INVIGILATION
                            WHERE
                                EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND STUDENT_ID = ?STUDENT_ID
                                    AND EXAM_DATE = ?EXAM_DATE
                                    AND `SET` = ?SET
                                    AND COURSE_ID = ?COURSE_ID
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamSettingByExamSettingId:
                    {
                        query = @"SELECT 
                                ONLINE_EXAM_SETTING_ID,
                                SETTING_NAME,
                                EXAM_SETTING_ID,
                                IS_NEED_CAMERA,
                                IS_NEED_CHAT,
                                IS_NEED_LOG,
                                IS_AUTO_EVALUATION,
                                IS_AUTO_START
                            FROM
                                EXAM_ONLINE_EXAM_SETTING
                            WHERE
                                ONLINE_EXAM_SETTING_ID = ?EXAM_SETTING_ID AND IS_DELETED != 1 AND IS_ACTIVE=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseInfoForOnlineExamByTime:
                    {
                        query = @"SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                EI.STUDENT_ID,
                                SP.FIRST_NAME,
                                EI.COURSE_ID,
                                CCR.COURSE_TITLE,
                                CCR.COURSE_CODE,
                                DATE_FORMAT(EI.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                ES.EXAM_SETTING_ID,
                                ES.EXAM_NAME,
                                EI.SET AS SET_ID,
                                TIME(EI.START_TIME) AS START_TIME,
                                TIME(EI.END_TIME) AS END_TIME,
                                SI.FIRST_NAME AS INVIGILATOR,
                                SI.MOBILE_NO,
                                SI.STAFF_ID,
                                CC.CLASS_NAME,TOTAL_HOURS,MINUTES_SECONDS
                            FROM
                                EXAM_INVIGILATION AS EI
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                    INNER JOIN
                                STU_CLASS AS SC ON SC.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                                    INNER JOIN
                                EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = EI.EXAM_SETTING_ID
                                    LEFT JOIN
                                STF_PERSONAL_INFO AS SI ON SI.STAFF_ID = EI.EXAM_INVIGILATOR_ID
                            WHERE
		                            EI.IS_DELETED != 1
                                    AND EI.EXAM_SETTING_ID IN (SELECT 
                                        EXAM_SETTING_ID
                                    FROM
                                        EXAM_SETTING
                                    WHERE
                                        IS_DELETED != 1 AND IS_ACTIVE = 1)
                                    AND EI.EXAM_DATE = CURDATE()
                                     AND DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s') >= DATE_FORMAT(EI.START_TIME, '%Y-%m-%d %H:%i:%s')
                                    AND DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s') <= DATE_FORMAT(EI.END_TIME, '%Y-%m-%d %H:%i:%s')                                 
                                    AND EI.STUDENT_ID = ?STUDENT_ID
		                            AND EI.COURSE_ID IN (?COURSE_ID)
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamquestionpatternsection:
                    {
                        query = @"SELECT 
                                EQ.QUIZ_ID, EQ.SET_ID, EQ.COURSE_ID, EQ.PATTERN_SECTION_ID
                            FROM
                                EXAM_OBJECTIVE_QUESTIONS AS EQ
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS QPS ON QPS.PATTERN_SECTION_ID = EQ.PATTERN_SECTION_ID
                            WHERE
                                EQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EQ.IS_DELETED != 1
                            GROUP BY EQ.PATTERN_SECTION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsEligableforAutoEvaluation:
                    {
                        query = @"SELECT 
                                PATTERN_SECTION_ID
                            FROM
                                EXAM_QUESTION_PATTERN_SECTION
                            WHERE
                                QUESTION_PATTERN_ID IN (?PATTERN_SECTION_ID)
                                    AND QUESTION_TYPE  IN (?QUESTION_TYPE) AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchObjectiveQuestionsByExamSettingId:
                    {
                        query = @"SELECT 
                                EQ.QUIZ_ID,
                                EQ.QUESTION,
                                EQ.SET_ID,
                                EQ.COURSE_ID,
                                EQ.PATTERN_SECTION_ID,
                                QPS.QUESTION_PATTERN_ID,
                                QPS.MARK_FOR_EACH_QUESTION,
                                QPS.QUESTION_TYPE
                            FROM
                                EXAM_OBJECTIVE_QUESTIONS AS EQ
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS QPS ON EQ.PATTERN_SECTION_ID = QPS.PATTERN_SECTION_ID
                            WHERE
                                EQ.IS_DELETED != 1
                                    AND EQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;

                    }
                case ExaminationSQLCommands.FetchStudentListByCourseId:
                    {
                        query = @"SELECT 
	                            EI.EXAM_INVIGILATION_ID,
                                EI.EXAM_SETTING_ID,
                                EI.COURSE_ID,
                                EI.STUDENT_ID,
                                EI.SET
                            FROM
                                EXAM_INVIGILATION AS EI
                            WHERE
                                EI.COURSE_ID = ?COURSE_ID
                                    AND EI.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND EI.IS_DELETED != 1
                            GROUP BY EI.STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.SaveAutoEvaluationMarks:
                    {
                        query = @"INSERT INTO
                                 EXAM_EVALUATION_MARKS
                                 (INVIGILATION_ID,EVALUATION_ID,QUESTION_ID,
                                 QUESTION_TYPE,TOTAL_MARK,SECURED_MARK,
                                 EXAM_SETTING_ID,EVALUATION_TYPE,ACADEMIC_YEAR) VALUES";
                        break;
                    }
                case ExaminationSQLCommands.Fetchobjectiveanswers:
                    {
                        query = @"SELECT 
                                    ESO.QUIZ_SAVE_ID,
                                    ESO.QUIZ_ID, 
                                    ESO.COURSE_ID,
                                    ESO.STATUS
                                FROM
                                    EXAM_SAVE_OBJECTIVES AS ESO
                                WHERE
                                    STUDENT_ID = ?STUDENT_ID AND QUIZ_ID = ?QUIZ_ID
                                        AND COURSE_ID = ?COURSE_ID
                                        AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFilltheblanksanswers:
                    {
                        query = @"SELECT 
                                ESF.QUIZ_SAVE_ID, 
                                ESF.QUIZ_ID, 
                                ESF.COURSE_ID,
                                ESF.STATUS
                            FROM
                                EXAM_SAVE_FILL_IN_BLANKS AS ESF
                            WHERE
                                STUDENT_ID = ?STUDENT_ID AND QUIZ_ID = ?QUIZ_ID
                                    AND COURSE_ID = ?COURSE_ID
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFilltheBlanksQuestionsByExamSettingId:
                    {
                        query = @"SELECT 
                                EQ.QUIZ_ID,
                                EQ.QUESTION,
                                EQ.SET_ID,
                                EQ.COURSE_ID,
                                EQ.PATTERN_SECTION_ID,
                                QPS.QUESTION_PATTERN_ID,
                                QPS.MARK_FOR_EACH_QUESTION,
                                QPS.QUESTION_TYPE
                            FROM
                                EXAM_FILL_IN_BLANK_QUESTIONS AS EQ
                                    INNER JOIN
                                EXAM_QUESTION_PATTERN_SECTION AS QPS ON EQ.PATTERN_SECTION_ID = QPS.PATTERN_SECTION_ID
                            WHERE
                                EQ.IS_DELETED != 1
                                    AND EQ.EXAM_SETTING_ID = ?EXAM_SETTING_ID;";
                        break;
                    }
                case ExaminationSQLCommands.CheckIsOnlneExamSettingExist:
                    {
                        query = @"
                                SELECT 
                                    ONLINE_EXAM_SETTING_ID
                                FROM
                                    EXAM_ONLINE_EXAM_SETTING
                                WHERE
                                    IS_DELETED != 1 AND EXAM_SETTING_ID=?EXAM_SETTING_ID AND EXAM_TYPE=?EXAM_TYPE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchEvaluationmarksBySettingId:
                    {
                        query = @"SELECT 
                                SP.FIRST_NAME,
                                SP.ROLL_NO,
                                SP.REGISTER_NO,
                                CCR.COURSE_CODE,
                                CCR.COURSE_TITLE,
                                SUM(SECURED_MARK) AS SECURED_MARK,
                                SUM(TOTAL_MARK) AS TOTAL_MARK
                            FROM
                                EXAM_EVALUATION_MARKS AS EM
                                    INNER JOIN
                                EXAM_INVIGILATION AS EI ON EI.EXAM_INVIGILATION_ID = EM.INVIGILATION_ID
                                    INNER JOIN
                                CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = EI.COURSE_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EI.STUDENT_ID
                            WHERE
                                EM.IS_DELETED != 1
                                    AND EM.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                            GROUP BY EM.INVIGILATION_ID
                            ORDER BY EI.COURSE_ID,SP.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamsettingsByAcyear:
                    {
                        query = @"SELECT 
                                ONLINE_EXAM_SETTING_ID AS EXAM_SETTING_ID,
                                CONCAT(SETTING_NAME, '-', SQT.QUIZ_TYPE_NAME) AS EXAM_NAME
                            FROM
                                EXAM_ONLINE_EXAM_SETTING AS OES
                                    INNER JOIN
                                SUP_QUIZ_TYPE AS SQT ON SQT.QUIZ_TYPE_ID = OES.EXAM_TYPE
                            WHERE
                                OES.IS_DELETED != 1
                                    AND OES.ACADEMIC_YEAR = ?AC_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchInternalCoursebyExamSettingId:
                    {
                        query = @"SELECT 
                                    CCR.COURSE_ROOT_ID,
                                    CONCAT(CCR.COURSE_CODE,
                                            '( ',
                                            DATE_FORMAT(EXAM_DATE, '%d/%m/%Y'),
                                            ' ) - ',
                                            '( ',
                                            TIME_FORMAT(TT.START_TIME, '%h:%m:%s'),
                                            ' to ',
                                            TIME_FORMAT(TT.END_TIME, '%h:%m:%s'),
                                            ' ) ') AS COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    TT.TIMETABLE_ID
                                FROM
                                    CP_COURSE_ROOT AS CCR
                                        INNER JOIN
                                    CIA_ONLINE_EXAM_TIMETABLE AS TT ON TT.COURSE_ID = CCR.COURSE_ROOT_ID
                                        AND TT.IS_DELETED != 1
                                WHERE
                                    TT.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        AND CCR.IS_DELETED != 1
                                ORDER BY CCR.PART;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIATimeTableByTimetableId:
                    {
                        query = @"SELECT 
                                    TIMETABLE_ID, COURSE_ID, COURSE_CODE, EXAM_SETTING_ID
                                FROM
                                    CIA_ONLINE_EXAM_TIMETABLE AS T
                                WHERE
                                    T.TIMETABLE_ID = ?TIMETABLE_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassessByCourse:
                    {
                        query = @"SELECT 
                                CLSCRSSTF_ID, CLASS_ID
                            FROM
                                CP_CLASS_COURSE_STAFF
                            WHERE
                                COURSE_ID = ?COURSE_ID AND ACADEMIC_YEAR = ?AC_YEAR
                                    AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.BindInternalExamShuffleStudentInvigilation:
                    {
                        query = @"SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                TT.TIMETABLE_ID,
                                SP.STUDENT_ID,
                                SP.REGISTER_NO AS ROLL_NO,
                                SP.FIRST_NAME,
                                DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS DATE_OF_BIRTH,
                                DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                TIMESTAMPDIFF(MINUTE,
                                    TT.START_TIME,
                                    TT.END_TIME) AS TOTAL_HOURS,
                                TT.ACADEMIC_YEAR,
                                TT.START_TIME,
                                TT.END_TIME,
                                C.CLASS_NAME,
                                TT.COURSE_ID
                            FROM
                                STU_CLASS AS SC
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                                    INNER JOIN
                                CIA_ONLINE_EXAM_TIMETABLE AS TT ON TT.COURSE_ID = ?COURSE_ID
                                    AND TT.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND TT.IS_DELETED != 1
                                    AND TT.TIMETABLE_ID = ?TIMETABLE_ID
                                    LEFT JOIN
                                EXAM_INVIGILATION AS EI ON EI.STUDENT_ID = SC.STUDENT_ID
                                    AND EI.COURSE_ID = TT.COURSE_ID
                                    AND EI.EXAM_SETTING_ID = ?ONLINE_EXAM_SETTING_ID
                                    AND EI.IS_DELETED != 1
                            WHERE
                                SC.CLASS_ID IN(?CLASS_ID) AND SC.IS_DELETED != 1 AND EI.EXAM_INVIGILATION_ID IS NULL
                                    AND SC.ACADEMIC_YEAR = ?AC_YEAR
                            GROUP BY SC.STUDENT_ID 
                            UNION SELECT 
                                EI.EXAM_INVIGILATION_ID,
                                TT.TIMETABLE_ID,
                                CLS.STUDENT_ID,
                                SP.REGISTER_NO AS ROLL_NO,
                                SP.FIRST_NAME,
                                DATE_FORMAT(SP.DATE_OF_BIRTH, '%d/%m/%Y') AS DATE_OF_BIRTH,
                                DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                TIMESTAMPDIFF(MINUTE,
                                    TT.START_TIME,
                                    TT.END_TIME) AS TOTAL_HOURS,
                                TT.ACADEMIC_YEAR,
                                TT.START_TIME,
                                TT.END_TIME,
                                C.CLASS_NAME,
                                TT.COURSE_ID
                            FROM
                                STU_COURSE_INFO AS CLS
                                    INNER JOIN
                                CP_CLASSES AS C ON C.CLASS_ID = CLS.S_CLASS_ID
                                    INNER JOIN
                                STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                    AND SP.IS_DELETED != 1
                                    AND SP.IS_LEFT != 1
                                    INNER JOIN
                                CIA_ONLINE_EXAM_TIMETABLE AS TT ON TT.COURSE_ID = 1
                                    AND TT.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                    AND TT.IS_DELETED != 1
                                    AND TT.TIMETABLE_ID = ?TIMETABLE_ID
                                    LEFT JOIN
                                EXAM_INVIGILATION AS EI ON EI.STUDENT_ID = CLS.STUDENT_ID
                                    AND EI.COURSE_ID = TT.COURSE_ID
                                    AND EI.EXAM_SETTING_ID = ?ONLINE_EXAM_SETTING_ID
                                    AND EI.IS_DELETED != 1
                            WHERE
                                CLS.S_CLASS_ID IN(?CLASS_ID) AND EI.EXAM_INVIGILATION_ID IS NULL
                                    AND CLS.IS_DELETED != 1
                                    AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                            GROUP BY CLS.STUDENT_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchClasscourseStaffByCourseId:
                    {
                        query = @"SELECT 
                                C.CLASS_ID,C.CLASS_NAME
                            FROM
                                CP_CLASS_COURSE_STAFF AS CCS
	                            INNER JOIN CP_CLASSES AS C ON C.CLASS_ID=CCS.CLASS_ID
                            WHERE
                                CCS.COURSE_ID = ?COURSE_ID AND CCS.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CCS.IS_DELETED != 1 GROUP BY C.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIATimetableInfoById:
                    {
                        query = @"SELECT 
                                TT.TIMETABLE_ID,
                                DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                TIMESTAMPDIFF(MINUTE,
                                    TT.START_TIME,
                                    TT.END_TIME) AS TOTAL_HOURS,
                                TT.ACADEMIC_YEAR,
                                TT.START_TIME,
                                TT.END_TIME,
                                TT.COURSE_ID
                            FROM
                                CIA_ONLINE_EXAM_TIMETABLE AS TT
                            WHERE
                                TT.IS_DELETED != 1 AND TT.COURSE_ID = ?COURSE_ID
                            LIMIT 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStudentForInternalInvigilationByClassId:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    TT.TIMETABLE_ID,
                                    DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    TIMESTAMPDIFF(MINUTE,
                                        TT.START_TIME,
                                        TT.END_TIME) AS TOTAL_HOURS,
                                    TT.ACADEMIC_YEAR,
                                    TT.START_TIME,
                                    TT.END_TIME,
                                    C.CLASS_NAME,
                                    TT.COURSE_ID
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                        INNER JOIN
                                    CIA_ONLINE_EXAM_TIMETABLE AS TT ON TT.COURSE_ID = ?COURSE_ID                                       
                                        AND TT.IS_DELETED != 1
                                        AND TT.TIMETABLE_ID = ?TIMETABLE_ID
                                WHERE
                                    SC.CLASS_ID IN (?CLASS_ID)
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                GROUP BY SC.STUDENT_ID 
                                UNION SELECT 
                                    CLS.STUDENT_ID,
                                    TT.TIMETABLE_ID,
                                    DATE_FORMAT(TT.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                    TIMESTAMPDIFF(MINUTE,
                                        TT.START_TIME,
                                        TT.END_TIME) AS TOTAL_HOURS,
                                    TT.ACADEMIC_YEAR,
                                    TT.START_TIME,
                                    TT.END_TIME,
                                    C.CLASS_NAME,
                                    TT.COURSE_ID
                                FROM
                                    STU_COURSE_INFO AS CLS
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.CLASS_ID = CLS.S_CLASS_ID
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = CLS.STUDENT_ID
                                        AND SP.IS_DELETED != 1
                                        AND SP.IS_LEFT != 1
                                        INNER JOIN
                                    CIA_ONLINE_EXAM_TIMETABLE AS TT ON TT.COURSE_ID = ?COURSE_ID                                    
                                        AND TT.IS_DELETED != 1
                                        AND TT.TIMETABLE_ID =?TIMETABLE_ID
                                WHERE
                                    CLS.S_CLASS_ID IN (?CLASS_ID)
                                        AND CLS.IS_DELETED != 1
                                        AND CLS.ACADEMIC_YEAR = ?AC_YEAR
                                GROUP BY CLS.STUDENT_ID;";
                        break;
                    }

                case ExaminationSQLCommands.FetchArrearExamCourseByStaffId:
                    {
                        query = @"SELECT 
                                        ET.COURSE_ID AS COURSE_ROOT_ID,
                                        ET.COURSE_CODE
                                    FROM
                                        ARREAR_EXAM_COURSE_STAFF AS AE
                                            INNER JOIN
                                        ARREAR_EXAM_TIMETABLE AS ET ON ET.COURSE_ID = AE.COURSE_ID
                                            AND ET.EXAM_SETTING_ID = (SELECT 
                                                EXAM_SETTING_ID
                                            FROM
                                                EXAM_SETTING
                                            WHERE
                                                IS_ACTIVE = 1)
		                                    AND ET.IS_DELETED!=1
                                    WHERE
                                        AE.STAFF_ID = ?STAFF_ID
                                            AND AE.EXAM_SETTING_ID = ET.EXAM_SETTING_ID
                                            AND AE.IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamGoogleMeetForCourseStaffbyStaffId:
                    {
                        query = @"SELECT 
                                        C.CLASS_CODE,
                                        C.CLASS_NAME,
                                        ET.EXAM_TIME,
                                        C.ONLINE_CLASS_LINK
                                    FROM
                                        EXAM_TIMETABLE AS ET
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CCS.COURSE_ID = ET.COURSE_ID
                                            AND CCS.ACADEMIC_YEAR = ET.ACADEMIC_YEAR
                                            AND CCS.STAFF_ID=?STAFF_ID
                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CCS.SEMESTER_TYPE_ID
                                          --  AND ST.IS_ACTIVE = 1
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ET.EXAM_SETTING_ID
		                                    AND ES.ACADEMIC_YEAR=ET.ACADEMIC_YEAR
                                            AND ES.IS_ACTIVE = 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = CCS.CLASS_ID
                                    WHERE
                                        ET.ACADEMIC_YEAR = ?AC_YEAR
		                                    AND ET.EXAM_DATE=CURDATE()
                                             AND IF(START_TIME<=TIME_FORMAT(CURTIME(),'%h:%i:%s'),'1','0')=1
											  AND IF(END_TIME>=TIME_FORMAT(CURTIME(),'%h:%i:%s') ,'1','0')=1
                                            AND ET.IS_DELETED!=1
                                    ORDER BY C.CLASS_LEVEL,C.CLASS_YEAR,C.SHIFT;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamGoogleMeetForAdmin:
                    {
                        query = @"SELECT 
                                        C.CLASS_CODE,
                                        C.CLASS_NAME,
                                        ET.EXAM_TIME,
                                        GROUP_CONCAT(SP.STAFF_CODE) AS STAFF_CODE,
                                        GROUP_CONCAT(SP.FIRST_NAME) AS FIRST_NAME,
