                                            AND CCS.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CCS.SEMESTER_TYPE_ID
                                         --   AND ST.IS_ACTIVE = 1
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ET.EXAM_SETTING_ID
		                                    AND ES.ACADEMIC_YEAR=ET.ACADEMIC_YEAR
                                            AND ES.IS_ACTIVE = 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = CCS.CLASS_ID
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SP ON SP.STAFF_ID=CCS.STAFF_ID
                                            AND SP.IS_DELETED!=1
                                    WHERE
                                        ET.ACADEMIC_YEAR = ?AC_YEAR
		                                    AND ET.EXAM_DATE=CURDATE()
                                             AND IF(START_TIME<=TIME_FORMAT(CURTIME(),'%h:%i:%s'),'1','0')=1
											 AND IF(END_TIME>=TIME_FORMAT(CURTIME(),'%h:%i:%s') ,'1','0')=1
                                            AND ET.IS_DELETED!=1
                                    GROUP BY C.CLASS_ID
                                    ORDER BY C.CLASS_LEVEL,C.CLASS_YEAR,C.SHIFT;";
