                case ExaminationSQLCommands.FetchArrearExamAnswerbyCourseId:
                    {
                        query = @"SELECT ROLL_NO,FIRST_NAME,COURSE_CODE FROM ARREAR_STUDENT_REGISTRATION WHERE COURSE_ID=?COURSE_ID AND IS_DELETED!=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassesbyUserId:
                    {
                        query = @"SELECT 
                                        CLS.CLASS_ID,
                                        CONCAT(IFNULL(CLS.CLASS_CODE, ''),
                                                ' ',
                                                IFNULL(CONCAT('(', SPM.PROGRAMME_MODE, ') - '),
                                                        ''),
                                                IFNULL(CONCAT(' SHIFT - ', SH.SHIFT_NAME), '')) AS CLASS_NAME,
                                         CONCAT(IFNULL(CLS.CLASS_NAME, ''),' ',
                                                IFNULL(CONCAT(' SHIFT - ', SH.SHIFT_NAME), '')) AS CLASS_CODE
                                    FROM
                                        STU_CLASS AS SC
                                        INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = SC.CLASS_ID
                                            LEFT JOIN
                                        CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID = CLS.PROGRAMME_GROUP_ID
                                            AND CPG.PROGRAMME_MODE = CLS.PROGRAMME_MODE
                                            AND CPG.SHIFT = CLS.SHIFT
                                            LEFT JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPG.PROGRAMME_ID
                                            LEFT JOIN
                                        SUP_SHIFT AS SH ON SH.SHIFT_ID = CPG.SHIFT
                                            LEFT JOIN
                                        SUP_PROGRAMME_MODE AS SPM ON SPM.PROGRAMME_MODE_ID = CPG.PROGRAMME_MODE
                                    WHERE
                                        CLS.IS_DELETED != 1
                                        AND SC.STUDENT_ID = ?STUDENT_ID
                                    ORDER BY CLS.CLASS_TYPE,CLS.CLASS_LEVEL,CLS.PROGRAMME_GROUP_ID,CLS.CLASS_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassesbyUserId1:
                    {
                        query = @"SELECT 
                                        CLS.CLASS_ID,
                                        CONCAT(IFNULL(CLS.CLASS_CODE, ''),
                                                ' ',
                                                IFNULL(CONCAT('(', SPM.PROGRAMME_MODE, ') - '),
                                                        ''),
                                                IFNULL(CONCAT(' SHIFT - ', SH.SHIFT_NAME), '')) AS CLASS_NAME,
                                         CONCAT(IFNULL(CLS.CLASS_NAME, ''),' ',
                                                IFNULL(CONCAT(' SHIFT - ', SH.SHIFT_NAME), '')) AS CLASS_CODE
                                    FROM
                                        CP_CLASSES AS CLS
                                            LEFT JOIN
                                        CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID = CLS.PROGRAMME_GROUP_ID
                                            AND CPG.PROGRAMME_MODE = CLS.PROGRAMME_MODE
                                            AND CPG.SHIFT = CLS.SHIFT
                                            LEFT JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPG.PROGRAMME_ID
                                            LEFT JOIN
                                        SUP_SHIFT AS SH ON SH.SHIFT_ID = CPG.SHIFT
                                            LEFT JOIN
                                        SUP_PROGRAMME_MODE AS SPM ON SPM.PROGRAMME_MODE_ID = CPG.PROGRAMME_MODE
                                    WHERE
                                        CLS.IS_DELETED != 1
                                    ORDER BY CLS.CLASS_TYPE,CLS.CLASS_LEVEL,CLS.PROGRAMME_GROUP_ID,CLS.CLASS_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassesbyUserId2:
                    {
                        query = @"SELECT 
                                        CLS.CLASS_ID,
                                        CONCAT(IFNULL(CLS.CLASS_CODE, ''),
                                                ' ',
                                                IFNULL(CONCAT('(', SPM.PROGRAMME_MODE, ') - '),
                                                        ''),
                                                IFNULL(CONCAT(' SHIFT - ', SH.SHIFT_NAME), '')) AS CLASS_NAME,
                                         CONCAT(IFNULL(CLS.CLASS_NAME, ''),' ',
                                                IFNULL(CONCAT(' SHIFT - ', SH.SHIFT_NAME), '')) AS CLASS_CODE
                                    FROM
                                        CP_CLASSES AS CLS
                                            LEFT JOIN
                                        CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID = CLS.PROGRAMME_GROUP_ID
                                            AND CPG.PROGRAMME_MODE = CLS.PROGRAMME_MODE
                                            AND CPG.SHIFT = CLS.SHIFT
                                            LEFT JOIN
                                        CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPG.PROGRAMME_ID
                                            LEFT JOIN
                                        SUP_SHIFT AS SH ON SH.SHIFT_ID = CPG.SHIFT
                                            LEFT JOIN
                                        SUP_PROGRAMME_MODE AS SPM ON SPM.PROGRAMME_MODE_ID = CPG.PROGRAMME_MODE
                                    WHERE
                                        CLS.IS_DELETED != 1
                                        AND CLS.CLASS_TYPE = 2
                                    ORDER BY CLS.CLASS_TYPE,CLS.CLASS_LEVEL,CLS.PROGRAMME_GROUP_ID,CLS.CLASS_YEAR;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOnlineExamGoogleMeetForStudent:
                    {
                        query = @"SELECT 
                                        ET.COURSE_CODE AS COURSE,
                                        ET.EXAM_TIME,
                                        IFNULL(CC.ONLINE_CLASS_LINK,C.ONLINE_CLASS_LINK) ONLINE_CLASS_LINK
                                    FROM
                                        EXAM_TIMETABLE AS ET
                                            INNER JOIN
                                        EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.COURSE_ID = ET.COURSE_ID
                                            AND ER.IS_DELETED != 1
                                            AND ER.EXAM_SETTING_ID = ET.EXAM_SETTING_ID
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID = ER.STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                            AND SC.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                             LEFT JOIN
										CP_CLASSES AS CC ON CC.COURSE_ID=ER.COURSE_ID
											AND CC.SHIFT=C.SHIFT
                                    WHERE
                                        ET.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ET.EXAM_SETTING_ID = (SELECT 
                                                EXAM_SETTING_ID
                                            FROM
                                                EXAM_SETTING
                                            WHERE
                                                IS_ACTIVE = 1)
		                                    AND SC.STUDENT_ID=?STUDENT_ID
		                                    AND ET.IS_DELETED!=1
                                            AND ET.EXAM_DATE=CURDATE()
                                            AND IF(START_TIME<=TIME_FORMAT(CURTIME(),'%h:%i:%s'),'1','0')=1
		                                    AND IF(END_TIME>=TIME_FORMAT(CURTIME(),'%h:%i:%s') ,'1','0')=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchQuizQuestionBySettingId:
                    {
                        query = @"SELECT QUIZ_ID,SETTING_ID FROM QUIZ_OBJECTIVE_QUESTIONS WHERE SETTING_ID=?SETTING_ID AND IS_DELETED!=1 ;";
                        break;
                    }
                case ExaminationSQLCommands.DeleteQuizBySettingId:
                    {
                        query = @"DELETE FROM QUIZ_OBJECTIVE_QUESTIONS WHERE SETTING_ID=?SETTING_ID AND QUIZ_ID!=0;
                                   DELETE FROM QUIZ_OBJECTIVE_OPTIONS WHERE SETTING_ID=?SETTING_ID AND OPTION_ID!=0; ";
                        break;
                    }
                case ExaminationSQLCommands.UpdateQuizAnswerForObjExamQuestions:
                    {
                        query = @"UPDATE QUIZ_OBJECTIVE_QUESTIONS 
                                SET 
                                    ANSWER_ID = ?ANSWER_ID
                                WHERE
                                    QUIZ_ID = ?QUIZ_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseListbySemesterType:
                    {
                        query = @"SELECT 
                                        COURSE_ROOT_ID,
                                        CLSCRSSTF_ID,
                                       concat( UPPER(CCR.COURSE_TITLE) ,' - ',ccr.COURSE_CODE) AS 'COURSE_TITLE'
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CCS
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CCS.CLASS_ID
                                            AND CLS.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCS.COURSE_ID
                                            INNER JOIN
                                        SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CCS.SEMESTER_TYPE_ID
                                            AND ST.IS_ACTIVE = 1
                                    WHERE
                                       
                                             CCS.IS_DELETED != 1
                                            AND CCR.IS_DELETED != 1
                                            AND CCS.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY CCR.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassListbyCourseID:
                    {
                        query = @"SELECT 
                                        CS.CLASS_ID,
                                        CLS.CLASS_NAME,
                                        CLS.PROGRAMME_GROUP_ID,
                                        CLS.CLASS_LEVEL,
                                        CLS.SHIFT,
                                        CLS.PROGRAMME_MODE,
                                        CLS.DEPARTMENT
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CS
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CS.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS RT ON RT.COURSE_ROOT_ID = CS.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CS.SEMESTER_TYPE_ID
                                            AND ST.IS_ACTIVE = 1
                                    WHERE
                                        CS.COURSE_ID = ?COURSE_ID 
                                        AND CS.IS_DELETED != 1
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY CS.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.GetSettingInfoByClassCourseForAdmin:
                    {
                        query = @"SELECT 
                                        SETTING_ID,
                                        SETTING_NAME
                                    FROM
                                        QUIZ_SETTING AS QS
                                            INNER JOIN
                                        CP_CLASS_COURSE_STAFF AS CCS ON CLSCRSSTF_ID= QS.QUIZ_STF_ID
                                    WHERE
                                        QS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCS.CLASS_ID = ?CLASS_ID
                                            AND CCS.COURSE_ID = ?COURSE_ID
                                            AND QS.IS_DELETED!=1 AND CCS.IS_DELETED!=1;";
                        break;
                    }
                #region  Cia fail list for COE
                case ExaminationSQLCommands.FetchCourseByYearAndClassIdAndSemesterIdforHOD:
                    {
                        query = @"SELECT 
                                        CCS.CLASS_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        CCR.SEMESTER_ID,
                                        CCR.UGC_COURSE_TYPE,
                                        CCR.PROGRAMME_LEVEL_ID
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                            INNER JOIN
                                        CP_CLASSES AS CCS ON CCS.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                           -- AND CCS.CLASS_ID = ?CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                            AND CCR.SEMESTER_ID IN (?SEMESTER_ID) 
                                            INNER JOIN
										ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID=CCS.PROGRAMME_GROUP_ID
											AND SEM.SEMESTER=CCR.SEMESTER_ID
                                            AND SEM.ACADEMIC_YEAR=CCP.ACADEMIC_YEAR
                                            AND SEM.IS_DELETED!=1
                                            INNER JOIN
										ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR=CCS.CLASS_YEAR
											AND AB.ACADEMIC_YEAR_ID=(SELECT ACADEMIC_YEAR_ID FROM ACADEMIC_YEAR WHERE AC_YEAR=?AC_YEAR)
                                            AND AB.BATCH_ID=SEM.BATCH
                                    WHERE
                                        CCP.ACADEMIC_YEAR = ?AC_YEAR
									   -- AND CCS.CLASS_LEVEL= ?APPLICATION_TYPE_ID
                                       -- AND CCS.CLASS_YEAR= ?CLASS_YEAR
                                          AND CCS.CLASS_ID in(?CLASS_ID)
                                            AND CCP.IS_DELETED != 1
                                    GROUP BY CCR.COURSE_ROOT_ID
                                    ORDER BY CCR.PART;";
                        break;
                    }
                case ExaminationSQLCommands.BindYearWishCIAFailMarksForHOD:
                    {

                        query = @"SELECT 
                                    IF(SUM(IFNULL(INSTANT, 0)) != 0,
                                        SUM(IFNULL(INSTANT, 0)),
                                        SUM(IFNULL(CUMULATIVE, 0))) TOTAL,
                                    STUDENT_ID,
                                    ROLL_NO,
                                    REGISTER_NO,
                                    PROGRAMME_GROUP_ID,
                                    UPPER(NAME) AS 'NAME',
                                    COURSE_ID,
                                    BATCH,
                                    CLASSLEVEL,
                                    CLASS_ID
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN CIA.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN CIA.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            IF(CIA.COMPONENT = 'INSTANT', COURSE_GROUP_MARK, 0) AS INSTANT,
                                            C.CLASS_ID,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO,
                                            SP.REGISTER_NO,
                                            CCP.PROGRAMME_GROUP_ID,
                                            CCP.COURSE_ID,
                                            SB.BATCH,
                                            CLASSLEVEL,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS 'NAME'
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                    INNER JOIN CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                    INNER JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                    INNER JOIN CP_COURSE_TYPE_GROUP AS CTG ON CTG.COURSE_TYPE_ID = CCR.COURSE_TYPE
                                    INNER JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_ID = CTG.GROUP_ID
                                    INNER JOIN SUP_CIA_COMPONENTS AS CIA ON CIA.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        AND CIA.IS_DELETED != 1
                                    INNER JOIN STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                        AND SC.ACADEMIC_YEAR = CCP.ACADEMIC_YEAR
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                    INNER JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.SEMESTER_ID IN (?SEMESTER_ID)
                                        AND CGM.COURSE_ID = CCP.COURSE_ID
                                        AND CGM.COURSE_GROUP_ID = CGC.CIA_GROUP_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    INNER JOIN SUP_BATCHES AS SB ON SB.BATCH_ID = SC.BATCH
                                    INNER JOIN sup_class_level AS CL ON CL.CLASSLEVELID = C.CLASS_LEVEL
                                    WHERE
                                        C.CLASS_ID IN (?CLASS_ID)
                                            AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND CCP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            AND SP.IS_DELETED != 1
                                    GROUP BY SP.STUDENT_ID , CCP.COURSE_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID , COURSE_ID;";
                        //               query = @"SELECT
