                case ExaminationSQLCommands.FetchHallTicketValidationActiveSetting:
                    {
                        query = @"SELECT 
                                    HALL_TICKET_VALIDATION_ID, 
                                    STUDENT_ID,
                                    REASON
                                FROM
                                    HALL_TICKET_VALIDATION AS HTV
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = HTV.EXAM_SETTING_ID
                                        AND ES.IS_ACTIVE = 1
                                WHERE
                                    HTV.IS_DELETED != 1
                                        AND HTV.STUDENT_ID = ?STUDENT_ID
                                        AND HTV.ACADEMIC_YEAR = ?AC_YEAR
                                        AND ES.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchStuDueDetailsForHallTicket:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    FIRST_NAME,
                                    REGISTER_NO,
                                    CD.DEPARTMENT,
                                    ROLL_NO,
                                    SC.ACADEMIC_YEAR,
                                    SUM(IFNULL(sfd.TERMFEE1, 0)) - SUM(IFNULL(sfd.TERMFEE1PAID, 0)) + SUM(IFNULL(sfd.TERMFEE2, 0)) - SUM(IFNULL(sfd.TERMFEE2PAID, 0)) AS COLLEGE_FEE,
                                    SUM(IFNULL(hfs.CREDIT, 0)) - SUM(IFNULL(hfs.DEBIT, 0)) AS HOSTELFEEDUE,
                                    SUM(IFNULL(bfs.B_CREDIT, 0)) - SUM(IFNULL(bfs.B_DEBIT, 0)) AS BUSFEEDUE,
                                    IFNULL(EF.EXAM_FEE, 0) AS EXAMFEEDUE,
                                    (
                                        GREATEST(SUM(IFNULL(sfd.TERMFEE1, 0)) - SUM(IFNULL(sfd.TERMFEE1PAID, 0)), 0)
                                        + GREATEST(SUM(IFNULL(sfd.TERMFEE2, 0)) - SUM(IFNULL(sfd.TERMFEE2PAID, 0)), 0)
                                        + GREATEST(SUM(IFNULL(hfs.CREDIT, 0)) - SUM(IFNULL(hfs.DEBIT, 0)), 0)
                                        + GREATEST(SUM(IFNULL(bfs.B_CREDIT, 0)) - SUM(IFNULL(bfs.B_DEBIT, 0)), 0)
                                        + IFNULL(EF.EXAM_FEE, 0)
                                    ) AS TOTAL_DUE_AMOUNT,
                                    IFNULL(SHSA.IS_APPROVED, 0) AS IS_APPROVED,
                                        es.EXAM_SETTING_ID
                                FROM
                                    STU_CLASS AS SC
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_DEPARTMENT AS CD ON CD.DEPARTMENT_ID = CC.DEPARTMENT
                                        LEFT JOIN
                                    STU_FEE_DUE_INFO AS sfd ON sfd.STUDENT_ID = SP.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = sfd.ACADEMIC_YEAR
                                        AND sfd.IS_DELETED != 1
                                        LEFT JOIN
                                    EXAM_SETTING AS ES ON ES.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND es.IS_DELETED != 1 AND ES.IS_ACTIVE=1
                                        LEFT JOIN
                                    EXAM_HALLTICKET_SPECIAL_APPROVALS AS SHSA ON SHSA.EXAM_SETTING_ID = es.EXAM_SETTING_ID
                                        AND SHSA.STUDENT_ID = SP.STUDENT_ID
                                        AND SHSA.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SHSA.IS_DELETED != 1

                                        LEFT JOIN
                                    (SELECT 
                                        student_id,
                                            SUM(IFNULL(CREDIT, '0')) AS CREDIT,
                                            SUM(IFNULL(DEBIT, '0')) AS DEBIT
                                    FROM
                                        hostel_fee_student_account AS hs
                                    WHERE
                                        hs.IS_DELETED != 1
                                            AND ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY STUDENT_ID) AS hfs ON hfs.STUDENT_ID = sc.student_id
                                        LEFT JOIN
                                    (SELECT 
                                        student_id,
                                            SUM(IFNULL(CREDIT, '0')) AS B_CREDIT,
                                            SUM(IFNULL(DEBIT, '0')) AS B_DEBIT
                                    FROM
                                        bus_fee_student_account AS bs
                                    WHERE
                                        bs.IS_DELETED != 1
                                            AND bs.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY STUDENT_ID) AS bfs ON bfs.STUDENT_ID = sc.student_id
                                        LEFT JOIN
                                    (SELECT 
                                        FSA.STUDENT_ID,
                                        CAST(GREATEST(SUM(IFNULL(FSA.CREDIT, 0)) - SUM(IFNULL(FSA.DEBIT, 0)), 0) AS SIGNED) AS EXAM_FEE
                                    FROM
                                        FEE_STUDENT_ACCOUNT AS FSA
                                    INNER JOIN FEE_FREQUENCY_FEE_MODE AS FFF ON FFF.FREQUENCY_ID = FSA.FREQUENCY_ID
                                    INNER JOIN SUP_FEE_FREQUENCY AS SFF ON SFF.FREQUENCY_ID = FFF.FREQUENCY_ID
                                    INNER JOIN SUP_FREQUENCY_TYPE AS SFT ON SFT.FREQUENCY_TYPE_ID = FFF.FEE_MODE
                                    INNER JOIN ACADEMIC_YEAR AS AY ON AY.AC_YEAR = SFF.ACADEMIC_YEAR AND AY.ACTIVE_YEAR = 1 AND AY.IS_DELETED <> 1
                                    INNER JOIN SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID = SFF.SEMESTER_TYPE AND SST.IS_ACTIVE = 1 AND SST.IS_DELETED <> 1
                                    WHERE
                                        SFT.FREQUENCY_TYPE_ID = 1
                                        AND FSA.IS_DELETED <> 1
                                        AND SFF.IS_DELETED <> 1
                                    GROUP BY FSA.STUDENT_ID) EF ON EF.STUDENT_ID = SC.STUDENT_ID
                                WHERE
                                    SP.IS_DELETED != 1
                                    -- AND SHSA.IS_APPROVED != 1
                                        AND sc.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SC.STUDENT_ID = ?STUDENT_ID
                                GROUP BY SP.STUDENT_ID
                                HAVING TOTAL_DUE_AMOUNT > 0 AND (IS_APPROVED = 0 OR (IS_APPROVED = 1 AND EXAMFEEDUE > 0));";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingIdbyAcYear:
                    {
                        query = @" SELECT 
                                        EXAM_NAME, EXAM_SETTING_ID
                                    FROM
                                        EXAM_SETTING
                                    WHERE
                                        ACADEMIC_YEAR = ?AC_YEAR
                                            -- AND SEMESTER_TYPE = ?SEMESTER_TYPE
                                            AND IS_ACTIVE = 1
                                            AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchHallticketDAlreadyExistOrNot:
                    {
                        query = @"SELECT 
                                        spi.STUDENT_ID,
                                        ccr.COURSE_ROOT_ID as COURSE_ID,
                                        HALL_TICKET_ID
                                    FROM
                                        stu_personal_info AS spi
                                            LEFT JOIN
                                        cp_course_root AS ccr ON ccr.COURSE_CODE = ?COURSE_CODE
                                            LEFT JOIN
                                        stu_hall_ticket_info AS sti ON spi.STUDENT_ID = sti.student_id
                                            AND ccr.course_root_id = sti.COURSE_ID
                                            AND sti.IS_DELETED != 1
                                            AND sti.ACADEMIC_YEAR = ?AC_YEAR
                                            AND sti.SEMESTER_TYPE = ?SEMESTER_TYPE
                                    WHERE
                                         spi.ROLL_NO = ?ROLL_NO  having (COURSE_ID is not null and STUDENT_ID is not null);";
                        break;
                    }
                case ExaminationSQLCommands.UpdateStuHallTicket:
                    {
                        query = @"UPDATE STU_HALL_TICKET_INFO
                                                    set 
                                                    STUDENT_ID=?STUDENT_ID,
                                                    REGISTER_NO=?REGISTER_NO,
                                                    DATE_OF_EXAM=?DATE_OF_EXAM,
                                                    SESSION_NAME=?SESSION_NAME,
                                                    HALL_NAME=?HALL_NAME,
                                                    ELIGIBLE_TYPE=?ELIGIBLE_TYPE,
                                                    ACADEMIC_YEAR=?ACADEMIC_YEAR,
                                                    SEMESTER_TYPE=?SEMESTER_TYPE,
                                                    COURSE_ID=?COURSE_ID,
                                                    EXAM_SETTING_ID=?EXAM_SETTING_ID,
                                                    FIRST_NAME=?FIRST_NAME,
                                                    DATE_OF_BIRTH=?DATE_OF_BIRTH
	                                           WHERE 
                                                    HALL_TICKET_ID=?HALL_TICKET_ID";
                        break;
                    }
                case ExaminationSQLCommands.SaveStuHallTicket:
                    {
                        query = @"INSERT INTO STU_HALL_TICKET_INFO 
                                                        (STUDENT_ID,
                                                        REGISTER_NO,
                                                        DATE_OF_EXAM,
                                                        SESSION_NAME,
                                                        HALL_NAME,
                                                        ELIGIBLE_TYPE,
                                                        ACADEMIC_YEAR,
                                                        SEMESTER_TYPE,
                                                        COURSE_ID,
                                                        EXAM_SETTING_ID,
                                                        FIRST_NAME,
                                                        DATE_OF_BIRTH)
	                                                VALUES(
	                                                    ?STUDENT_ID,
                                                        ?REGISTER_NO,
                                                        ?DATE_OF_EXAM,
                                                        ?SESSION_NAME,
                                                        ?HALL_NAME,
                                                        ?ELIGIBLE_TYPE,
                                                        ?ACADEMIC_YEAR,
                                                        ?SEMESTER_TYPE,
                                                        ?COURSE_ID,
                                                        ?EXAM_SETTING_ID,
                                                        ?FIRST_NAME,
                                                        ?DATE_OF_BIRTH);";
                        break;
                    }
                #endregion

                #region Exam Verification list 

                case ExaminationSQLCommands.FetchExamVerifiedAndUnVerfiedList:
                    {
                        query = @"SELECT 
                                    SPI.ROLL_NO,
                                    SPI.FIRST_NAME,
                                    SPI.STUDENT_ID,
                                    ER.REGISTRATION_ID,
                                    ER.ACADEMIC_YEAR,
                                    ER.AMOUNT,
                                    CC.CLASS_NAME,
                                    ER.IS_VIRIFIED,
                                    ER.EXAM_SETTING_ID,
                                    SS.SEMESTER_NAME AS SEMESTER
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS ER
                                        INNER JOIN
                                    STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = ER.STUDENT_ID
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = SPI.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ER.ACADEMIC_YEAR
                                        INNER JOIN
                                    CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = ER.COURSE_ID
                                        INNER JOIN
                                    EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = ER.EXAM_SETTING_ID
                                        AND ES.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        INNER JOIN
                                    SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = ER.EXAM_SEMESTER
                                    WHERE
                                        ER.IS_DELETED != 1  AND SC.CLASS_ID IN (?CLASS_ID)
                                            AND SC.IS_DELETED != 1
                                            AND SPI.IS_DELETED != 1
                                           -- vf and IS_VIRIFIED=1 
                                            -- nvf and (IS_VIRIFIED !=1 || IS_VIRIFIED is null || IS_VIRIFIED ='0')
                                            AND IS_LEFT != 1
                                    GROUP BY STUDENT_ID ORDER BY CLASS_NAME,ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamVerifiedStatus:
                    {
                        query = @"SET SQL_SAFE_UPDATES=0;
                                    UPDATE EXAM_REGISTRATION_?AC_YEAR
                                                               SET 
                                                                   IS_VIRIFIED = ?IS_VIRIFIED
                                                               WHERE
                                                                   EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                                                       AND STUDENT_ID = ?STUDENT_ID;   
                                                                   SET SQL_SAFE_UPDATES=1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingByACYear:
                    {
                        query = @" SELECT 
                                        EXAM_SETTING_ID, CONCAT(exam_name, ' - ', academic_year) as EXAM_NAME
                                    FROM
                                        exam_setting
                                    WHERE
                                        academic_year = ?AC_YEAR AND IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.CheckHallTicketExistOrNot:
                    {
                        query = @"SELECT 
                                    HALL_TICKET_ID, STUDENT_ID, COURSE_ID
                                FROM
                                    stu_hall_ticket_info
                                WHERE
                                    IS_DELETED != 1 AND EXAM_SETTING_ID =?EXAM_SETTING_ID ;";
                        break;
                    }
                #endregion

                case ExaminationSQLCommands.FetchCourseListByStudentIdForHTValidation:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                    SC.CLASS_ID,
                                    CCR.SEMESTER_ID
                                FROM
                                    CIA_GROUP_MARKS_?AC_YEAR AS CGM
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = CGM.STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SC.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                                        AND PG.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        AND P.IS_DELETED != 1
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                                        AND C.IS_DELETED != 1
                                        INNER JOIN
                                    SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CGM.SEMESTER_ID
                                        AND SS.IS_ACTIVE = 1
                                        INNER JOIN
                                    FBFEEDBACK_SETTINGS AS FS ON FS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND FS.IS_DELETED != 1
                                        AND FS.IS_ACTIVE = 1
                                        INNER JOIN
                                    SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID = FS.SEMESTER_TYPE_ID
                                        AND SST.IS_ACTIVE = 1
                                        INNER JOIN
                                    FBFEEDBACK_ROLE_SETTINGS AS FRS ON FRS.FEEDBACK_ID = FS.FEEDBACK_ID
                                        AND FS.ACADEMIC_YEAR = FRS.ACADEMIC_YEAR
                                        AND FRS.IS_DELETED != 1
                                        AND SUP_FEEDBACK_ROLE_ID = ?SUP_FEEDBACK_ROLE_ID
                                        INNER JOIN
                                    FB_CLASS_SETTING AS FCS ON FCS.ACADEMIC_YEAR = FS.ACADEMIC_YEAR
                                        AND FCS.SETTING_ID = FS.FEEDBACK_ID
                                        AND FCS.CLASS_ID = SC.CLASS_ID
                                        AND FCS.IS_DELETED !=1
                                WHERE
                                    SC.STUDENT_ID = ?STUDENT_ID
                                GROUP BY CCR.SEMESTER_ID , CCR.PART , CCR.COURSE_CODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFeedbackEnteredCourseListForHTValidation:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID, 
                                        CCR.COURSE_CODE
                                    FROM
                                        FBFEEDBACK_SETTINGS AS FFS
                                            INNER JOIN
                                        FBEVALUATION?AC_YEAR AS FE ON FFS.FEEDBACK_ID = FE.FEEDBACK_ID
                                            AND ffs.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ffs.IS_DELETED != 1
                                            AND fe.ISDELETED != 1
                                            INNER JOIN
                                        STU_CLASS AS sc ON sc.STUDENT_ID = fe.ASSESSOR
		                                    and SC.ACADEMIC_YEAR=FFS.ACADEMIC_YEAR
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = FE.COURSE_ID
                                            INNER JOIN
                                        SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID = FFS.SEMESTER_TYPE_ID
                                            AND sst.IS_ACTIVE = 1
                                    WHERE
                                        fe.ASSESSOR = ?STUDENT_ID
                                    GROUP BY sc.STUDENT_ID , ccr.COURSE_ROOT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchFeedbackNotEnterSettingForHTValidation:
                    {
                        query = @"SELECT 
                                        EF.FEEDBACK_ID,
                                        CASE
                                            WHEN AF.FEEDBACK_ID IS NULL THEN 'NOT ATTENDED'
                                            ELSE 'ATTENDED'
                                        END AS ATTENDANCE_STATUS,
                                        FEEDBACK_NAME
                                    FROM
                                        (SELECT 
                                            FFS.FEEDBACK_ID, FFS.FEEDBACK_NAME
                                        FROM
                                            FBFEEDBACK_SETTINGS AS FFS
                                        INNER JOIN FB_CLASS_SETTING AS FCS ON FCS.ACADEMIC_YEAR = FFS.ACADEMIC_YEAR
                                            AND FCS.SETTING_ID = FFS.FEEDBACK_ID
                                            AND FFS.IS_ACTIVE = 1
                                            AND FFS.IS_DELETED != 1
                                            AND FCS.IS_DELETED != 1
                                            AND FFS.ACADEMIC_YEAR = ?AC_YEAR
                                        INNER JOIN STU_CLASS AS SC ON SC.CLASS_ID = FCS.CLASS_ID
                                            AND SC.ACADEMIC_YEAR = FFS.ACADEMIC_YEAR
                                            AND SC.IS_DELETED != 1
                                        INNER JOIN SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID = FFS.SEMESTER_TYPE_ID
                                            AND FFS.IS_ACTIVE = 1
                                        WHERE
                                            SC.ACADEMIC_YEAR = ?AC_YEAR
                                                AND FFS.IS_HOSTEL != 1
                                                AND SC.STUDENT_ID = ?STUDENT_ID) AS EF
                                            LEFT JOIN
                                        (SELECT DISTINCT
                                            FEEDBACK_ID
                                        FROM
                                            FBEVALUATION?AC_YEAR
                                        WHERE
                                            ASSESSOR = ?STUDENT_ID) AS AF ON EF.FEEDBACK_ID = AF.FEEDBACK_ID
                                    HAVING ATTENDANCE_STATUS != 'ATTENDED' 
                                    UNION SELECT 
                                        EF.FEEDBACK_ID,
                                        CASE
                                            WHEN AF.FEEDBACK_ID IS NULL THEN 'NOT ATTENDED'
                                            ELSE 'ATTENDED'
                                        END AS ATTENDANCE_STATUS,
                                        FEEDBACK_NAME
                                    FROM
                                        (SELECT 
                                            FFS.FEEDBACK_ID, FFS.FEEDBACK_NAME
                                        FROM
                                            FBFEEDBACK_SETTINGS AS FFS
                                        INNER JOIN STU_CLASS AS SC ON SC.ACADEMIC_YEAR = FFS.ACADEMIC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND ffs.academic_year = ?AC_YEAR
                                        INNER JOIN SUP_SEMESTER_TYPE AS SST ON SST.SEMESTER_TYPE_ID = FFS.SEMESTER_TYPE_ID
                                            AND FFS.IS_ACTIVE = 1
                                        INNER JOIN HOSTEL_STUDENT_INFO AS HSI ON HSI.STUDENT_ID = SC.STUDENT_ID
                                            AND HSI.IS_DELETED != 1 and HSI.ACADEMIC_YEAR = ?AC_YEAR
                                        WHERE
                                            SC.ACADEMIC_YEAR = ?AC_YEAR
                                                AND FFS.IS_HOSTEL = 1
                                                AND SC.STUDENT_ID = ?STUDENT_ID) AS EF
                                            LEFT JOIN
                                        (SELECT DISTINCT
                                            FEEDBACK_ID
                                        FROM
                                            FBEVALUATION?AC_YEAR
                                        WHERE
                                            ASSESSOR = ?STUDENT_ID) AS AF ON EF.FEEDBACK_ID = AF.FEEDBACK_ID
                                    HAVING ATTENDANCE_STATUS != 'ATTENDED';";
                        break;
                    }
                case ExaminationSQLCommands.FetchHallTicketValidationbyRollNO:
                    {
                        query = @"SELECT 
                                        HALL_TICKET_VALIDATION_ID, htv.STUDENT_ID, REASON
                                    FROM
                                        HALL_TICKET_VALIDATION AS HTV
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = HTV.EXAM_SETTING_ID
                                            AND ES.IS_ACTIVE = 1
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = HTV.STUDENT_ID
   
                                    WHERE
                                        HTV.IS_DELETED != 1
                                            and SPI.ROLL_NO='?ROLL_NO'
                                            AND HTV.ACADEMIC_YEAR = ?AC_YEAR
                                            AND ES.IS_DELETED != 1;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseListForHTValidation:
                    {
                        // Query For Fetch All The Courses From Course Pattern..
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CS.COURSE_STRUCTURE_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    CONCAT(UPPER(CCR.COURSE_TITLE),' (', UPPER(CCR.COURSE_CODE),')') as 'COURSE_TITLE',
                                    CCR.IS_COMPULSORY,
                                    SC.CLASS_ID,
                                    CCR.PART,
                                    ccr.INTERNAL,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    CP.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    CP_COURSE_STRUCTURE AS CS
                                        INNER JOIN
                                    CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                        AND CP.IS_DELETED != 1
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                        AND PG.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        AND P.IS_DELETED != 1
                                        INNER JOIN
                                    CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                        AND C.IS_DELETED != 1
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                        AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                        AND SC.IS_DELETED != 1
                                          INNER JOIN
                                    CP_CLASS_COURSE_STAFF AS CCS ON CCS.CLASS_ID = SC.CLASS_ID
                                        AND CCS.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND CCS.COURSE_ID = CP.COURSE_ID
                                        AND CCS.IS_DELETED != 1
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                        AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                            ACADEMIC_YEAR_ID
                                        FROM
                                            ACADEMIC_YEAR
                                        WHERE
                                            AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS S ON S.SEMESTER = CCR.SEMESTER_ID
                                        AND S.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                        AND S.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND S.BATCH = AB.BATCH_ID
                                        AND S.IS_DELETED != 1
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    CP.ACADEMIC_YEAR = ?AC_YEAR
                                        AND S.IS_ACTIVE = 1
                                        AND SC.STUDENT_ID = ?STUDENT_ID
                                        AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CS.IS_DELETED != 1
                                GROUP BY CCR.COURSE_CODE ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalCoursesForHTValidation:
                    {
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CCR.COURSE_ROOT_ID,
                                    CCR.COURSE_CODE,
                                    CONCAT(UPPER(CCR.COURSE_TITLE),' (',CCR.COURSE_CODE,')') AS 'COURSE_TITLE',
                                    CCR.IS_COMPULSORY,
                                    SC.S_CLASS_ID AS CLASS_ID,
                                    CCR.PART,
                                    CCR.SEMESTER_ID,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    SC.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER
                                FROM
                                    STU_COURSE_INFO AS SC
                                        INNER JOIN
                                    STU_CLASS AS S ON S.STUDENT_ID = SC.STUDENT_ID
                                        AND S.IS_DELETED != 1
                                        AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
										INNER JOIN
									CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID AND C.IS_DELETED != 1
										INNER JOIN
									ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
									AND AB.ACADEMIC_YEAR_ID = (SELECT 
										ACADEMIC_YEAR_ID
									FROM
										ACADEMIC_YEAR
									WHERE
										AC_YEAR = ?AC_YEAR AND IS_DELETED != 1)
                                        INNER JOIN
                                    ACADEMIC_SEMESTER AS SEM ON SEM.SEMESTER = CCR.SEMESTER_ID
                                        AND SEM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                        AND SEM.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                        AND SEM.BATCH = AB.BATCH_ID
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                WHERE
                                    SC.STUDENT_ID = ?STUDENT_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SEM.IS_ACTIVE = 1
                                        AND CCR.IS_DELETED != 1
                                        AND SC.IS_DELETED != 1 ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseListbyStaffId:
                    {
                        query = @"SELECT 
                                        CS.COURSE_ID, UPPER(CR.COURSE_TITLE) AS 'COURSE_TITLE'
                                    FROM
                                        CP_CLASS_COURSE_STAFF AS CS
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = CS.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS CLS ON CLS.CLASS_ID = CS.CLASS_ID
                                            INNER JOIN
                                        SEMESTER_TYPE AS ST ON ST.SEMESTER_TYPE_ID = CS.SEMESTER_TYPE_ID
                                            AND ST.IS_ACTIVE = 1
                                    WHERE
                                        CS.CLASS_ID = ?CLASS_ID AND CS.STAFF_ID = ?STAFF_ID
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY COURSE_ID;";

                        break;
                    }
                case ExaminationSQLCommands.FetchCourseListCourseIDByClassId:
                    {
                        query = @"SELECT 
                                        C.CLASS_ID, 
                                        CCR.COURSE_ROOT_ID AS COURSE_ID, 
                                        CCR.COURSE_CODE, 
                                        CCR.COURSE_TITLE
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                ACTIVE_YEAR = 1)
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            AND SEM.SEMESTER = CCR.SEMESTER_ID
                                            AND AB.BATCH_ID = SEM.BATCH
                                            AND SEM.IS_DELETED != 1
                                    WHERE
                                        CCP.IS_DELETED != 1
                                            AND SEM.IS_ACTIVE = 1 
                                            AND CCP.ACADEMIC_YEAR=?AC_YEAR
                                            AND C.CLASS_ID = ?CLASS_ID   -- AND CCR.COURSE_ROOT_ID=?COURSE_ID
                                             ORDER BY CCR.PART;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamFeeNotPaidForApproval:
                    {
                        query = @"SELECT 
                                        sfd.STUDENT_ID,
                                        spi.FIRST_NAME,
                                        spi.ROLL_NO,
                                        STU_DUE_ID,
                                        cc.CLASS_NAME,
                                        cc.CLASS_ID,
                                        sfd.TERMFEE1,
                                        TERMFEE1PAID,
                                        IF(TERMFEE1 IS NULL,
                                            TERMFEE1,
                                            SUM(IFNULL(TERMFEE1, 0) - IFNULL(TERMFEE1PAID, 0))) AS TERMFEE1DUE,
                                        sfd.TERMFEE2,
                                        sfd.TERMFEE2PAID,
                                        IF(TERMFEE2 IS NULL,
                                            TERMFEE2,
                                            SUM(IFNULL(TERMFEE2, 0)) - SUM(IFNULL(TERMFEE2PAID, 0))) AS TERMFEE2DUE,
                                        sfd.EXAMFEE,
                                        EXAMFEEPAID,
                                        IF(EXAMFEE IS NULL,
                                            EXAMFEE,
                                            SUM(IFNULL(EXAMFEE, 0) - IFNULL(EXAMFEEPAID, 0))) AS EXAMFEEDUE,
                                        B_CREDIT AS BUSFEE,
                                        B_DEBIT AS BUSFEEPAID,
                                        IF(B_CREDIT IS NULL,
                                            B_CREDIT,
                                            SUM(IFNULL(B_CREDIT, 0) - IFNULL(B_DEBIT, 0))) AS BUSFEEDUE,
                                        IF(HFSA.CREDIT IS NULL,
                                            HFSA.CREDIT,
                                            SUM(IFNULL(HFSA.CREDIT, '0'))) AS HOSTELFEE,
                                        IF(HFSA.DEBIT IS NULL,
                                            HFSA.DEBIT,
                                            SUM(IFNULL(HFSA.DEBIT, '0'))) HOSTELFEEPAID,
                                        IF(HFSA.CREDIT IS NULL,
                                            NULL,
                                            SUM(IFNULL(HFSA.CREDIT, '0')) - SUM(IFNULL(HFSA.DEBIT, '0'))) AS HOSTELFEEDUE,
                                        SUM(CASE
                                            WHEN sfd.TERMFEE1 IS NULL THEN 0
                                            ELSE IF(IFNULL(sfd.TERMFEE1, 0) - IFNULL(sfd.TERMFEE1PAID, 0) < 0,
                                                0,
                                                IFNULL(sfd.TERMFEE1, 0) - IFNULL(sfd.TERMFEE1PAID, 0))
                                        END + CASE
                                            WHEN sfd.TERMFEE2 IS NULL THEN 0
                                            ELSE IF(IFNULL(sfd.TERMFEE2, 0) - IFNULL(sfd.TERMFEE2PAID, 0)<0,
                                                0,
                                                IFNULL(sfd.TERMFEE2, 0) - IFNULL(sfd.TERMFEE2PAID, 0))
                                        END + CASE
                                            WHEN sfd.EXAMFEE IS NULL THEN 0
                                            ELSE IF(IFNULL(sfd.EXAMFEE, 0) - IFNULL(sfd.EXAMFEEPAID, 0)<0,
                                                0,
                                                IFNULL(sfd.EXAMFEE, 0) - IFNULL(sfd.EXAMFEEPAID, 0))
                                        END + CASE
                                            WHEN B_CREDIT IS NULL THEN 0
                                            ELSE IF(IFNULL(B_CREDIT, 0) - IFNULL(B_DEBIT, 0)<0,
                                                0,
                                                IFNULL(B_CREDIT, 0) - IFNULL(B_DEBIT, 0))
                                        END + CASE
                                            WHEN HFSA.CREDIT IS NULL THEN 0
                                            ELSE IF(IFNULL(HFSA.CREDIT, 0) - IFNULL(HFSA.DEBIT, 0)<0,
                                                0,
                                                IFNULL(HFSA.CREDIT, 0) - IFNULL(HFSA.DEBIT, 0))
                                        END) AS TOTAL_DUE_AMOUNT,
                                        SFD.ENTRY_ID,
                                        SFD.ENTRY_DATE,
                                        ifnull(SHSA.IS_APPROVED,0) AS IS_APPROVED
                                    FROM
                                        STU_PERSONAL_INFO AS SPI
                                            INNER JOIN
                                        STU_FEE_DUE_INFO AS SFD ON SPI.STUDENT_ID = SFD.STUDENT_ID
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID = SPI.STUDENT_ID
                                            AND SC.ACADEMIC_YEAR = SFD.ACADEMIC_YEAR
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                                            LEFT JOIN
                                         EXAM_HALLTICKET_SPECIAL_APPROVALS AS SHSA ON SHSA.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                                    AND SHSA.STUDENT_ID = SPI.STUDENT_ID
                                                    AND SHSA.ACADEMIC_YEAR = ?AC_YEAR 
                                                    AND SHSA.IS_DELETED != 1
                                            LEFT JOIN
                                        (SELECT 
                                            STUDENT_ID,
                                                SUM(IFNULL(CREDIT, '0')) AS CREDIT,
                                                SUM(IFNULL(DEBIT, '0')) AS DEBIT
                                        FROM
                                            HOSTEL_FEE_STUDENT_ACCOUNT AS hf
                                        WHERE
                                            hf.IS_DELETED != 1
                                                AND hf.ACADEMIC_YEAR = ?AC_YEAR
                                        GROUP BY STUDENT_ID) AS HFSA ON HFSA.STUDENT_ID = SPI.STUDENT_ID
                                            LEFT JOIN
                                        (SELECT 
                                            STUDENT_ID,
                                                SUM(IFNULL(CREDIT, '0')) AS B_CREDIT,
                                                SUM(IFNULL(DEBIT, '0')) AS B_DEBIT
                                        FROM
                                            BUS_FEE_STUDENT_ACCOUNT AS Bf
                                        WHERE
                                            Bf.IS_DELETED != 1
                                                AND Bf.ACADEMIC_YEAR = ?AC_YEAR
                                        GROUP BY STUDENT_ID) AS BFSA ON BFSA.STUDENT_ID = SPI.STUDENT_ID
                                    WHERE
                                        SFD.ACADEMIC_YEAR =?AC_YEAR 
                                            AND SC.IS_DELETED != 1
                                            AND SFD.IS_DELETED != 1
                                            AND SPI.IS_DELETED != 1
                                            AND SPI.IS_LEFT != 1
                                    GROUP BY SFD.STUDENT_ID , sfd.ACADEMIC_YEAR having TOTAL_DUE_AMOUNT > 0
                                    ORDER BY ROLL_NO, SC.CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchHTSpecialApprovalsForCheckExist:
                    {
                        query = @" SELECT 
                                        APPROVAL_ID,
                                        EXAM_SETTING_ID,
                                        ACADEMIC_YEAR,
                                        STUDENT_ID,
                                        APPROVAL_REASON,
                                        APPROVED_BY,
                                        APPROVAL_DATE,
                                        VALID_FROM,
                                        VALID_TO,
                                        APPROVAL_DAYS,
                                        IS_APPROVED
                                    FROM
                                        exam_hallticket_special_approvals
                                    WHERE
                                        IS_DELETED != 1 AND EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                            AND ACADEMIC_YEAR = ?AC_YEAR
                                            AND STUDENT_ID = ?STUDENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.UpdateExamHTSpecialApprovals:
                    {
                        query = @" UPDATE EXAM_HALLTICKET_SPECIAL_APPROVALS SET              
                                                                    APPROVAL_REASON=?APPROVAL_REASON,
                                                                    APPROVED_BY=?APPROVED_BY,
                                                                    APPROVAL_DATE=?APPROVAL_DATE,
                                                                    VALID_TO=?VALID_TO,
                                                                    APPROVAL_DAYS=?APPROVAL_DAYS,
                                                                    IS_APPROVED=?IS_APPROVED,
                                                                    EXAM_SETTING_ID=?EXAM_SETTING_ID,
                                                                    STUDENT_ID=?STUDENT_ID,
                                                                    ACADEMIC_YEAR=?ACADEMIC_YEAR 
                                                                 WHERE 
                                                                    APPROVAL_ID=?APPROVAL_ID;";
                        break;
                    }
                case ExaminationSQLCommands.saveExamHTSpecialApprovals:
                    {
                        query = @"INSERT INTO EXAM_HALLTICKET_SPECIAL_APPROVALS(
                                                                        EXAM_SETTING_ID,
                                                                        ACADEMIC_YEAR,
                                                                        STUDENT_ID,
                                                                        APPROVAL_REASON,
                                                                        APPROVED_BY,
                                                                        APPROVAL_DATE,
                                                                        VALID_TO,
                                                                        VALID_FROM,
                                                                        APPROVAL_DAYS,
                                                                        IS_APPROVED)
                                                                    VALUES(
                                                                        ?EXAM_SETTING_ID,
                                                                        ?ACADEMIC_YEAR,
                                                                        ?STUDENT_ID,
                                                                        ?APPROVAL_REASON,
                                                                        ?APPROVED_BY,
                                                                        ?APPROVAL_DATE,
                                                                        ?VALID_TO,
                                                                        ?VALID_FROM,
                                                                        ?APPROVAL_DAYS,
                                                                        ?IS_APPROVED
                                                                        );";
                        break;
                    }
                case ExaminationSQLCommands.CheckClassType:
                    {
                        query = @" SELECT 
                                        CLASS_ID, CLASS_TYPE
                                    FROM
                                        CP_CLASSES
                                    WHERE
                                        CLASS_ID = ?CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchOptionalStuIdandClassId:
                    {
                        query = @"SELECT 
                                       CLASS_ID,STUDENT_ID
                                    FROM
                                        stu_course_info
                                    WHERE
                                        ACADEMIC_YEAR = ?AC_YEAR
                                            AND COURSE_ID = ?COURSE_ID
                                            AND S_CLASS_ID = ?CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCourseListForInstant:
                    {
                        query = @"SELECT 
                                        C.CLASS_ID,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE
                                    FROM
                                        CP_COURSE_PATTERN AS CCP
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CCP.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            INNER JOIN
                                        ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = C.CLASS_YEAR
                                            AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                                ACADEMIC_YEAR_ID
                                            FROM
                                                ACADEMIC_YEAR
                                            WHERE
                                                ACTIVE_YEAR = 1)
                                            INNER JOIN
                                        ACADEMIC_SEMESTER AS SEM ON SEM.PROGRAMME_GROUP_ID = CCP.PROGRAMME_GROUP_ID
                                            AND SEM.SEMESTER = CCR.SEMESTER_ID
                                            AND AB.BATCH_ID = SEM.BATCH
                                            AND SEM.IS_DELETED != 1
                                    WHERE
                                        CCP.IS_DELETED != 1
                                            AND SEM.IS_ACTIVE = 1
                                            AND CCP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND C.CLASS_ID = ?CLASS_ID
                                    UNION  SELECT 
                                        SCI.CLASS_ID,
                                        CCR.COURSE_ROOT_ID AS COURSE_ID,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE
                                    FROM
                                        STU_COURSE_INFO AS SCI
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SCI.COURSE_ID
                                    WHERE
                                        SCI.CLASS_ID = ?CLASS_ID
                                            AND SCI.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SCI.COURSE_ID = ?COURSE_ID AND SCI.IS_DELETED !=1
                                    GROUP BY COURSE_ID , CLASS_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchCIATotalforIndivudalStaffInstant:
                    {
                        query = @"SELECT 
                                    SUM(IFNULL(T.CUMULATIVE, 0)) AS TOTAL,
                                    T.STUDENT_ID,
                                    T.ADMISSION_NO,
                                    T.COURSE_ID,
                                    T.REGISTER_NO,
                                    T.COURSE_CODE,
                                    T.COURSE_TITLE,
                                    UPPER(T.NAME) AS NAME
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN scc.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN scc.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            CGM.COURSE_ID,
                                            SP.REGISTER_NO,
                                            CCR.COURSE_CODE,
                                            CCR.COURSE_TITLE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS NAME
                                    FROM
                                        STU_CLASS AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND CGM.COURSE_ID = ?COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN SUP_CIA_COMPONENTS AS scc ON scc.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    INNER JOIN CP_CLASS_COURSE AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                        AND CC.COURSE_ID = ?COURSE_ID
                                        AND CC.IS_DELETED != 1
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID
                                            AND CGM.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID 

                                UNION 

                                SELECT 
                                    SUM(IFNULL(T.CUMULATIVE, 0)) AS TOTAL,
                                    T.STUDENT_ID,
                                    T.ADMISSION_NO,
                                    T.COURSE_ID,
                                    T.REGISTER_NO,
                                    T.COURSE_CODE,
                                    T.COURSE_TITLE,
                                    UPPER(T.NAME) AS NAME
                                FROM
                                    (SELECT 
                                        (SUM(
                                            CASE
                                                WHEN scc.COMPONENT_ID = 1 THEN
                                                    -- For component 1, check if component 63 exists
                                                    CASE
                                                        WHEN EXISTS (
                                                            SELECT 1 
                                                            FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                            JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                AND cgc63.IS_DELETED != 1
                                                            JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                AND scom63.COMPONENT_ID = 63
                                                            WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                AND cm.COURSE_ID = CGM.COURSE_ID
                                                                AND cm.COURSE_GROUP_MARK != '-1'
                                                                AND cm.COURSE_GROUP_MARK != 0
                                                        ) THEN
                                                            -- Both components exist, take the max mark
                                                            GREATEST(
                                                                IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK),
                                                                COALESCE((
                                                                    SELECT IF(cm.COURSE_GROUP_MARK = -1, 0, cm.COURSE_GROUP_MARK)
                                                                    FROM CIA_GROUP_MARKS_?AC_YEAR AS cm
                                                                    JOIN CIA_GROUP_COMPONENT AS cgc63 ON cgc63.CIA_GROUP_COMPONENT_ID = cm.COURSE_GROUP_ID
                                                                        AND cgc63.IS_DELETED != 1
                                                                    JOIN SUP_CIA_COMPONENTS AS scom63 ON scom63.COMPONENT_ID = cgc63.SUP_CIA_COMPONENT_ID
                                                                        AND scom63.COMPONENT_ID = 63
                                                                    WHERE cm.STUDENT_ID = CGM.STUDENT_ID
                                                                        AND cm.COURSE_ID = CGM.COURSE_ID
                                                                        AND cm.COURSE_GROUP_MARK != '-1'
                                                                        AND cm.COURSE_GROUP_MARK != 0
                                                                    LIMIT 1
                                                                ), 0)
                                                            )
                                                        ELSE
                                                            -- Only component 1 exists, take its mark
                                                            IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                                    END
                                                WHEN scc.COMPONENT_ID = 63 THEN
                                                    -- For component 63, we've already handled it with component 1, so skip
                                                    0
                                                ELSE
                                                    -- For all other components, take the mark normally
                                                    IF(CGM.COURSE_GROUP_MARK = -1, 0, CGM.COURSE_GROUP_MARK)
                                            END
                                        ) / SUM(MAX_MARK)) * (
                                            SELECT GROUP_MARK
                                            FROM CP_COURSE_TYPE_GROUP AS CTG
                                            WHERE CTG.GROUP_ID = CGC.CIA_GROUP_ID
                                            LIMIT 1
                                        ) AS CUMULATIVE,
                                            SP.STUDENT_ID,
                                            SP.ROLL_NO AS ADMISSION_NO,
                                            CGM.COURSE_ID,
                                            SP.REGISTER_NO,
                                            CCR.COURSE_CODE,
                                            CCR.COURSE_TITLE,
                                            CONCAT(IF(SP.FIRST_NAME IS NULL, '', SP.FIRST_NAME), ' ', IF(SP.LAST_NAME IS NULL, '', SP.LAST_NAME)) AS NAME
                                    FROM
                                        STU_COURSE_INFO AS SC
                                    INNER JOIN STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = SC.STUDENT_ID
                                        AND SP.IS_LEFT != 1
                                        AND SP.IS_DELETED != 1
                                    LEFT JOIN CIA_GROUP_MARKS_?AC_YEAR AS CGM ON CGM.STUDENT_ID = SC.STUDENT_ID
                                        AND SC.COURSE_ID = CGM.COURSE_ID
                                    LEFT JOIN CIA_GROUP_COMPONENT AS CGC ON CGC.CIA_GROUP_COMPONENT_ID = CGM.COURSE_GROUP_ID
                                    LEFT JOIN SUP_CIA_COMPONENTS AS scc ON scc.COMPONENT_ID = CGC.SUP_CIA_COMPONENT_ID
                                        AND CGC.IS_DELETED != 1
                                    LEFT JOIN CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CGM.COURSE_ID
                                        AND CCR.IS_DELETED != 1
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID
                                            AND SC.COURSE_ID = ?COURSE_ID
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND SC.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                    GROUP BY SP.STUDENT_ID , CGC.CIA_GROUP_ID) AS T
                                GROUP BY STUDENT_ID
                                ORDER BY ADMISSION_NO;";

                        break;
                    }
                /// <summary>
                ///  CIA Malpractice query
                /// </summary>
                /// <returns></returns>
                /// <author>Yesudass</author>
                /// <date>05 May 2025</date>
                case ExaminationSQLCommands.FetchCIAMalpracticeList:
                    {
                        query = @" SELECT 
                                        SM.CIA_MALPRACTICE_ID,
                                        SPI.FIRST_NAME,
                                        SPI.ROLL_NO,
                                        CC.CLASS_NAME,
                                        CCR.COURSE_CODE,
                                        CCR.COURSE_TITLE,
                                        SCC.COMPONENT,
                                        date_format(sm.ENTRY_DATE,'%d/%m/%Y') as ENTRY_DATE 
                                    FROM
                                        EXAM_SETTING AS ES
                                            INNER JOIN
                                        CIA_MALPRACTICE AS SM ON SM.EXAM_SETTING_ID = ES.EXAM_SETTING_ID
                                            INNER JOIN
                                        STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = SM.STUDENT_ID
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.STUDENT_ID = SPI.STUDENT_ID
                                            AND SM.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SM.COURSE_ID
                                            INNER JOIN
                                        SUP_CIA_COMPONENTS AS SCC ON SCC.COMPONENT_ID = SM.COMPONENT_ID
                                    WHERE
                                        SM.IS_DELETED != 1 and SM.EXAM_SETTING_ID = ?EXAM_SETTING_ID order by COMPONENT,ROLL_NO;";

                        break;
                    }
                case ExaminationSQLCommands.DeleteCIAMalpracticeList:
                    {
                        query = @"UPDATE CIA_MALPRACTICE 
                                                        SET 
                                                            IS_DELETED = 1
                                                        WHERE
                                                            CIA_MALPRACTICE_ID = ?CIA_MALPRACTICE_ID;";

