                    {
                        query = @"SELECT 
                                        EIS.SESSION,
                                        SS.SESSION_NAME
                                    FROM
                                        EXAM_INVIGILATION_STAFF_WISE AS EIS
                                            INNER JOIN
                                        SUP_SESSION AS SS ON SS.SESSION_ID = EIS.SESSION
                                    WHERE
                                        EIS.IS_DELETED != 1 
                                        AND EIS.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        ?DATE_FILTER
                                    GROUP BY EIS.SESSION, SS.SESSION_NAME
                                    ORDER BY EIS.SESSION;";
                        break;
                    }
                case ExaminationSQLCommands.FetchDateAndSessionWiseInvigilationReport:
                    {
                        query = @"SELECT 
                                        EIS.EXAM_INVIGILATION_ID,
                                        EIS.EXAM_SETTING_ID,
                                        DATE_FORMAT(EIS.EXAM_DATE, '%d/%m/%Y') AS EXAM_DATE,
                                        EIS.EXAM_INVIGILATOR_ID,
                                        EIS.HALL_NAME,
                                        EIS.SESSION,
                                        EIS.ACADEMIC_YEAR,
                                        SPI.STAFF_CODE,
                                        SPI.FIRST_NAME,
                                        SS.SESSION_NAME,
                                        ES.EXAM_NAME,
                                        ES.M_EXAM,
                                        CD.DEPARTMENT_CODE
                                    FROM
                                        EXAM_INVIGILATION_STAFF_WISE AS EIS
                                            INNER JOIN
                                        STF_PERSONAL_INFO AS SPI ON SPI.STAFF_ID = EIS.EXAM_INVIGILATOR_ID
                                            INNER JOIN
                                        SUP_SESSION AS SS ON SS.SESSION_ID = EIS.SESSION
                                            INNER JOIN
                                        EXAM_SETTING AS ES ON ES.EXAM_SETTING_ID = EIS.EXAM_SETTING_ID
                                            LEFT JOIN
                                        CP_DEPARTMENT AS CD ON CD.DEPARTMENT_ID = SPI.DEPARTMENT
                                            LEFT JOIN
                                        sup_college_block AS SCB ON EIS.HALL_NAME LIKE CONCAT('%', SCB.BLOCK_NAME, '%')
                                    WHERE
                                        EIS.IS_DELETED != 1 
                                        AND EIS.EXAM_SETTING_ID = ?EXAM_SETTING_ID
                                        ?DATE_FILTER
                                        ?SESSION_FILTER
                                    ORDER BY 
                                        EIS.EXAM_DATE,
                                        EIS.SESSION,
                                        CASE 
                                            WHEN EIS.HALL_NAME LIKE '%FLOOR%INCHARGE%' OR EIS.HALL_NAME LIKE '%FLOOR%IMCHARGE%' THEN 1
                                            WHEN EIS.HALL_NAME LIKE '%Stand%' THEN 2
                                            ELSE 3
                                        END,
                                        IFNULL(SCB.BLOCK_ORDER, 999),
                                        CASE 
                                            WHEN EIS.HALL_NAME LIKE '%-%' AND CAST(SUBSTRING_INDEX(EIS.HALL_NAME, '-', -1) AS UNSIGNED) > 0 
                                            THEN CAST(SUBSTRING_INDEX(EIS.HALL_NAME, '-', -1) AS UNSIGNED) 
                                            ELSE 999 
                                        END,
                                        EIS.HALL_NAME,
                                        EIS.EXAM_INVIGILATION_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchClassWiseRegularCourseList:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CS.COURSE_STRUCTURE_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                        CCR.COURSE_TYPE,
                                        CCR.IS_COMPULSORY,
                                        SC.CLASS_ID,
                                        CCR.SEMESTER_ID
                                    FROM
                                        CP_COURSE_STRUCTURE AS CS
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                            AND CP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                            AND CCR.IS_DELETED != 1
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                            AND PG.IS_DELETED != 1
                                            INNER JOIN
                                        CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                            AND P.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                            AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                            AND SC.IS_DELETED != 1
                                            INNER JOIN 
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=CCR.SEMESTER_ID AND SS.IS_ACTIVE=1
                                    WHERE
                                        CP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FIND_IN_SET(CCR.SEMESTER_ID,
                                                IF(C.CLASS_YEAR = '1',
                                                    '1,2',
                                                    IF(C.CLASS_YEAR = '2',
                                                        '3,4',
                                                        IF(C.CLASS_YEAR = '3', '5,6', ''))))
                                            AND SC.CLASS_ID = ?CLASS_ID
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY CCR.SEMESTER_ID,CCR.PART,CCR.COURSE_CODE;";

                        break;
                    }
                case ExaminationSQLCommands.FetchClassWiseOptionalCourseList:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CP.COURSE_STRUCTURE_ID,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                        CCR.COURSE_TYPE,
                                        CCR.IS_COMPULSORY,
                                        SC.S_CLASS_ID,
                                        S.CLASS_ID,
                                        CCR.SEMESTER_ID
                                    FROM
                                        STU_COURSE_INFO AS SC
                                            INNER JOIN
                                        STU_CLASS AS S ON S.STUDENT_ID = SC.STUDENT_ID
                                            AND S.IS_DELETED != 1
                                            AND S.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = SC.COURSE_ID
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.CLASS_ID = SC.CLASS_ID
                                            AND C.IS_DELETED != 1
                                            LEFT JOIN
                                        CP_COURSE_PATTERN AS CP ON CP.COURSE_ID = CCR.COURSE_ROOT_ID
                                            AND CP.ACADEMIC_YEAR = SC.ACADEMIC_YEAR
                                            AND S.PROGRAMME_GROUP_ID= CP.PROGRAMME_GROUP_ID
                                            AND CP.IS_DELETED != 1
                                            INNER JOIN 
                                        SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID=CCR.SEMESTER_ID AND SS.IS_ACTIVE=1
                                    WHERE
                                        SC.CLASS_ID = ?CLASS_ID
                                            AND FIND_IN_SET(CCR.SEMESTER_ID,
                                                IF(C.CLASS_YEAR = '1',
                                                    '1,2',
                                                    IF(C.CLASS_YEAR = '2',
                                                        '3,4',
                                                        IF(C.CLASS_YEAR = '3', '5,6', ''))))
                                            AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CCR.IS_DELETED != 1
                                            AND SC.IS_DELETED != 1
                                    GROUP BY CCR.SEMESTER_ID , CCR.PART , CCR.COURSE_CODE , SC.STUDENT_ID;";

                        break;
                    }
                case ExaminationSQLCommands.FetchClassWiseRegularCourseListbyStudent:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CS.COURSE_STRUCTURE_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                        CCR.IS_COMPULSORY,
                                        SC.CLASS_ID,
                                        CCR.SEMESTER_ID
                                    FROM
                                        CP_COURSE_STRUCTURE AS CS
                                            INNER JOIN
                                        CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                            AND CP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                            AND CCR.IS_DELETED != 1
                                        INNER JOIN SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CCR.SEMESTER_ID AND SS.IS_ACTIVE =1
                                            INNER JOIN
                                        CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                            AND PG.IS_DELETED != 1
                                            INNER JOIN
                                        CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                            AND P.IS_DELETED != 1
                                            INNER JOIN
                                        CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                            AND C.IS_DELETED != 1
                                            INNER JOIN
                                        STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                            AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                            AND SC.IS_DELETED != 1
                                    WHERE
                                        CP.ACADEMIC_YEAR = ?AC_YEAR
                                            AND FIND_IN_SET(CCR.SEMESTER_ID,
                                                IF(C.CLASS_YEAR = '1',
                                                    '1,2',
                                                    IF(C.CLASS_YEAR = '2',
                                                        '3,4',
                                                        IF(C.CLASS_YEAR = '3', '5,6', ''))))
                                            AND SC.STUDENT_ID = ?STUDENT_ID
                                            AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                            AND CS.IS_DELETED != 1
                                    GROUP BY CCR.SEMESTER_ID,CCR.PART,CCR.COURSE_CODE;";

                        break;
                    }
                
                case ExaminationSQLCommands.FetchStudentegularCourseListbyStudentexamRegitration:
                    {
                        query = @"SELECT 
                                            SC.STUDENT_ID,
                                            CS.COURSE_STRUCTURE_ID,
                                            CCR.COURSE_ROOT_ID,
                                            CCR.COURSE_CODE,
                                            UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
                                            CCR.IS_COMPULSORY,
                                            SC.CLASS_ID,
                                            CCR.SEMESTER_ID
                                        FROM
                                            CP_COURSE_STRUCTURE AS CS
                                                INNER JOIN
                                            CP_COURSE_PATTERN AS CP ON CP.COURSE_STRUCTURE_ID = CS.COURSE_STRUCTURE_ID
                                                AND CP.IS_DELETED != 1
                                                INNER JOIN
                                            CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CP.COURSE_ID
                                                AND CCR.IS_DELETED != 1
                                                INNER JOIN
                                            SUP_SEMESTER AS SS ON SS.SUP_SEMESTER_ID = CCR.SEMESTER_ID
                                                AND SS.IS_ACTIVE = 1
                                                INNER JOIN
                                            CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                                INNER JOIN
                                            EXAM_REGISTRATION_?AC_YEAR AS ER ON ER.COURSE_ID = CP.COURSE_ID
                                                AND ER.IS_DELETED != 1
                                                AND EXAM_SEMESTER = CCR.SEMESTER_ID
                                                AND PG.IS_DELETED != 1
                                                AND STATUS = 'R'
                                                INNER JOIN
                                            CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                                AND P.IS_DELETED != 1
                                                INNER JOIN
                                            CP_CLASSES AS C ON C.PROGRAMME_GROUP_ID = CP.PROGRAMME_GROUP_ID
                                                AND C.IS_DELETED != 1
                                                INNER JOIN
                                            STU_CLASS AS SC ON SC.CLASS_ID = C.CLASS_ID
                                                AND SC.ACADEMIC_YEAR = CP.ACADEMIC_YEAR
                                                AND SC.STUDENT_ID = ER.STUDENT_ID
                                                AND SC.IS_DELETED != 1
                                        WHERE
                                            CP.ACADEMIC_YEAR = ?AC_YEAR
                                                AND FIND_IN_SET(CCR.SEMESTER_ID,
                                                    IF(C.CLASS_YEAR = '1',
                                                        '1,2',
                                                        IF(C.CLASS_YEAR = '2',
                                                            '3,4',
                                                            IF(C.CLASS_YEAR = '3', '5,6', ''))))
                                                AND SC.STUDENT_ID = ?STUDENT_ID
                                                AND CS.ACADEMIC_YEAR = ?AC_YEAR
                                                AND CS.IS_DELETED != 1
                                        GROUP BY CCR.SEMESTER_ID , CCR.PART , CCR.COURSE_CODE;";

                        break;
                    }
                case ExaminationSQLCommands.FetchClassWiseOptionalCourseListbyStudent:
                    {
                        query = @"SELECT 
                                        SC.STUDENT_ID,
                                        CCR.COURSE_ROOT_ID,
                                        CCR.COURSE_CODE,
                                        CP.COURSE_STRUCTURE_ID,
                                        UPPER(CCR.COURSE_TITLE) AS 'COURSE_TITLE', CCR.COURSE_TYPE,
