                #region chatroom
                case ExaminationSQLCommands.FetchExamRegistrationForLms:
                    {
                        // Query For Fetch All The Courses From Course Pattern..
                        query = @"SELECT 
                                    SC.STUDENT_ID,
                                    CCR.COURSE_ROOT_ID,
TRIM(TRAILING '.' FROM CCR.COURSE_CODE) AS COURSE_CODE,
                                    CCR.COURSE_TITLE,
                                    CCR.IS_COMPULSORY,
                                    SC.CLASS_ID,
                                    CCR.PART,CCR.INTERNAL,
                                    CCR.SEMESTER_ID,SSS.SEMESTER_NAME,
                                    CCR.SUBJECT_TYPE AS 'SUBJECT_TYPE_ID',
                                    SS.SUBJECT_TYPE,
                                    SPI.FIRST_NAME,
                                    CP.ACADEMIC_YEAR AS 'AC_YEAR',
                                    CCR.COURSE_ORDER,
                                    CCR.COURSE_TYPE
                                FROM
                                
                                    LMS_CLASS_COURSE_STAFF AS CS
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = CS.COURSE_ID
                                        AND CCR.IS_DELETED != 1
										INNER JOIN
								    STU_CLASS AS SC ON SC.CLASS_ID = CS.CLASS_ID
                                     AND SC.ACADEMIC_YEAR = CS.ACADEMIC_YEAR
                                         INNER JOIN
									CP_CLASSES AS CP ON CP.CLASS_ID = SC.CLASS_ID
                                        AND CP.IS_DELETED != 1
                                        INNER JOIN
                                         STF_PERSONAL_INFO AS SPI ON SPI.STAFF_ID =CS.STAFF_ID
                                        INNER JOIN
                                    CP_PROGRAMME_GROUP AS PG ON PG.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                                        AND PG.IS_DELETED != 1
                                        INNER JOIN
                                    CP_PROGRAMME AS P ON P.PROGRAMME_ID = PG.PROGRAMME_ID
                                        AND P.IS_DELETED != 1
                                        INNER JOIN
                                    ACADEMIC_BATCHES AS AB ON AB.BATCH_YEAR = CP.CLASS_YEAR
                                        AND AB.ACADEMIC_YEAR_ID = (SELECT 
                                            ACADEMIC_YEAR_ID
                                        FROM
                                            ACADEMIC_YEAR
                                        WHERE
                                            AC_YEAR =  ?AC_YEAR AND IS_DELETED != 1)
                                        
                                        LEFT JOIN
                                    SUP_SUBJECT_TYPE AS SS ON SS.SUBJECT_TYPE_ID = CCR.SUBJECT_TYPE
                                        AND SS.IS_DELETED != 1
                                       INNER JOIN
                                    SUP_SEMESTER AS SSS ON  SSS.SEMESTER_TYPE =CS.SEMESTER_TYPE_ID
                                    AND SSS.IS_ACTIVE =1
                                WHERE
                                 SC.STUDENT_ID = ?STUDENT_ID
                                        AND SC.IS_DELETED != 1
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND CS.IS_DELETED != 1
                                GROUP BY CCR.COURSE_CODE ORDER BY CCR.PART,CCR.COURSE_ORDER;";
                        break;
                    }
                #endregion


