                case ExaminationSQLCommands.FetchExamHeadsByStudentId:
                    {
                        query = @"SELECT 
                       HEAD, COST AS CREDIT
                   FROM
                       FEE_MAIN_HEADS AS FM
                           INNER JOIN
                       EXAM_HEADS AS EH ON EH.ACADEMIC_YEAR = FM.ACADEMIC_YEAR
                           AND EH.FREQUENCY_ID = FM.FREQUENCY_ID
                           AND EH.FEE_MAIN_HEAD_ID = FM.FEE_MAIN_HEAD_ID
                           INNER JOIN
                       SUP_HEAD AS SH ON SH.HEAD_ID = FM.HEAD_ID
                           INNER JOIN
                       STU_CLASS AS SC ON SC.ACADEMIC_YEAR = FM.ACADEMIC_YEAR
                           AND SC.STUDENT_ID = ?STUDENT_ID
                           AND SC.IS_DELETED != 1
                           INNER JOIN
                       CP_PROGRAMME_GROUP AS CP ON CP.PROGRAMME_GROUP_ID = SC.PROGRAMME_GROUP_ID
                           AND CP.SHIFT = EH.SHIFT_ID
                           AND CP.APPTYPE_ID = EH.PROGRAMME_TYPE_ID
                           INNER JOIN
                       CP_CLASSES AS CC ON CC.CLASS_ID = SC.CLASS_ID
                           AND CC.CLASS_YEAR = EH.PROGRAMME_LEVEL_ID
                   WHERE
                       FM.FREQUENCY_ID = 22 AND FM.IS_DELETED!=1;";
                        break;
                    }
            


