                case ExaminationSQLCommands.Fetchdatatobindforpacketandreferenceinsert:
                    {
                        query = @"
                                  SELECT  
                                      EP.COURSE_ID, EP.EXAM_SETTING_ID, 
                                      EP.PACKET_NO, EP.PACKET_REFERENCE_NO,
                                      concat(CP.COURSE_TITLE,' - ',CP.COURSE_CODE) AS COURSE_TITLE,CP.COURSE_CODE,
                                      GROUP_CONCAT(DISTINCT EPRC.MAPPING_ID) as MAPPING_ID,
                                      GROUP_CONCAT(DISTINCT EPRC.STAFF_ID) AS STAFF_ID
                                      FROM
                                      EXAM_PACKET_PROCESS AS EP
                                      INNER JOIN
                                      cp_course_root AS CP ON EP.COURSE_ID = CP.COURSE_ROOT_ID
                                      INNER JOIN exam_timetable AS ET ON ET.COURSE_ID = EP.COURSE_ID AND ET.EXAM_DATE IN(?EXAM_DATE)
                                      INNER JOIN
                                      STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EP.STUDENT_ID
                                          AND SP.BATCH IN (?BATCH)
                                          INNER JOIN
                                      SUP_SESSION AS SS ON SS.SESSION_ID = ET.EXAM_SESSION_ID
                                      LEFT JOIN exam_packet_reference_coursemap AS EPRC on EP.COURSE_ID = EPRC.COURSE_ID AND EP.PACKET_NO = EPRC.PACKET_NO  AND EPRC.IS_DELETED !=1        
                                  WHERE
                                      EP.EXAM_SETTING_ID = ?EXAM_SETTING_ID    
                                  GROUP BY COURSE_ID, PACKET_NO,EP.PACKET_REFERENCE_NO ORDER BY PACKET_REFERENCE_NO,PACKET_NO;
                                ";
                        break;
                    }

                case ExaminationSQLCommands.Fetchdatatobindforpacketandreferenceinsertcourse:
                    {
                        query = @"
                                 SELECT  
                                      EP.COURSE_ID, EP.EXAM_SETTING_ID, 
                                      EP.PACKET_NO, EP.PACKET_REFERENCE_NO,
                                      concat(CP.COURSE_TITLE,' - ',CP.COURSE_CODE) AS COURSE_TITLE,CP.COURSE_CODE,
                                      GROUP_CONCAT(DISTINCT EPRC.MAPPING_ID) as MAPPING_ID,
                                      GROUP_CONCAT(DISTINCT EPRC.STAFF_ID) AS STAFF_ID
                                      FROM
                                      EXAM_PACKET_PROCESS AS EP
                                      INNER JOIN
                                      cp_course_root AS CP ON EP.COURSE_ID = CP.COURSE_ROOT_ID AND CP.PROGRAMME_LEVEL_ID=?PROGRAMME_LEVEL
                                      INNER JOIN exam_timetable AS ET ON ET.COURSE_ID = EP.COURSE_ID
                                      INNER JOIN
                                      STU_PERSONAL_INFO AS SP ON SP.STUDENT_ID = EP.STUDENT_ID
                                          AND SP.BATCH IN (?BATCH)
                                          INNER JOIN
                                      SUP_SESSION AS SS ON SS.SESSION_ID = ET.EXAM_SESSION_ID
                                      LEFT JOIN exam_packet_reference_coursemap AS EPRC on EP.COURSE_ID = EPRC.COURSE_ID AND EP.PACKET_NO = EPRC.PACKET_NO  AND EPRC.IS_DELETED !=1       
                                  WHERE
                                      EP.EXAM_SETTING_ID = ?EXAM_SETTING_ID AND EP.COURSE_ID IN(?COURSE_ID)    
                                  GROUP BY COURSE_ID , PACKET_NO,EP.PACKET_REFERENCE_NO ORDER BY PACKET_REFERENCE_NO,PACKET_NO;
                                ";
