                case ExaminationSQLCommands.FetchAcademicYearByExamSetting:
                    {
                        query = @"SELECT 
                                EXAM_SETTING_ID, 
                                EXAM_NAME, 
                                ACADEMIC_YEAR,
                                M_PASS,
                                SEMESTER_TYPE
                            FROM
                                EXAM_SETTING
                            WHERE
                                ACADEMIC_YEAR = ?ACADEMIC_YEAR 
                                AND IS_DELETED != 1;";

                        break;
                    }


                case ExaminationSQLCommands.FetchBatchBySettingId:
                    {
                        query = @" SELECT 
                                    SB.BATCH AS BATCH,SC.BATCH AS BATCH_ID
                                FROM
                                    EXAM_REGISTRATION_?AC_YEAR AS ER
                                         INNER JOIN 
								     STU_CLASS AS SC ON SC.STUDENT_ID= ER.STUDENT_ID 
									      INNER JOIN 
									 cp_classes AS CC ON CC.CLASS_ID=SC.CLASS_ID
                                          INNER JOIN 
									CP_PROGRAMME_GROUP AS CPG ON CPG.PROGRAMME_GROUP_ID=CC.PROGRAMME_GROUP_ID
                                        INNER JOIN
                                    CP_PROGRAMME AS CP ON CP.PROGRAMME_ID = CPG.PROGRAMME_ID
                                        INNER JOIN
                                    CP_COURSE_ROOT AS CCR ON CCR.COURSE_ROOT_ID = ER.COURSE_ID
                                         INNER JOIN 
                                    SUP_BATCHES AS SB ON SB.BATCH_ID=SC.BATCH    
                                WHERE
                                         CCR.COURSE_ROOT_ID IN (?COURSE_ROOT_ID)  AND ER.EXAM_SETTING_ID=?EXAM_SETTING_ID
                                GROUP BY SB.BATCH ORDER BY SB.BATCH_ID DESC;";
                        break;
                    }
                case ExaminationSQLCommands.FetchexternalcourseInfo:
                    {
                        query = @"SELECT 
                                  EXAM_NAME,
                                  CD.DEPARTMENT,
                                  CONCAT(COURSE_TITLE, '(', COURSE_CODE, ')') AS COURSE_TITLE,
                                  DUE_DATE
                                  FROM
                                  EXAM_SETTING AS ES
                                      INNER JOIN
                                  EXAM_EXAMINER_ORDER AS EO ON EO.EXAM_SETTING_ID = ES.EXAM_SETTING_ID
                                      INNER JOIN
                                  CP_DEPARTMENT AS CD ON CD.DEPARTMENT_ID = EO.DEPARTMENT_ID
                                      INNER JOIN
                                  CP_COURSE_ROOT AS CR ON CR.COURSE_ROOT_ID = EO.COURSE_ID
                                  WHERE
                                  EO.IS_DELETED != 1 AND ES.IS_ACTIVE = 1
                                      AND ES.ACADEMIC_YEAR = ?ACADEMIC_YEAR AND EO.STAFF_ID=?STAFF_ID;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearClassSummaryReport:
                    {
                        query = @"SELECT 
                                      CLS.CLASS_NAME, 
                                      COUNT(DISTINCT EAR.STUDENT_ID) AS STUDENT_COUNT,
                                      COUNT(EAR.COURSE_ID) AS COURSE_COUNT
                                  FROM EXAM_REGISTRATION_ARREAR EAR
                                  INNER JOIN STU_CLASS SC ON SC.STUDENT_ID = EAR.STUDENT_ID AND SC.IS_DELETED != 1
                                  INNER JOIN CP_CLASSES CLS ON CLS.CLASS_ID = SC.CLASS_ID
                                  WHERE EAR.IS_REGISTERED = '1' AND EAR.IS_ACTIVE = '1'
                                    AND DATE_FORMAT(EAR.REGISTER_DATE,'%Y-%m-%d') between ?FROM_DATE AND ?TO_DATE
                                  GROUP BY CLS.CLASS_NAME
                                  ORDER BY CLS.CLASS_NAME";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearCourseSummaryReport:
                    {
                        query = @"SELECT 
                                      CR.COURSE_CODE,
                                      CR.COURSE_TITLE,
                                      COUNT(DISTINCT EAR.STUDENT_ID) AS STUDENT_COUNT,
                                      COUNT(EAR.STUDENT_ID) AS REGISTRATION_COUNT
                                  FROM EXAM_REGISTRATION_ARREAR EAR
                                  INNER JOIN CP_COURSE_ROOT CR ON CR.COURSE_ROOT_ID = EAR.COURSE_ID
                                  WHERE EAR.IS_REGISTERED = '1' AND EAR.IS_ACTIVE = '1'
                                    AND DATE_FORMAT(EAR.REGISTER_DATE,'%Y-%m-%d') between ?FROM_DATE AND ?TO_DATE
                                  GROUP BY CR.COURSE_CODE, CR.COURSE_TITLE
                                  ORDER BY CR.COURSE_CODE";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearDetailedReport:
                    {
                        query = @"SELECT 
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        UPPER(CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                        ' ',
                                                        IFNULL(SP.LAST_NAME, ''))) AS STUDENT_NAME,
                                        CR.COURSE_CODE,
                                        CR.COURSE_TITLE,
                                        CR.SEMESTER_ID AS SEMESTER,
                                        DATE_FORMAT(EAR.REGISTER_DATE, '%d/%m/%Y %h:%i %p') AS REGISTER_DATE_DISPLAY,
                                        EAR.EXAM_SETTING_ID,
                                        EAR.IS_REGISTERED,
                                        EAR.IS_PAID
                                    FROM
                                        EXAM_REGISTRATION_ARREAR EAR
                                            INNER JOIN
                                        STU_PERSONAL_INFO SP ON SP.STUDENT_ID = EAR.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            AND SP.IS_LEFT != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT CR ON CR.COURSE_ROOT_ID = EAR.COURSE_ID
                                    WHERE
                                        EAR.IS_REGISTERED = '1'
                                            AND EAR.IS_ACTIVE = '1'
                                            AND DATE_FORMAT(EAR.REGISTER_DATE, '%Y-%m-%d') BETWEEN ?FROM_DATE AND ?TO_DATE
                                    GROUP BY EAR.STUDENT_ID , EAR.COURSE_ID
                                    ORDER BY EAR.REGISTER_DATE DESC , SP.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearExamReceiptsByStudentId:
                    {
                        query = @"SELECT
                                      FT.TRANSACTION_ID,
                                      FT.RECEIPT_NO,
                                      FT.COLLECTED,
                                      DATE_FORMAT(FT.PAYMENT_DATE, '%d/%m/%Y') AS PAYMENT_DATE,
                                      SPM.PAYMENT_MODE
                                  FROM fee_transaction FT
                                  LEFT JOIN SUP_PAYMENT_MODE SPM ON SPM.PAYMENT_MODE_ID = FT.PAYMENT_MODE
                                  WHERE FT.STUDENT_ID = ?STUDENT_ID
                                    AND FT.FREQUENCY = 26
                                    AND FT.IS_DELETED != 1
                                  GROUP BY FT.RECEIPT_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearCourseWiseSummary:
                    {
                        query = @"SELECT
                                      CR.COURSE_CODE,
                                      CR.COURSE_TITLE,
                                      CR.SEMESTER_ID,
                                      COUNT(DISTINCT EAR.STUDENT_ID) AS STUDENT_COUNT,
                                      COUNT(DISTINCT CASE WHEN EAR.IS_REGISTERED = '1' THEN EAR.STUDENT_ID END) AS REGISTERED_STUDENTS,
                                      COUNT(DISTINCT CASE WHEN EAR.IS_PAID = '1' THEN EAR.STUDENT_ID END) AS PAID_STUDENTS
                                  FROM EXAM_REGISTRATION_ARREAR EAR
                                  INNER JOIN CP_COURSE_ROOT CR ON CR.COURSE_ROOT_ID = EAR.COURSE_ID
                                  WHERE EAR.IS_ACTIVE = '1'
                                    AND EAR.ACADEMIC_YEAR = ?AC_YEAR
                                  GROUP BY CR.COURSE_CODE, CR.COURSE_TITLE, CR.SEMESTER_ID
                                  ORDER BY CR.SEMESTER_ID, CR.COURSE_CODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearStudentsByCourse:
                    {
                        query = @"SELECT
                                      SP.FIRST_NAME AS STUDENT_NAME,
                                      SP.ROLL_NO,
                                      EAR.IS_REGISTERED,
                                      EAR.IS_PAID
                                  FROM EXAM_REGISTRATION_ARREAR EAR
                                  INNER JOIN STU_PERSONAL_INFO SP ON SP.STUDENT_ID = EAR.STUDENT_ID
                                      AND SP.IS_DELETED != 1
                                  INNER JOIN CP_COURSE_ROOT CR ON CR.COURSE_ROOT_ID = EAR.COURSE_ID
                                  WHERE EAR.IS_ACTIVE = '1'
                                    AND EAR.IS_REGISTERED = '1'
                                    AND EAR.ACADEMIC_YEAR = ?AC_YEAR
                                    AND CR.COURSE_CODE = ?COURSE_CODE
                                  ORDER BY SP.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearPaidStudentList:
                    {
                        query = @"SELECT
                                      SPI.ROLL_NO,
                                      SPI.FIRST_NAME,
                                      SPI.ACADEMIC_YEAR,
                                      IF(SPI.APPTYPE_ID = '1', 'UG', 'PG') AS APPTYPE_ID,
                                      EAR.EXAM_SETTING_ID,
                                      CR.SEMESTER_ID,
                                      CR.COURSE_CODE,
                                      CR.COURSE_TITLE
                                  FROM EXAM_REGISTRATION_ARREAR EAR
                                  INNER JOIN CP_COURSE_ROOT CR ON CR.COURSE_ROOT_ID = EAR.COURSE_ID
                                  INNER JOIN STU_PERSONAL_INFO AS SPI ON SPI.STUDENT_ID = EAR.STUDENT_ID
                                  WHERE EAR.IS_ACTIVE = '1'
                                    AND EAR.IS_PAID = 1
                                    AND EAR.ACADEMIC_YEAR = ?AC_YEAR
                                  GROUP BY CR.COURSE_CODE, CR.COURSE_TITLE, EAR.STUDENT_ID
                                  ORDER BY CR.SEMESTER_ID, CR.COURSE_CODE;";
                        break;
                    }
                case ExaminationSQLCommands.FetchArrearOverallEligibleList:
                    {
                        query = @"SELECT 
                                        SP.ROLL_NO,
                                        SP.REGISTER_NO,
                                        UPPER(CONCAT(IFNULL(SP.FIRST_NAME, ''),
                                                        ' ',
                                                        IFNULL(SP.LAST_NAME, ''))) AS STUDENT_NAME,
                                        CR.COURSE_CODE,
                                        CR.COURSE_TITLE,
                                        CR.SEMESTER_ID AS SEMESTER,
                                        DATE_FORMAT(EAR.REGISTER_DATE, '%d/%m/%Y %h:%i %p') AS REGISTER_DATE_DISPLAY,
                                        EAR.EXAM_SETTING_ID,
                                        EAR.IS_REGISTERED,
                                        EAR.IS_PAID
                                    FROM
                                        EXAM_REGISTRATION_ARREAR EAR
                                            INNER JOIN
                                        STU_PERSONAL_INFO SP ON SP.STUDENT_ID = EAR.STUDENT_ID
                                            AND SP.IS_DELETED != 1
                                            INNER JOIN
                                        CP_COURSE_ROOT CR ON CR.COURSE_ROOT_ID = EAR.COURSE_ID
                                    WHERE
                                        EAR.IS_ACTIVE = '1'
                                            AND EAR.ACADEMIC_YEAR = ?AC_YEAR
                                    GROUP BY EAR.STUDENT_ID , EAR.COURSE_ID
                                    ORDER BY CR.SEMESTER_ID, CR.COURSE_CODE, SP.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchUploadedAttendanceMarks:
                    {
                        query = @"SELECT 
                                    u.ATT_MARK_UPLOAD_ID,
                                    u.STUDENT_ID,
                                    u.ROLL_NO,
                                    u.ATTENDANCE_MARK,
                                    u.ACADEMIC_YEAR,
                                    u.SEMESTER_TYPE,
                                    DATE_FORMAT(u.CREATED_DATE, '%d/%m/%Y %h:%i %p') AS CREATED_DATE_DISPLAY,
                                    CONCAT(IFNULL(sp.FIRST_NAME,''), ' ', IFNULL(sp.LAST_NAME,'')) AS STUDENT_NAME,
                                    IFNULL(c.CLASS_NAME, '') AS CLASS_NAME
                                FROM att_attendance_mark_upload u
                                INNER JOIN stu_personal_info sp ON sp.STUDENT_ID = u.STUDENT_ID AND sp.IS_DELETED != 1
                                LEFT JOIN stu_class sc ON sc.STUDENT_ID = u.STUDENT_ID AND sc.ACADEMIC_YEAR = u.ACADEMIC_YEAR
                                LEFT JOIN cp_classes c ON c.CLASS_ID = sc.CLASS_ID
                                WHERE u.ACADEMIC_YEAR = ?AC_YEAR 
                                  AND (u.SEMESTER_TYPE = ?SEMESTER_TYPE OR ?SEMESTER_TYPE = '')
                                  AND u.IS_DELETED != 1
                                ORDER BY u.ROLL_NO;";
                        break;
                    }
                case ExaminationSQLCommands.FetchExamSettingsByAcademicYear:
                    {
                        query = @"SELECT 
                                    EXAM_SETTING_ID,
                                    EXAM_NAME,
                                    ACADEMIC_YEAR,
                                    SEMESTER_TYPE,
                                    IS_ACTIVE
                                FROM EXAM_SETTING
                                WHERE ACADEMIC_YEAR = ?AC_YEAR AND IS_DELETED != 1
                                ORDER BY EXAM_SETTING_ID DESC;";
                        break;
                    }
                case ExaminationSQLCommands.PushAttendanceMarksUpdateCIA:
                    {
                        query = @"UPDATE cia_group_marks_?AC_YEAR AS c
                                INNER JOIN exam_registration_?AC_YEAR AS er ON er.STUDENT_ID = c.STUDENT_ID 
                                    AND er.COURSE_ID = c.COURSE_ID 
                                    AND er.EXAM_SETTING_ID = ?EXAM_SETTING_ID 
                                    AND er.IS_DELETED != 1
                                INNER JOIN exam_setting AS es ON es.EXAM_SETTING_ID = er.EXAM_SETTING_ID
                                INNER JOIN cp_course_root AS cr ON cr.COURSE_ROOT_ID = er.COURSE_ID AND cr.IS_DELETED != 1
                                INNER JOIN cp_course_type_group AS ctg ON ctg.COURSE_TYPE_ID = cr.COURSE_TYPE
                                INNER JOIN cia_group_component AS cgc ON cgc.CIA_GROUP_ID = ctg.GROUP_ID 
                                    AND cgc.CIA_GROUP_COMPONENT_ID = c.COURSE_GROUP_ID 
                                    AND cgc.IS_DELETED != 1
                                INNER JOIN sup_cia_components AS scc ON scc.COMPONENT_ID = cgc.SUP_CIA_COMPONENT_ID 
                                    AND UPPER(scc.COMPONENT) = 'ATTENDANCE'
                                INNER JOIN att_attendance_mark_upload AS att ON att.STUDENT_ID = er.STUDENT_ID 
                                    AND att.ACADEMIC_YEAR = ?AC_YEAR 
                                    AND (
                                        att.SEMESTER_TYPE = CAST(es.SEMESTER_TYPE AS CHAR)
                                        OR (es.SEMESTER_TYPE = 1 AND UPPER(att.SEMESTER_TYPE) IN ('ODD', '1'))
                                        OR (es.SEMESTER_TYPE = 2 AND UPPER(att.SEMESTER_TYPE) IN ('EVEN', '2'))
                                        OR es.SEMESTER_TYPE = 0
                                    )
                                    AND att.IS_DELETED != 1
                                SET c.COURSE_GROUP_MARK = LEAST(att.ATTENDANCE_MARK, cgc.MAX_MARK),
                                    c.ENTRY_ID = ?ENTRY_ID
                                WHERE c.COURSE_GROUP_ID = cgc.CIA_GROUP_COMPONENT_ID;";
                        break;
                    }
                case ExaminationSQLCommands.PushAttendanceMarksInsertCIA:
                    {
                        query = @"INSERT INTO cia_group_marks_?AC_YEAR (STUDENT_ID, COURSE_ID, COURSE_GROUP_ID, COURSE_GROUP_MARK, SEMESTER_ID, ENTRY_ID)
                                SELECT 
                                    er.STUDENT_ID,
                                    er.COURSE_ID,
                                    cgc.CIA_GROUP_COMPONENT_ID,
                                    LEAST(att.ATTENDANCE_MARK, cgc.MAX_MARK),
                                    cr.SEMESTER_ID,
                                    ?ENTRY_ID
                                FROM exam_registration_?AC_YEAR AS er
                                INNER JOIN exam_setting AS es ON es.EXAM_SETTING_ID = er.EXAM_SETTING_ID
                                INNER JOIN cp_course_root AS cr ON cr.COURSE_ROOT_ID = er.COURSE_ID AND cr.IS_DELETED != 1
                                INNER JOIN cp_course_type_group AS ctg ON ctg.COURSE_TYPE_ID = cr.COURSE_TYPE
                                INNER JOIN cia_group_component AS cgc ON cgc.CIA_GROUP_ID = ctg.GROUP_ID AND cgc.IS_DELETED != 1
                                INNER JOIN sup_cia_components AS scc ON scc.COMPONENT_ID = cgc.SUP_CIA_COMPONENT_ID 
                                    AND UPPER(scc.COMPONENT) = 'ATTENDANCE'
                                INNER JOIN att_attendance_mark_upload AS att ON att.STUDENT_ID = er.STUDENT_ID 
                                    AND att.ACADEMIC_YEAR = ?AC_YEAR 
                                    AND (
                                        att.SEMESTER_TYPE = CAST(es.SEMESTER_TYPE AS CHAR)
                                        OR (es.SEMESTER_TYPE = 1 AND UPPER(att.SEMESTER_TYPE) IN ('ODD', '1'))
                                        OR (es.SEMESTER_TYPE = 2 AND UPPER(att.SEMESTER_TYPE) IN ('EVEN', '2'))
                                        OR es.SEMESTER_TYPE = 0
                                    )
                                    AND att.IS_DELETED != 1
                                LEFT JOIN cia_group_marks_?AC_YEAR AS c ON c.STUDENT_ID = er.STUDENT_ID 
                                    AND c.COURSE_ID = er.COURSE_ID 
                                    AND c.COURSE_GROUP_ID = cgc.CIA_GROUP_COMPONENT_ID
                                WHERE er.EXAM_SETTING_ID = ?EXAM_SETTING_ID 
                                  AND er.IS_DELETED != 1
                                  AND c.CIA_GROUP_MARK_ID IS NULL;";
                        break;
                    }
            }




            return query;
        }
    }

}
